import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';
import QuoteView from './pages/QuoteView';

// Em um app real, aqui teríamos o Router.
// Como é uma SPA focada na experiência de proposta, renderizamos a View direta.
const App: React.FC = () => {
  return (
    <main className="w-full min-h-screen bg-neutral-950 text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden">
      <QuoteView />
    </main>
  );
};

export default App;

// Definições de Entidades do Sistema

export interface ServiceItem {
  id: string;
  title: string;
  description: string;
  price: number;
  isOptional: boolean;
  category: 'pre-production' | 'production' | 'post-production' | 'delivery';
  image?: string; // Para thumbnail no upsell
}

export interface ClientData {
  name: string;
  company: string;
  projectTitle: string;
}

export interface QuoteData {
  id: string;
  client: ClientData;
  date: string;
  validUntil: string;
  items: ServiceItem[];
  moodboardImages: string[];
}

// Props Types
export interface CheckboxProps {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label?: string;
  price?: number;
}

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Utilitário para combinar classes Tailwind de forma segura (merge de conflitos).
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Formatador de moeda BRL (Real Brasileiro).
 * Estilo "Contábil" limpo para interfaces financeiras.
 */
export const formatCurrency = (value: number): string => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(value);
};

/**
 * Delay assíncrono para simular loading ou steps de animação
 */
export const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

import { Variants } from 'framer-motion';

// Animação de entrada suave de baixo para cima
export const fadeInUp: Variants = {
  hidden: { opacity: 0, y: 40 },
  visible: { 
    opacity: 1, 
    y: 0,
    transition: { duration: 0.8, ease: [0.22, 1, 0.36, 1] } // Easing cinematográfico
  }
};

// Container que orquestra filhos com delay
export const staggerContainer: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.15,
      delayChildren: 0.3
    }
  }
};

// Efeito de "Scale" sutil para imagens
export const scaleIn: Variants = {
  hidden: { opacity: 0, scale: 1.1 },
  visible: { 
    opacity: 1, 
    scale: 1,
    transition: { duration: 1.5, ease: "easeOut" }
  }
};

// Modal slide in
export const modalVariants: Variants = {
  hidden: { opacity: 0, scale: 0.95, y: 20 },
  visible: { 
    opacity: 1, 
    scale: 1, 
    y: 0,
    transition: { type: "spring", stiffness: 300, damping: 30 }
  },
  exit: { 
    opacity: 0, 
    scale: 0.95, 
    y: 20,
    transition: { duration: 0.2 }
  }
};

import React from 'react';
import { motion, HTMLMotionProps } from 'framer-motion';
import { cn } from '../../lib/utils';

interface ButtonProps extends HTMLMotionProps<"button"> {
  variant?: 'primary' | 'secondary' | 'glass';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}

const Button: React.FC<ButtonProps> = ({ 
  className, 
  variant = 'primary', 
  size = 'md', 
  children, 
  ...props 
}) => {
  const variants = {
    primary: "bg-brand-DEFAULT text-white shadow-[0_0_20px_rgba(220,38,38,0.4)] hover:shadow-[0_0_30px_rgba(220,38,38,0.6)] border border-brand-DEFAULT",
    secondary: "bg-transparent border border-white/20 text-white hover:bg-white/5",
    glass: "bg-white/10 backdrop-blur-md border border-white/10 text-white hover:bg-white/20"
  };

  const sizes = {
    sm: "px-4 py-2 text-sm",
    md: "px-8 py-3 text-base",
    lg: "px-10 py-4 text-lg font-medium tracking-wide"
  };

  return (
    <motion.button
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.98 }}
      className={cn(
        "relative rounded-full transition-colors duration-300 flex items-center justify-center font-sans",
        variants[variant],
        sizes[size],
        className
      )}
      {...props}
    >
      {children}
    </motion.button>
  );
};

export default Button;

