const QuoteView: React.FC = () => {
  // Estado para armazenar os IDs dos itens extras selecionados
  const [selectedExtras, setSelectedExtras] = useState<Set<string>>(new Set());

  // Controle do Modal
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Estado final de aprovação
  const [isApproved, setIsApproved] = useState(false);

  // Cálculo reativo do preço total
  const totalPrice = useMemo(() => {
    const baseTotal = mockQuote.items
      .filter(item => !item.isOptional)
      .reduce((acc, item) => acc + item.price, 0);

    const extrasTotal = mockQuote.items
      .filter(item => item.isOptional && selectedExtras.has(item.id))
      .reduce((acc, item) => acc + item.price, 0);

    return baseTotal + extrasTotal;
  }, [selectedExtras]);

  // Handler para toggle de itens opcionais
  const handleToggleExtra = (id: string) => {
    if (isApproved) return; // Trava edição após aprovação

    const newSelected = new Set(selectedExtras);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedExtras(newSelected);
  };

  // Handler de sucesso da assinatura
  const handleSignatureSuccess = (signatureData: string) => {
    console.log("Signature captured:", signatureData);
    setIsModalOpen(false);
    setIsApproved(true);

    // Scroll to top or show celebration (simplified here)
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className="pb-32 relative">
      <Hero data={mockQuote} />

      {/* Container de conteúdo com max-width */}
      <div className="relative z-10">

        {/* Intro Text / Letter */}
        <section className="py-20 px-6 max-w-3xl mx-auto text-center">
            <motion.p 
              initial={{ opacity: 0 }}
              whileInView={{ opacity: 1 }}
              transition={{ duration: 1 }}
              className="font-serif text-2xl italic text-neutral-400 leading-relaxed"
            >
              "Capturar a essência da Nebula Motors exige mais do que câmeras; exige uma visão. Esta proposta desenha um horizonte onde a velocidade encontra a arte."
            </motion.p>
            <div className="mt-8 flex items-center justify-center gap-4">
                <div className="h-px w-12 bg-white/20"></div>
                <span className="text-xs uppercase tracking-widest text-white/50">EAREC Creative</span>
                <div className="h-px w-12 bg-white/20"></div>
            </div>
        </section>

        <Moodboard images={mockQuote.moodboardImages} />

        <UpsellList 
          items={mockQuote.items} 
          selectedExtras={selectedExtras}
          onToggleExtra={handleToggleExtra}
        />

        {/* Technical Details Area (Filler for visual balance) */}
        <section className="py-20 px-6 border-t border-white/5 bg-neutral-950">
           <div className="max-w-4xl mx-auto grid grid-cols-2 md:grid-cols-4 gap-8 text-neutral-500 text-sm">
              <div>
                  <h5 className="text-white mb-2 font-medium">Timeline</h5>
                  <p>Pre-prod: 2 Weeks</p>
                  <p>Production: 3 Days</p>
                  <p>Post: 3 Weeks</p>
              </div>
              <div>
