                  <p>Global Perpetuity</p>
                  <p>Digital & Broadcast</p>
              </div>
              <div>
                  <h5 className="text-white mb-2 font-medium">Payment</h5>
                  <p>50% on Approval</p>
                  <p>50% on Delivery</p>
              </div>
