import React from 'react';
import { motion, Variants } from 'framer-motion';
import { cn } from '../../lib/utils';
// Importação da Imagem Local
// Certifique-se de que a imagem existe em src/assets/logo.png
import logoSrc from '../../assets/logo.png'; 

interface LogoProps {
  className?: string; // Classes CSS extras para tamanho (w-*, h-*)
  animate?: boolean;  // Se true, anima a entrada da logo
}

/**
 * Componente de Logo
 * ------------------
 * Exibe a imagem da marca.
 * Para alterar o tamanho, passe classes via props (ex: className="w-32").
 */
const Logo: React.FC<LogoProps> = ({ className, animate = false }) => {

  // Configuração da animação (Framer Motion)
  const imageVariants: Variants = {
    hidden: { opacity: 0, scale: 0.8, filter: 'blur(10px)' },
    visible: { 
      opacity: 1, 
      scale: 1, 
      filter: 'blur(0px)',
      transition: { duration: 1.2, ease: [0.22, 1, 0.36, 1] } 
    }
  };

  if (!animate) {
    return (
      <div className={cn("relative select-none", className)}>
        <img 
          src={logoSrc} 
          alt="EAREC Logo" 
          className="w-full h-auto object-contain"
        />
      </div>
    );
  }

  return (
    <motion.div 
      initial="hidden"
      animate="visible"
      variants={imageVariants}
      className={cn("relative select-none", className)}
    >
      <img 
        src={logoSrc} 
        alt="EAREC Logo" 
        className="w-full h-auto object-contain drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]"
      />
    </motion.div>
  );
};

export default Logo;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { ArrowRight, Calendar, MapPin, User, Smartphone } from 'lucide-react';
import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button';
import { ClientData } from '../types';
import { fadeInUp, staggerContainer } from '../lib/animations';

interface WelcomeViewProps {
  onStart: (data: ClientData) => void; // Função chamada ao enviar o formulário
}

/**
 * Tela de Boas-Vindas (Landing Page)
 * ----------------------------------
 * Responsável por causar a primeira impressão e coletar dados básicos.
 */
const WelcomeView: React.FC<WelcomeViewProps> = ({ onStart }) => {
  // Estado que armazena os dados do formulário
  const [formData, setFormData] = useState<ClientData>({
    name: '',
    location: '',
    date: '',
    contact: ''
  });

  // Atualiza o estado conforme o usuário digita
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Envia os dados para o componente pai (App.tsx)
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.contact) {
      onStart(formData);
    }
  };

  return (
    <div className="w-full h-screen flex flex-col items-center justify-center bg-neutral-950 relative overflow-hidden px-6">

      {/* Background Decorativo (Luzes e Gradientes) */}
