    </motion.div>
  );
};

export default Logo;

import React, { useState, useMemo, useEffect } from 'react';
import Hero from '../components/quote/Hero';
import Moodboard from '../components/quote/Moodboard';
import UpsellList from '../components/quote/UpsellList';
import StickyFooter from '../components/quote/StickyFooter';
import SignatureModal from '../components/quote/SignatureModal';
import { mockQuote } from '../data/mock';
import { formatCurrency } from '../lib/utils';
import { motion } from 'framer-motion';
import { OccasionType, LocationType, ClientData, QuoteData } from '../types';

interface QuoteViewProps {
  clientData: ClientData;
}

const QuoteView: React.FC<QuoteViewProps> = ({ clientData }) => {
  // Merge dos dados do cliente com o Mock (Template)
  const quoteData: QuoteData = useMemo(() => ({
    ...mockQuote,
    client: {
        ...mockQuote.client,
        ...clientData,
        projectTitle: `Project: ${clientData.name}`
    }
  }), [clientData]);

  // Estados do Configurador
  const [occasion, setOccasion] = useState<OccasionType>('advertising');
  const [location, setLocation] = useState<LocationType>('external');
  const [photoQty, setPhotoQty] = useState<number>(20); 
  const [videoQty, setVideoQty] = useState<number>(1); 

  // Controle do Modal
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isApproved, setIsApproved] = useState(false);

  // Cálculo reativo do preço total
  const totalPrice = useMemo(() => {
    let total = quoteData.basePrice;

    if (location === 'studio') {
      total += quoteData.studioFee;
    }

    total += (photoQty * quoteData.photoUnitPrice);
    total += (videoQty * quoteData.videoUnitPrice);

    return total;
  }, [location, photoQty, videoQty, quoteData]);

  const handleSignatureSuccess = (signatureData: string) => {
    console.log("Signature captured:", signatureData);
    setIsModalOpen(false);
    setIsApproved(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Helper para formatar data corrigindo Timezone (Evita que caia no dia anterior)
  const formatDateSafe = (dateString: string) => {
    if (!dateString) return 'A definir';
    // Adiciona meio-dia para evitar problemas de UTC-3 (Brasil) virando dia anterior
    const date = new Date(`${dateString}T12:00:00`);
    return date.toLocaleDateString('pt-BR');
  };

  return (
    <div className="pb-32 relative">
      <Hero data={quoteData} />

      <div className="relative z-10">

        {/* Intro Text / Letter */}
        <section className="py-20 px-6 max-w-3xl mx-auto text-center">
            <motion.p 
              initial={{ opacity: 0 }}
              whileInView={{ opacity: 1 }}
              transition={{ duration: 1 }}
              className="font-serif text-2xl italic text-neutral-400 leading-relaxed"
            >
              "Cada frame importa. Para o projeto de <span className="text-white not-italic">{clientData.name}</span>, traremos uma estética cinematográfica única, onde a técnica serve à emoção."
            </motion.p>
            <div className="mt-8 flex items-center justify-center gap-4">
                <div className="h-px w-12 bg-white/20"></div>
                <span className="text-xs uppercase tracking-widest text-white/50">EAREC Creative</span>
                <div className="h-px w-12 bg-white/20"></div>
            </div>
        </section>

        <Moodboard images={quoteData.moodboardImages} />

        {/* Novo Configurador */}
        <UpsellList 
          data={quoteData}
          occasion={occasion}
          setOccasion={setOccasion}
          location={location}
          setLocation={setLocation}
          photoQty={photoQty}
          setPhotoQty={setPhotoQty}
          videoQty={videoQty}
          setVideoQty={setVideoQty}
        />

        {/* Technical Details */}
        <section className="py-20 px-6 border-t border-white/5 bg-neutral-950">
           <div className="max-w-4xl mx-auto grid grid-cols-2 md:grid-cols-4 gap-8 text-neutral-500 text-sm">
              <div>
                  <h5 className="text-white mb-2 font-medium">Data Alvo</h5>
                  <p>{formatDateSafe(clientData.date)}</p>
                  <p>Produção: 1 Diária</p>
                  <p>Contato: {clientData.contact}</p>
              </div>
              <div>
                  <h5 className="text-white mb-2 font-medium">Entrega</h5>
                  <p>Link Privado</p>
                  <p>Alta Resolução</p>
                  <p>Backup Cloud</p>
              </div>
              <div>
                  <h5 className="text-white mb-2 font-medium">Direitos</h5>
                  <p>Uso Comercial</p>
                  <p>Redes Sociais</p>
              </div>
              <div>
                  <h5 className="text-white mb-2 font-medium">Pagamento</h5>
                  <p>50% Reserva</p>
                  <p>50% Entrega</p>
              </div>
           </div>
        </section>

      </div>

      <StickyFooter 
        totalPrice={totalPrice} 
        onApprove={() => setIsModalOpen(true)}
        isApproved={isApproved}
      />

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />
    </div>
  );
};

export default QuoteView;

import React, { useRef, useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import SignatureCanvas from 'react-signature-canvas';
import { X, Loader2 } from 'lucide-react';
import Button from '../ui/Button';
import { modalVariants } from '../../lib/animations';

interface SignatureModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (signatureData: string) => void;
  totalValue: string;
}

/**
 * Modal de Assinatura
 * -------------------
 * Permite que o cliente desenhe a assinatura.
 * IMPORTANTE: O Canvas precisa saber o tamanho exato do container para não distorcer.
 */
const SignatureModal: React.FC<SignatureModalProps> = ({ isOpen, onClose, onConfirm, totalValue }) => {
  const sigPad = useRef<SignatureCanvas>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [isEmpty, setIsEmpty] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Estado para controlar o tamanho do canvas dinamicamente
  const [canvasSize, setCanvasSize] = useState({ width: 0, height: 0 });

  // CORREÇÃO DE PROPORÇÃO & RESIZE:
  // Usa offsetWidth/Height para pegar o tamanho exato interno, garantindo
  // que o traço do mouse corresponda exatamente ao desenho.
  useEffect(() => {
    if (isOpen && containerRef.current) {
      const updateSize = () => {
        if (containerRef.current) {
          setCanvasSize({ 
            width: containerRef.current.offsetWidth, 
            height: containerRef.current.offsetHeight 
          }); 
        }
      };

      // Pequeno delay e chamado imediato para garantir renderização correta após animação
      updateSize();
      const timer = setTimeout(updateSize, 100);

      window.addEventListener('resize', updateSize);
      return () => {
        window.removeEventListener('resize', updateSize);
        clearTimeout(timer);
      };
    }
  }, [isOpen]);

  const clear = () => {
    sigPad.current?.clear();
    setIsEmpty(true);
  };

  const handleEndDrawing = () => {
    if (sigPad.current && !sigPad.current.isEmpty()) {
      setIsEmpty(false);
    }
  };

  const handleConfirm = async () => {
    if (isEmpty || !sigPad.current) return;

    setIsSubmitting(true);
    // Simula envio para API
    await new Promise(r => setTimeout(r, 1500));

    // Pega a imagem em Base64
    const dataUrl = sigPad.current.toDataURL();
    onConfirm(dataUrl);
    setIsSubmitting(false);
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          {/* Fundo Escuro (Backdrop) */}
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-neutral-950/80 backdrop-blur-sm"
            onClick={onClose}
          />

          {/* Janela do Modal */}
          <motion.div
            variants={modalVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            className="relative bg-neutral-900 border border-white/10 rounded-xl shadow-2xl w-full max-w-md overflow-hidden"
          >
            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-serif text-2xl text-white">Aprovar Proposta</h3>
                <button onClick={onClose} className="text-neutral-400 hover:text-white transition-colors">
                  <X size={24} />
                </button>
              </div>

              <div className="mb-6 space-y-2">
                <p className="text-sm text-neutral-400">Ao assinar, você concorda com o valor total de:</p>
                <p className="text-3xl text-white font-sans font-medium">{totalValue}</p>
              </div>

              {/* 
                 Container do Canvas 
                 Removemos 'border' daqui para não afetar o cálculo de width/height interno do canvas.
                 A borda vai no wrapper externo ou via ring.
              */}
              <div 
                ref={containerRef}
                className="relative rounded-lg bg-white/5 overflow-hidden mb-4 h-48 ring-1 ring-white/20"
              >
                {/* O Canvas só renderiza quando temos o tamanho calculado > 0 */}
                {canvasSize.width > 0 && (
                  <SignatureCanvas 
                    ref={sigPad}
                    penColor="white"
                    // Passamos width e height explícitos para garantir resolução correta
                    canvasProps={{
                      width: canvasSize.width,
                      height: canvasSize.height,
                      className: "cursor-crosshair block"
                    }}
                    onEnd={handleEndDrawing}
                  />
                )}

                {/* Botão Limpar */}
                {!isEmpty && (
                  <button 
                    onClick={clear}
                    className="absolute top-2 right-2 text-xs text-neutral-400 hover:text-white bg-black/50 px-2 py-1 rounded z-10"
                  >
                    Limpar
                  </button>
                )}

                {/* Texto "Assine aqui" de fundo */}
                {isEmpty && (
                  <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-white/10 select-none">
                    <span className="font-serif italic text-2xl">Assine aqui</span>
                  </div>
                )}
              </div>

              <div className="flex gap-3">
                <Button 
                  variant="secondary" 
                  className="flex-1"
                  onClick={onClose}
                >
                  Cancelar
                </Button>
                <Button 
                  variant="primary" 
                  className="flex-1"
                  disabled={isEmpty || isSubmitting}
                  onClick={handleConfirm}
                >
                  {isSubmitting ? (
                    <Loader2 className="animate-spin" size={20} />
                  ) : (
                    "Confirmar Contratação"
                  )}
                </Button>
              </div>
            </div>

            {/* Linha decorativa inferior */}
            <div className="h-1 w-full bg-gradient-to-r from-neutral-900 via-brand-DEFAULT to-neutral-900" />
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

export default SignatureModal;

