import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowRight, Calendar, MapPin, User, Smartphone, Lock, CheckCircle2, Loader2 } from 'lucide-react';
import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button';
import { ClientData } from '../types';
import { fadeInUp, staggerContainer } from '../lib/animations';

interface WelcomeViewProps {
  onStart: (data: ClientData) => void;
  onAdminClick: () => void;
}

// Sub-componente para Input com Validação "Cinematográfica"
// Aguarda 3s parado -> Mostra Loading -> Mostra Sucesso
const SmartInput = ({ 
  icon: Icon, 
  name, 
  type = "text", 
  placeholder, 
  value, 
  onChange, 
  minLength = 3,
  className 
}: any) => {
  const [status, setStatus] = useState<'idle' | 'typing' | 'loading' | 'valid'>('idle');
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    // Se estiver vazio, reseta
    if (!value) {
      setStatus('idle');
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      return;
    }

    // Se usuário está digitando (mudou valor), seta status typing e reinicia timer
    setStatus('typing');
    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    // Inicia timer de 3 segundos após parar de digitar
    timeoutRef.current = setTimeout(() => {
      // Começa "validação" (Loading)
      setStatus('loading');

      // Delay estético do loading (1.5s) antes de confirmar
      setTimeout(() => {
        if (value.length >= minLength) {
          setStatus('valid');
        } else {
          setStatus('idle');
        }
      }, 1500);

    }, 3000); // 3 Segundos de espera

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [value, minLength]);

  return (
    <div className="group relative">
      <Icon className="absolute left-0 top-3 text-neutral-500 group-focus-within:text-brand-DEFAULT transition-colors" size={20} />
      <input 
        type={type} 
        name={name}
        required
        placeholder={placeholder}
        value={value}
        onChange={onChange}
        className={`w-full bg-transparent border-b border-white/20 py-3 pl-8 pr-8 text-white focus:outline-none focus:border-brand-DEFAULT transition-colors placeholder:text-neutral-600 ${className}`}
      />

      <AnimatePresence mode="wait">
        {status === 'loading' && (
          <motion.div
            key="loader"
            initial={{ opacity: 0, scale: 0.5 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.5 }}
            className="absolute right-0 top-3 text-neutral-400"
          >
            <Loader2 size={18} className="animate-spin" />
          </motion.div>
        )}

        {status === 'valid' && (
          <motion.div
            key="success"
            initial={{ scale: 0, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0, opacity: 0 }}
            transition={{ type: "spring", stiffness: 400, damping: 15 }}
            className="absolute right-0 top-3 text-emerald-500 drop-shadow-[0_0_8px_rgba(16,185,129,0.5)]"
          >
            <CheckCircle2 size={20} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};


