  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.4, // Aumentado ligeiramente para dar tempo da logo subir
      delayChildren: 0.2
    }
  }
};

// Variante específica da Logo: Começa mais baixo (centro) e sobe
const logoVariant: Variants = {
  hidden: { 
    opacity: 0, 
    y: 180, // Começa deslocado para baixo (simulando o centro visual inicial)
    scale: 1.1 
  },
  visible: { 
    opacity: 1, 
    y: 0, // Vai para a posição original no fluxo
    scale: 1,
    transition: { 
      duration: 1.5, // Duração sutilmente aumentada
      ease: [0.25, 0.1, 0.25, 1.0] // Cubic bezier suave
    } 
