              className="font-serif text-3xl md:text-4xl italic text-neutral-300 leading-relaxed"
            >
              "Cada frame importa. Para o projeto de <span className="text-white not-italic font-medium border-b border-brand-DEFAULT/50 pb-1">{clientData.name}</span>, traremos uma estética cinematográfica única, onde a técnica serve à emoção."
            </motion.p>
            <div className="mt-12 flex items-center justify-center gap-4">
                <div className="h-px w-16 bg-white/20"></div>
                <a 
                  href="https://www.instagram.com/earecmidia/" 
                  target="_blank" 
                  rel="noopener noreferrer" 
                  className="text-xs uppercase tracking-[0.3em] text-brand-DEFAULT font-bold hover:text-white transition-colors cursor-pointer"
                >
                  @EARECMIDIA
                </a>
                <div className="h-px w-16 bg-white/20"></div>
            </div>
        </section>

        <Moodboard images={quoteData.moodboardImages} />

        <UpsellList 
          data={quoteData}
          occasion={occasion}
          setOccasion={setOccasion}
          location={location}
          setLocation={setLocation}
          photoQty={photoQty}
          setPhotoQty={setPhotoQty}
          videoQty={videoQty}
          setVideoQty={setVideoQty}
        />

        {/* Technical Details */}
        {/* Adicionado o trigger de Viewport aqui para destacar o botão no rodapé */}
        <motion.section 
          className="py-32 px-6 bg-neutral-950 relative border-t border-white/5"
          onViewportEnter={() => setHighlightCTA(true)}
          onViewportLeave={() => setHighlightCTA(false)}
        >
           <div className="absolute top-0 left-1/2 -translate-x-1/2 w-px h-24 bg-gradient-to-b from-brand-DEFAULT to-transparent opacity-50" />

           <div className="max-w-6xl mx-auto">
             <h3 className="text-center font-serif text-4xl text-white mb-20">Detalhes do Contrato</h3>

             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12">
                {/* Data */}
                <div className="flex flex-col items-center text-center p-6 border border-brand-DEFAULT/20 rounded-lg bg-white/[0.02] hover:bg-white/[0.04] transition-colors">
                    <div className="mb-6 p-4 rounded-full bg-brand-DEFAULT/10 text-brand-DEFAULT border border-brand-DEFAULT/20">
                      <Calendar size={32} />
                    </div>
                    <h5 className="font-serif text-2xl text-brand-DEFAULT mb-3">Cronograma</h5>
                    <p className="text-lg text-white font-light">{formatDateSafe(clientData.date)}</p>
                    <p className="text-sm text-neutral-500 mt-2">Produção: 1 Diária Completa</p>
                </div>

                {/* Entrega */}
                <div className="flex flex-col items-center text-center p-6 border border-brand-DEFAULT/20 rounded-lg bg-white/[0.02] hover:bg-white/[0.04] transition-colors">
                    <div className="mb-6 p-4 rounded-full bg-brand-DEFAULT/10 text-brand-DEFAULT border border-brand-DEFAULT/20">
                      <CheckCircle size={32} />
                    </div>
                    <h5 className="font-serif text-2xl text-brand-DEFAULT mb-3">Formatos</h5>
                    <p className="text-lg text-white font-light">Link Privado 4K</p>
                    <p className="text-sm text-neutral-500 mt-2">Galeria Web + Backup Cloud</p>
                </div>

                {/* Direitos */}
                <div className="flex flex-col items-center text-center p-6 border border-brand-DEFAULT/20 rounded-lg bg-white/[0.02] hover:bg-white/[0.04] transition-colors">
                    <div className="mb-6 p-4 rounded-full bg-brand-DEFAULT/10 text-brand-DEFAULT border border-brand-DEFAULT/20">
                      <Copyright size={32} />
                    </div>
                    <h5 className="font-serif text-2xl text-brand-DEFAULT mb-3">Licenciamento</h5>
                    <p className="text-lg text-white font-light">Uso Comercial Full</p>
                    <p className="text-sm text-neutral-500 mt-2">Redes Sociais & Site</p>
                </div>

                {/* Pagamento */}
                <div className="flex flex-col items-center text-center p-6 border border-brand-DEFAULT/20 rounded-lg bg-white/[0.02] hover:bg-white/[0.04] transition-colors">
                    <div className="mb-6 p-4 rounded-full bg-brand-DEFAULT/10 text-brand-DEFAULT border border-brand-DEFAULT/20">
                      <CreditCard size={32} />
                    </div>
                    <h5 className="font-serif text-2xl text-brand-DEFAULT mb-3">Condições</h5>
                    <p className="text-lg text-white font-light">50% Reserva</p>
                    <p className="text-sm text-neutral-500 mt-2">50% na Entrega Final</p>
                </div>
             </div>

             <div className="mt-16 text-center">
                <p className="text-neutral-500">Contato direto: <span className="text-white border-b border-white/20">earecmidia@gmail.com</span></p>
             </div>
           </div>
        </motion.section>

      </div>

      <StickyFooter 
        totalPrice={totalPrice} 
        onApprove={() => setIsModalOpen(true)}
        isApproved={isApproved}
        highlight={highlightCTA} // Passa o estado de destaque
      />

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />
    </div>
  );
};

export default QuoteView;

import React, { useState, useRef } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import { fadeInUp, staggerContainer } from '../../lib/animations';
import { cn } from '../../lib/utils';

interface MoodboardProps {
  images: string[];
}

const Moodboard: React.FC<MoodboardProps> = ({ images }) => {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const containerRef = useRef(null);

  // Hooks para o efeito Parallax
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"]
  });

  // Transformações diferentes para cada coluna simular "troca de posição" relativa
  const yColumn1 = useTransform(scrollYProgress, [0, 1], [0, -100]); // Sobe rápido
  const yColumn2 = useTransform(scrollYProgress, [0, 1], [0, 50]);   // Desce devagar
  const yColumn3 = useTransform(scrollYProgress, [0, 1], [0, -50]);  // Sobe devagar

  // Dividindo as imagens em 3 colunas para o layout masonry manual (compatível com parallax)
  const col1 = images.filter((_, i) => i % 3 === 0);
  const col2 = images.filter((_, i) => i % 3 === 1);
  const col3 = images.filter((_, i) => i % 3 === 2);

  const renderImage = (src: string, originalIndex: number) => (
    <motion.div
      key={originalIndex}
      className="relative group overflow-hidden rounded-sm mb-6"
      onMouseEnter={() => setHoveredIndex(originalIndex)}
      onMouseLeave={() => setHoveredIndex(null)}
    >
        <div className={cn(
        "absolute inset-0 bg-black/60 z-10 transition-opacity duration-500",
        hoveredIndex === null ? "opacity-0" : hoveredIndex === originalIndex ? "opacity-0" : "opacity-70"
        )} />

        <img 
        src={src} 
        alt={`Moodboard ${originalIndex}`} 
        className="w-full h-auto object-cover transform transition-transform duration-700 group-hover:scale-110"
        />

        {/* Overlay Border Effect */}
        <div className="absolute inset-0 border border-white/0 group-hover:border-white/20 transition-all duration-500 pointer-events-none z-20" />
    </motion.div>
  );

  return (
    <section ref={containerRef} className="py-24 px-6 md:px-12 bg-neutral-950 relative overflow-hidden">
      <div className="max-w-7xl mx-auto">
        <motion.div 
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-100px" }}
          variants={staggerContainer}
          className="mb-16 relative z-10"
        >
          <motion.h2 variants={fadeInUp} className="font-serif text-4xl md:text-5xl mb-4 text-white">
            Direção Audiovisual
          </motion.h2>
          <motion.p variants={fadeInUp} className="text-neutral-400 max-w-2xl text-lg font-light">
            Projetos com identidades visuais marcantes e únicas, onde cada frame conta uma história inesquecível.
          </motion.p>
        </motion.div>

        {/* Parallax Masonry Layout */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {/* Coluna 1 */}
            <motion.div style={{ y: yColumn1 }}>
                {col1.map((src, i) => renderImage(src, i * 3))}
            </motion.div>

            {/* Coluna 2 */}
            <motion.div style={{ y: yColumn2 }} className="pt-12 md:pt-24">
                 {col2.map((src, i) => renderImage(src, i * 3 + 1))}
            </motion.div>

            {/* Coluna 3 */}
            <motion.div style={{ y: yColumn3 }} className="pt-6 md:pt-0">
                 {col3.map((src, i) => renderImage(src, i * 3 + 2))}
            </motion.div>
        </div>
      </div>
    </section>
  );
};

export default Moodboard;

