        onApprove={() => setIsModalOpen(true)}
        isApproved={isApproved}
        highlight={highlightCTA} 
      />

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />
    </div>
  );
};

