import React, { useState, useMemo, useEffect } from 'react';
import Hero from '../components/quote/Hero';
import Moodboard from '../components/quote/Moodboard';
import UpsellList from '../components/quote/UpsellList';
import StickyFooter from '../components/quote/StickyFooter';
import SignatureModal from '../components/quote/SignatureModal';
import SummaryView from './SummaryView';
import SuccessView from './SuccessView';
import { formatCurrency } from '../lib/utils';
import { motion, useScroll, useSpring, AnimatePresence } from 'framer-motion';
import { OccasionType, LocationType, ClientData, QuoteData } from '../types';
import { ChevronDown } from 'lucide-react';

interface QuoteViewProps {
  clientData: ClientData;
  config: QuoteData;
}

// Tipo de estado da view para navegar entre Configuração, Resumo e Sucesso
type ViewState = 'config' | 'summary' | 'success';

const QuoteView: React.FC<QuoteViewProps> = ({ clientData, config }) => {
  // Estado de Navegação Interna
  const [viewState, setViewState] = useState<ViewState>('config');

  // Configuração da Barra de Progresso (Topo)
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  // Estado para controlar a visibilidade do rodapé (StickyFooter)
  const [showFooter, setShowFooter] = useState(false);

  const quoteData: QuoteData = useMemo(() => ({
    ...config,
    client: {
        ...config.client,
        ...clientData,
        projectTitle: `Project: ${clientData.name}`
    }
  }), [clientData, config]);

  // --- Estados do Configurador ---
  const [occasion, setOccasion] = useState<OccasionType>('advertising');
  const [customOccasionText, setCustomOccasionText] = useState('');

  const [location, setLocation] = useState<LocationType>('external');
  const [photoQty, setPhotoQty] = useState<number>(20); 
  const [videoQty, setVideoQty] = useState<number>(1); 
  const [distance, setDistance] = useState<number>(0); 

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isApproved, setIsApproved] = useState(false);

  useEffect(() => {
    if (clientData.location) {
        let hash = 0;
        const str = clientData.location.toLowerCase();
        for (let i = 0; i < str.length; i++) {
            hash = str.charCodeAt(i) + ((hash << 5) - hash);
        }
        const calculatedDistance = (Math.abs(hash) % 135) + 15;
        setDistance(Math.floor(calculatedDistance));
    }
  }, [clientData.location]);

  const totalPrice = useMemo(() => {
    let total = quoteData.basePrice;
    if (location === 'studio') total += quoteData.studioFee;
    total += (photoQty * quoteData.photoUnitPrice);
    total += (videoQty * quoteData.videoUnitPrice);
    if (distance > 0) {
        total += (distance * 2 * quoteData.pricePerKm);
    }
    return total;
  }, [location, photoQty, videoQty, distance, quoteData]);

  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    setIsApproved(true);
    setViewState('success');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReset = () => {
    window.location.reload(); 
  };

  const ScrollCursor = () => (
    <motion.div 
      initial={{ opacity: 0 }}
      animate={{ opacity: showFooter ? 0 : 1 }} 
      transition={{ duration: 0.5 }}
      className="fixed bottom-10 right-10 z-30 hidden md:flex flex-col items-center gap-2 mix-blend-difference pointer-events-none"
    >
        <span className="text-[10px] font-bold uppercase tracking-[0.3em] text-white rotate-90 origin-right translate-x-4">
            Scroll
        </span>
        <motion.div
            animate={{ y: [0, 10, 0] }}
            transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
            className="w-px h-12 bg-white"
        />
        <ChevronDown size={16} className="text-white" />
    </motion.div>
  );

  if (viewState === 'success') {
      return (
        <SuccessView 
            onReset={handleReset} 
            clientData={clientData}
            totalPrice={totalPrice}
        />
      );
  }

  return (
    <div className="relative">

      {/* 
        Container Principal
        IMPORTANTE: Não usar 'hidden' aqui. Isso destrói o layout e reseta o scroll quando voltamos do resumo.
        Em vez disso, mantemos o bloco renderizado por baixo. 
      */}
      <div className="block pb-40">

          {/* Barra de progresso no TOPO (z-50) para ficar acima de tudo */}
          <motion.div
            className="fixed top-0 left-0 right-0 h-1 bg-brand-DEFAULT z-50 origin-left shadow-[0_0_15px_#DC2626]"
            style={{ scaleX }}
          />

          <ScrollCursor />

          <Hero data={quoteData} />

          <div className="relative z-10">

            <section className="py-24 px-6 max-w-4xl mx-auto text-center">
                <motion.p 
                  initial={{ opacity: 0 }}
                  whileInView={{ opacity: 1 }}
                  transition={{ duration: 1 }}
                  className="font-serif text-3xl md:text-4xl italic text-neutral-300 leading-relaxed"
                >
                  "Cada frame importa. Para o projeto de <span className="text-white not-italic font-medium border-b border-brand-DEFAULT/50 pb-1">{clientData.name}</span>, traremos uma estética cinematográfica única, onde a técnica serve à emoção."
                </motion.p>
                <div className="mt-12 flex items-center justify-center gap-4">
                    <div className="h-px w-16 bg-white/20"></div>
                    <a 
                      href="https://www.instagram.com/earecmidia/" 
                      target="_blank" 
                      rel="noopener noreferrer" 
                      className="text-xs uppercase tracking-[0.3em] text-brand-DEFAULT font-bold hover:text-white transition-colors cursor-pointer"
                    >
                      @EARECMIDIA
                    </a>
                    <div className="h-px w-16 bg-white/20"></div>
                </div>
            </section>

            <Moodboard images={quoteData.moodboardImages} />

            {/* 
                Sensor de Scroll (Trigger): 
                Garante que o rodapé apareça logo antes de começar a configurar, 
                tanto no desktop quanto no mobile. 
            */}
            <motion.div 
                onViewportEnter={() => setShowFooter(true)}
                className="h-px w-full pointer-events-none opacity-0" 
            />

            <UpsellList 
              data={quoteData}
              occasion={occasion}
              setOccasion={setOccasion}
              customOccasionText={customOccasionText}
              setCustomOccasionText={setCustomOccasionText}
              location={location}
              setLocation={setLocation}
              photoQty={photoQty}
              setPhotoQty={setPhotoQty}
              videoQty={videoQty}
              setVideoQty={setVideoQty}
              distance={distance}
              onVisible={() => setShowFooter(true)}
            />

          </div>

          <AnimatePresence>
            {showFooter && (
                <StickyFooter 
                    totalPrice={totalPrice} 
                    onApprove={() => setViewState('summary')} 
                    isApproved={isApproved}
                    highlight={true} 
                />
            )}
          </AnimatePresence>
      </div>

      {/* Página de Resumo (Overlay Fixo) */}
      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                quoteData={quoteData}
                totalPrice={totalPrice}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
            />
         )}
      </AnimatePresence>

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />
    </div>
  );
};

export default QuoteView;

import React, { useState, useRef } from 'react';
import { motion, useScroll, useTransform, useSpring } from 'framer-motion';
import { fadeInUp, staggerContainer } from '../../lib/animations';
import { cn } from '../../lib/utils';

interface MoodboardProps {
  images: string[];
}

const Moodboard: React.FC<MoodboardProps> = ({ images }) => {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Hooks para o efeito Parallax
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"]
  });

  // Suavização do scroll para o movimento parecer "pesado" e cinematográfico
  const smoothProgress = useSpring(scrollYProgress, {
    stiffness: 50,
    damping: 20,
    restDelta: 0.001
  });

  // CONFIGURAÇÃO DO MOVIMENTO "CRUZADO" (CROSS-PARALLAX)
  // Coluna 1: Começa baixo, sobe rápido (Movimento padrão acelerado)
  const yCol1 = useTransform(smoothProgress, [0, 1], [100, -150]);

  // Coluna 2: Começa alto, desce levemente (Resistência oposta -> Efeito de Cruzamento)
  // Isso faz com que a coluna do meio pareça estar indo "contra" as laterais
  const yCol2 = useTransform(smoothProgress, [0, 1], [-150, 100]);

  // Coluna 3: Igual a coluna 1, mas com um offset para não ficar simétrico demais
  const yCol3 = useTransform(smoothProgress, [0, 1], [150, -200]);

  // Divisão das imagens em colunas
  const col1 = images.filter((_, i) => i % 3 === 0);
  const col2 = images.filter((_, i) => i % 3 === 1);
  const col3 = images.filter((_, i) => i % 3 === 2);

  const renderImage = (src: string, originalIndex: number, priority: boolean = false) => (
    <motion.div
      key={originalIndex}
      initial={{ opacity: 0, scale: 0.9 }}
      whileInView={{ opacity: 1, scale: 1 }}
      viewport={{ once: true, margin: "-50px" }}
      transition={{ duration: 0.8 }}
      className="relative group mb-8 md:mb-12 w-full"
      onMouseEnter={() => setHoveredIndex(originalIndex)}
      onMouseLeave={() => setHoveredIndex(null)}
    >
        {/* Container da Imagem com Aspect Ratio Vertical (Cinematic Portrait) */}
        <div className="relative overflow-hidden rounded-lg shadow-[0_20px_50px_rgba(0,0,0,0.5)] border border-white/5">
            {/* Overlay Escuro que some no Hover */}
            <div className={cn(
                "absolute inset-0 bg-black/40 z-10 transition-all duration-700 ease-in-out",
                hoveredIndex === null ? "opacity-40" : hoveredIndex === originalIndex ? "opacity-0" : "opacity-80 grayscale"
            )} />

            <img 
                src={src} 
                alt={`Moodboard ${originalIndex}`} 
                className="w-full h-auto object-cover transform transition-transform duration-1000 ease-out group-hover:scale-105"
                loading={priority ? "eager" : "lazy"}
            />

            {/* Bordas Brilhantes no Hover */}
            <div className="absolute inset-0 border border-white/0 group-hover:border-white/20 transition-all duration-700 pointer-events-none z-20" />
        </div>
    </motion.div>
  );

  return (
    <section ref={containerRef} className="py-32 px-6 md:px-12 bg-neutral-950 relative overflow-hidden">

      {/* Background Decorativo Sutil */}
      <div className="absolute top-0 left-0 w-full h-64 bg-gradient-to-b from-black to-transparent z-10 pointer-events-none" />
      <div className="absolute bottom-0 left-0 w-full h-64 bg-gradient-to-t from-black to-transparent z-10 pointer-events-none" />

      <div className="max-w-7xl mx-auto">
        <motion.div 
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          variants={staggerContainer}
          className="mb-24 relative z-20 text-center md:text-left"
        >
          <motion.div variants={fadeInUp} className="flex items-center gap-4 justify-center md:justify-start mb-4">
             <div className="h-px w-12 bg-brand-DEFAULT shadow-[0_0_10px_#DC2626]" />
             <span className="text-brand-DEFAULT uppercase tracking-widest text-xs font-bold drop-shadow-md">Direção de Arte</span>
          </motion.div>
          <motion.h2 variants={fadeInUp} className="font-serif text-4xl md:text-6xl text-white mb-6 drop-shadow-[0_5px_5px_rgba(0,0,0,0.8)]">
            Estética Visual
          </motion.h2>
          <motion.p variants={fadeInUp} className="text-neutral-400 max-w-xl text-lg font-light leading-relaxed mx-auto md:mx-0 drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">
            Uma curadoria de referências visuais que definem o tom, a iluminação e a atmosfera cinematográfica do seu projeto.
          </motion.p>
        </motion.div>

        {/* 
            GRID CINEMATOGRÁFICO CRUZADO 
            Desktop: 3 Colunas com Parallax Oposto
            Mobile: 1 Coluna simples (sem parallax agressivo para usabilidade)
        */}
        <div className="hidden md:grid grid-cols-3 gap-8 min-h-[800px]">
            {/* Coluna 1: Sobe Rápido */}
            <motion.div style={{ y: yCol1 }} className="flex flex-col pt-12">
                {col1.map((src, i) => renderImage(src, i * 3))}
            </motion.div>

            {/* Coluna 2: Desce (Contra-fluxo) - Cria o efeito de cruzamento */}
            <motion.div style={{ y: yCol2 }} className="flex flex-col -mt-24">
                 {col2.map((src, i) => renderImage(src, i * 3 + 1, true))}
            </motion.div>

            {/* Coluna 3: Sobe Muito Rápido */}
            <motion.div style={{ y: yCol3 }} className="flex flex-col pt-32">
                 {col3.map((src, i) => renderImage(src, i * 3 + 2))}
            </motion.div>
        </div>

        {/* Layout Mobile (Simples, sem risco de quebra) */}
        <div className="md:hidden grid grid-cols-1 gap-6">
             {images.map((src, i) => renderImage(src, i))}
        </div>

      </div>
    </section>
  );
};

export default Moodboard;

