                           {addRealTime && <div className="w-2 h-2 bg-white rounded-full" />}
                        </div>
                        <div>
                            <p className="text-white font-medium">Fotos Real Time (+ R$ 600)</p>
                            <p className="text-xs text-neutral-400">Entrega imediata durante o evento.</p>
