                           {addDrone && <div className="w-2 h-2 bg-white rounded-full" />}
                        </div>
                        <div>
                            <p className="text-white font-medium">Imagens de Drone (+ R$ 250)</p>
                            <p className="text-xs text-neutral-400">Perspectivas aéreas cinematográficas.</p>
                        </div>
