  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

  // Controle do indicador de rolagem (Scroll Incentive)
  const [showScrollIndicator, setShowScrollIndicator] = useState(true);

  // Monitora o scroll para esconder o indicador quando chegar perto do fim
  useEffect(() => {
    return scrollYProgress.on('change', (latest) => {
      if (latest > 0.9) setShowScrollIndicator(false);
      else setShowScrollIndicator(true);
    });
  }, [scrollYProgress]);

  // Controle de visibilidade do footer
  const [showFooter, setShowFooter] = useState(true);

  // Memoização dos dados combinados (Cliente + Config)
  const quoteData: QuoteData = useMemo(() => ({
    ...config,
    client: { ...config.client, ...clientData, projectTitle: `Project: ${clientData.name}` }
  }), [clientData, config]);

  // --- ESTADOS DO SELETOR DE SERVIÇOS ---
  const [category, setCategory] = useState<ServiceCategory>('social');
  const [serviceId, setServiceId] = useState<ServiceId>('birthday');

  // Variáveis Quantitativas (Horas ou Unidades)
  const [hours, setHours] = useState<number>(2);
  const [qty, setQty] = useState<number>(10);

  // Adicionais (Checkboxes)
  const [addDrone, setAddDrone] = useState(false);
  const [addRealTime, setAddRealTime] = useState(false);

  // --- ESTADO DE PAGAMENTO ---
  // Elevado para QuoteView para persistir entre as telas de resumo e sucesso
  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');

  // --- LÓGICA DE GEOLOCALIZAÇÃO ---
  const [distance, setDistance] = useState<number>(0); 
  const [isModalOpen, setIsModalOpen] = useState(false); // Modal de Assinatura
  const [isApproved, setIsApproved] = useState(false);   // Estado de Aprovação

  // Effect: Calcula distância assim que a tela carrega (ou se o local mudar)
  useEffect(() => {
    let isMounted = true;
    const updateDistance = async () => {
        if (clientData.location) {
            // Chama a API de Mapas (lib/maps.ts)
            const dist = await calculateDistance(clientData.location);
            if (isMounted) setDistance(dist);
        }
    };
    updateDistance();
    return () => { isMounted = false; };
  }, [clientData.location]);

  /**
   * 🔄 MOTOR DE CÁLCULO DE PREÇO (PRICING ENGINE)
   * ---------------------------------------------
   * Utiliza useMemo para recalcular o total apenas quando as dependências mudam.
   * A lógica segue 3 etapas:
   * 1. Preço Base do Serviço Selecionado.
   * 2. Adicionais Globais (Drone, etc).
   * 3. Logística (Frete por KM).
   */
  const totalPrice = useMemo(() => {
    let total = 0;

    // ETAPA 1: Cálculo do Serviço Principal
    if (category === 'social') {
        const s = PRICING_TABLE.social;
        switch (serviceId) {
            case 'birthday':
            case 'fifteen':
                // Regra: Preço Base + (Horas Extras * Valor Hora)
                total += s.birthday.base;
                if (hours > s.birthday.hoursIncluded) {
                    total += (hours - s.birthday.hoursIncluded) * s.birthday.hourPrice;
                }
                break;
            case 'graduation': total += s.graduation.base; break;
            case 'wedding_base': total += s.wedding_base.base; break;
            case 'wedding_classic': total += s.wedding_classic.base; break;
            case 'wedding_romance': total += s.wedding_romance.base; break;
            case 'wedding_essence': total += s.wedding_essence.base; break;
        }
        // Adicional específico de Social
        if (addRealTime) total += s.realtime.fixed;
    } 
    else if (category === 'commercial') {
        if (serviceId === 'comm_photo') total += qty * PRICING_TABLE.commercial.photo.unit;
        if (serviceId === 'comm_video') total += PRICING_TABLE.commercial.video.fixed;
        if (serviceId === 'comm_combo') {
            // Regra Combo: Preço Vídeo + (Qtd Fotos * Valor Foto)
            total += PRICING_TABLE.commercial.combo.videoBase + (qty * PRICING_TABLE.commercial.combo.photoUnit);
        }
    }
    else if (category === 'studio') {
        if (serviceId === 'studio_photo') total += qty * PRICING_TABLE.studio.photo.unit;
        if (serviceId === 'studio_video') total += PRICING_TABLE.studio.video.fixed;
    }
    else if (category === 'video_production') {
        if (serviceId === 'edit_only') total += qty * PRICING_TABLE.video_production.edit.unit;
        if (serviceId === 'cam_cap') total += PRICING_TABLE.video_production.cam_cap.fixed;
        if (serviceId === 'mobile_cap') total += PRICING_TABLE.video_production.mobile_cap.fixed;
        if (serviceId === 'drone') total += PRICING_TABLE.video_production.drone.fixed;
    }
    else if (category === 'custom') {
        total += PRICING_TABLE.custom.custom_project.base;
    }

    // ETAPA 2: Adicionais Globais
    // Drone é cobrado extra se não for a categoria 'video_production' (onde já é um item principal)
    if (addDrone && category !== 'video_production' && category !== 'custom') { 
         total += PRICING_TABLE.video_production.drone.fixed; 
    }

    // ETAPA 3: Logística (Frete)
    // REGRA DE NEGÓCIO: Estúdio e Custom não cobram deslocamento automático.
    if (distance > 0 && category !== 'studio' && category !== 'custom') {
        // Fórmula: Distância (Ida) * 2 (Volta) * Preço/Km
        total += (distance * 2 * quoteData.pricePerKm);
    }

    return total;
  }, [category, serviceId, hours, qty, addDrone, addRealTime, distance, quoteData.pricePerKm]);

  // Effect: Resetar inputs quantitativos ao trocar de categoria para evitar estados inconsistentes
  useEffect(() => {
      // Defaults inteligentes por categoria
      if (category === 'social') setServiceId('birthday');
      if (category === 'commercial') setServiceId('comm_photo');
      if (category === 'studio') setServiceId('studio_photo');
      if (category === 'video_production') setServiceId('edit_only');
      if (category === 'custom') setServiceId('custom_project');

      // Reseta valores numéricos
      setHours(2);
      setQty(10);
      setAddRealTime(false);
  }, [category]);

  // Handler: Assinatura realizada com sucesso
  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    setIsApproved(true);
    setViewState('success'); // Muda para tela final
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReset = () => { window.location.reload(); };

  // --- PREPARAÇÃO DE DADOS PARA TELAS (SUMMARY E SUCCESS) ---

  // 1. Obtém o label legível do serviço atual
  let label = 'Serviço Personalizado';
  if (category === 'social') label = PRICING_TABLE.social[serviceId as keyof typeof PRICING_TABLE.social]?.label || label;
  if (category === 'commercial') {
      if (serviceId === 'comm_combo') label = PRICING_TABLE.commercial.combo.label;
      else label = PRICING_TABLE.commercial[serviceId as keyof typeof PRICING_TABLE.commercial]?.label || label;
  }
  if (category === 'studio') label = PRICING_TABLE.studio[serviceId as keyof typeof PRICING_TABLE.studio]?.label || label;
  if (category === 'video_production') label = PRICING_TABLE.video_production[serviceId as keyof typeof PRICING_TABLE.video_production]?.label || label;

  // 2. Define a métrica principal (Horas ou Quantidade) para exibição
  let metricLabel = '';
  if (category === 'social' && (serviceId === 'birthday' || serviceId === 'fifteen')) {
    metricLabel = `${hours} Horas de Cobertura`;
  } else if (category === 'commercial' && serviceId === 'comm_combo') {
    metricLabel = `Vídeo + ${qty} Fotos`;
  } else if (category === 'commercial' && serviceId === 'comm_photo') {
    metricLabel = `${qty} Fotos`;
  } else if (category === 'studio' && serviceId === 'studio_photo') {
    metricLabel = `${qty} Fotos`;
  } else if (category === 'video_production' && serviceId === 'edit_only') {
    metricLabel = `${qty} Vídeos`;
  } else if (category === 'custom') {
    metricLabel = 'Sob medida';
  } else {
    metricLabel = 'Taxa Fixa / Diária';
  }

  // 3. Lista de Adicionais Ativos
  const activeAddons = [];
  if (addDrone && category !== 'video_production') activeAddons.push('Drone (Aéreo)');
  if (addRealTime) activeAddons.push('Fotos Real Time');

  // Objeto de Detalhes para o SummaryView
  const summaryDetails = {
    serviceName: label,
    categoryLabel: category === 'social' ? 'Social' : category === 'commercial' ? 'Comercial' : category === 'studio' ? 'Estúdio' : 'Produção',
    metricLabel,
    addons: activeAddons
  };

  // Objeto de Detalhes para o SuccessView (mantendo compatibilidade)
  const quoteDetails = {
    occasion: category === 'custom' ? 'custom' : (category as any),
    customOccasionText: label,
    location: (category === 'studio' ? 'studio' : 'external'),
    photoQty: (category === 'studio' || (category === 'commercial' && serviceId === 'comm_photo') || (category === 'commercial' && serviceId === 'comm_combo')) ? qty : 0,
    videoQty: (category === 'video_production' && serviceId === 'edit_only') ? qty : 
              ((category === 'commercial' && (serviceId === 'comm_video' || serviceId === 'comm_combo'))) ? 1 : 0,
    distance,
    paymentMethod 
  };

  // --- RENDERIZAÇÃO CONDICIONAL DE VIEW ---

  if (viewState === 'success') {
      return (
        <SuccessView 
            onReset={handleReset} 
            clientData={clientData}
            totalPrice={totalPrice}
            quoteDetails={quoteDetails as any}
        />
      );
  }

  return (
    <div className="relative">
      <div className="block pb-40">
          {/* Barra de Progresso Vermelha no Topo */}
          <motion.div
            className="fixed top-0 left-0 right-0 h-1 bg-brand-DEFAULT z-50 origin-left shadow-[0_0_15px_#DC2626]"
            style={{ scaleX }}
          />

          <Hero data={quoteData} />

          <div className="relative z-10">
            {/* Componente que contém os Cards de Serviço e Controles */}
            <UpsellList 
              category={category} setCategory={setCategory}
              serviceId={serviceId} setServiceId={setServiceId}
              hours={hours} setHours={setHours}
              qty={qty} setQty={setQty}
              addDrone={addDrone} setAddDrone={setAddDrone}
              addRealTime={addRealTime} setAddRealTime={setAddRealTime}
              distance={distance}
              pricePerKm={quoteData.pricePerKm}
              locationClient={clientData.location}
            />
          </div>

          {/* INDICADOR DE ROLAGEM (Scroll Incentive) */}
          <AnimatePresence>
            {showScrollIndicator && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed bottom-24 left-1/2 -translate-x-1/2 z-30 pointer-events-none text-neutral-500"
              >
                 <motion.div
                    animate={{ y: [0, 8, 0] }}
                    transition={{ duration: 1.5, repeat: Infinity, ease: "easeInOut" }}
                    className="flex flex-col items-center"
                 >
                    <span className="text-[10px] uppercase tracking-widest mb-1 opacity-70">Role</span>
                    <ChevronsDown size={24} />
                 </motion.div>
              </motion.div>
            )}
          </AnimatePresence>

          <AnimatePresence>
            {showFooter && (
                <StickyFooter 
                    totalPrice={totalPrice} 
                    onApprove={() => setViewState('summary')} 
                    isApproved={isApproved}
                    highlight={true} 
                />
            )}
          </AnimatePresence>
      </div>

      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={quoteData}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={summaryDetails} // Passando o resumo
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
            />
         )}
      </AnimatePresence>

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />
    </div>
  );
};

export default QuoteView;

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Calendar, CheckCircle, Copyright, CreditCard, ArrowLeft, PenTool, MapPin, Settings2, User, Phone, Edit2, Save, X, Banknote, QrCode, FileText, Check } from 'lucide-react';
import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button';
import AnimatedPrice from '../components/ui/AnimatedPrice';
import { QuoteData, ClientData } from '../types';
import { cn } from '../lib/utils';

interface SummaryDetails {
    serviceName: string;
    categoryLabel: string;
    metricLabel: string;
    addons: string[];
}

interface SummaryViewProps {
  clientData: ClientData;
  onUpdateClientData: (data: ClientData) => void;
  quoteData: QuoteData;
  totalPrice: number;
  paymentMethod: string;
  setPaymentMethod: (method: string) => void;
  onBack: () => void;
  onProceedToSign: () => void;
  summaryDetails: SummaryDetails; // Nova prop
}

/**
 * Componente: SummaryView (Revisão)
 * ---------------------------------
 * Exibe o resumo final do pedido antes da assinatura.
 * Permite edição rápida dos dados do cliente (Nome, Data, Local).
 * Permite seleção da forma de pagamento.
 */
const SummaryView: React.FC<SummaryViewProps> = ({ 
  clientData, 
  onUpdateClientData,
  quoteData, 
  totalPrice,
  paymentMethod,
  setPaymentMethod,
  onBack, 
  onProceedToSign,
  summaryDetails
}) => {
  const [showContent, setShowContent] = useState(false);

  // Estado que controla se os campos estão em modo de edição
  const [isEditing, setIsEditing] = useState(false);

  // Estado temporário (Buffer) para armazenar as mudanças durante a edição.
  // Só é comitado para o estado principal se o usuário clicar em "Salvar".
  const [tempData, setTempData] = useState<ClientData>(clientData);

  // Sincroniza estado local se clientData mudar externamente
  useEffect(() => {
    setTempData(clientData);
  }, [clientData]);

  // Sequência de Animação de Entrada
  useEffect(() => {
    const timer = setTimeout(() => {
      setShowContent(true);
    }, 1500); 
    return () => clearTimeout(timer);
  }, []);

  // Comita as mudanças para o componente pai
  const handleSave = () => {
    onUpdateClientData(tempData);
    setIsEditing(false);
  };

  // Descarta as mudanças e restaura o valor original
  const handleCancel = () => {
    setTempData(clientData);
    setIsEditing(false);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setTempData(prev => ({ ...prev, [name]: value }));
  };

  // Helper para mostrar datas de forma amigável
  const formatDateSafe = (dateString: string) => {
    if (!dateString) return 'A definir';
    try {
        const date = new Date(`${dateString}T12:00:00`);
        return date.toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
    } catch (e) {
        return dateString;
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-neutral-950 overflow-y-auto">

      {/* 
         INTRO OVERLAY 
         Cobre a tela inteira com o logo enquanto os dados "carregam" 
         (efeito visual para transição de estados)
      */}
      <AnimatePresence>
        {!showContent && (
          <motion.div
            key="intro-overlay"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, scale: 1.1, filter: 'blur(10px)' }}
            transition={{ duration: 0.8 }}
            className="absolute inset-0 flex items-center justify-center bg-black z-50"
          >
            <motion.div
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 1 }}
            >
              <Logo className="w-64" animate />
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* CONTEÚDO PRINCIPAL */}
      {showContent && (
        <motion.div
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="min-h-screen py-12 px-4 md:px-6 relative"
        >
             {/* Efeito de Luz no topo */}
             <div className="fixed top-0 left-0 w-full h-1/2 bg-gradient-to-b from-brand-DEFAULT/5 to-transparent pointer-events-none" />

             <div className="max-w-3xl mx-auto relative z-10">

                {/* Header Navigation Compacto */}
                <div className="flex items-center justify-between mb-8 border-b border-white/5 pb-4">
                    <button 
                        onClick={onBack}
                        className="flex items-center gap-2 text-neutral-500 hover:text-white transition-colors group text-sm"
                    >
                        <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
                        VOLTAR
                    </button>
                    <div className="text-right">
                        <p className="text-xs text-neutral-500 uppercase tracking-widest">Resumo do Pedido</p>
                        <p className="text-white font-serif text-lg">{quoteData.id}</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 gap-6">

                    {/* SEÇÃO 1: DADOS DO CLIENTE (EDITÁVEL) */}
                    <motion.div 
                        layout
                        className="bg-neutral-900/50 border border-white/10 rounded-lg overflow-hidden relative"
                    >
                        {/* Barra de Título / Ações */}
                        <div className="flex items-center justify-between px-6 py-4 bg-white/5 border-b border-white/5">
                            <h3 className="text-sm font-medium text-white flex items-center gap-2">
                                <User size={14} className="text-brand-DEFAULT" />
                                Dados do Cliente
                            </h3>
                            {!isEditing ? (
                                <button 
                                    onClick={() => setIsEditing(true)}
                                    className="text-xs text-neutral-400 hover:text-white flex items-center gap-1 transition-colors px-2 py-1 rounded hover:bg-white/5"
                                >
                                    <Edit2 size={12} /> Editar
                                </button>
                            ) : (
                                <div className="flex gap-2">
                                    <button onClick={handleCancel} className="text-neutral-400 hover:text-white p-1"><X size={14}/></button>
                                    <button onClick={handleSave} className="text-brand-DEFAULT hover:text-white p-1"><Save size={14}/></button>
                                </div>
                            )}
                        </div>

                        <div className="p-6">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-8">
                                {/* NOME */}
                                <div className="space-y-1">
                                    <label className="text-[10px] text-neutral-500 uppercase tracking-widest">Nome / Empresa</label>
                                    {isEditing ? (
                                        <input 
                                            name="name" value={tempData.name} onChange={handleChange}
                                            className="w-full bg-transparent border-b border-brand-DEFAULT text-white py-1 focus:outline-none"
                                        />
                                    ) : (
                                        <p className="text-white font-medium">{clientData.name}</p>
                                    )}
                                </div>

                                {/* DATA */}
                                <div className="space-y-1">
                                    <label className="text-[10px] text-neutral-500 uppercase tracking-widest">Data do Evento</label>
                                    {isEditing ? (
                                        <input 
                                            name="date" type="date" value={tempData.date} onChange={handleChange}
                                            className="w-full bg-transparent border-b border-brand-DEFAULT text-white py-1 focus:outline-none [&::-webkit-calendar-picker-indicator]:invert"
                                        />
                                    ) : (
                                        <p className="text-white font-medium flex items-center gap-2">
                                            {formatDateSafe(clientData.date)}
                                        </p>
                                    )}
                                </div>

                                {/* LOCAL */}
                                <div className="space-y-1">
                                    <label className="text-[10px] text-neutral-500 uppercase tracking-widest">Localização</label>
                                    {isEditing ? (
                                        <input 
                                            name="location" value={tempData.location} onChange={handleChange}
                                            className="w-full bg-transparent border-b border-brand-DEFAULT text-white py-1 focus:outline-none"
                                        />
                                    ) : (
                                        <p className="text-white font-medium flex items-center gap-2">
                                            <MapPin size={12} className="text-neutral-500" />
                                            {clientData.location}
                                        </p>
                                    )}
                                </div>

                                {/* CONTATO */}
                                <div className="space-y-1">
                                    <label className="text-[10px] text-neutral-500 uppercase tracking-widest">Contato</label>
                                    {isEditing ? (
                                        <input 
                                            name="contact" value={tempData.contact} onChange={handleChange}
                                            className="w-full bg-transparent border-b border-brand-DEFAULT text-white py-1 focus:outline-none"
                                        />
                                    ) : (
                                        <p className="text-white font-medium flex items-center gap-2">
                                            <Phone size={12} className="text-neutral-500" />
                                            {clientData.contact}
                                        </p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </motion.div>

                    {/* SEÇÃO NOVA: RESUMO DO SERVIÇO */}
                    <motion.div 
                        layout
                        className="bg-neutral-900/50 border border-white/10 rounded-lg overflow-hidden"
                    >
                         <div className="flex items-center px-6 py-4 bg-white/5 border-b border-white/5">
                            <h3 className="text-sm font-medium text-white flex items-center gap-2">
                                <FileText size={14} className="text-brand-DEFAULT" />
                                Escopo do Projeto
                            </h3>
                         </div>
                         <div className="p-6 flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <p className="text-[10px] text-neutral-500 uppercase tracking-widest mb-1">{summaryDetails.categoryLabel}</p>
                                <h2 className="text-xl md:text-2xl font-serif text-white">{summaryDetails.serviceName}</h2>
                                <p className="text-brand-DEFAULT font-medium mt-1">{summaryDetails.metricLabel}</p>
                            </div>

                            {summaryDetails.addons.length > 0 && (
                                <div className="flex flex-wrap gap-2 md:justify-end">
                                    {summaryDetails.addons.map((addon, idx) => (
                                        <span key={idx} className="flex items-center gap-1.5 text-xs bg-white/5 border border-white/10 rounded-full px-3 py-1.5 text-neutral-300">
                                            <Check size={12} className="text-brand-DEFAULT" />
                                            {addon}
                                        </span>
                                    ))}
                                </div>
                            )}
                         </div>
                    </motion.div>

                    {/* SEÇÃO 2: DETALHES DO CONTRATO E PAGAMENTO */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {/* Termos Legais */}
                        <div className="bg-white/5 border border-white/10 rounded-lg p-5 flex items-start gap-4">
                            <div className="mt-1 text-neutral-400"><Copyright size={18} /></div>
                            <div>
                                <h4 className="text-sm font-medium text-white mb-1">Direitos de Imagem</h4>
                                <p className="text-xs text-neutral-500 leading-relaxed">
                                    Licenciamento incluso para uso comercial em redes sociais, website e tráfego pago por tempo indeterminado.
                                </p>
                            </div>
                        </div>

                         {/* SELEÇÃO DE PAGAMENTO */}
                         <div className="bg-white/5 border border-white/10 rounded-lg p-5">
                            <div className="flex items-center gap-2 mb-3 text-white">
                                <CreditCard size={18} className="text-neutral-400" />
                                <h4 className="text-sm font-medium">Forma de Pagamento</h4>
                            </div>

                            <div className="grid grid-cols-3 gap-2">
                                {/* PIX */}
                                <button 
                                    onClick={() => setPaymentMethod('Pix')}
                                    className={cn(
                                        "flex flex-col items-center justify-center p-2 rounded border text-xs transition-all",
                                        paymentMethod === 'Pix' 
                                            ? "bg-brand-DEFAULT/20 border-brand-DEFAULT text-white" 
                                            : "bg-black/20 border-white/5 text-neutral-500 hover:bg-white/5"
                                    )}
                                >
                                    <QrCode size={16} className="mb-1" />
                                    <span>Pix</span>
                                </button>

                                {/* Cartão (Com Acréscimo) */}
                                <button 
                                    onClick={() => setPaymentMethod('Cartão')}
                                    className={cn(
                                        "flex flex-col items-center justify-center p-2 rounded border text-xs transition-all",
                                        paymentMethod === 'Cartão' 
                                            ? "bg-brand-DEFAULT/20 border-brand-DEFAULT text-white" 
                                            : "bg-black/20 border-white/5 text-neutral-500 hover:bg-white/5"
                                    )}
                                >
                                    <CreditCard size={16} className="mb-1" />
                                    <span>Cartão</span>
                                </button>

                                {/* Espécie (Substituto do Boleto) */}
                                <button 
                                    onClick={() => setPaymentMethod('Espécie')}
                                    className={cn(
                                        "flex flex-col items-center justify-center p-2 rounded border text-xs transition-all",
                                        paymentMethod === 'Espécie' 
                                            ? "bg-brand-DEFAULT/20 border-brand-DEFAULT text-white" 
                                            : "bg-black/20 border-white/5 text-neutral-500 hover:bg-white/5"
                                    )}
                                >
                                    <Banknote size={16} className="mb-1" />
                                    <span>Espécie</span>
                                </button>
                            </div>

                            {/* Texto Dinâmico de Condições */}
                            <p className="text-[10px] text-neutral-500 mt-2 text-center">
                                {paymentMethod === 'Pix' && "Pagamento à vista."}
                                {paymentMethod === 'Cartão' && "Parcelamento em até 12x (com acréscimo)."}
                                {paymentMethod === 'Espécie' && "Pagamento no ato do contrato."}
                            </p>
                        </div>
                    </div>

                    {/* TOTAL FINAL & AÇÃO */}
                    <div className="mt-8 pt-8 border-t border-white/10 flex flex-col items-center">
                        <p className="text-xs uppercase tracking-widest text-neutral-500 mb-2">Valor Final do Investimento</p>
                        <div className="text-5xl font-serif text-white mb-8 flex items-baseline gap-2">
                            <AnimatedPrice value={totalPrice} />
                            <span className="text-lg text-neutral-600 font-sans">BRL</span>
                        </div>

                        <div className="flex gap-4 w-full md:w-auto">
                            <Button 
                                onClick={onBack}
                                variant="secondary"
                                className="flex-1 md:flex-none md:w-40 border-white/10 text-neutral-400 hover:text-white"
                            >
                                Ajustar Itens
                            </Button>
                            <Button 
                                onClick={onProceedToSign}
                                size="lg" 
                                className="flex-1 md:flex-none md:w-64 shadow-[0_0_30px_rgba(220,38,38,0.3)]"
                            >
                                <PenTool size={18} className="mr-2" />
                                Assinar Contrato
                            </Button>
                        </div>
                    </div>

                </div>

             </div>
        </motion.div>
      )}
    </div>
  );
};

