// Variantes para a sequência de entrada "Cinematográfica"
const introContainer: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.4, 
      delayChildren: 0.2
    }
  }
};

const logoVariant: Variants = {
  hidden: { 
    opacity: 0, 
    y: 180, 
    scale: 1.1 
  },
  visible: { 
    opacity: 1, 
    y: 0, 
    scale: 1,
    transition: { 
      duration: 1.5, 
