                                highlight
                            />
                        </div>
                    </motion.div>
                </div>
            )}

            {/* CATEGORIA: COMERCIAL */}
            {category === 'commercial' && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
                    <motion.div variants={fadeInUp}><ServiceCard 
                        active={serviceId === 'comm_photo'} onClick={() => handleServiceClick('comm_photo')}
