          <div className="flex justify-center mb-8">
            <motion.div 
                key="normal"
                initial={{ scale: 0 }} animate={{ scale: 1 }}
                className="p-4 bg-brand-DEFAULT/10 rounded-full text-brand-DEFAULT shadow-[0_0_20px_rgba(220,38,38,0.1)]"
