import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import QuoteView from './src/pages/QuoteView';
import WelcomeView from './src/pages/WelcomeView';
import IntroView from './src/pages/IntroView';
import Loading from './src/components/ui/Loading';
import Logo from './src/components/ui/Logo';
import { ClientData, QuoteData } from './src/types';
import { mockQuote } from './src/data/mock';
import { delay } from './src/lib/utils';

// Definição dos estados possíveis da aplicação
type ViewState = 'intro' | 'welcome' | 'quote';

const App: React.FC = () => {
  // --- GERENCIAMENTO DE ESTADO GLOBAL ---

  // Controla a Splash Screen Inicial
  const [showSplash, setShowSplash] = useState(true);

  // Controla qual "Página" está visível para o usuário
  const [view, setView] = useState<ViewState>('intro');

  // Armazena os dados do cliente capturados na WelcomeView
  const [clientData, setClientData] = useState<ClientData | null>(null);

  // Controla a exibição da tela de carregamento "cinematográfica"
  const [isLoading, setIsLoading] = useState(false);

  // Configuração global de preços e regras.
  // Como removemos o Admin, usamos apenas o mock inicial (read-only em tempo de execução).
  const [config] = useState<QuoteData>(mockQuote);

  // Efeito para remover a Splash Screen após alguns segundos
  useEffect(() => {
    // Garante que o scroll esteja no topo ao carregar
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
    window.scrollTo(0, 0);

    const timer = setTimeout(() => {
      setShowSplash(false);
    }, 3500); // 3.5 segundos para garantir visualização da animação
    return () => clearTimeout(timer);
  }, []);

  /**
   * Handler: Início do Processo
   */
  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    await delay(2000); 
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  return (
    <main className="w-full min-h-screen bg-neutral-950 text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans">

      {/* 
        SPLASH SCREEN (Abertura)
        Tela inicial com Logo e Texto "Orçamento Facilitado"
      */}
      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            transition={{ duration: 1.0, ease: "easeInOut" }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
             <div className="flex flex-col items-center justify-center w-full h-full p-4">
               <motion.div
                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 1.2, ease: "easeOut" }}
                 className="mb-8"
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 1.2, duration: 0.8 }}
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-400 font-serif italic text-xl md:text-2xl tracking-widest">Orçamento Facilitado</p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 
        AnimatePresence: Loading Overlay
      */}
      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      {/* RENDERIZAÇÃO CONDICIONAL DAS VIEWS */}
      {!showSplash && !isLoading && (
        <>
          {/* 1. View: Intro (Escolha de Caminho) */}
          {view === 'intro' && (
             <IntroView onContinue={() => setView('welcome')} />
          )}

          {/* 2. View: Welcome (Formulário de Dados) */}
          {view === 'welcome' && (
            <WelcomeView 
              onStart={handleStart} 
            />
          )}

          {/* 3. View: Quote (Configurador Principal) */}
          {view === 'quote' && clientData && (
            <QuoteView 
              clientData={clientData} 
              onUpdateClientData={setClientData}
              config={config} 
            />
          )}
        </>
      )}
    </main>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence, Variants } from 'framer-motion';
import { ArrowRight, Calendar, MapPin, User, Smartphone, CheckCircle2, Loader2, XCircle, AlertCircle, Map as MapIcon } from 'lucide-react';
import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button';
import LocationMapModal from '../components/ui/LocationMapModal';
import { ClientData } from '../types';
import { checkDateAvailability } from '../lib/calendar';

interface WelcomeViewProps {
  onStart: (data: ClientData) => void;
}

// Variantes para a sequência de entrada "Cinematográfica"
const introContainer: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.4, 
      delayChildren: 0.2
    }
  }
};

const logoVariant: Variants = {
  hidden: { 
    opacity: 0, 
    y: 180, 
    scale: 1.1 
  },
  visible: { 
    opacity: 1, 
    y: 0, 
    scale: 1,
    transition: { 
      duration: 1.5, 
      ease: [0.25, 0.1, 0.25, 1.0] 
    } 
  }
};

const formVariant: Variants = {
  hidden: { opacity: 0, y: 40 },
  visible: { 
    opacity: 1, 
    y: 0,
    transition: { duration: 1.0, ease: "easeOut" } 
  }
};

// Sub-componente SmartInput Melhorado
const SmartInput = ({ 
  icon: Icon, 
  name, 
  type = "text", 
  placeholder, 
  value, 
  onChange, 
  minLength = 3,
  className,
  externalStatus = null, // 'loading', 'valid', 'error', 'idle' ou null (para usar lógica interna)
  errorMessage = "",
  rightElement = null, // Elemento opcional na direita (ex: botão mapa)
  ...props // Permite passar outras props como 'min', 'max', etc.
}: any) => {
  const [internalStatus, setInternalStatus] = useState<'idle' | 'typing' | 'loading' | 'valid'>('idle');
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Se receber status externo, usa ele. Se não, usa lógica interna.
  const status = externalStatus || internalStatus;

  useEffect(() => {
    // Se houver status externo controlado pelo pai, ignoramos a lógica interna de validação simples
    if (externalStatus !== null) return;

    if (!value) {
      setInternalStatus('idle');
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      return;
    }

    setInternalStatus('typing');
    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    timeoutRef.current = setTimeout(() => {
      setInternalStatus('loading');

      setTimeout(() => {
        if (value.length >= minLength) {
          setInternalStatus('valid');
        } else {
          setInternalStatus('idle');
        }
      }, 800);

    }, 1000); 

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [value, minLength, externalStatus]);

  // Ajusta o padding-right se houver elemento extra
  const paddingRight = rightElement ? 'pr-20' : 'pr-8';

  return (
    <div className="group relative">
      <Icon className="absolute left-0 top-3 text-neutral-500 group-focus-within:text-brand-DEFAULT transition-colors" size={20} />
      <input 
        type={type} 
        name={name}
        required
        placeholder={placeholder}
        value={value}
        onChange={onChange}
        className={`w-full bg-transparent border-b border-white/20 py-3 pl-8 ${paddingRight} text-white focus:outline-none focus:border-brand-DEFAULT transition-colors placeholder:text-neutral-600 ${className} ${status === 'error' ? 'border-red-500/50 text-red-100' : ''}`}
        {...props}
      />

      {/* Elemento Opcional (Botão Mapa) */}
      {rightElement && (
          <div className="absolute right-0 top-1.5 z-20">
              {rightElement}
          </div>
      )}

      {/* Ícones de Status (Só aparecem se não houver elemento direito ocupando espaço ou se o status for crítico) */}
      <AnimatePresence mode="wait">
        {!rightElement && status === 'loading' && (
          <motion.div
            key="loader"
            initial={{ opacity: 0, scale: 0.5 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.5 }}
            className="absolute right-0 top-3 text-neutral-400"
          >
            <Loader2 size={18} className="animate-spin" />
          </motion.div>
        )}

        {!rightElement && status === 'valid' && (
          <motion.div
            key="success"
            initial={{ scale: 0, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0, opacity: 0 }}
            transition={{ type: "spring", stiffness: 400, damping: 15 }}
            className="absolute right-0 top-3 text-emerald-500 drop-shadow-[0_0_8px_rgba(16,185,129,0.5)]"
          >
            <CheckCircle2 size={20} />
          </motion.div>
        )}

        {status === 'error' && (
           <motion.div
             key="error"
             initial={{ scale: 0, opacity: 0 }}
             animate={{ scale: 1, opacity: 1 }}
             exit={{ scale: 0, opacity: 0 }}
             className={`absolute top-3 text-red-500 drop-shadow-[0_0_8px_rgba(220,38,38,0.5)] ${rightElement ? 'right-10' : 'right-0'}`}
           >
             <XCircle size={20} />
           </motion.div>
        )}
      </AnimatePresence>

      {/* Mensagem de Erro Abaixo do Input */}
      <AnimatePresence>
        {status === 'error' && errorMessage && (
            <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="overflow-hidden"
            >
                <p className="text-red-400 text-xs mt-1 flex items-center gap-1">
                    <AlertCircle size={10} /> {errorMessage}
                </p>
            </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

