                </div>
            )}

            {/* CATEGORIA: ESTÚDIO */}
            {category === 'studio' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-start">
                    <motion.div variants={fadeInUp}><ServiceCard 
