import React, { useRef, useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import SignatureCanvas from 'react-signature-canvas';
import { X, Loader2, ShieldCheck } from 'lucide-react';
import Button from '../ui/Button';
import { modalVariants } from '../../lib/animations';

interface SignatureModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (signatureData: string) => void;
  totalValue: string;
}

/**
 * Modal de Assinatura
 * -------------------
 * Permite que o cliente desenhe a assinatura.
 * IMPORTANTE: O Canvas precisa saber o tamanho exato do container para não distorcer.
 */
const SignatureModal: React.FC<SignatureModalProps> = ({ isOpen, onClose, onConfirm, totalValue }) => {
  const sigPad = useRef<SignatureCanvas>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [isEmpty, setIsEmpty] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Estado para controlar o tamanho do canvas dinamicamente
  const [canvasSize, setCanvasSize] = useState({ width: 0, height: 0 });

  // CORREÇÃO DE PROPORÇÃO & RESIZE:
  useEffect(() => {
    if (isOpen && containerRef.current) {
      const updateSize = () => {
        if (containerRef.current) {
          setCanvasSize({ 
            width: containerRef.current.offsetWidth, 
            height: containerRef.current.offsetHeight 
          }); 
        }
      };

      updateSize();
      const timer = setTimeout(updateSize, 100);

      window.addEventListener('resize', updateSize);
      return () => {
        window.removeEventListener('resize', updateSize);
        clearTimeout(timer);
      };
    }
  }, [isOpen]);

  const clear = () => {
    sigPad.current?.clear();
    setIsEmpty(true);
  };

  const handleEndDrawing = () => {
    if (sigPad.current && !sigPad.current.isEmpty()) {
      setIsEmpty(false);
    }
  };

  const handleConfirm = async () => {
    if (isEmpty || !sigPad.current) return;

    setIsSubmitting(true);
    // Simula envio para API
    await new Promise(r => setTimeout(r, 1500));

    // Pega a imagem em Base64
    const dataUrl = sigPad.current.toDataURL();
    onConfirm(dataUrl);
    setIsSubmitting(false);
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          {/* Fundo Escuro com BLUR INTENSO para desfocar o filme no background global */}
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-neutral-950/80 backdrop-blur-md"
            onClick={onClose}
          />

          {/* Janela do Modal */}
          <motion.div
            variants={modalVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            className="relative bg-neutral-900 border border-white/10 rounded-xl shadow-2xl w-full max-w-md overflow-hidden"
          >
            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-serif text-2xl text-white">Aprovar Proposta</h3>
                <button onClick={onClose} className="text-neutral-400 hover:text-white transition-colors">
                  <X size={24} />
                </button>
              </div>

              <div className="mb-6 space-y-2">
                <p className="text-sm text-neutral-400">Ao assinar, você concorda com o valor total de:</p>
                <p className="text-3xl text-white font-sans font-medium">{totalValue}</p>
              </div>

              {/* Aviso de Privacidade */}
              <div className="flex items-center gap-2 mb-2">
                <ShieldCheck size={14} className="text-green-500" />
                <p className="text-xs text-neutral-500 font-medium uppercase tracking-wide">
                    Não guardamos sua assinatura
                </p>
              </div>

              {/* Container do Canvas */}
              <div 
                ref={containerRef}
                className="relative rounded-lg bg-white/5 overflow-hidden mb-4 h-48 ring-1 ring-white/20"
              >
                {canvasSize.width > 0 && (
                  <SignatureCanvas 
                    ref={sigPad}
                    {...({ penColor: "white" } as any)}
                    canvasProps={{
                      width: canvasSize.width,
                      height: canvasSize.height,
                      className: "cursor-crosshair block"
                    }}
                    onEnd={handleEndDrawing}
                  />
                )}

                {!isEmpty && (
                  <button 
                    onClick={clear}
                    className="absolute top-2 right-2 text-xs text-neutral-400 hover:text-white bg-black/50 px-2 py-1 rounded z-10"
                  >
                    Limpar
                  </button>
                )}

                {isEmpty && (
                  <div className="absolute inset-0 pointer-events-none flex items-center justify-center text-white/10 select-none">
                    <span className="font-serif italic text-2xl">Assine aqui</span>
                  </div>
                )}
              </div>

              <div className="flex gap-3">
                <Button 
                  variant="secondary" 
                  className="flex-1"
                  onClick={onClose}
                >
                  Cancelar
                </Button>
                <Button 
                  variant="primary" 
                  className="flex-1"
                  disabled={isEmpty || isSubmitting}
                  onClick={handleConfirm}
                >
                  {isSubmitting ? (
                    <Loader2 className="animate-spin" size={20} />
                  ) : (
                    "Confirmar Contratação"
                  )}
                </Button>
              </div>
            </div>

            <div className="h-1 w-full bg-gradient-to-r from-neutral-900 via-brand-DEFAULT to-neutral-900" />
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

export default SignatureModal;

import React from 'react';
import { motion } from 'framer-motion';
import { CheckCircle, MessageCircle, ArrowDown } from 'lucide-react';
import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button';
import { fadeInUp, staggerContainer } from '../lib/animations';
import { ClientData, OccasionType, LocationType } from '../types';
import { formatCurrency } from '../lib/utils';

// Interface atualizada para receber os detalhes do orçamento
interface SuccessViewProps {
  onReset: () => void;
  clientData: ClientData;
  totalPrice: number;
  quoteDetails?: {
      occasion: OccasionType;
      customOccasionText?: string;
      location: LocationType;
      photoQty: number;
      videoQty: number;
      distance: number;
      paymentMethod?: string;
  };
}

/**
 * Componente: AnimatedClock
 * Renderiza um ícone SVG com ponteiros ancorados corretamente no centro.
 */
const AnimatedClock = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-yellow-500">
    <circle cx="12" cy="12" r="10" />

    {/* Ponteiro das Horas (Curto) */}
    {/* x1/y1 = Centro (12, 12). x2/y2 = Ponta (12, 6). Comprimento 6px */}
    <motion.line
      x1="12" y1="12" x2="12" y2="7"
      initial={{ rotate: 0 }}
      animate={{ rotate: 360 }}
      transition={{ duration: 12, repeat: Infinity, ease: "linear" }}
      // originX: 0.5 (centro horizontal da linha), originY: 1 (base da linha, que é o y1=12)
      style={{ originX: 0.5, originY: 1 }}
    />

    {/* Ponteiro dos Minutos (Longo) */}
    {/* x1/y1 = Centro (12, 12). x2/y2 = Ponta (12, 3). Comprimento 9px */}
    <motion.line
      x1="12" y1="12" x2="12" y2="3"
      initial={{ rotate: 0 }}
      animate={{ rotate: 360 }}
      transition={{ duration: 2, repeat: Infinity, ease: "linear" }}
      style={{ originX: 0.5, originY: 1 }}
    />
  </svg>
);

/**
 * SuccessView
 * -----------
 * Tela final exibida após a assinatura do contrato.
 * Confirma o envio e fornece um call-to-action para contato via WhatsApp.
 */
const SuccessView: React.FC<SuccessViewProps> = ({ onReset, clientData, totalPrice, quoteDetails }) => {

  const whatsappNumber = "5584981048857";

  // Construção da Mensagem Formatada
  let message = "";

  if (quoteDetails) {
      // 1. Definição do Escopo
      let escopo = "";
      if (quoteDetails.photoQty > 0 && quoteDetails.videoQty > 0) {
          escopo = `${quoteDetails.photoQty} Fotos + ${quoteDetails.videoQty} Vídeo(s)`;
      } else if (quoteDetails.photoQty > 0) {
          escopo = `${quoteDetails.photoQty} Fotos`;
      } else if (quoteDetails.videoQty > 0) {
          escopo = `${quoteDetails.videoQty} Vídeo(s)`;
      } else {
          escopo = "Cobertura por Hora/Diária";
      }

      // 2. Definição do Ambiente
      const ambiente = quoteDetails.location === 'studio' ? "Estúdio Controlado" : "Externo / In Loco";

      // 3. Logística
      const distanciaStr = `${quoteDetails.distance}km (Ida)`;
      const freteStr = quoteDetails.location === 'studio' ? "Grátis (Estúdio)" : "Incluso no total";

      // 4. Pagamento
      const pagamentoStr = quoteDetails.paymentMethod || "A combinar";

      // 5. Montagem do Texto
      message = `
*🔔 NOVA PROPOSTA APROVADA*

*👤 DADOS DO CLIENTE*
*Nome:* ${clientData.name}
*Local:* ${clientData.location}

*🎬 DETALHES DO SERVIÇO*

*Ocasião:* ${quoteDetails.customOccasionText}
*Ambiente:* ${ambiente}
*Escopo:* ${escopo}

*🚚 LOGÍSTICA*

*Distância:* ${distanciaStr}
*Frete:* ${freteStr}

*💰 FINANCEIRO*

*Valor Total:* ${formatCurrency(totalPrice)}
*Pagamento:* ${pagamentoStr}
*Status:* Aprovado no Sistema
──────────────
*🔗 PRÓXIMOS PASSOS*
Aguardando emissão do contrato.
`.trim();
  }

  const whatsappUrl = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;

  return (
    <div className="w-full min-h-screen flex flex-col items-center justify-center bg-neutral-950 relative overflow-hidden px-6">

      {/* Background Decorativo e Gradientes */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-neutral-900 via-neutral-950 to-black z-0" />
      <div className="absolute bottom-0 right-0 w-full h-1/2 bg-gradient-to-t from-brand-DEFAULT/10 to-transparent pointer-events-none" />

      <motion.div 
        variants={staggerContainer}
        initial="hidden"
        animate="visible"
        className="relative z-10 w-full max-w-md text-center"
      >
        {/* Logo EAREC - Reduzida */}
        <motion.div variants={fadeInUp} className="flex justify-center mb-8">
          <Logo className="w-40" />
        </motion.div>

        {/* Ícone de Sucesso Animado - Reduzido */}
        <motion.div variants={fadeInUp} className="mb-6 flex justify-center">
            <div className="relative">
                <div className="absolute inset-0 bg-green-500/20 blur-xl rounded-full" />
                <CheckCircle className="text-green-500 relative z-10" size={50} />
            </div>
        </motion.div>

        {/* Texto Alterado */}
        <motion.h1 variants={fadeInUp} className="text-2xl md:text-4xl font-serif text-white mb-2">
            Orçamento Completo!
        </motion.h1>

        {/* Call to Action Animado */}
        <motion.div variants={fadeInUp} className="mb-8">
             <motion.p 
                animate={{ y: [0, 5, 0] }}
                transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
                className="text-brand-DEFAULT font-medium text-sm flex items-center justify-center gap-2"
             >
                Enviar orçamento clicando no botão abaixo
                <ArrowDown size={14} />
             </motion.p>
        </motion.div>

        {/* Botões de Ação (Trocado de Posição: Agora vem PRIMEIRO) */}
        <motion.div variants={fadeInUp} className="space-y-3 px-4 mb-8">
            {/* Botão Principal: WhatsApp */}
            <a href={whatsappUrl} target="_blank" rel="noopener noreferrer" className="block w-full">
                <Button variant="primary" size="md" className="w-full flex items-center gap-2 justify-center bg-green-600 border-green-600 hover:bg-green-700 shadow-green-900/20 py-4 text-base font-bold tracking-wide">
                    <MessageCircle size={20} />
                    ENVIAR AGORA
                </Button>
            </a>

            {/* Botão Secundário: Reiniciar */}
            <Button onClick={onReset} size="md" variant="secondary" className="w-full py-3 text-sm border-transparent hover:bg-white/5 text-neutral-500 hover:text-white">
                Voltar ao Início
            </Button>
        </motion.div>

        {/* Card de Status do Pedido - Compacto (Trocado de Posição: Agora vem DEPOIS) */}
        <motion.div 
            variants={fadeInUp}
            className="bg-white/5 border border-white/10 rounded-lg p-4 flex items-center justify-between mx-4"
        >
            <div className="flex items-center gap-3">
                <div className="p-2 bg-yellow-500/10 rounded-full text-yellow-500">
                    <AnimatedClock />
                </div>
                <div className="text-left">
                    <p className="text-[10px] text-neutral-500 uppercase tracking-wider">Status</p>
                    <p className="text-white text-sm font-medium">Esperando sua mensagem!</p>
                </div>
            </div>
            {/* Bolinha pulsante */}
            <div className="h-1.5 w-1.5 rounded-full bg-yellow-500 animate-pulse" />
        </motion.div>

      </motion.div>
    </div>
  );
};

export default SuccessView;

import React from 'react';
import { motion } from 'framer-motion';

/**
 * Componente SVG: Tira de Filme (Film Strip)
 * Renderiza uma tira vertical infinita usando patterns SVG.
 */
const FilmStripTexture = ({ className }: { className?: string }) => (
  <svg
    viewBox="0 0 100 800"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    preserveAspectRatio="none"
  >
    {/* Fundo sutil da tira */}
    <rect x="15" width="70" height="800" fill="currentColor" fillOpacity="0.05" />

    {/* Bordas da área de imagem */}
    <line x1="18" y1="0" x2="18" y2="800" stroke="currentColor" strokeWidth="1" strokeOpacity="0.5" />
    <line x1="82" y1="0" x2="82" y2="800" stroke="currentColor" strokeWidth="1" strokeOpacity="0.5" />

    {/* Definição do Padrão de Furos (Sprockets) e Quadros */}
    <defs>
      <pattern id="film-holes" x="0" y="0" width="100" height="60" patternUnits="userSpaceOnUse">
         {/* Furos Esquerdos */}
         <rect x="2" y="15" width="12" height="20" rx="2" fill="currentColor" fillOpacity="0.4" />
         {/* Furos Direitos */}
         <rect x="86" y="15" width="12" height="20" rx="2" fill="currentColor" fillOpacity="0.4" />
         {/* Linha divisória de quadro (Frame Line) */}
         <line x1="18" y1="59" x2="82" y2="59" stroke="currentColor" strokeWidth="2" strokeOpacity="0.2" />
      </pattern>
    </defs>

    {/* Aplicação do padrão */}
    <rect width="100" height="800" fill="url(#film-holes)" />
  </svg>
);

