import React, { useEffect } from 'react';
import { motion, useSpring, useTransform } from 'framer-motion';

interface AnimatedNumberProps {
  value: number;
  className?: string;
}

/**
 * Componente que anima números inteiros.
 * Configurado para criar um efeito "decrescente" (do maior para o menor)
 * ao ser montado na tela, gerando impacto visual nos cards de quantidade.
 */
const AnimatedNumber: React.FC<AnimatedNumberProps> = ({ value, className }) => {
  // Inicializa o spring com um valor maior (value + 15) para criar o efeito de contagem decrescente/settling
  const spring = useSpring(value + 15, { mass: 0.8, stiffness: 75, damping: 15 });
  const display = useTransform(spring, (current) => Math.round(current));

  useEffect(() => {
    spring.set(value);
  }, [value, spring]);

  return <motion.span className={className}>{display}</motion.span>;
};

export default AnimatedNumber;

