// === DEFINIÇÕES DE TIPO DE DOMÍNIO (DDD) ===
// Este arquivo centraliza todas as interfaces que modelam o negócio.

// Tipos de Locação (Afetam o cálculo de frete)
export type LocationType = 'studio' | 'external';

// Tipos de Ocasião (Usados para categorização na mensagem final)
export type OccasionType = 'institutional' | 'advertising' | 'social' | 'wedding' | 'custom';

// Categorias principais de Serviço (Abas do Configurador)
export type ServiceCategory = 'wedding' | 'social' | 'commercial' | 'studio' | 'video_production' | 'custom';

// IDs únicos para cada "Produto" vendável no sistema
// Isso garante tipagem forte e evita erros de digitação ("magic strings") no código.
export type ServiceId = 
  | 'birthday' | 'fifteen' | 'graduation' 
  | 'wedding_base' | 'wedding_classic' | 'wedding_romance' | 'wedding_essence'
  | 'comm_photo' | 'comm_video' | 'comm_combo'
  | 'studio_photo' | 'studio_video'
  | 'edit_only' | 'cam_cap' | 'mobile_cap' | 'drone'
  | 'custom_project';

// Estado persistente da tela de Orçamento
export interface QuoteState {
  category: ServiceCategory;
  serviceId: ServiceId;
  hours: number;
  qty: number;
  addDrone: boolean;
  addRealTime: boolean;
}

// Estrutura de um item individual dentro de um orçamento
export interface ServiceItem {
  id: string;
  title: string;
  description: string;
  price: number;
  isIncluded?: boolean;
  type: 'fixed' | 'variable_photo' | 'variable_video';
}

// Dados do Cliente (Input do Formulário Inicial)
export interface ClientData {
  name: string;
  location: string;
  date: string;     // Formato ISO string (YYYY-MM-DD)
  contact: string;  // Telefone ou Email
  company?: string;
  projectTitle?: string;
}

// Objeto Mestre de Configuração do Orçamento
// Contém tanto os dados do cliente quanto as regras de preço globais.
export interface QuoteData {
  id: string;
  client: ClientData;
  date: string;
  validUntil: string;

  // Regras de Preço (Editáveis via Admin)
  basePrice: number;       // Custo de mobilização mínima
  studioFee: number;       // Taxa de uso do estúdio
  photoUnitPrice: number;  // Custo por foto extra
  videoUnitPrice: number;  // Custo por vídeo extra
  pricePerKm: number;      // Custo de combustível/desgaste por Km

  items: ServiceItem[];
  moodboardImages: string[];
}

// Props para componentes de UI
export interface CheckboxProps {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label?: string;
  price?: number;
}

import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import QuoteView from './src/pages/QuoteView';
import WelcomeView from './src/pages/WelcomeView';
import IntroView from './src/pages/IntroView';
import LandingView from './src/pages/LandingView';
import AdminDashboard from './src/pages/AdminDashboard';
import Loading from './src/components/ui/Loading';
import Logo from './src/components/ui/Logo';
import BackgroundFilmStrips from './src/components/ui/BackgroundFilmStrips';
import { ClientData, QuoteData, QuoteState } from './src/types';
import { mockQuote } from './src/data/mock';
import { delay } from './src/lib/utils';

// Definição dos estados possíveis da aplicação
type ViewState = 'landing' | 'intro' | 'welcome' | 'quote' | 'admin';

const App: React.FC = () => {
  // --- GERENCIAMENTO DE ESTADO GLOBAL ---

  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<ViewState>('landing');
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<QuoteData>(mockQuote);

  // PERSISTÊNCIA DE DADOS (Evitar perda ao recarregar)
  const [clientData, setClientData] = useState<ClientData | null>(() => {
    const saved = localStorage.getItem('earec_client_data');
    return saved ? JSON.parse(saved) : null;
  });

  // ESTADO ELEVADO DO ORÇAMENTO (Para manter seleções ao voltar)
  const [quoteState, setQuoteState] = useState<QuoteState>({
    category: 'wedding',
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    addDrone: false,
    addRealTime: false
  });

  // Salva no localStorage sempre que mudar
  useEffect(() => {
    if (clientData) {
      localStorage.setItem('earec_client_data', JSON.stringify(clientData));
    }
  }, [clientData]);

  useEffect(() => {
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
    window.scrollTo(0, 0);
    const timer = setTimeout(() => setShowSplash(false), 3500); 
    return () => clearTimeout(timer);
  }, []);

  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    await delay(2000); 
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  const handleAdminUpdate = (newConfig: QuoteData) => {
    setConfig(newConfig);
  };

  return (
    <main className="w-full min-h-screen bg-neutral-950 text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans relative">
      <BackgroundFilmStrips />

      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            transition={{ duration: 1.0, ease: "easeInOut" }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
             <div className="flex flex-col items-center justify-center w-full h-full p-4">
               <motion.div
                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 1.2, ease: "easeOut" }}
                 className="mb-8"
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 1.2, duration: 0.8 }}
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-400 font-serif italic text-xl md:text-2xl tracking-widest">Orçamento Facilitado</p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'landing' && (
                <LandingView onNext={() => setView('intro')} />
            )}

            {view === 'intro' && (
                <IntroView 
                    onContinue={() => setView('welcome')} 
                    onBack={() => setView('landing')} // Habilita botão voltar na Intro
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
                  onBack={() => setView('intro')} // Conecta o botão de voltar
                />
            )}

            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView('welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                />
            )}

            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={handleAdminUpdate}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

export default App;

