import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import QuoteView from './src/pages/QuoteView';
import WelcomeView from './src/pages/WelcomeView';
import IntroView from './src/pages/IntroView';
import LandingView from './src/pages/LandingView';
import AdminDashboard from './src/pages/AdminDashboard';
import Loading from './src/components/ui/Loading';
import Logo from './src/components/ui/Logo';
import BackgroundFilmStrips from './src/components/ui/BackgroundFilmStrips';
import { ClientData, QuoteData, QuoteState } from './src/types';
import { mockQuote } from './src/data/mock';
import { delay } from './src/lib/utils';

// Definição dos estados possíveis da aplicação
type ViewState = 'landing' | 'intro' | 'welcome' | 'quote' | 'admin';

const App: React.FC = () => {
  // --- GERENCIAMENTO DE ESTADO GLOBAL ---

  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<ViewState>('landing');
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<QuoteData>(mockQuote);

  // PERSISTÊNCIA DE DADOS (Evitar perda ao recarregar)
  const [clientData, setClientData] = useState<ClientData | null>(() => {
    const saved = localStorage.getItem('earec_client_data');
    return saved ? JSON.parse(saved) : null;
  });

  // ESTADO ELEVADO DO ORÇAMENTO (Para manter seleções ao voltar)
  const [quoteState, setQuoteState] = useState<QuoteState>({
    category: 'wedding',
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    addDrone: false,
    addRealTime: false
  });

  // Salva no localStorage sempre que mudar
  useEffect(() => {
    if (clientData) {
      localStorage.setItem('earec_client_data', JSON.stringify(clientData));
    }
  }, [clientData]);

  useEffect(() => {
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
    window.scrollTo(0, 0);
    const timer = setTimeout(() => setShowSplash(false), 3500); 
    return () => clearTimeout(timer);
  }, []);

  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    await delay(2000); 
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  const handleAdminUpdate = (newConfig: QuoteData) => {
    setConfig(newConfig);
  };

  return (
    <main className="w-full min-h-screen bg-black text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans relative">
      <BackgroundFilmStrips />

      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            transition={{ duration: 1.0, ease: "easeInOut" }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
             <div className="flex flex-col items-center justify-center w-full h-full p-4">
               <motion.div
                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 1.2, ease: "easeOut" }}
                 className="mb-8"
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 1.2, duration: 0.8 }}
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-400 font-serif italic text-xl md:text-2xl tracking-widest">Orçamento Facilitado</p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'landing' && (
                <LandingView onNext={() => setView('intro')} />
            )}

            {view === 'intro' && (
                <IntroView 
                    onContinue={() => setView('welcome')} 
                    onBack={() => setView('landing')} 
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
                  onBack={() => setView('intro')} 
                />
            )}

            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView('welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                />
            )}

            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={handleAdminUpdate}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

export default App;

import React from 'react';
import { motion } from 'framer-motion';

/**
 * Componente SVG: Tira de Filme (Film Strip)
 * Renderiza uma tira vertical infinita usando patterns SVG.
 */
const FilmStripTexture = ({ className }: { className?: string }) => (
  <svg
    viewBox="0 0 100 800"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    preserveAspectRatio="none"
  >
    {/* Fundo sutil da tira */}
    <rect x="15" width="70" height="800" fill="currentColor" fillOpacity="0.05" />

    {/* Bordas da área de imagem */}
    <line x1="18" y1="0" x2="18" y2="800" stroke="currentColor" strokeWidth="1" strokeOpacity="0.5" />
    <line x1="82" y1="0" x2="82" y2="800" stroke="currentColor" strokeWidth="1" strokeOpacity="0.5" />

    {/* Definição do Padrão de Furos (Sprockets) e Quadros */}
    <defs>
      <pattern id="film-holes" x="0" y="0" width="100" height="60" patternUnits="userSpaceOnUse">
         {/* Furos Esquerdos */}
         <rect x="2" y="15" width="12" height="20" rx="2" fill="currentColor" fillOpacity="0.4" />
         {/* Furos Direitos */}
         <rect x="86" y="15" width="12" height="20" rx="2" fill="currentColor" fillOpacity="0.4" />
         {/* Linha divisória de quadro (Frame Line) */}
         <line x1="18" y1="59" x2="82" y2="59" stroke="currentColor" strokeWidth="2" strokeOpacity="0.2" />
      </pattern>
    </defs>

    {/* Aplicação do padrão */}
    <rect width="100" height="800" fill="url(#film-holes)" />
  </svg>
);

const BackgroundFilmStrips: React.FC = () => {
  return (
    <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden h-screen w-screen">
      {/* 
        === FILME DE CÂMERA VERMELHO (GLOBAL) === 
        Opacidade ajustada para 0.3 (30%) para garantir visibilidade
        contra o fundo preto absoluto, sem ser intrusivo.
      */}

      {/* Tira Superior Direita */}
      <motion.div
        initial={{ opacity: 0, x: 100, rotate: -35 }}
        animate={{ 
            opacity: 1, 
            x: 0,
            y: [0, -20, 0] // Flutuação lenta
        }}
        transition={{ 
            opacity: { duration: 1.5 },
            y: { duration: 8, repeat: Infinity, ease: "easeInOut" }
        }}
        className="absolute -top-20 -right-20 md:right-0 w-32 md:w-48 h-[120vh] text-brand-DEFAULT opacity-30"
      >
         <FilmStripTexture className="w-full h-full drop-shadow-[0_0_15px_rgba(220,38,38,0.3)]" />
      </motion.div>

      {/* Tira Inferior Esquerda */}
      <motion.div
        initial={{ opacity: 0, x: -100, rotate: -35 }}
        animate={{ 
            opacity: 1, 
            x: 0,
            y: [0, 20, 0] // Flutuação lenta inversa
        }}
        transition={{ 
            opacity: { duration: 1.5 },
            y: { duration: 9, repeat: Infinity, ease: "easeInOut", delay: 1 }
        }}
        className="absolute -bottom-20 -left-20 md:left-0 w-32 md:w-48 h-[120vh] text-brand-DEFAULT opacity-30"
      >
         <FilmStripTexture className="w-full h-full drop-shadow-[0_0_15px_rgba(220,38,38,0.3)]" />
      </motion.div>

      {/* 
        Elemento de brilho central global
        Opacidade reduzida drasticamente (0.01-0.03) para não "lavar" o preto do fundo.
      */}
      <motion.div 
