      >
         {/* Speed 1.5s por frame = Rápido/Normal */}
         <FilmStripTexture className="w-full h-full drop-shadow-[0_0_15px_rgba(220,38,38,0.3)]" speed={1.5} direction={1} />
      </motion.div>

      {/* Tira Inferior Esquerda */}
      <motion.div
