                    </motion.div>
                ) : null}

                <h4 className={cn("font-serif text-lg leading-tight mb-2", active ? "text-white" : "text-neutral-300")}>{title}</h4>
                {desc && <p className="text-xs text-neutral-500 mb-3 max-w-[90%] mx-auto">{desc}</p>}
