      */}

      {/* Tira Superior Direita */}
      <motion.div
        initial={{ opacity: 0, x: 100, rotate: -35 }}
        animate={{ 
            opacity: 1, 
            x: 0,
            y: [0, -20, 0] // Flutuação lenta do container
        }}
        transition={{ 
            opacity: { duration: 1.5 },
            y: { duration: 8, repeat: Infinity, ease: "easeInOut" }
        }}
        className="absolute -top-20 -right-20 md:right-0 w-32 md:w-48 h-[120vh] text-brand-DEFAULT opacity-[0.15]"
      >
         {/* Speed 12s por frame = Muito Lento / Ambiente */}
         <FilmStripTexture className="w-full h-full drop-shadow-[0_0_15px_rgba(220,38,38,0.3)]" speed={12} direction={1} />
      </motion.div>

      {/* Tira Inferior Esquerda */}
      <motion.div
        initial={{ opacity: 0, x: -100, rotate: -35 }}
        animate={{ 
            opacity: 1, 
            x: 0,
            y: [0, 20, 0] // Flutuação lenta inversa
        }}
        transition={{ 
            opacity: { duration: 1.5 },
            y: { duration: 9, repeat: Infinity, ease: "easeInOut", delay: 1 }
        }}
        className="absolute -bottom-20 -left-20 md:left-0 w-32 md:w-48 h-[120vh] text-brand-DEFAULT opacity-[0.15]"
      >
         {/* Speed 15s por frame = Muito Lento. Direção oposta (-1) */}
         <FilmStripTexture className="w-full h-full drop-shadow-[0_0_15px_rgba(220,38,38,0.3)]" speed={15} direction={-1} />
      </motion.div>

      {/* CAMADA DE ESCURECIMENTO (30% OPACIDADE) */}
      <div className="absolute inset-0 bg-black/30 pointer-events-none" />
    </div>
  );
};

