        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {/* LandingView foi removida. O fluxo começa direto aqui: */}

            {view === 'intro' && (
                <IntroView 
                    onContinue={() => setView('welcome')} 
                    // onBack removido, pois esta é a tela principal agora
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
