const QuoteView: React.FC<QuoteViewProps> = ({ 
    clientData, onUpdateClientData, config, onBack, 
    quoteState, setQuoteState, onSuccess 
}) => {
  const [viewState, setViewState] = useState<ViewState>('config');

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

  const [showScrollIndicator, setShowScrollIndicator] = useState(true);

  useEffect(() => {
    return scrollYProgress.on('change', (latest) => {
      if (latest > 0.9) setShowScrollIndicator(false);
      else setShowScrollIndicator(true);
    });
  }, [scrollYProgress]);

  const [showFooter, setShowFooter] = useState(true);

  const quoteData: QuoteData = useMemo(() => ({
    ...config,
    client: { ...config.client, ...clientData, projectTitle: `Project: ${clientData.name}` }
  }), [clientData, config]);

  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');

  const [distance, setDistance] = useState<number>(0); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false); 
  const [isApproved, setIsApproved] = useState(false);

  const { category, serviceId, hours, qty, addDrone, addRealTime } = quoteState;

  const setCategory = (c: ServiceCategory) => setQuoteState(prev => ({ ...prev, category: c }));
  const setServiceId = (s: ServiceId) => setQuoteState(prev => ({ ...prev, serviceId: s }));
  const setHours = (h: number) => setQuoteState(prev => ({ ...prev, hours: h }));
  const setQty = (q: number) => setQuoteState(prev => ({ ...prev, qty: q }));
  const setAddDrone = (b: boolean) => setQuoteState(prev => ({ ...prev, addDrone: b }));
  const setAddRealTime = (b: boolean) => setQuoteState(prev => ({ ...prev, addRealTime: b }));

  useEffect(() => {
    let isMounted = true;
    const updateDistance = async () => {
        if (clientData.location) {
            const dist = await calculateDistance(clientData.location);
            if (isMounted) setDistance(dist);
        }
    };
    updateDistance();
    return () => { isMounted = false; };
  }, [clientData.location]);

  const handleUpdateLocation = (address: string) => {
      onUpdateClientData({ ...clientData, location: address });
  };

  const { totalPrice, priceBreakdown } = useMemo(() => {
    let total = 0;
    let breakdown: { label: string; value: number; type: 'base' | 'addon' | 'freight' }[] = [];

    if (category === 'wedding') {
        const s = PRICING_TABLE.wedding;
        let baseVal = 0;
        let baseLabel = "";

        switch (serviceId) {
            case 'wedding_base': baseVal = s.wedding_base.base; baseLabel = s.wedding_base.label; break;
            case 'wedding_classic': baseVal = s.wedding_classic.base; baseLabel = s.wedding_classic.label; break;
            case 'wedding_romance': baseVal = s.wedding_romance.base; baseLabel = s.wedding_romance.label; break;
            case 'wedding_essence': baseVal = s.wedding_essence.base; baseLabel = s.wedding_essence.label; break;
        }
        total += baseVal;
        breakdown.push({ label: baseLabel, value: baseVal, type: 'base' });
        if (addRealTime) {
            total += s.realtime.fixed;
            breakdown.push({ label: s.realtime.label, value: s.realtime.fixed, type: 'addon' });
        }
    }
    else if (category === 'social') {
        const s = PRICING_TABLE.social;
        if (serviceId === 'birthday' || serviceId === 'fifteen') {
            const ref = serviceId === 'birthday' ? s.birthday : s.fifteen;
            total += ref.base;
            breakdown.push({ label: `${ref.label} (2h)`, value: ref.base, type: 'base' });
            if (hours > ref.hoursIncluded) {
                const extraHoursVal = (hours - ref.hoursIncluded) * ref.hourPrice;
                total += extraHoursVal;
                breakdown.push({ label: `Horas Extras (+${hours - ref.hoursIncluded}h)`, value: extraHoursVal, type: 'addon' });
            }
        } else if (serviceId === 'graduation') {
             total += s.graduation.base;
             breakdown.push({ label: s.graduation.label, value: s.graduation.base, type: 'base' });
        }
        if (addRealTime) {
            total += s.realtime.fixed;
            breakdown.push({ label: s.realtime.label, value: s.realtime.fixed, type: 'addon' });
        }
    } 
    else if (category === 'commercial') {
        const s = PRICING_TABLE.commercial;
        if (serviceId === 'comm_photo') {
            const val = qty * s.photo.unit;
            total += val;
            breakdown.push({ label: `${s.photo.label} (${qty}x)`, value: val, type: 'base' });
        }
        if (serviceId === 'comm_video') {
            total += s.video.fixed;
            breakdown.push({ label: s.video.label, value: s.video.fixed, type: 'base' });
        }
        if (serviceId === 'comm_combo') {
            const val = s.combo.videoBase + (qty * s.combo.photoUnit);
            total += val;
            breakdown.push({ label: `${s.combo.label} (${qty} fotos)`, value: val, type: 'base' });
        }
    }
    else if (category === 'studio') {
        const s = PRICING_TABLE.studio;
        if (serviceId === 'studio_photo') {
            const val = qty * s.photo.unit;
            total += val;
            breakdown.push({ label: `${s.photo.label} (${qty}x)`, value: val, type: 'base' });
        }
        if (serviceId === 'studio_video') {
            total += s.video.base;
            breakdown.push({ label: `${s.video.label} (2h)`, value: s.video.base, type: 'base' });
             if (hours > s.video.hoursIncluded) {
                 const extraHoursVal = (hours - s.video.hoursIncluded) * s.video.hourPrice;
                 total += extraHoursVal;
                 breakdown.push({ label: `Horas Extras (+${hours - s.video.hoursIncluded}h)`, value: extraHoursVal, type: 'addon' });
             }
        }
    }
    else if (category === 'video_production') {
        const s = PRICING_TABLE.video_production;
        if (serviceId === 'edit_only') {
             const val = qty * s.edit.unit;
             total += val;
             breakdown.push({ label: `${s.edit.label} (${qty}x)`, value: val, type: 'base' });
        }
        if (serviceId === 'cam_cap') { total += s.cam_cap.fixed; breakdown.push({ label: s.cam_cap.label, value: s.cam_cap.fixed, type: 'base' }); }
        if (serviceId === 'mobile_cap') { total += s.mobile_cap.fixed; breakdown.push({ label: s.mobile_cap.label, value: s.mobile_cap.fixed, type: 'base' }); }
        if (serviceId === 'drone') { total += s.drone.fixed; breakdown.push({ label: s.drone.label, value: s.drone.fixed, type: 'base' }); }
    }
    else if (category === 'custom') {
        total += PRICING_TABLE.custom.custom_project.base;
        breakdown.push({ label: "Projeto Personalizado", value: 0, type: 'base' });
    }

    if (addDrone && category !== 'video_production' && category !== 'custom') { 
         const dronePrice = PRICING_TABLE.video_production.drone.fixed;
         total += dronePrice; 
         breakdown.push({ label: "Drone (Imagens Aéreas)", value: dronePrice, type: 'addon' });
    }

    const isExemptFromTravel = category === 'studio' || category === 'custom' || serviceId === 'edit_only';
    if (!isExemptFromTravel) {
        if (distance > 0) {
            const freight = (distance * 2 * quoteData.pricePerKm);
            total += freight;
            breakdown.push({ label: `Deslocamento (${distance}km)`, value: freight, type: 'freight' });
        } else {
             breakdown.push({ label: "Deslocamento", value: 0, type: 'freight' });
        }
    }
    return { totalPrice: total, priceBreakdown: breakdown };
  }, [category, serviceId, hours, qty, addDrone, addRealTime, distance, quoteData.pricePerKm]);

  useEffect(() => {
      const currentCategoryGroup = Object.keys(PRICING_TABLE[category as keyof typeof PRICING_TABLE]);
      const isIdValid = currentCategoryGroup.some(key => key === serviceId);
      if (!isIdValid) {
        if (category === 'wedding') setServiceId('wedding_base');
        if (category === 'social') setServiceId('birthday');
        if (category === 'commercial') setServiceId('comm_photo');
        if (category === 'studio') setServiceId('studio_photo');
        if (category === 'video_production') setServiceId('edit_only');
        if (category === 'custom') setServiceId('custom_project');
        setHours(2);
        if (category === 'video_production') setQty(1); else setQty(10);
      }
  }, [category]);

  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    setIsApproved(true);
    onSuccess();
    setViewState('success');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReset = () => { window.location.reload(); };

  const handleRemoveAddon = (addonName: string) => {
      const name = addonName.toLowerCase();
      if (name.includes('drone')) setAddDrone(false);
      if (name.includes('tempo real')) setAddRealTime(false);
  };

  let label = 'Serviço Personalizado';
  if (category === 'wedding') label = PRICING_TABLE.wedding[serviceId as keyof typeof PRICING_TABLE.wedding]?.label || label;
  if (category === 'social') label = PRICING_TABLE.social[serviceId as keyof typeof PRICING_TABLE.social]?.label || label;
  if (category === 'commercial') {
      if (serviceId === 'comm_combo') label = PRICING_TABLE.commercial.combo.label;
      else label = PRICING_TABLE.commercial[serviceId as keyof typeof PRICING_TABLE.commercial]?.label || label;
  }
  if (category === 'studio') label = PRICING_TABLE.studio[serviceId as keyof typeof PRICING_TABLE.studio]?.label || label;
  if (category === 'video_production') label = PRICING_TABLE.video_production[serviceId as keyof typeof PRICING_TABLE.video_production]?.label || label;

  let metricLabel = '';
  if (category === 'wedding') metricLabel = 'Pacote Completo';
  else if (category === 'social' && (serviceId === 'birthday' || serviceId === 'fifteen')) metricLabel = `${hours} Horas de Cobertura`;
  else if (category === 'commercial' && serviceId === 'comm_combo') metricLabel = `Vídeo + ${qty} Fotos`;
  else if (category === 'commercial' && serviceId === 'comm_photo') metricLabel = `${qty} Fotos`;
  else if (category === 'studio' && serviceId === 'studio_photo') metricLabel = `${qty} Fotos`;
  else if (category === 'studio' && serviceId === 'studio_video') metricLabel = `${hours} Horas de Gravação`;
  else if (category === 'video_production' && serviceId === 'edit_only') metricLabel = `${qty} Vídeos`;
  else if (category === 'custom') metricLabel = 'Sob medida';
  else metricLabel = 'Taxa Fixa / Diária';

  const activeAddons = [];
  if (addDrone && category !== 'video_production') activeAddons.push('Drone (Aéreo)');
  if (addRealTime) activeAddons.push('Fotos em Tempo Real');

  const summaryDetails = {
    serviceName: label,
    categoryLabel: category === 'wedding' ? 'Casamento' : category === 'social' ? 'Social' : category === 'commercial' ? 'Comercial' : category === 'studio' ? 'Estúdio' : 'Produção',
    metricLabel,
    addons: activeAddons
  };

  const quoteDetails = {
    occasion: category === 'custom' ? 'custom' : (category as any),
    customOccasionText: label,
    location: (category === 'studio' ? 'studio' : 'external'),
    photoQty: (category === 'studio' || (category === 'commercial' && serviceId === 'comm_photo') || (category === 'commercial' && serviceId === 'comm_combo')) ? qty : 0,
    videoQty: (category === 'video_production' && serviceId === 'edit_only') ? qty : 
              ((category === 'commercial' && (serviceId === 'comm_video' || serviceId === 'comm_combo'))) ? 1 : 0,
    distance,
    paymentMethod 
  };

  if (viewState === 'success') {
      return (
        <SuccessView 
            onReset={handleReset} 
            clientData={clientData}
            totalPrice={totalPrice}
            quoteDetails={quoteDetails as any}
        />
      );
  }

  return (
    <div className="relative">
      <div className="block pb-40">
          <motion.div
            className="fixed top-0 left-0 right-0 h-1 bg-brand-DEFAULT z-50 origin-left shadow-[0_0_15px_#DC2626]"
            style={{ scaleX }}
          />

          {/* 
              BOTÃO VOLTAR REVISADO: 
              Aparece apenas na fase de configuração. 
              Ao entrar no Resumo, o botão do próprio resumo assume o controle.
          */}
          <AnimatePresence>
              {viewState === 'config' && (
                  <motion.button 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -20 }}
                    onClick={onBack}
                    className="fixed top-6 left-6 z-[60] text-neutral-400 hover:text-white flex items-center gap-2 transition-colors text-sm uppercase tracking-wider bg-black/20 p-2 rounded-lg backdrop-blur-sm hover:bg-black/50 shadow-lg border border-white/5"
                    title="Voltar ao Cadastro"
                  >
                     <ArrowLeft size={18} /> Voltar
                  </motion.button>
              )}
          </AnimatePresence>

          <Hero data={quoteData} />

          <div className="relative z-10">
            <UpsellList 
              category={category} setCategory={setCategory}
              serviceId={serviceId} setServiceId={setServiceId}
              hours={hours} setHours={setHours}
              qty={qty} setQty={setQty}
              addDrone={addDrone} setAddDrone={setAddDrone}
              addRealTime={addRealTime} setAddRealTime={setAddRealTime}
              distance={distance}
              pricePerKm={quoteData.pricePerKm}
              locationClient={clientData.location}
              onOpenMap={() => setIsMapOpen(true)}
            />
          </div>

          <AnimatePresence>
            {showScrollIndicator && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed bottom-36 md:bottom-36 left-1/2 -translate-x-1/2 z-50 pointer-events-none text-white drop-shadow-md"
              >
                 <motion.div
                    animate={{ y: [0, 8, 0] }}
                    transition={{ duration: 1.5, repeat: Infinity, ease: "easeInOut" }}
                    className="flex flex-col items-center"
                 >
                    <ChevronsDown size={28} className="animate-pulse" />
                 </motion.div>
              </motion.div>
            )}
          </AnimatePresence>

          <AnimatePresence>
            {showFooter && (
                <StickyFooter 
                    totalPrice={totalPrice} 
                    onApprove={() => setViewState('summary')} 
                    isApproved={isApproved}
                    highlight={true} 
                />
            )}
          </AnimatePresence>
      </div>

      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={quoteData}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={summaryDetails}
                priceBreakdown={priceBreakdown}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
                onRemoveAddon={handleRemoveAddon}
            />
         )}
      </AnimatePresence>

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleUpdateLocation}
        initialAddress={clientData.location}
      />
    </div>
  );
};

export default QuoteView;

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Calendar, CheckCircle, Copyright, CreditCard, ArrowLeft, PenTool, MapPin, Settings2, User, Phone, Edit2, Save, X, Banknote, QrCode, FileText, Check, Map as MapIcon, RefreshCcw, Trash2 } from 'lucide-react';
import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button';
import AnimatedPrice from '../components/ui/AnimatedPrice';
import LocationMapModal from '../components/ui/LocationMapModal';
import { QuoteData, ClientData } from '../types';
import { cn, formatCurrency } from '../lib/utils';
import { fadeInUp, staggerContainer } from '../lib/animations';

interface SummaryDetails {
    serviceName: string;
    categoryLabel: string;
    metricLabel: string;
    addons: string[];
}

interface PriceItem {
    label: string;
    value: number;
    type: 'base' | 'addon' | 'freight';
}

interface SummaryViewProps {
  clientData: ClientData;
  onUpdateClientData: (data: ClientData) => void;
  quoteData: QuoteData;
  totalPrice: number;
  paymentMethod: string;
  setPaymentMethod: (method: string) => void;
  onBack: () => void;
  onProceedToSign: () => void;
  summaryDetails: SummaryDetails;
  priceBreakdown?: PriceItem[];
  onRemoveAddon?: (addonName: string) => void;
}

const SummaryView: React.FC<SummaryViewProps> = ({ 
  clientData, onUpdateClientData, quoteData, totalPrice, paymentMethod,
  setPaymentMethod, onBack, onProceedToSign, summaryDetails, priceBreakdown = [], onRemoveAddon
}) => {
  const [showContent, setShowContent] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false);
  const [tempData, setTempData] = useState<ClientData>(clientData);
  const today = new Date().toISOString().split('T')[0];

  useEffect(() => { setTempData(clientData); }, [clientData]);

  useEffect(() => {
    const timer = setTimeout(() => { setShowContent(true); }, 1500); 
    return () => clearTimeout(timer);
  }, []);

  const handleSave = () => { onUpdateClientData(tempData); setIsEditing(false); };
  const handleCancel = () => { setTempData(clientData); setIsEditing(false); };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;

    // LÓGICA DE CONTATO: Apenas Números e Limite de Caracteres
    if (name === 'contact') {
        const numericValue = value.replace(/\D/g, ''); // Remove tudo que não for dígito
        if (numericValue.length > 15) return; // Limite de caracteres
        setTempData(prev => ({ ...prev, [name]: numericValue }));
        return;
    }

    setTempData(prev => ({ ...prev, [name]: value }));
  };

  const handleLocationSelect = (address: string) => {
      setTempData(prev => ({ ...prev, location: address }));
  };

  const formatDateSafe = (dateString: string) => {
    if (!dateString) return 'A definir';
    try {
        const datePart = dateString.includes('T') ? dateString.split('T')[0] : dateString;
        const date = new Date(`${datePart}T12:00:00`);
        return date.toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
    } catch (e) { return dateString; }
  };

  const getInputDateValue = (dateString: string) => {
      if (!dateString) return '';
      return dateString.includes('T') ? dateString.split('T')[0] : dateString;
  };

  return (
    <div className="fixed inset-0 z-50 bg-neutral-950 overflow-y-auto">
      <AnimatePresence>
        {!showContent && (
          <motion.div
            key="intro-overlay"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, scale: 1.1, filter: 'blur(10px)' }}
            transition={{ duration: 0.8 }}
            className="absolute inset-0 flex items-center justify-center bg-black z-50"
          >
            <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ duration: 1 }}>
              <Logo className="w-64" animate />
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {showContent && (
        <motion.div
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="min-h-screen py-12 px-4 md:px-6 relative"
        >
             <div className="fixed top-0 left-0 w-full h-1/2 bg-gradient-to-b from-brand-DEFAULT/5 to-transparent pointer-events-none" />

             <motion.div className="max-w-3xl mx-auto relative z-10" variants={staggerContainer} initial="hidden" animate="visible">

                <motion.div variants={fadeInUp} className="flex items-center justify-between mb-8 border-b border-white/5 pb-4">
                    <button onClick={onBack} className="flex items-center gap-2 text-neutral-500 hover:text-white transition-colors group text-sm">
                        <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
                        VOLTAR
                    </button>
                    <div className="text-right">
                        <p className="text-xs text-neutral-500 uppercase tracking-widest">Resumo do Pedido</p>
                        <p className="text-white font-serif text-lg">{quoteData.id}</p>
                    </div>
                </motion.div>

                <div className="grid grid-cols-1 gap-6">

                    {/* DADOS DO CLIENTE */}
                    <motion.div variants={fadeInUp} layout className="bg-neutral-900/50 border border-white/10 rounded-lg overflow-hidden relative">
                        <div className="flex items-center justify-between px-6 py-4 bg-white/5 border-b border-white/5">
                            <h3 className="text-sm font-medium text-white flex items-center gap-2">
                                <User size={14} className="text-brand-DEFAULT" />
                                Dados do Cliente
                            </h3>
                            {!isEditing ? (
                                <button onClick={() => setIsEditing(true)} className="text-xs text-neutral-400 hover:text-white flex items-center gap-1 transition-colors px-2 py-1 rounded hover:bg-white/5">
                                    <Edit2 size={12} /> Editar
                                </button>
                            ) : (
                                <div className="flex gap-2">
                                    <button onClick={handleCancel} className="text-neutral-400 hover:text-white p-1"><X size={14}/></button>
                                    <button onClick={handleSave} className="text-brand-DEFAULT hover:text-white p-1"><Save size={14}/></button>
                                </div>
                            )}
                        </div>

                        <div className="p-6">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-8">
                                <div className="space-y-1">
                                    <label className="text-[10px] text-neutral-500 uppercase tracking-widest">Nome / Empresa</label>
                                    {isEditing ? (
                                        <input name="name" value={tempData.name} onChange={handleChange} className="w-full bg-transparent border-b border-brand-DEFAULT text-white py-1 focus:outline-none" />
                                    ) : ( <p className="text-white font-medium">{clientData.name}</p> )}
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[10px] text-neutral-500 uppercase tracking-widest">Data do Evento</label>
                                    {isEditing ? (
                                        <input name="date" type="date" min={today} value={getInputDateValue(tempData.date)} onChange={handleChange} className="w-full bg-transparent border-b border-brand-DEFAULT text-white py-1 focus:outline-none [&::-webkit-calendar-picker-indicator]:invert" />
                                    ) : ( <p className="text-white font-medium">{formatDateSafe(clientData.date)}</p> )}
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[10px] text-neutral-500 uppercase tracking-widest">Local do Serviço</label>
                                    {isEditing ? (
                                        <div className="relative">
                                            <input name="location" value={tempData.location} onChange={handleChange} className="w-full bg-transparent border-b border-brand-DEFAULT text-white py-1 pr-10 focus:outline-none" />
                                            <button onClick={() => setIsMapOpen(true)} className="absolute right-0 top-0 text-neutral-400 hover:text-brand-DEFAULT p-1" title="Abrir Mapa"><MapIcon size={16} /></button>
                                        </div>
                                    ) : ( <p className="text-white font-medium flex items-center gap-2"><MapPin size={12} className="text-neutral-500" />{clientData.location}</p> )}
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[10px] text-neutral-500 uppercase tracking-widest">Contato</label>
                                    {isEditing ? (
                                        <input 
                                            name="contact" 
                                            type="tel"
                                            value={tempData.contact} 
                                            onChange={handleChange} 
                                            placeholder="Apenas números"
                                            className="w-full bg-transparent border-b border-brand-DEFAULT text-white py-1 focus:outline-none" 
                                        />
                                    ) : ( <p className="text-white font-medium flex items-center gap-2"><Phone size={12} className="text-neutral-500" />{clientData.contact}</p> )}
                                </div>
                            </div>
                        </div>
                    </motion.div>

                    {/* ESCOPO DO PROJETO DETALHADO */}
                    <motion.div variants={fadeInUp} layout className="bg-neutral-900/50 border border-white/10 rounded-lg overflow-hidden flex flex-col">
                         <div className="flex items-center justify-between px-6 py-4 bg-white/5 border-b border-white/5">
                            <h3 className="text-sm font-medium text-white flex items-center gap-2">
                                <FileText size={14} className="text-brand-DEFAULT" />
                                Escopo Financeiro
                            </h3>
                            <button onClick={onBack} className="text-xs text-neutral-400 hover:text-white flex items-center gap-1 transition-colors px-2 py-1 rounded hover:bg-white/5">
                                <RefreshCcw size={12} /> Alterar Itens
                            </button>
                         </div>

                         <div className="p-6 flex-1 flex flex-col">
                            {/* Categoria */}
                            <p className="text-[10px] text-neutral-500 uppercase tracking-widest mb-4">
                                {summaryDetails.categoryLabel}
                            </p>

                            {/* Lista de Itens com Preços */}
                            <div className="space-y-3 mb-6">
                                {priceBreakdown.map((item, idx) => (
                                    <div 
                                        key={idx} 
                                        className={cn(
                                            "flex justify-between items-center text-sm py-1 border-b border-white/5 px-2 -mx-2 rounded transition-colors group",
                                            item.type === 'freight' ? "text-neutral-400 italic cursor-default" : "text-neutral-200",
                                            item.type === 'addon' ? "hover:bg-white/5 cursor-pointer" : ""
                                        )}
                                        onDoubleClick={() => {
                                            // FIX: Permite remoção apenas para itens adicionais (addons), não deslocamento ou base.
                                            if (item.type === 'addon' && onRemoveAddon) {
                                                onRemoveAddon(item.label);
                                            }
                                        }}
                                        title={item.type === 'addon' ? "Duplo clique para remover" : ""}
                                    >
                                        <div className="flex items-center gap-2">
                                            <span>{item.label}</span>
                                            {item.type === 'addon' && <Trash2 size={12} className="text-red-500 opacity-0 group-hover:opacity-100 transition-opacity" />}
                                        </div>
                                        <div className="flex items-center gap-1">
                                            {item.value === 0 ? (
                                                <span className="text-green-500 text-xs uppercase font-medium">Incluso</span>
                                            ) : (
                                                <span className="font-mono">{formatCurrency(item.value)}</span>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="mt-auto pt-4 border-t border-white/10">
                                <div className="flex justify-between items-end">
                                    <div className="text-left">
                                         <p className="text-[10px] text-neutral-500 uppercase tracking-widest mb-1">Total Final</p>
                                         <p className="text-2xl text-white font-serif"><AnimatedPrice value={totalPrice} /></p>
                                    </div>
                                    {/* FIX: Mostra a dica apenas se houver addons removíveis na lista */}
                                    {priceBreakdown.some(i => i.type === 'addon') && (
                                        <p className="text-[9px] text-neutral-600 italic max-w-[150px] text-right">
                                            Dica: Clique duas vezes em um item adicional para removê-lo.
                                        </p>
                                    )}
                                </div>
                            </div>
                         </div>
                    </motion.div>

                    {/* CONTRATO E PAGAMENTO */}
                    <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="bg-white/5 border border-white/10 rounded-lg p-5 flex items-start gap-4 h-full">
                            <div className="mt-1 text-neutral-400"><Copyright size={18} /></div>
                            <div>
                                <h4 className="text-sm font-medium text-white mb-1">Condições de Pagamento</h4>
                                <p className="text-xs text-neutral-500 leading-relaxed">
                                    Entrada de 50% na assinatura do contrato para reserva da data e 50% na entrega do material final.
                                </p>
                            </div>
                        </div>

                         <div className="bg-white/5 border border-white/10 rounded-lg p-5 h-full">
                            <div className="flex items-center gap-2 mb-3 text-white">
                                <CreditCard size={18} className="text-neutral-400" />
                                <h4 className="text-sm font-medium">Forma de Pagamento</h4>
                            </div>
                            <div className="grid grid-cols-3 gap-2">
                                {['Pix', 'Cartão', 'Espécie'].map((method) => (
                                    <button 
                                        key={method}
                                        onClick={() => setPaymentMethod(method)}
                                        className={cn(
                                            "flex flex-col items-center justify-center p-2 rounded border text-xs transition-all",
                                            paymentMethod === method 
                                                ? "bg-brand-DEFAULT/20 border-brand-DEFAULT text-white" 
                                                : "bg-black/20 border-white/5 text-neutral-500 hover:bg-white/5"
                                        )}
                                    >
                                        {method === 'Pix' && <QrCode size={16} className="mb-1" />}
                                        {method === 'Cartão' && <CreditCard size={16} className="mb-1" />}
                                        {method === 'Espécie' && <Banknote size={16} className="mb-1" />}
                                        <span>{method}</span>
                                    </button>
                                ))}
                            </div>
                            <p className="text-[10px] text-neutral-500 mt-2 text-center">
                                {paymentMethod === 'Pix' && "Pagamento à vista."}
                                {paymentMethod === 'Cartão' && "Parcelamento em até 12x (com acréscimo)."}
                                {paymentMethod === 'Espécie' && "Pagamento no ato do contrato."}
                            </p>
                        </div>
                    </motion.div>

                    {/* TOTAL FINAL */}
                    <motion.div variants={fadeInUp} className="mt-8 pt-8 border-t border-white/10 flex flex-col items-center">
                        <Button 
                            onClick={onProceedToSign}
                            size="lg" 
                            className="w-full md:w-auto md:min-w-[300px] shadow-[0_0_30px_rgba(220,38,38,0.3)] py-4 text-lg"
                        >
                            <PenTool size={20} className="mr-2" />
                            Confirmar Orçamento
                        </Button>
                    </motion.div>

                </div>
             </motion.div>
        </motion.div>
      )}

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleLocationSelect}
        initialAddress={tempData.location}
      />
    </div>
  );
};

export default SummaryView;

import React, { useState, useMemo, useEffect } from 'react';
import Hero from '../components/quote/Hero';
import UpsellList from '../components/quote/UpsellList';
import StickyFooter from '../components/quote/StickyFooter';
import SignatureModal from '../components/quote/SignatureModal';
import LocationMapModal from '../components/ui/LocationMapModal';
import SummaryView from './SummaryView';
import SuccessView from './SuccessView';
import { formatCurrency } from '../lib/utils';
import { calculateDistance } from '../lib/maps';
import { motion, useScroll, useSpring, AnimatePresence } from 'framer-motion';
import { ClientData, QuoteData, ServiceCategory, ServiceId, QuoteState } from '../types';
import { ChevronDown, ChevronsDown, ArrowLeft } from 'lucide-react';

interface QuoteViewProps {
  clientData: ClientData; 
  onUpdateClientData: (data: ClientData) => void; 
  config: QuoteData;      
  onBack: () => void;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  onSuccess: () => void; 
}

type ViewState = 'config' | 'summary' | 'success';

const PRICING_TABLE = {
    wedding: {
        wedding_base: { base: 650, label: "Casamento (Base)" },
        wedding_classic: { base: 900, label: "Pacote Clássico" },
        wedding_romance: { base: 1150, label: "Pacote Romance" },
        wedding_essence: { base: 1750, label: "Pacote Essência" },
        realtime: { fixed: 600, label: "Fotos em Tempo Real" }
    },
    social: {
        birthday: { base: 400, hoursIncluded: 2, hourPrice: 250, label: "Chá Revelação / Aniversário" },
        fifteen: { base: 450, hoursIncluded: 2, hourPrice: 250, label: "15 Anos" }, 
        graduation: { base: 800, label: "Formatura" },
        realtime: { fixed: 600, label: "Fotos em Tempo Real" }
    },
    commercial: {
        photo: { unit: 20, label: "Comércio (Fotos)" },
        video: { fixed: 500, label: "Comércio (Vídeo)" },
        combo: { videoBase: 500, photoUnit: 20, label: "Comércio (Foto + Vídeo)" }
    },
    studio: {
        photo: { unit: 25, label: "Estúdio (Fotos)" },
        video: { base: 350, hoursIncluded: 2, hourPrice: 250, label: "Estúdio (Vídeo)" },
    },
    video_production: {
        edit: { unit: 250, label: "Apenas Edição" },
        cam_cap: { fixed: 350, label: "Captação Câmera" },
        mobile_cap: { fixed: 250, label: "Captação Celular" },
        drone: { fixed: 250, label: "Drone (Imagens Aéreas)" }
    },
    custom: {
        custom_project: { base: 0, label: "Projeto Personalizado" } 
    }
};

const QuoteView: React.FC<QuoteViewProps> = ({ 
    clientData, onUpdateClientData, config, onBack, 
    quoteState, setQuoteState, onSuccess 
}) => {
  const [viewState, setViewState] = useState<ViewState>('config');

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

  const [showScrollIndicator, setShowScrollIndicator] = useState(true);

  useEffect(() => {
    return scrollYProgress.on('change', (latest) => {
      if (latest > 0.9) setShowScrollIndicator(false);
      else setShowScrollIndicator(true);
    });
  }, [scrollYProgress]);

  const [showFooter, setShowFooter] = useState(true);

  const quoteData: QuoteData = useMemo(() => ({
    ...config,
    client: { ...config.client, ...clientData, projectTitle: `Project: ${clientData.name}` }
  }), [clientData, config]);

  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');

  const [distance, setDistance] = useState<number>(0); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false); 
  const [isApproved, setIsApproved] = useState(false);

  const { category, serviceId, hours, qty, addDrone, addRealTime } = quoteState;

  const setCategory = (c: ServiceCategory) => setQuoteState(prev => ({ ...prev, category: c }));
  const setServiceId = (s: ServiceId) => setQuoteState(prev => ({ ...prev, serviceId: s }));
  const setHours = (h: number) => setQuoteState(prev => ({ ...prev, hours: h }));
  const setQty = (q: number) => setQuoteState(prev => ({ ...prev, qty: q }));
  const setAddDrone = (b: boolean) => setQuoteState(prev => ({ ...prev, addDrone: b }));
  const setAddRealTime = (b: boolean) => setQuoteState(prev => ({ ...prev, addRealTime: b }));

  useEffect(() => {
    let isMounted = true;
    const updateDistance = async () => {
        if (clientData.location) {
            const dist = await calculateDistance(clientData.location);
            if (isMounted) setDistance(dist);
        }
    };
    updateDistance();
    return () => { isMounted = false; };
  }, [clientData.location]);

  const handleUpdateLocation = (address: string) => {
      onUpdateClientData({ ...clientData, location: address });
  };

  const { totalPrice, priceBreakdown } = useMemo(() => {
    let total = 0;
    let breakdown: { label: string; value: number; type: 'base' | 'addon' | 'freight' }[] = [];

    if (category === 'wedding') {
        const s = PRICING_TABLE.wedding;
        let baseVal = 0;
        let baseLabel = "";

        switch (serviceId) {
            case 'wedding_base': baseVal = s.wedding_base.base; baseLabel = s.wedding_base.label; break;
            case 'wedding_classic': baseVal = s.wedding_classic.base; baseLabel = s.wedding_classic.label; break;
            case 'wedding_romance': baseVal = s.wedding_romance.base; baseLabel = s.wedding_romance.label; break;
            case 'wedding_essence': baseVal = s.wedding_essence.base; baseLabel = s.wedding_essence.label; break;
        }
        total += baseVal;
        breakdown.push({ label: baseLabel, value: baseVal, type: 'base' });
        if (addRealTime) {
            total += s.realtime.fixed;
            breakdown.push({ label: s.realtime.label, value: s.realtime.fixed, type: 'addon' });
        }
    }
    else if (category === 'social') {
        const s = PRICING_TABLE.social;
        if (serviceId === 'birthday' || serviceId === 'fifteen') {
            const ref = serviceId === 'birthday' ? s.birthday : s.fifteen;
            total += ref.base;
            breakdown.push({ label: `${ref.label} (2h)`, value: ref.base, type: 'base' });
            if (hours > ref.hoursIncluded) {
                const extraHoursVal = (hours - ref.hoursIncluded) * ref.hourPrice;
                total += extraHoursVal;
                breakdown.push({ label: `Horas Extras (+${hours - ref.hoursIncluded}h)`, value: extraHoursVal, type: 'addon' });
            }
        } else if (serviceId === 'graduation') {
             total += s.graduation.base;
             breakdown.push({ label: s.graduation.label, value: s.graduation.base, type: 'base' });
        }
        if (addRealTime) {
            total += s.realtime.fixed;
            breakdown.push({ label: s.realtime.label, value: s.realtime.fixed, type: 'addon' });
        }
    } 
    else if (category === 'commercial') {
        const s = PRICING_TABLE.commercial;
        if (serviceId === 'comm_photo') {
            const val = qty * s.photo.unit;
            total += val;
            breakdown.push({ label: `${s.photo.label} (${qty}x)`, value: val, type: 'base' });
        }
        if (serviceId === 'comm_video') {
            total += s.video.fixed;
            breakdown.push({ label: s.video.label, value: s.video.fixed, type: 'base' });
        }
        if (serviceId === 'comm_combo') {
            const val = s.combo.videoBase + (qty * s.combo.photoUnit);
            total += val;
            breakdown.push({ label: `${s.combo.label} (${qty} fotos)`, value: val, type: 'base' });
        }
    }
    else if (category === 'studio') {
        const s = PRICING_TABLE.studio;
        if (serviceId === 'studio_photo') {
            const val = qty * s.photo.unit;
            total += val;
            breakdown.push({ label: `${s.photo.label} (${qty}x)`, value: val, type: 'base' });
        }
        if (serviceId === 'studio_video') {
            total += s.video.base;
            breakdown.push({ label: `${s.video.label} (2h)`, value: s.video.base, type: 'base' });
             if (hours > s.video.hoursIncluded) {
                 const extraHoursVal = (hours - s.video.hoursIncluded) * s.video.hourPrice;
                 total += extraHoursVal;
                 breakdown.push({ label: `Horas Extras (+${hours - s.video.hoursIncluded}h)`, value: extraHoursVal, type: 'addon' });
             }
        }
    }
    else if (category === 'video_production') {
        const s = PRICING_TABLE.video_production;
        if (serviceId === 'edit_only') {
             const val = qty * s.edit.unit;
             total += val;
             breakdown.push({ label: `${s.edit.label} (${qty}x)`, value: val, type: 'base' });
        }
        if (serviceId === 'cam_cap') { total += s.cam_cap.fixed; breakdown.push({ label: s.cam_cap.label, value: s.cam_cap.fixed, type: 'base' }); }
        if (serviceId === 'mobile_cap') { total += s.mobile_cap.fixed; breakdown.push({ label: s.mobile_cap.label, value: s.mobile_cap.fixed, type: 'base' }); }
        if (serviceId === 'drone') { total += s.drone.fixed; breakdown.push({ label: s.drone.label, value: s.drone.fixed, type: 'base' }); }
    }
    else if (category === 'custom') {
        total += PRICING_TABLE.custom.custom_project.base;
        breakdown.push({ label: "Projeto Personalizado", value: 0, type: 'base' });
    }

    if (addDrone && category !== 'video_production' && category !== 'custom') { 
         const dronePrice = PRICING_TABLE.video_production.drone.fixed;
         total += dronePrice; 
         breakdown.push({ label: "Drone (Imagens Aéreas)", value: dronePrice, type: 'addon' });
    }

    const isExemptFromTravel = category === 'studio' || category === 'custom' || serviceId === 'edit_only';
    if (!isExemptFromTravel) {
        if (distance > 0) {
            const freight = (distance * 2 * quoteData.pricePerKm);
            total += freight;
            breakdown.push({ label: `Deslocamento (${distance}km)`, value: freight, type: 'freight' });
        } else {
             breakdown.push({ label: "Deslocamento", value: 0, type: 'freight' });
        }
    }
    return { totalPrice: total, priceBreakdown: breakdown };
  }, [category, serviceId, hours, qty, addDrone, addRealTime, distance, quoteData.pricePerKm]);

  useEffect(() => {
      const currentCategoryGroup = Object.keys(PRICING_TABLE[category as keyof typeof PRICING_TABLE]);
      const isIdValid = currentCategoryGroup.some(key => key === serviceId);
      if (!isIdValid) {
        if (category === 'wedding') setServiceId('wedding_base');
        if (category === 'social') setServiceId('birthday');
        if (category === 'commercial') setServiceId('comm_photo');
        if (category === 'studio') setServiceId('studio_photo');
        if (category === 'video_production') setServiceId('edit_only');
        if (category === 'custom') setServiceId('custom_project');
        setHours(2);
        if (category === 'video_production') setQty(1); else setQty(10);
      }
  }, [category]);

  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    setIsApproved(true);
    onSuccess();
    setViewState('success');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReset = () => { window.location.reload(); };

  // FIX: Função de remoção aprimorada para permitir o reset de Horas Extras e remoção de Drone/Tempo Real.
  // Deslocamento (freight) não é removido aqui para cumprir a regra de segurança.
  const handleRemoveAddon = (addonName: string) => {
      const name = addonName.toLowerCase();
      if (name.includes('drone')) setAddDrone(false);
      if (name.includes('tempo real')) setAddRealTime(false);
      if (name.includes('horas extras')) setHours(2); // Reseta para a carga horária base incluída (2h)
  };

  let label = 'Serviço Personalizado';
  if (category === 'wedding') label = PRICING_TABLE.wedding[serviceId as keyof typeof PRICING_TABLE.wedding]?.label || label;
  if (category === 'social') label = PRICING_TABLE.social[serviceId as keyof typeof PRICING_TABLE.social]?.label || label;
  if (category === 'commercial') {
      if (serviceId === 'comm_combo') label = PRICING_TABLE.commercial.combo.label;
      else label = PRICING_TABLE.commercial[serviceId as keyof typeof PRICING_TABLE.commercial]?.label || label;
  }
  if (category === 'studio') label = PRICING_TABLE.studio[serviceId as keyof typeof PRICING_TABLE.studio]?.label || label;
  if (category === 'video_production') label = PRICING_TABLE.video_production[serviceId as keyof typeof PRICING_TABLE.video_production]?.label || label;

  let metricLabel = '';
  if (category === 'wedding') metricLabel = 'Pacote Completo';
  else if (category === 'social' && (serviceId === 'birthday' || serviceId === 'fifteen')) metricLabel = `${hours} Horas de Cobertura`;
  else if (category === 'commercial' && serviceId === 'comm_combo') metricLabel = `Vídeo + ${qty} Fotos`;
  else if (category === 'commercial' && serviceId === 'comm_photo') metricLabel = `${qty} Fotos`;
  else if (category === 'studio' && serviceId === 'studio_photo') metricLabel = `${qty} Fotos`;
  else if (category === 'studio' && serviceId === 'studio_video') metricLabel = `${hours} Horas de Gravação`;
  else if (category === 'video_production' && serviceId === 'edit_only') metricLabel = `${qty} Vídeos`;
  else if (category === 'custom') metricLabel = 'Sob medida';
  else metricLabel = 'Taxa Fixa / Diária';

  const activeAddons = [];
  if (addDrone && category !== 'video_production') activeAddons.push('Drone (Aéreo)');
  if (addRealTime) activeAddons.push('Fotos em Tempo Real');

  const summaryDetails = {
    serviceName: label,
    categoryLabel: category === 'wedding' ? 'Casamento' : category === 'social' ? 'Social' : category === 'commercial' ? 'Comercial' : category === 'studio' ? 'Estúdio' : 'Produção',
    metricLabel,
    addons: activeAddons
  };

  const quoteDetails = {
    occasion: category === 'custom' ? 'custom' : (category as any),
    customOccasionText: label,
    location: (category === 'studio' ? 'studio' : 'external'),
    photoQty: (category === 'studio' || (category === 'commercial' && serviceId === 'comm_photo') || (category === 'commercial' && serviceId === 'comm_combo')) ? qty : 0,
    videoQty: (category === 'video_production' && serviceId === 'edit_only') ? qty : 
              ((category === 'commercial' && (serviceId === 'comm_video' || serviceId === 'comm_combo'))) ? 1 : 0,
    distance,
    paymentMethod 
  };

  if (viewState === 'success') {
      return (
        <SuccessView 
            onReset={handleReset} 
            clientData={clientData}
            totalPrice={totalPrice}
            quoteDetails={quoteDetails as any}
        />
      );
  }

  return (
    <div className="relative">
      <div className="block pb-40">
          <motion.div
            className="fixed top-0 left-0 right-0 h-1 bg-brand-DEFAULT z-50 origin-left shadow-[0_0_15px_#DC2626]"
            style={{ scaleX }}
          />

          <AnimatePresence>
              {viewState === 'config' && (
                  <motion.button 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -20 }}
                    onClick={onBack}
                    className="fixed top-6 left-6 z-[60] text-neutral-400 hover:text-white flex items-center gap-2 transition-colors text-sm uppercase tracking-wider bg-black/20 p-2 rounded-lg backdrop-blur-sm hover:bg-black/50 shadow-lg border border-white/5"
                    title="Voltar ao Cadastro"
                  >
                     <ArrowLeft size={18} /> Voltar
                  </motion.button>
              )}
          </AnimatePresence>

          <Hero data={quoteData} />

          <div className="relative z-10">
            <UpsellList 
              category={category} setCategory={setCategory}
              serviceId={serviceId} setServiceId={setServiceId}
              hours={hours} setHours={setHours}
              qty={qty} setQty={setQty}
              addDrone={addDrone} setAddDrone={setAddDrone}
              addRealTime={addRealTime} setAddRealTime={setAddRealTime}
              distance={distance}
              pricePerKm={quoteData.pricePerKm}
              locationClient={clientData.location}
              onOpenMap={() => setIsMapOpen(true)}
            />
          </div>

          <AnimatePresence>
            {showScrollIndicator && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed bottom-36 md:bottom-36 left-1/2 -translate-x-1/2 z-50 pointer-events-none text-white drop-shadow-md"
              >
                 <motion.div
                    animate={{ y: [0, 8, 0] }}
                    transition={{ duration: 1.5, repeat: Infinity, ease: "easeInOut" }}
                    className="flex flex-col items-center"
                 >
                    <ChevronsDown size={28} className="animate-pulse" />
                 </motion.div>
              </motion.div>
            )}
          </AnimatePresence>

          <AnimatePresence>
            {showFooter && (
                <StickyFooter 
                    totalPrice={totalPrice} 
                    onApprove={() => setViewState('summary')} 
                    isApproved={isApproved}
                    highlight={true} 
                />
            )}
          </AnimatePresence>
      </div>

      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={quoteData}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={summaryDetails}
                priceBreakdown={priceBreakdown}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
                onRemoveAddon={handleRemoveAddon}
            />
         )}
      </AnimatePresence>

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleUpdateLocation}
        initialAddress={clientData.location}
      />
    </div>
  );
};

export default QuoteView;

// === DEFINIÇÕES DE TIPO DE DOMÍNIO (DDD) ===
// Este arquivo centraliza todas as interfaces que modelam o negócio.

// Tipos de Locação (Afetam o cálculo de frete)
export type LocationType = 'studio' | 'external';

// Tipos de Ocasião (Usados para categorização na mensagem final)
export type OccasionType = 'institutional' | 'advertising' | 'social' | 'wedding' | 'custom';

// Categorias principais de Serviço (Abas do Configurador)
export type ServiceCategory = 'wedding' | 'social' | 'commercial' | 'studio' | 'video_production' | 'custom';

// IDs únicos para cada "Produto" vendável no sistema
export type ServiceId = 
  | 'birthday' | 'fifteen' | 'graduation' 
  | 'wedding_base' | 'wedding_classic' | 'wedding_romance' | 'wedding_essence'
  | 'comm_photo' | 'comm_video' | 'comm_combo'
  | 'studio_photo' | 'studio_video'
  | 'edit_only' | 'cam_cap' | 'mobile_cap' | 'drone'
  | 'custom_project';

// Estado persistente da tela de Orçamento
export interface QuoteState {
  category: ServiceCategory;
  serviceId: ServiceId;
  hours: number;
  qty: number;
  addDrone: boolean;
  addRealTime: boolean;
  selectionMode: 'duration' | 'quantity'; // Novo: Define se cobra por tempo ou por entrega
}

// Estrutura de um item individual dentro de um orçamento
export interface ServiceItem {
  id: string;
  title: string;
  description: string;
  price: number;
  isIncluded?: boolean;
  type: 'fixed' | 'variable_photo' | 'variable_video';
}

// Dados do Cliente (Input do Formulário Inicial)
export interface ClientData {
  name: string;
  location: string;
  date: string;     // Formato ISO string (YYYY-MM-DD)
  contact: string;  // Telefone ou Email
  company?: string;
  projectTitle?: string;
}

// Objeto Mestre de Configuração do Orçamento
export interface QuoteData {
  id: string;
  client: ClientData;
  date: string;
  validUntil: string;

  // Regras de Preço (Editáveis via Admin)
  basePrice: number;       
  studioFee: number;       
  photoUnitPrice: number;  
  videoUnitPrice: number;  
  pricePerKm: number;      

  items: ServiceItem[];
  moodboardImages: string[];
}

// Props para componentes de UI
export interface CheckboxProps {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label?: string;
  price?: number;
}

import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import QuoteView from './src/pages/QuoteView';
import WelcomeView from './src/pages/WelcomeView';
import IntroView from './src/pages/IntroView';
import AdminDashboard from './src/pages/AdminDashboard';
import Loading from './src/components/ui/Loading';
import Logo from './src/components/ui/Logo';
import BackgroundFilmStrips from './src/components/ui/BackgroundFilmStrips';
import { ClientData, QuoteData, QuoteState } from './src/types';
import { mockQuote } from './src/data/mock';
import { delay } from './src/lib/utils';

// Definição dos estados possíveis da aplicação
type ViewState = 'intro' | 'welcome' | 'quote' | 'admin';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<ViewState>('intro');
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<QuoteData>(mockQuote);
  const [isQuoteSuccess, setIsQuoteSuccess] = useState(false);

  const [clientData, setClientData] = useState<ClientData | null>(() => {
    const saved = localStorage.getItem('earec_client_data');
    return saved ? JSON.parse(saved) : null;
  });

  const [quoteState, setQuoteState] = useState<QuoteState>({
    category: 'wedding',
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    addDrone: false,
    addRealTime: false,
    selectionMode: 'duration'
  });

  useEffect(() => {
    if (clientData) {
      localStorage.setItem('earec_client_data', JSON.stringify(clientData));
    }
  }, [clientData]);

  useEffect(() => {
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
    window.scrollTo(0, 0);
    const timer = setTimeout(() => setShowSplash(false), 3500); 
    return () => clearTimeout(timer);
  }, []);

  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    setIsQuoteSuccess(false);
    await delay(2000); 
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  const handleAdminUpdate = (newConfig: QuoteData) => {
    setConfig(newConfig);
  };

  return (
    <main className="w-full min-h-screen bg-black text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans relative">
      {(view !== 'quote' || isQuoteSuccess) && <BackgroundFilmStrips />}

      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            transition={{ duration: 1.0, ease: "easeInOut" }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
             <div className="flex flex-col items-center justify-center w-full h-full p-4">
               <motion.div
                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 1.2, ease: "easeOut" }}
                 className="mb-8"
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 1.2, duration: 0.8 }}
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-400 font-serif italic text-xl md:text-2xl tracking-widest">Orçamento Facilitado</p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'intro' && (
                <IntroView 
                    onContinue={() => setView('welcome')} 
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
                  onBack={() => setView('intro')} 
                />
            )}

            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView('welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                  onSuccess={() => setIsQuoteSuccess(true)}
                />
            )}

            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={handleAdminUpdate}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

