import React from 'react';
import { motion, Variants } from 'framer-motion';
import { cn } from '../../lib/utils';

interface LogoProps {
  className?: string; // Classes CSS opcionais para ajustar tamanho (ex: w-32, h-auto)
  animate?: boolean;  // Se 'true', ativa a animação de entrada (fade-in + scale)
}

/**
 * Componente: Logo
 * ----------------
 * Renderiza a marca EAREC vetorialmente (SVG).
 * Design: "EA" (Branco/Cinza) + Dot (Vermelho) + "REC" (Vermelho).
 * Elimina dependência de arquivos de imagem externos.
 */
const Logo: React.FC<LogoProps> = ({ className, animate = false }) => {

  const containerVariants: Variants = {
    hidden: { 
      opacity: 0, 
      scale: 0.8, 
      filter: 'blur(10px)' 
    },
    visible: { 
      opacity: 1, 
      scale: 1, 
      filter: 'blur(0px)',
      transition: { 
        duration: 1.2, 
        ease: [0.22, 1, 0.36, 1] 
      } 
    }
  };

  const SvgContent = () => (
    <svg 
      viewBox="0 0 250 70" 
      fill="none" 
      xmlns="http://www.w3.org/2000/svg" 
      className="w-full h-full drop-shadow-[0_0_15px_rgba(255,255,255,0.05)]"
      aria-label="EAREC Logo"
    >
      {/* Texto EA - Cinza Claro/Branco - Ajustado para Negrito Extra (900) */}
      <text 
        x="10" 
        y="52" 
        fontFamily="'Inter', sans-serif" 
        fontWeight="900" 
        fontSize="55" 
        fill="#E5E5E5" 
        letterSpacing="-3"
        className="drop-shadow-sm"
      >
        EA
      </text>

      {/* Ponto Central - Vermelho Marca */}
      <motion.circle 
        cx="105" 
        cy="33" 
        r="16" 
        fill="#DC2626" 
        className="drop-shadow-[0_0_10px_rgba(220,38,38,0.9)]"
        animate={{ opacity: [1, 0.6, 1] }}
        transition={{ 
          duration: 3, 
          repeat: Infinity, 
          ease: "easeInOut" 
        }}
      />

      {/* Texto REC - Vermelho Marca - Ajustado para Negrito Extra (900) */}
      <text 
        x="132" 
        y="52" 
        fontFamily="'Inter', sans-serif" 
        fontWeight="900" 
        fontSize="55" 
        fill="#DC2626" 
        letterSpacing="-3"
        className="drop-shadow-[0_0_5px_rgba(220,38,38,0.4)]"
      >
        REC
      </text>
    </svg>
  );

  if (!animate) {
    return (
      <div className={cn("relative select-none", className)}>
        <SvgContent />
      </div>
    );
  }

  return (
    <motion.div 
      initial="hidden"
      animate="visible"
      variants={containerVariants}
      className={cn("relative select-none", className)}
    >
      <SvgContent />
    </motion.div>
  );
};

export default Logo;

import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import QuoteView from './src/pages/QuoteView';
import WelcomeView from './src/pages/WelcomeView';
import IntroView from './src/pages/IntroView';
import AdminDashboard from './src/pages/AdminDashboard';
import Loading from './src/components/ui/Loading';
import Logo from './src/components/ui/Logo';
import BackgroundFilmStrips from './src/components/ui/BackgroundFilmStrips';
import { ClientData, QuoteData, QuoteState } from './src/types';
import { mockQuote } from './src/data/mock';
import { delay } from './src/lib/utils';

// Definição dos estados possíveis da aplicação
type ViewState = 'intro' | 'welcome' | 'quote' | 'admin';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<ViewState>('intro');
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<QuoteData>(mockQuote);
  const [isQuoteSuccess, setIsQuoteSuccess] = useState(false);

  const [clientData, setClientData] = useState<ClientData | null>(() => {
    const saved = localStorage.getItem('earec_client_data');
    return saved ? JSON.parse(saved) : null;
  });

  const [quoteState, setQuoteState] = useState<QuoteState>({
    category: 'wedding',
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    addDrone: false,
    addRealTime: false,
    selectionMode: 'duration'
  });

  useEffect(() => {
    if (clientData) {
      localStorage.setItem('earec_client_data', JSON.stringify(clientData));
    }
  }, [clientData]);

  useEffect(() => {
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
    window.scrollTo(0, 0);
    const timer = setTimeout(() => setShowSplash(false), 3500); 
    return () => clearTimeout(timer);
  }, []);

  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    setIsQuoteSuccess(false);
    await delay(2000); 
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  const handleAdminUpdate = (newConfig: QuoteData) => {
    setConfig(newConfig);
  };

  return (
    <main className="w-full min-h-screen bg-black text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans relative">
      {(view !== 'quote' || isQuoteSuccess) && <BackgroundFilmStrips />}

      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            transition={{ duration: 1.0, ease: "easeInOut" }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
             <div className="flex flex-col items-center justify-center w-full h-full p-4">
               <motion.div
                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 1.2, ease: "easeOut" }}
                 className="mb-4" // Reduzido de mb-8 para subir o texto abaixo
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 10 }} // y reduzido para efeito mais "alto"
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 1.2, duration: 0.8 }}
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-400 font-serif italic text-xl md:text-2xl tracking-widest">Orçamento Facilitado</p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'intro' && (
                <IntroView 
                    onContinue={() => setView('welcome')} 
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
                  onBack={() => setView('intro')} 
                />
            )}

            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView('welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                  onSuccess={() => setIsQuoteSuccess(true)}
                />
            )}

            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={handleAdminUpdate}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

export default App;

