  return (
    <div className="relative">
      <div className="block pb-40">
          <motion.div
            className="fixed top-0 left-0 right-0 h-1 bg-brand-DEFAULT z-50 origin-left shadow-[0_0_15px_#DC2626]"
            style={{ scaleX }}
          />

          <AnimatePresence>
              {viewState === 'config' && (
                  <motion.button 
                    initial={{ opacity: 0, x: -20 }}
