      >
         <FilmStripTexture className="w-full h-full drop-shadow-[0_0_15px_rgba(220,38,38,0.2)]" speed={45} direction={1} />
      </motion.div>

      {/* Tira Inferior Esquerda */}
      <motion.div
        initial={{ opacity: 0, x: -100, rotate: -35 }}
        animate={{ 
