  const showQuantity = selectionMode === 'quantity' || (category === 'commercial') || (category === 'studio' && serviceId === 'studio_photo');

  return (
    <section className="pt-8 pb-32 px-4 md:px-8 bg-neutral-900/30 min-h-screen">
      <div className="max-w-4xl mx-auto space-y-16">

        {/* Categorias */}
        <div className="text-center">
            <p className={cn(TYPOGRAPHY.label, "mb-6")}>Escolha a Categoria</p>
            <div className="flex flex-wrap justify-center gap-2">
                {categories.map((cat) => (
                    <button
                        key={cat.id}
                        onClick={() => setCategory(cat.id as ServiceCategory)}
                        className={cn(
