                    <motion.div 
                        key="quantity"
                        variants={fadeInUp} initial="hidden" animate="visible" exit="hidden"
                        className="w-full max-w-md bg-neutral-900/60 p-8 rounded-3xl border border-white/5 shadow-2xl flex flex-col items-center text-center"
