import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import QuoteView from './pages/QuoteView';
import WelcomeView from './pages/WelcomeView';
import IntroView from './pages/IntroView';
import AdminDashboard from './pages/AdminDashboard';
import Loading from './components/ui/Loading';
import Logo from './components/ui/Logo';
import BackgroundFilmStrips from './components/ui/BackgroundFilmStrips';
import { ClientData, QuoteData, QuoteState } from './types';
import { mockQuote } from './data/mock';
import { delay } from './lib/utils';

type ViewState = 'intro' | 'welcome' | 'quote' | 'admin';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<ViewState>('intro');
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<QuoteData>(mockQuote);
  const [isQuoteSuccess, setIsQuoteSuccess] = useState(false);

  const [clientData, setClientData] = useState<ClientData | null>(() => {
    const saved = localStorage.getItem('earec_client_data');
    return saved ? JSON.parse(saved) : null;
  });

  const [quoteState, setQuoteState] = useState<QuoteState>({
    category: 'wedding',
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    addDrone: false,
    addRealTime: false,
    selectionMode: 'duration'
  });

  useEffect(() => {
    if (clientData) {
      localStorage.setItem('earec_client_data', JSON.stringify(clientData));
    }
  }, [clientData]);

  useEffect(() => {
    const timer = setTimeout(() => setShowSplash(false), 2200); 
    return () => clearTimeout(timer);
  }, []);

  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    setIsQuoteSuccess(false);
    await delay(1500); 
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  return (
    <main className="w-full min-h-screen bg-black text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans relative">
      {(view !== 'quote' || isQuoteSuccess) && <BackgroundFilmStrips />}

      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
            <Logo className="w-64 md:w-96" animate={true} />
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>{isLoading && <Loading key="loader" />}</AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'intro' && <IntroView onContinue={() => setView('welcome')} />}
            {view === 'welcome' && <WelcomeView onStart={handleStart} onAdminClick={() => setView('admin')} onBack={() => setView('intro')} />}
            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView('welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                  onSuccess={() => setIsQuoteSuccess(true)}
                />
            )}
            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={setConfig}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

export default App;

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export const formatCurrency = (value: number): string => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(value);
};

export const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * SISTEMA DE TIPOGRAFIA ATÔMICA
 * Altere estas classes para mudar o estilo de texto em todo o aplicativo.
 */
export const TYPOGRAPHY = {
  // Títulos grandes de seção
  display: "font-serif text-3xl md:text-5xl text-white tracking-tight leading-tight",
  // Títulos de cards e modais
  title: "font-serif text-xl md:text-2xl text-white tracking-normal",
  // Subtítulos e parágrafos de apoio
  subtitle: "text-sm md:text-base text-neutral-400 font-light leading-relaxed",
  // Rótulos técnicos e auxiliares
  label: "text-[10px] md:text-xs text-neutral-500 uppercase tracking-[0.2em] font-bold",
  // Valores numéricos e preços grandes
  value: "text-3xl md:text-6xl font-sans font-bold text-white tracking-tighter",
  // Textos de botões
  button: "text-sm font-bold tracking-widest uppercase",
  // Tags de preço destacadas
  priceTag: "text-brand-DEFAULT font-mono font-bold"
};

export const smoothScrollTo = (elementId: string, duration: number = 1200) => {
    const target = document.getElementById(elementId);
    if (!target) return;
    const targetPosition = target.getBoundingClientRect().top + window.pageYOffset;
    const offsetPosition = targetPosition - (window.innerHeight / 2) + (target.offsetHeight / 2);
    const startPosition = window.pageYOffset;
    const distance = offsetPosition - startPosition;
    let startTime: number | null = null;

    function easeInOutCubic(t: number, b: number, c: number, d: number) {
        t /= d / 2;
        if (t < 1) return c / 2 * t * t * t + b;
        t -= 2;
        return c / 2 * (t * t * t + 2) + b;
    }

    function animation(currentTime: number) {
        if (startTime === null) startTime = currentTime;
        const timeElapsed = currentTime - startTime;
        const run = easeInOutCubic(timeElapsed, startPosition, distance, duration);
        window.scrollTo(0, run);
        if (timeElapsed < duration) requestAnimationFrame(animation);
    }
    requestAnimationFrame(animation);
};

