export const smoothScrollTo = (elementId: string, duration: number = 1200) => {
    const target = document.getElementById(elementId);
    if (!target) return;
    const targetPosition = target.getBoundingClientRect().top + window.pageYOffset;
    const offsetPosition = targetPosition - (window.innerHeight / 2) + (target.offsetHeight / 2);
    const startPosition = window.pageYOffset;
    const distance = offsetPosition - startPosition;
    let startTime: number | null = null;

    function easeInOutCubic(t: number, b: number, c: number, d: number) {
        t /= d / 2;
        if (t < 1) return c / 2 * t * t * t + b;
        t -= 2;
        return c / 2 * (t * t * t + 2) + b;
    }

    function animation(currentTime: number) {
        if (startTime === null) startTime = currentTime;
        const timeElapsed = currentTime - startTime;
        const run = easeInOutCubic(timeElapsed, startPosition, distance, duration);
        window.scrollTo(0, run);
        if (timeElapsed < duration) requestAnimationFrame(animation);
    }
    requestAnimationFrame(animation);
};

import { QuoteState, QuoteData, ServiceCategory, ServiceId } from '../types';

export interface PriceBreakdownItem {
  label: string;
  value: number;
  type: 'base' | 'addon' | 'freight';
}

export class PricingEngine {
  public static readonly TABLE: any = {
    wedding: {
      wedding_base: { label: "Casamento (Base)" },
      wedding_classic: { label: "Pacote Clássico" },
      wedding_romance: { label: "Pacote Romance" },
      wedding_essence: { label: "Pacote Essência" }
    },
    social: {
      birthday: { label: "Chá Revelação / Aniversário" },
      fifteen: { label: "15 Anos" }, 
      graduation: { label: "Formatura" }
    },
    commercial: {
      comm_photo: { label: "Comércio (Fotos)" },
      comm_video: { label: "Comércio (Vídeo)" },
      comm_combo: { label: "Comércio (Foto + Vídeo)" }
    },
    studio: {
      studio_photo: { label: "Estúdio (Fotos)" },
      studio_video: { label: "Estúdio (Vídeo)" },
    },
    video_production: {
      edit_only: { label: "Apenas Edição" },
      cam_cap: { label: "Captação Câmera" },
      mobile_cap: { label: "Captação Celular" },
      drone: { label: "Drone (Imagens Aéreas)" }
    }
  };

  public static calculate(state: QuoteState, config: QuoteData, distance: number): { totalPrice: number, priceBreakdown: PriceBreakdownItem[] } {
    let total = 0;
    const breakdown: PriceBreakdownItem[] = [];

    // 1. Lógica Base por Categoria
    switch (state.category) {
      case 'wedding':
        const wBase = state.serviceId === 'wedding_essence' ? 1750 : state.serviceId === 'wedding_romance' ? 1150 : 650;
        total += wBase;
        breakdown.push({ label: this.getLabel('wedding', state.serviceId), value: wBase, type: 'base' });
        break;
      case 'social':
        const sBase = state.serviceId === 'graduation' ? 800 : 450;
        total += sBase;
        breakdown.push({ label: this.getLabel('social', state.serviceId), value: sBase, type: 'base' });
        break;
      case 'commercial':
        const cBase = state.serviceId === 'comm_combo' ? 800 : (state.qty * config.photoUnitPrice);
        total += cBase;
        breakdown.push({ label: this.getLabel('commercial', state.serviceId), value: cBase, type: 'base' });
        break;
      case 'studio':
        const stBase = state.selectionMode === 'quantity' ? state.qty * 25 : 350;
        total += stBase;
        breakdown.push({ label: this.getLabel('studio', state.serviceId), value: stBase, type: 'base' });
        break;
      default:
        total += config.basePrice || 200;
        breakdown.push({ label: "Serviço Base", value: config.basePrice || 200, type: 'base' });
    }

    // 2. Horas Extras
    if (state.selectionMode === 'duration' && state.hours > 2) {
      const extra = (state.hours - 2) * 250;
      total += extra;
      breakdown.push({ label: `Horas Extras (+${state.hours - 2}h)`, value: extra, type: 'addon' });
    }

    // 3. Adicionais
    if (state.addRealTime) {
      total += 600;
      breakdown.push({ label: "Fotos em Tempo Real", value: 600, type: 'addon' });
    }
    if (state.addDrone) {
      total += 250;
      breakdown.push({ label: "Drone (Aéreo)", value: 250, type: 'addon' });
    }

    // 4. Logística
    if (state.category !== 'studio' && distance > 0) {
      const freight = distance * 2 * (config.pricePerKm || 1.5);
      total += freight;
      breakdown.push({ label: `Logística (${distance}km)`, value: freight, type: 'freight' });
    }

    return { totalPrice: total, priceBreakdown: breakdown };
  }

  public static getLabel(category: ServiceCategory, serviceId: ServiceId): string {
    const group = (this.TABLE as any)[category];
    return group?.[serviceId]?.label || "Serviço Personalizado";
  }
}

