        <motion.h1 variants={fadeInUp} className="text-3xl font-serif text-white mb-2">
            Proposta Pronta!
        </motion.h1>

        <motion.p variants={fadeInUp} className="text-neutral-500 mb-8 text-sm">
            Tudo certo. Agora envie os detalhes para nossa produção via WhatsApp.
        </motion.p>

        <motion.div variants={fadeInUp} className="space-y-4 px-4">
            <a href={whatsappUrl} target="_blank" rel="noopener noreferrer" className="block w-full">
                <Button variant="primary" className="w-full py-4 bg-green-600 border-green-600 shadow-green-900/20 text-base font-bold">
                    <MessageCircle size={20} className="mr-2" />
