import { QuoteState, ServiceCategory, ServiceId, QuoteData } from '../types/index';

export interface PriceBreakdownItem {
  label: string;
  value: number;
  type: 'base' | 'addon' | 'freight';
}

export class PricingEngine {
  public static readonly TABLE = {
    wedding: {
      wedding_base: { base: 650, label: "Casamento (Base)" },
      wedding_classic: { base: 900, label: "Pacote Clássico" },
      wedding_romance: { base: 1150, label: "Pacote Romance" },
      wedding_essence: { base: 1750, label: "Pacote Essência" },
      realtime: { fixed: 600, label: "Fotos em Tempo Real" }
    },
    social: {
      birthday: { base: 400, hoursIncluded: 2, hourPrice: 250, label: "Chá Revelação / Aniversário" },
      fifteen: { base: 450, hoursIncluded: 2, hourPrice: 250, label: "15 Anos" }, 
      graduation: { base: 800, label: "Formatura" },
      realtime: { fixed: 600, label: "Fotos em Tempo Real" }
    },
    commercial: {
      photo: { unit: 20, label: "Comércio (Fotos)" },
      video: { unit: 500, label: "Comércio (Vídeo)" },
      combo: { videoBase: 800, label: "Comércio (Foto + Vídeo)" }
    },
    studio: {
      photo: { unit: 25, label: "Estúdio (Fotos)" },
      video: { base: 350, hoursIncluded: 2, hourPrice: 250, label: "Estúdio (Vídeo)" },
    },
    video_production: {
      edit: { unit: 250, label: "Apenas Edição" },
      cam_cap: { fixed: 350, label: "Captação Câmera" },
      mobile_cap: { fixed: 250, label: "Captação Celular" },
      drone: { fixed: 250, label: "Drone (Imagens Aéreas)" }
    }
  };

  public static calculate(state: QuoteState, config: QuoteData, distance: number): { totalPrice: number, priceBreakdown: PriceBreakdownItem[] } {
    const { category, serviceId, hours, qty, addDrone, addRealTime, selectionMode } = state;
    let total = 0;
    const breakdown: PriceBreakdownItem[] = [];

    // Lógica por Categoria
    if (category === 'wedding') {
      const s = this.TABLE.wedding;
      const item = s[serviceId as keyof typeof s] as any;
      if (item) {
        total += item.base;
        breakdown.push({ label: item.label, value: item.base, type: 'base' });
      }
      if (selectionMode === 'duration' && hours > 2) {
        const extra = (hours - 2) * 250;
        total += extra;
        breakdown.push({ label: `Horas Extras (+${hours - 2}h)`, value: extra, type: 'addon' });
      }
    } else if (category === 'social') {
      const s = this.TABLE.social;
      if (serviceId === 'birthday' || serviceId === 'fifteen') {
        const ref = s[serviceId];
        if (selectionMode === 'duration') {
          total += ref.base;
          breakdown.push({ label: `${ref.label} (Base 2h)`, value: ref.base, type: 'base' });
          if (hours > ref.hoursIncluded) {
            const extra = (hours - ref.hoursIncluded) * ref.hourPrice;
            total += extra;
            breakdown.push({ label: `Horas Extras (+${hours - ref.hoursIncluded}h)`, value: extra, type: 'addon' });
          }
        } else {
          const val = qty * (config.photoUnitPrice || 25);
          total += val;
          breakdown.push({ label: `${ref.label} (${qty} Fotos)`, value: val, type: 'base' });
        }
      } else if (serviceId === 'graduation') {
        total += s.graduation.base;
        breakdown.push({ label: s.graduation.label, value: s.graduation.base, type: 'base' });
      }
    } else if (category === 'commercial') {
      const s = this.TABLE.commercial;
      if (serviceId === 'comm_photo') {
        const val = qty * s.photo.unit;
        total += val;
        breakdown.push({ label: `${s.photo.label} (${qty}x)`, value: val, type: 'base' });
      } else if (serviceId === 'comm_video') {
        const val = qty * s.video.unit;
        total += val;
        breakdown.push({ label: `${s.video.label} (${qty}x)`, value: val, type: 'base' });
      } else if (serviceId === 'comm_combo') {
        total += s.combo.videoBase;
        breakdown.push({ label: s.combo.label, value: s.combo.videoBase, type: 'base' });
      }
    } else if (category === 'studio') {
      const s = this.TABLE.studio;
      if (selectionMode === 'quantity') {
        const val = qty * s.photo.unit;
        total += val;
        breakdown.push({ label: `${s.photo.label} (${qty}x)`, value: val, type: 'base' });
      } else {
        total += s.video.base;
        breakdown.push({ label: s.video.label, value: s.video.base, type: 'base' });
        if (hours > 2) {
          const extra = (hours - 2) * 200;
          total += extra;
          breakdown.push({ label: `Horas Extras (+${hours - 2}h)`, value: extra, type: 'addon' });
        }
      }
    } else if (category === 'video_production') {
      const s = this.TABLE.video_production;
      const item = s[serviceId as keyof typeof s] as any;
      if (item) {
        const val = (serviceId === 'edit_only') ? qty * item.unit : item.fixed;
        total += val;
        breakdown.push({ label: item.label + (serviceId === 'edit_only' ? ` (${qty}x)` : ''), value: val, type: 'base' });
      }
    }

    // Adicionais Globais
    if (addRealTime && (category === 'wedding' || category === 'social')) {
      total += 600;
      breakdown.push({ label: "Fotos em Tempo Real", value: 600, type: 'addon' });
    }

    if (addDrone && ['wedding', 'social', 'commercial'].includes(category)) {
      total += 250;
      breakdown.push({ label: "Drone (Imagens Aéreas)", value: 250, type: 'addon' });
    }

    // Deslocamento
    const isExempt = ['studio', 'custom'].includes(category) || serviceId === 'edit_only';
    if (!isExempt && distance > 0) {
      const freight = distance * 2 * (config.pricePerKm || 1.5);
      total += freight;
      breakdown.push({ label: `Logística (${distance}km)`, value: freight, type: 'freight' });
    }

    return { totalPrice: total, priceBreakdown: breakdown };
  }

  public static getLabel(category: ServiceCategory, serviceId: ServiceId): string {
    const group = (this.TABLE as any)[category];
    return group?.[serviceId]?.label || "Serviço Personalizado";
  }
}

