export class WhatsAppService {
  private static readonly PHONE = "5584981048857";

  private static formatDate(dateStr: string): string {
    if (!dateStr) return 'A definir';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y}`;
  }

  public static generateLink(params: MessageParams): string {
    const { client, total, details } = params;
    const formattedPrice = formatCurrency(total).replace(/\u00A0/g, ' ');

    const message = `
🔔 *NOVA PROPOSTA APROVADA - EAREC*

👤 *DADOS DO CLIENTE*
*Nome:* ${client.name}
*Data:* ${this.formatDate(client.date)}
*Contato:* ${client.contact}
*Local:* ${client.location}

🎬 *DETALHES DO SERVIÇO*
*Ocasião:* ${details.occasion}
*Ambiente:* ${details.locationType === 'studio' ? 'Estúdio' : 'Externo'}
*Escopo:* ${details.scope}

🚚 *LOGÍSTICA*
*Distância:* ${details.distance}km (Base: Goianinha)

💰 *FINANCEIRO*
*Valor Total:* ${formattedPrice}
*Pagamento:* ${details.payment}
*Status:* Aprovado via App
`.trim();

    return `https://api.whatsapp.com/send?phone=${this.PHONE}&text=${encodeURIComponent(message)}`;
  }
}

