import React, { useState, useMemo, useEffect, useCallback } from 'react';
import Hero from '../components/quote/Hero';
import UpsellList from '../components/quote/UpsellList';
import StickyFooter from '../components/quote/StickyFooter';
import SignatureModal from '../components/quote/SignatureModal';
import LocationMapModal from '../components/ui/LocationMapModal';
import AddonUpsellModal from '../components/quote/AddonUpsellModal';
import SummaryView from './SummaryView';
import SuccessView from './SuccessView';
import { formatCurrency } from '../lib/utils';
import { calculateDistance } from '../lib/maps';
import { PricingEngine } from '../lib/PricingEngine';
import { motion, useScroll, useSpring, AnimatePresence } from 'framer-motion';
import { ClientData, QuoteData, ServiceCategory, ServiceId, QuoteState } from '../types/index';
import { ChevronsDown, ArrowLeft } from 'lucide-react';

interface QuoteViewProps {
  clientData: ClientData; 
  onUpdateClientData: (data: ClientData) => void; 
  config: QuoteData;      
  onBack: () => void;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  onSuccess: () => void; 
}

type ViewState = 'config' | 'summary' | 'success';

const QuoteView: React.FC<QuoteViewProps> = ({ 
    clientData, onUpdateClientData, config, onBack, 
    quoteState, setQuoteState, onSuccess 
}) => {
  const [viewState, setViewState] = useState<ViewState>('config');
  const [showUpsell, setShowUpsell] = useState(false);
  const [distance, setDistance] = useState<number>(0); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false); 
  const [isApproved, setIsApproved] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');
  const [showScrollIndicator, setShowScrollIndicator] = useState(true);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30 });

  // Callbacks Otimizados
  const updateQuote = useCallback((updates: Partial<QuoteState>) => {
    setQuoteState(prev => ({ ...prev, ...updates }));
  }, [setQuoteState]);

  useEffect(() => {
    return scrollYProgress.on('change', (latest) => {
      // Esconde o indicador quando o usuário rolar 15% da tela
      setShowScrollIndicator(latest < 0.15);
    });
  }, [scrollYProgress]);

  useEffect(() => {
    let active = true;
    calculateDistance(clientData.location).then(d => {
      if (active) setDistance(d);
    });
    return () => { active = false; };
  }, [clientData.location]);

  // Inteligência de Cálculo via Classe PricingEngine
  const { totalPrice, priceBreakdown } = useMemo(() => {
    return PricingEngine.calculate(quoteState, config, distance);
  }, [quoteState, config, distance]);

  // Handlers
  const handleStartApproval = () => {
    const needsUpsell = (quoteState.category === 'wedding' || quoteState.category === 'social') && 
                       (!quoteState.addDrone || !quoteState.addRealTime);
    if (needsUpsell) setShowUpsell(true);
    else setViewState('summary');
  };

  const handleSignatureSuccess = () => {
    setIsModalOpen(false);
    setIsApproved(true);
    onSuccess();
    setViewState('success');
  };

  const label = PricingEngine.getLabel(quoteState.category, quoteState.serviceId);

  if (viewState === 'success') {
    return (
      <SuccessView 
        onReset={() => window.location.reload()} 
        clientData={clientData}
        totalPrice={totalPrice}
        quoteDetails={{
          occasion: quoteState.category as any,
          customOccasionText: label,
          location: quoteState.category === 'studio' ? 'studio' : 'external',
          photoQty: quoteState.selectionMode === 'quantity' ? quoteState.qty : 0,
          videoQty: (quoteState.category === 'commercial' && quoteState.serviceId !== 'comm_photo') ? quoteState.qty : 0,
          distance,
          paymentMethod
        }}
      />
    );
  }

  return (
    <div className="relative">
      <div className="block pb-40">
          {/* Barra de Progresso Superior */}
          <motion.div className="fixed top-0 left-0 right-0 h-1 bg-brand-DEFAULT z-50 origin-left" style={{ scaleX }} />

          <AnimatePresence>
              {viewState === 'config' && (
                  <motion.button 
                    initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}
                    onClick={onBack}
                    className="fixed top-6 left-6 z-[60] text-neutral-400 hover:text-white flex items-center gap-2 p-2 rounded-lg backdrop-blur-sm border border-white/5 transition-colors"
                  >
                     <ArrowLeft size={18} /> <span className="text-sm font-medium">Voltar</span>
                  </motion.button>
              )}
          </AnimatePresence>

          <Hero data={{ ...config, client: { ...config.client, ...clientData } }} />

          <UpsellList 
            {...quoteState}
            setCategory={(c) => updateQuote({ category: c })}
            setServiceId={(s) => updateQuote({ serviceId: s })}
            setHours={(h) => updateQuote({ hours: h })}
            setQty={(q) => updateQuote({ qty: q })}
            setAddDrone={(b) => updateQuote({ addDrone: b })}
            setAddRealTime={(b) => updateQuote({ addRealTime: b })}
            distance={distance}
            pricePerKm={config.pricePerKm}
            locationClient={clientData.location}
            onOpenMap={() => setIsMapOpen(true)}
            setSelectionMode={(m) => updateQuote({ selectionMode: m })}
          />

          {/* INDICADOR DE SCROLL (Posicionado acima do Sticky Footer) */}
          <AnimatePresence>
            {showScrollIndicator && (
              <motion.div 
                initial={{ opacity: 0, y: 10 }} 
                animate={{ opacity: 1, y: 0 }} 
                exit={{ opacity: 0, y: 10 }} 
                className="fixed bottom-32 left-1/2 -translate-x-1/2 z-30 pointer-events-none text-center"
              >
                 <motion.div 
                    animate={{ y: [0, 6, 0] }} 
                    transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }} 
                    className="flex flex-col items-center gap-2"
                >
                    <p className="text-[10px] uppercase tracking-widest text-neutral-500 font-medium bg-black/50 px-3 py-1 rounded-full backdrop-blur-sm">
                        Role para personalizar
                    </p>
                    <ChevronsDown size={24} className="text-white drop-shadow-[0_0_10px_rgba(255,255,255,0.5)]" />
                 </motion.div>
              </motion.div>
            )}
          </AnimatePresence>

          <StickyFooter totalPrice={totalPrice} onApprove={handleStartApproval} isApproved={isApproved} highlight />
      </div>

      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={config}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={{
                  serviceName: label,
                  categoryLabel: quoteState.category,
                  metricLabel: quoteState.selectionMode === 'duration' ? `${quoteState.hours}h` : `${quoteState.qty} und`,
                  addons: []
                }}
                priceBreakdown={priceBreakdown}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
            />
         )}
      </AnimatePresence>

      <AddonUpsellModal 
        isOpen={showUpsell}
        onClose={() => setShowUpsell(false)}
        onConfirm={() => { setShowUpsell(false); setViewState('summary'); }}
        addDrone={quoteState.addDrone}
        setAddDrone={(b) => updateQuote({ addDrone: b })}
        addRealTime={quoteState.addRealTime}
        setAddRealTime={(b) => updateQuote({ addRealTime: b })}
        totalPrice={totalPrice}
      />

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={(addr) => onUpdateClientData({ ...clientData, location: addr })}
        initialAddress={clientData.location}
      />
    </div>
  );
};

export default QuoteView;

import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import QuoteView from './src/pages/QuoteView';
import WelcomeView from './src/pages/WelcomeView';
import IntroView from './src/pages/IntroView';
import AdminDashboard from './src/pages/AdminDashboard';
import Loading from './src/components/ui/Loading';
import Logo from './src/components/ui/Logo';
import BackgroundFilmStrips from './src/components/ui/BackgroundFilmStrips';
import { ClientData, QuoteData, QuoteState } from './src/types/index';
import { mockQuote } from './src/data/mock';
import { delay } from './src/lib/utils';

// Definição dos estados possíveis da aplicação
type ViewState = 'intro' | 'welcome' | 'quote' | 'admin';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<ViewState>('intro');
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<QuoteData>(mockQuote);
  const [isQuoteSuccess, setIsQuoteSuccess] = useState(false);

  const [clientData, setClientData] = useState<ClientData | null>(() => {
    const saved = localStorage.getItem('earec_client_data');
    return saved ? JSON.parse(saved) : null;
  });

  const [quoteState, setQuoteState] = useState<QuoteState>({
    category: 'wedding',
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    addDrone: false,
    addRealTime: false,
    selectionMode: 'duration'
  });

  useEffect(() => {
    if (clientData) {
      localStorage.setItem('earec_client_data', JSON.stringify(clientData));
    }
  }, [clientData]);

  useEffect(() => {
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
    window.scrollTo(0, 0);
    // Tempo total de splash reduzido de 3500ms para 2200ms
    const timer = setTimeout(() => setShowSplash(false), 2200); 
    return () => clearTimeout(timer);
  }, []);

  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    setIsQuoteSuccess(false);
    await delay(2000); 
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  const handleAdminUpdate = (newConfig: QuoteData) => {
    setConfig(newConfig);
  };

  return (
    <main className="w-full min-h-screen bg-black text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans relative">
      {(view !== 'quote' || isQuoteSuccess) && <BackgroundFilmStrips />}

      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            transition={{ duration: 0.6, ease: "easeInOut" }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
             <div className="flex flex-col items-center justify-center w-full h-full p-4">
               <motion.div
                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 0.8, ease: "easeOut" }} // Reduzido de 1.2s para 0.8s
                 className="mb-4"
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.7, duration: 0.5 }} // Delay reduzido de 1.2s para 0.7s
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-400 font-serif italic text-xl md:text-2xl tracking-widest">Orçamento Facilitado</p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'intro' && (
                <IntroView 
                    onContinue={() => setView('welcome')} 
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
                  onBack={() => setView('intro')} 
                />
            )}

            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView('welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                  onSuccess={() => setIsQuoteSuccess(true)}
                />
            )}

            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={handleAdminUpdate}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

export default App;

