/**
 * SERVICE CATALOG
 * ----------------
 * Single Source of Truth for Service Definitions.
 * Edit this file to change prices, labels, and descriptions.
 */

export interface ServiceDefinition {
  id: ServiceId;
  label: string;
  description: string;
  priceModel: 'fixed' | 'hourly' | 'unit';
