import { QuoteState, PricingResult, QuoteData } from '../types';
import { CATALOG, ADDONS, ServiceDefinition } from './ServiceCatalog';

/**
 * PRICING ENGINE
 * --------------
 * Responsible for calculating the final price and generating the breakdown.
 * It decouples the UI from the Business Logic.
 */
export class PricingEngine {

  public static calculate(state: QuoteState, config: QuoteData, distanceKm: number): PricingResult {
    const { category, serviceId, qty, hours, addDrone, addRealTime, selectionMode } = state;

    // 1. Find the selected service definition in the Catalog
    const categoryGroup = CATALOG[category];
    const serviceDef = categoryGroup.find(s => s.id === serviceId);

    if (!serviceDef) {
      return { total: 0, breakdown: [] };
    }

    let total = 0;
    const breakdown = [];

    // 2. Calculate Base Service Price
    const baseCalculation = this.calculateBaseService(serviceDef, state);
    total += baseCalculation.amount;
    breakdown.push({ 
      label: baseCalculation.label, 
      value: baseCalculation.amount, 
      type: 'base' as const 
    });

    // 3. Calculate Extra Hours (if applicable)
    if (selectionMode === 'duration' && serviceDef.priceModel === 'hourly' && serviceDef.includedHours) {
      if (hours > serviceDef.includedHours) {
        const extraHours = hours - serviceDef.includedHours;
        const price = extraHours * (serviceDef.hourlyPrice || ADDONS.extraHour.price);
        total += price;
        breakdown.push({
          label: `Horas Extras (+${extraHours}h)`,
          value: price,
          type: 'addon' as const
        });
      }
    }

    // 4. Calculate Add-ons
    if (addRealTime) {
      total += ADDONS.realTime.price;
      breakdown.push({ label: ADDONS.realTime.label, value: ADDONS.realTime.price, type: 'addon' as const });
    }

    // Drone Logic: Some categories might have drone included in specific packages (e.g. wedding essence)
    // But for this logic, we follow the state.
    if (addDrone) {
       // Logic check: Avoid double charging if package already has drone (Business Rule)
       // For now, simpler logic:
       total += ADDONS.drone.price;
       breakdown.push({ label: ADDONS.drone.label, value: ADDONS.drone.price, type: 'addon' as const });
    }

    // 5. Calculate Logistics (Freight)
    const isExempt = category === 'studio' || category === 'custom' || serviceId === 'edit_only';
    if (!isExempt) {
      if (distanceKm > 0) {
        const freight = distanceKm * 2 * config.pricePerKm;
        total += freight;
        breakdown.push({ label: `Deslocamento (${distanceKm}km)`, value: freight, type: 'freight' as const });
      } else {
        breakdown.push({ label: "Deslocamento", value: 0, type: 'freight' as const });
      }
    }

    return { total, breakdown };
  }

  private static calculateBaseService(def: ServiceDefinition, state: QuoteState): { amount: number, label: string } {
    const { selectionMode, qty } = state;

    // Special Case: Commercial & Studio (Unit based vs Duration based)
    // If the catalog definition says it's a unit model, we multiply by Qty
    if (def.priceModel === 'unit') {
      const unitP = def.unitPrice || 0;
      return {
        amount: qty * unitP,
        label: `${def.label} (${qty} un)`
      };
    }

    // If it's hourly or fixed, but user selected Quantity mode (e.g. Social Photos)
    // We fallback to a generic photo unit price if logic dictates, OR we stick to the catalog definition.
    // In this app's logic, "Social" can be Quantity based.
    if (state.category === 'social' && selectionMode === 'quantity') {
       // Using a hardcoded photo price or one from config would be better. 
       // For now assuming 25 as per previous logic.
       const PHOTO_PRICE = 25; 
       return {
         amount: qty * PHOTO_PRICE,
         label: `${def.label} (${qty} Fotos)`
       };
    }

    // Default: Fixed Price or Base Hourly Package
    return {
      amount: def.basePrice || 0,
      label: def.label
    };
  }

  public static getLabel(category: string, serviceId: string): string {
    const group = CATALOG[category as keyof typeof CATALOG];
    const service = group?.find(s => s.id === serviceId);
    return service ? service.label : 'Serviço';
  }
}

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { motion, useScroll, useSpring, AnimatePresence } from 'framer-motion';
import { ChevronsDown, ArrowLeft } from 'lucide-react';

// Core
import { ClientData, QuoteData, QuoteState } from '../types';
import { PricingEngine } from '../core/PricingEngine';
import { calculateDistance } from '../lib/maps';
import { formatCurrency } from '../lib/utils';

// Components
import Hero from '../components/quote/Hero';
import UpsellList from '../components/quote/UpsellList';
import StickyFooter from '../components/quote/StickyFooter';
import SignatureModal from '../components/quote/SignatureModal';
import LocationMapModal from '../components/ui/LocationMapModal';
import AddonUpsellModal from '../components/quote/AddonUpsellModal';
import SummaryView from './SummaryView';
import SuccessView from './SuccessView';

interface QuoteViewProps {
  clientData: ClientData; 
  onUpdateClientData: (data: ClientData) => void; 
  config: QuoteData;      
  onBack: () => void;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  onSuccess: () => void; 
}

type ViewState = 'config' | 'summary' | 'success';

const QuoteView: React.FC<QuoteViewProps> = ({ 
    clientData, onUpdateClientData, config, onBack, 
    quoteState, setQuoteState, onSuccess 
}) => {
  // === UI STATE ===
  const [viewState, setViewState] = useState<ViewState>('config');
  const [showUpsell, setShowUpsell] = useState(false);
  const [showScrollIndicator, setShowScrollIndicator] = useState(true);

  // === MODAL STATES ===
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false); 

  // === BUSINESS LOGIC STATES ===
  const [distance, setDistance] = useState<number>(0); 
  const [isApproved, setIsApproved] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');

  // === SCROLL FX ===
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30 });

  // === DATA EFFECTS ===

  // Calculate Logistics
  useEffect(() => {
    let active = true;
    calculateDistance(clientData.location).then(d => {
      if (active) setDistance(d);
    });
    return () => { active = false; };
  }, [clientData.location]);

  // Hide scroll indicator
  useEffect(() => {
    return scrollYProgress.on('change', (latest) => {
      setShowScrollIndicator(latest < 0.15);
    });
  }, [scrollYProgress]);

  // === PRICING CALCULATION (Via Engine) ===
  const { totalPrice, breakdown } = useMemo(() => {
    // Adapter to match PricingResult interface
    const result = PricingEngine.calculate(quoteState, config, distance);
    return { totalPrice: result.total, breakdown: result.breakdown };
  }, [quoteState, config, distance]);

  // === HANDLERS ===
  const updateQuote = useCallback((updates: Partial<QuoteState>) => {
    setQuoteState(prev => ({ ...prev, ...updates }));
  }, [setQuoteState]);

  const handleStartApproval = () => {
    const needsUpsell = (quoteState.category === 'wedding' || quoteState.category === 'social') && 
                       (!quoteState.addDrone || !quoteState.addRealTime);
    if (needsUpsell) setShowUpsell(true);
    else setViewState('summary');
  };

  const handleSignatureSuccess = () => {
    setIsModalOpen(false);
    setIsApproved(true);
    onSuccess();
    setViewState('success');
  };

  // Get current label for UI
  const serviceLabel = PricingEngine.getLabel(quoteState.category, quoteState.serviceId);

  // === RENDER: SUCCESS VIEW ===
  if (viewState === 'success') {
    return (
      <SuccessView 
        onReset={() => window.location.reload()} 
        clientData={clientData}
        totalPrice={totalPrice}
        quoteDetails={{
          occasion: quoteState.category as any,
          customOccasionText: serviceLabel,
          location: quoteState.category === 'studio' ? 'studio' : 'external',
          photoQty: quoteState.selectionMode === 'quantity' ? quoteState.qty : 0,
          videoQty: (quoteState.category === 'commercial' && quoteState.serviceId !== 'comm_photo') ? quoteState.qty : 0,
          distance,
          paymentMethod
        }}
      />
    );
  }

  // === RENDER: MAIN VIEW ===
  return (
    <div className="relative min-h-screen bg-black">
      <div className="block pb-40">

          {/* Progress Bar */}
          <motion.div className="fixed top-0 left-0 right-0 h-1 bg-brand-DEFAULT z-50 origin-left shadow-[0_0_10px_#DC2626]" style={{ scaleX }} />

          {/* Back Button */}
          <AnimatePresence>
              {viewState === 'config' && (
                  <motion.button 
                    initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}
                    onClick={onBack}
                    className="fixed top-6 left-6 z-[60] text-neutral-400 hover:text-white flex items-center gap-2 p-2 rounded-lg backdrop-blur-md border border-white/5 transition-colors group"
                  >
                     <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> 
                     <span className="text-xs font-medium uppercase tracking-wider">Voltar</span>
                  </motion.button>
              )}
          </AnimatePresence>

          {/* Hero Section */}
          <Hero data={{ ...config, client: { ...config.client, ...clientData } }} />

          {/* Configurator */}
          <UpsellList 
            {...quoteState}
            setCategory={(c) => updateQuote({ category: c })}
            setServiceId={(s) => updateQuote({ serviceId: s })}
            setHours={(h) => updateQuote({ hours: h })}
            setQty={(q) => updateQuote({ qty: q })}
            setAddDrone={(b) => updateQuote({ addDrone: b })}
            setAddRealTime={(b) => updateQuote({ addRealTime: b })}
            distance={distance}
            pricePerKm={config.pricePerKm}
            locationClient={clientData.location}
            onOpenMap={() => setIsMapOpen(true)}
            setSelectionMode={(m) => updateQuote({ selectionMode: m })}
          />

          {/* Scroll Hint */}
          <AnimatePresence>
            {showScrollIndicator && (
              <motion.div 
                initial={{ opacity: 0, y: 10 }} 
                animate={{ opacity: 1, y: 0 }} 
                exit={{ opacity: 0, y: 10 }} 
                className="fixed bottom-32 left-1/2 -translate-x-1/2 z-30 pointer-events-none text-center"
              >
                 <motion.div 
                    animate={{ y: [0, 6, 0] }} 
                    transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }} 
                    className="flex flex-col items-center gap-2"
                >
                    <p className="text-[10px] uppercase tracking-widest text-neutral-500 font-medium bg-black/50 px-4 py-1.5 rounded-full backdrop-blur-md border border-white/5">
                        Role para personalizar
                    </p>
                    <ChevronsDown size={20} className="text-neutral-400" />
                 </motion.div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Footer Action */}
          <StickyFooter totalPrice={totalPrice} onApprove={handleStartApproval} isApproved={isApproved} highlight />
      </div>

      {/* Summary Overlay */}
      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={config}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={{
                  serviceName: serviceLabel,
                  categoryLabel: quoteState.category,
                  metricLabel: quoteState.selectionMode === 'duration' ? `${quoteState.hours}h` : `${quoteState.qty} und`,
                  addons: []
                }}
                priceBreakdown={breakdown}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
            />
         )}
      </AnimatePresence>

      {/* Modals */}
      <AddonUpsellModal 
        isOpen={showUpsell}
        onClose={() => setShowUpsell(false)}
        onConfirm={() => { setShowUpsell(false); setViewState('summary'); }}
        addDrone={quoteState.addDrone}
        setAddDrone={(b) => updateQuote({ addDrone: b })}
        addRealTime={quoteState.addRealTime}
        setAddRealTime={(b) => updateQuote({ addRealTime: b })}
        totalPrice={totalPrice}
      />

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={(addr) => onUpdateClientData({ ...clientData, location: addr })}
        initialAddress={clientData.location}
      />
    </div>
  );
};

export default QuoteView;

