  >
      <Icon size={22}/>
  </motion.button>
);

const ServiceCard = ({ active, onClick, icon: Icon, title, price, desc, highlight }: any) => (
    <motion.div 
        variants={fadeInUp}
        whileHover={{ y: -8, transition: { duration: 0.3, ease: "easeOut" } }}
