    >
        {highlight && (
            <div className={cn(
                "absolute top-0 right-0 text-[10px] font-bold px-4 py-1.5 rounded-bl-xl uppercase tracking-widest",
                active ? "bg-brand-DEFAULT text-white" : "bg-white/5 text-neutral-500"
            )}>
                Popular
            </div>
        )}

        <div className={cn(
            "p-5 rounded-full transition-all duration-500 group-hover:scale-110",
            active 
                ? "bg-brand-DEFAULT text-white shadow-[0_0_25px_rgba(220,38,38,0.6)]" 
                : "bg-white/5 text-neutral-500 group-hover:bg-brand-DEFAULT group-hover:text-white"
        )}>
            <Icon size={28} strokeWidth={1.5} />
        </div>

        <div className="space-y-2 flex-1">
            <h4 className={cn("text-2xl font-serif transition-colors", active ? "text-white" : "text-neutral-300 group-hover:text-white")}>
                {title}
            </h4>
            <p className="text-xs text-neutral-500 leading-relaxed font-light tracking-wide">{desc}</p>
        </div>

        <div className="w-16 h-px bg-white/10 my-2" />

        <p className={cn("text-sm font-bold tracking-widest uppercase", active ? "text-brand-DEFAULT drop-shadow-[0_0_8px_rgba(220,38,38,0.5)]" : "text-neutral-400")}>
            {price}
        </p>

        {/* Cinematic Glow Effect on Hover */}
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-brand-DEFAULT/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />
    </motion.div>
);

