import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Camera, Video, Gift, Crown, GraduationCap, Heart, 
  Store, Aperture, Plane, Clock, Minus, Plus, Route, Star, 
  Edit, Smartphone as SmartphoneIcon, Sparkles, Gem, HelpCircle, X
} from 'lucide-react';

import { cn, TYPOGRAPHY } from '../../lib/utils';
import { fadeInUp, staggerContainer, modalVariants } from '../../lib/animations';
import { ServiceCategory, ServiceId } from '../../types';
import AnimatedNumber from '../ui/AnimatedNumber';

interface UpsellListProps {
  category: ServiceCategory;
  setCategory: (c: ServiceCategory) => void;
  serviceId: ServiceId;
  setServiceId: (s: ServiceId) => void;
  hours: number;
  setHours: (h: number) => void;
  qty: number;
  setQty: (q: number) => void;
  addDrone: boolean;
  setAddDrone: (b: boolean) => void;
  addRealTime: boolean;
  setAddRealTime: (b: boolean) => void;
  distance: number;
  pricePerKm: number;
  locationClient: string;
  onOpenMap?: () => void;
  selectionMode?: 'duration' | 'quantity';
  setSelectionMode?: (mode: 'duration' | 'quantity') => void;
}

const UpsellList: React.FC<UpsellListProps> = (props) => {
  const { 
    category, setCategory, serviceId, setServiceId,
    hours, setHours, qty, setQty,
    distance, locationClient, onOpenMap, setSelectionMode 
  } = props;

  // Estado para controlar o modal de informações
  const [infoData, setInfoData] = useState<{ title: string; desc: string; price: string } | null>(null);

  const categories = [
    { id: 'wedding', label: 'Casamento', icon: Heart },
    { id: 'social', label: 'Social', icon: Gift },
    { id: 'commercial', label: 'Comercial', icon: Store },
    { id: 'studio', label: 'Estúdio', icon: Aperture },
    { id: 'video_production', label: 'Produção', icon: Video },
    { id: 'custom', label: 'Outros', icon: Star },
  ];

  // Logic: Handle Selection with Intelligent Defaults
  const handleServiceSelect = (id: ServiceId, mode: 'duration' | 'quantity' = 'duration') => {
    setServiceId(id);
    if (setSelectionMode) setSelectionMode(mode);

    // Smart Defaults (UX)
    if (id === 'comm_photo') setQty(20);
    else if (id === 'comm_video') setQty(1);
    else if (id === 'studio_photo') setQty(10);
  };

  // Visibility Logic
  const showDuration = (category === 'wedding' || (category === 'social' && serviceId !== 'graduation') || (category === 'studio' && serviceId === 'studio_video') || category === 'video_production');
  const showQuantity = (category === 'commercial') || (category === 'studio' && serviceId === 'studio_photo') || (category === 'video_production' && serviceId === 'edit_only');
  const isSocialTimeBased = category === 'social' && (serviceId === 'birthday' || serviceId === 'fifteen');

  return (
    <section className="pt-8 pb-48 px-4 md:px-8 bg-neutral-900/30 min-h-screen relative z-10">
      <div className="max-w-5xl mx-auto space-y-12">

        {/* === CATEGORY SELECTOR === */}
        <div className="space-y-8 text-center">
            <p className="text-[10px] uppercase tracking-[0.3em] text-neutral-500 font-medium">Selecione a Ocasião</p>
            <div className="flex flex-wrap justify-center gap-3">
                {categories.map((cat) => {
                    const isActive = category === cat.id;
                    return (
                        <motion.button
                            key={cat.id}
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => setCategory(cat.id as ServiceCategory)}
                            className={cn(
                                "flex items-center gap-3 px-6 py-3 rounded-full transition-all duration-300 text-xs font-bold uppercase tracking-widest border",
                                isActive 
                                    ? "bg-brand-DEFAULT border-brand-DEFAULT text-white shadow-[0_0_25px_rgba(220,38,38,0.3)]" 
                                    : "bg-neutral-900/80 border-white/5 text-neutral-400 hover:border-white/20 hover:text-white backdrop-blur-sm"
                            )}
                        >
                            <cat.icon size={14} className={isActive ? "text-white" : "text-neutral-500"} />
                            {cat.label}
                        </motion.button>
                    )
                })}
            </div>
        </div>

        {/* === SERVICE GRID (Manual Structure for Better Control) === */}
        <motion.div 
            key={category} 
            variants={staggerContainer}
            initial="hidden"
            animate="visible"
            className="grid grid-cols-1 md:grid-cols-3 gap-6"
        >
             {/* Wedding Options */}
             {category === 'wedding' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'wedding_base'} 
                        onClick={() => handleServiceSelect('wedding_base')} 
                        onInfo={setInfoData}
                        icon={Heart} title="Wedding Base" price="R$ 650" desc="Cerimônia Essencial" 
                    />
                    <ServiceCard 
                        active={serviceId === 'wedding_classic'} 
                        onClick={() => handleServiceSelect('wedding_classic')} 
                        onInfo={setInfoData}
                        icon={Sparkles} title="Clássico" price="R$ 900" desc="Pré-Wedding + Cerimônia" highlight 
                    />
                    <ServiceCard 
                        active={serviceId === 'wedding_essence'} 
                        onClick={() => handleServiceSelect('wedding_essence')} 
                        onInfo={setInfoData}
                        icon={Gem} title="Essência" price="R$ 1.750" desc="Cobertura Completa + Drone" highlight 
                    />
                </>
            )}

            {/* Social Options */}
            {category === 'social' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'birthday'} 
                        onClick={() => handleServiceSelect('birthday')} 
                        onInfo={setInfoData}
                        icon={Gift} title="Aniversário/Chá" price="R$ 400" desc="Cobertura de 2 Horas" 
                    />
                    <ServiceCard 
                        active={serviceId === 'fifteen'} 
                        onClick={() => handleServiceSelect('fifteen')} 
                        onInfo={setInfoData}
                        icon={Crown} title="15 Anos" price="R$ 450" desc="Festa e Detalhes" 
                    />
                    <ServiceCard 
                        active={serviceId === 'graduation'} 
                        onClick={() => handleServiceSelect('graduation')} 
                        onInfo={setInfoData}
                        icon={GraduationCap} title="Formatura" price="R$ 800" desc="Evento Completo" 
                    />
                </>
            )}

            {/* Commercial Options */}
            {category === 'commercial' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'comm_photo'} 
                        onClick={() => handleServiceSelect('comm_photo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Camera} title="Fotografia" price="R$ 20/un" desc="Alta Conversão" 
                    />
                    <ServiceCard 
                        active={serviceId === 'comm_video'} 
                        onClick={() => handleServiceSelect('comm_video', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Video} title="Vídeo Maker" price="R$ 500/un" desc="Reels / TikTok" 
                    />
                    <ServiceCard 
                        active={serviceId === 'comm_combo'} 
                        onClick={() => handleServiceSelect('comm_combo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Star} title="Combo Full" price="R$ 800" desc="Foto + Vídeo" highlight 
                    />
                </>
            )}

            {/* Studio Options */}
            {category === 'studio' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'studio_photo'} 
                        onClick={() => handleServiceSelect('studio_photo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Aperture} title="Ensaio Foto" price="R$ 25/un" desc="Estúdio Controlado" 
                    />
                    <ServiceCard 
                        active={serviceId === 'studio_video'} 
                        onClick={() => handleServiceSelect('studio_video', 'duration')} 
                        onInfo={setInfoData}
                        icon={Video} title="Ensaio Vídeo" price="R$ 350" desc="Clipes Cinematográficos" 
                    />
                </>
            )}

            {/* Production Options */}
            {category === 'video_production' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'edit_only'} 
                        onClick={() => handleServiceSelect('edit_only', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Edit} title="Apenas Edição" price="R$ 250" desc="Pós-produção" 
                    />
                    <ServiceCard 
                        active={serviceId === 'cam_cap'} 
                        onClick={() => handleServiceSelect('cam_cap', 'duration')} 
                        onInfo={setInfoData}
                        icon={Video} title="Op. Câmera" price="R$ 350" desc="Diária Profissional" 
                    />
                    <ServiceCard 
                        active={serviceId === 'mobile_cap'} 
                        onClick={() => handleServiceSelect('mobile_cap', 'duration')} 
                        onInfo={setInfoData}
                        icon={SmartphoneIcon} title="Mobile" price="R$ 250" desc="Captação iPhone" 
                    />
                    <ServiceCard 
                        active={serviceId === 'drone'} 
                        onClick={() => handleServiceSelect('drone', 'duration')} 
                        onInfo={setInfoData}
                        icon={Plane} title="Drone" price="R$ 250" desc="Imagens Aéreas" 
                    />
                </>
            )}

            {/* Custom Option */}
            {category === 'custom' && (
                <motion.div variants={fadeInUp} className="col-span-1 md:col-span-3 bg-white/5 border border-white/10 p-10 rounded-2xl text-center backdrop-blur-sm">
                    <Star className="mx-auto text-brand-DEFAULT mb-4" size={32} />
                    <h3 className="font-serif text-xl text-white mb-2">Projeto Personalizado</h3>
                    <p className="text-neutral-400">Descreva sua necessidade específica no WhatsApp após finalizar.</p>
                </motion.div>
            )}
        </motion.div>

        {/* === QUANTITY CONTROLS (Glassmorphism) === */}
        <div className="flex flex-col items-center gap-10 mt-16">
            <AnimatePresence mode="wait">
                {(showDuration || isSocialTimeBased) && (
                    <motion.div 
                        key="duration"
                        variants={fadeInUp} initial="hidden" animate="visible" exit="hidden"
                        className="w-full max-w-xl bg-neutral-900/40 p-10 rounded-[2.5rem] border border-white/10 shadow-2xl flex flex-col items-center text-center backdrop-blur-xl relative overflow-hidden group"
                    >
                         <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-brand-DEFAULT/50 to-transparent" />

                        <div className="flex items-center gap-3 mb-8">
                             <Clock className="text-brand-DEFAULT" size={18} />
                             <h3 className="text-xs font-bold uppercase tracking-[0.2em] text-neutral-400">Tempo de Cobertura</h3>
                        </div>

                        <div className="flex items-center justify-between w-full gap-10 px-4">
                            <ControlBtn onClick={() => setHours(Math.max(2, hours - 1))} icon={Minus} />

                            <div className="text-center">
                                <span className="block text-6xl font-serif text-white tracking-tighter mb-2 drop-shadow-lg">
                                    <AnimatedNumber value={hours} />
                                </span>
                                <span className="text-[10px] text-neutral-500 font-bold uppercase tracking-[0.4em]">Horas</span>
                            </div>

                            <ControlBtn onClick={() => setHours(hours + 1)} icon={Plus} active />
                        </div>

                        <div className="w-full h-1 bg-white/5 rounded-full mt-10 overflow-hidden">
                            <motion.div className="h-full bg-brand-DEFAULT shadow-[0_0_15px_#DC2626]" animate={{ width: `${(hours/12)*100}%` }} />
                        </div>
                    </motion.div>
                )}

                {showQuantity && (
                    <motion.div 
                        key="quantity"
                        variants={fadeInUp} initial="hidden" animate="visible" exit="hidden"
                        className="w-full max-w-xl bg-neutral-900/40 p-10 rounded-[2.5rem] border border-white/10 shadow-2xl flex flex-col items-center text-center backdrop-blur-xl relative overflow-hidden"
                    >
                        <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-brand-DEFAULT/50 to-transparent" />

                        <div className="flex items-center gap-3 mb-8">
                             <Camera className="text-brand-DEFAULT" size={18} />
                             <h3 className="text-xs font-bold uppercase tracking-[0.2em] text-neutral-400">Quantidade</h3>
                        </div>

                        <div className="flex items-center justify-between w-full gap-10 px-4">
                            <ControlBtn onClick={() => setQty(Math.max(1, qty - 1))} icon={Minus} />

                            <div className="text-center">
                                <span className="block text-6xl font-serif text-white tracking-tighter mb-2 drop-shadow-lg">
                                    <AnimatedNumber value={qty} />
                                </span>
                                <span className="text-[10px] text-neutral-500 font-bold uppercase tracking-[0.4em]">Unidades</span>
                            </div>

                            <ControlBtn onClick={() => setQty(qty + 1)} icon={Plus} active />
                        </div>

                        <div className="w-full h-1 bg-white/5 rounded-full mt-10 overflow-hidden">
                            <motion.div className="h-full bg-brand-DEFAULT shadow-[0_0_15px_#DC2626]" animate={{ width: `${Math.min(100, (qty/100)*100)}%` }} />
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>

        {/* LOGISTICS CARD */}
        <motion.div 
            variants={fadeInUp} 
            onClick={onOpenMap} 
            className="pt-12 border-t border-white/5 flex flex-col items-center cursor-pointer group hover:bg-white/[0.02] rounded-xl py-6 transition-colors"
        >
            <div className="p-4 bg-white/5 rounded-full text-brand-DEFAULT mb-4 group-hover:scale-110 group-hover:bg-brand-DEFAULT group-hover:text-white transition-all duration-300 shadow-[0_0_15px_rgba(0,0,0,0.5)]">
                <Route size={24} />
            </div>
            <p className={TYPOGRAPHY.label}>Logística do Evento</p>
            <p className="text-white text-xl mt-2 font-serif tracking-wide">{locationClient}</p>
            <p className="text-neutral-500 text-xs mt-2 bg-white/5 px-4 py-1.5 rounded-full border border-white/5">
                Distância estimada: {distance}km
            </p>
        </motion.div>

      </div>

      {/* INFO MODAL */}
      <AnimatePresence>
        {infoData && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
             <motion.div 
                initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                className="absolute inset-0 bg-black/60 backdrop-blur-md"
                onClick={() => setInfoData(null)}
             />
             <motion.div 
                variants={modalVariants} initial="hidden" animate="visible" exit="exit"
                className="relative bg-neutral-900 border border-white/10 rounded-2xl p-8 max-w-sm w-full text-center shadow-2xl"
             >
                <button 
                  onClick={() => setInfoData(null)}
                  className="absolute top-4 right-4 text-neutral-500 hover:text-white transition-colors"
                >
                    <X size={20} />
                </button>

                <h3 className="text-2xl font-serif text-white mb-4">{infoData.title}</h3>
                <div className="w-12 h-0.5 bg-brand-DEFAULT mx-auto mb-6" />
                <p className="text-neutral-300 leading-relaxed font-light text-sm mb-8">
                    {infoData.desc}
                    <br/><br/>
                    <span className="text-neutral-500 text-xs">Inclui suporte completo e equipamentos profissionais da EAREC.</span>
                </p>
                <div className="bg-white/5 py-2 px-4 rounded-full inline-block border border-white/5">
                    <span className="text-brand-DEFAULT font-bold">{infoData.price}</span>
                </div>
             </motion.div>
          </div>
        )}
      </AnimatePresence>

    </section>
  );
};

// === SUB-COMPONENTS ===

const ControlBtn = ({ onClick, icon: Icon, active }: any) => (
  <motion.button 
      whileHover={{ scale: 1.1, backgroundColor: active ? "rgba(220, 38, 38, 1)" : "rgba(255,255,255,0.1)" }}
      whileTap={{ scale: 0.9 }}
      onClick={onClick} 
      className={cn(
        "w-14 h-14 flex items-center justify-center rounded-full transition-colors border",
        active ? "bg-white/5 border-white/10 text-white" : "bg-transparent border-white/5 text-neutral-500"
      )}
  >
      <Icon size={22}/>
  </motion.button>
);

const ServiceCard = ({ active, onClick, onInfo, icon: Icon, title, price, desc, highlight }: any) => (
    <motion.div 
        variants={fadeInUp}
        whileHover={{ y: -8, transition: { duration: 0.3, ease: "easeOut" } }}
        onClick={onClick}
        className={cn(
            "cursor-pointer p-8 rounded-2xl border transition-all duration-500 flex flex-col items-center text-center gap-5 relative overflow-hidden group h-full", 
            active 
                ? "bg-brand-DEFAULT/5 border-brand-DEFAULT shadow-[0_0_40px_rgba(220,38,38,0.15)] z-10 backdrop-blur-sm" 
                : "bg-white/[0.02] border-white/5 hover:bg-white/[0.05] hover:border-white/10"
        )}
    >
        {highlight && (
            <div className={cn(
                "absolute top-0 right-0 text-[10px] font-bold px-4 py-1.5 rounded-bl-xl uppercase tracking-widest",
                active ? "bg-brand-DEFAULT text-white" : "bg-white/5 text-neutral-500"
            )}>
                Popular
            </div>
        )}

        {/* Botão de Interrogação (Help/Info) */}
        <button 
          className="absolute top-4 left-4 text-neutral-600 hover:text-white transition-colors z-20 p-2 hover:bg-white/5 rounded-full"
          onClick={(e) => {
             e.stopPropagation();
             // Passa os dados para abrir o modal
             if (onInfo) onInfo({ title, desc, price });
          }}
        >
            <HelpCircle size={18} strokeWidth={2} />
        </button>

        {/* ÍCONE (Sem background, apenas cor) */}
        <div className={cn(
            "mb-2 transition-all duration-500 group-hover:scale-110",
            active 
                ? "text-brand-DEFAULT drop-shadow-[0_0_15px_rgba(220,38,38,0.6)]" 
                : "text-neutral-500 group-hover:text-white"
        )}>
            <Icon size={32} strokeWidth={1.5} />
        </div>

        <div className="space-y-2 flex-1">
            <h4 className={cn("text-2xl font-serif transition-colors", active ? "text-white" : "text-neutral-300 group-hover:text-white")}>
                {title}
            </h4>
            <p className="text-xs text-neutral-500 leading-relaxed font-light tracking-wide">{desc}</p>
        </div>

        <div className="w-16 h-px bg-white/10 my-2" />

        <p className={cn("text-sm font-bold tracking-widest uppercase", active ? "text-brand-DEFAULT drop-shadow-[0_0_8px_rgba(220,38,38,0.5)]" : "text-neutral-400")}>
            {price}
        </p>

        {/* Cinematic Glow Effect on Hover */}
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-brand-DEFAULT/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />
    </motion.div>
