                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 0.8, ease: "easeOut" }}
                 className="mb-4"
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.7, duration: 0.5 }}
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-400 font-serif italic text-xl md:text-2xl tracking-widest">
                    {AppConfig.BRAND.NAME} Experience
                  </p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'intro' && (
                <IntroView 
                    onContinue={() => setView('welcome')} 
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
                  onBack={() => setView('intro')} 
                />
            )}

            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView('welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                  onSuccess={() => setIsQuoteSuccess(true)}
                />
            )}

            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={handleAdminUpdate}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import Hero from '../components/quote/Hero';
import UpsellList from '../components/quote/UpsellList';
import StickyFooter from '../components/quote/StickyFooter';
import SignatureModal from '../components/quote/SignatureModal';
import LocationMapModal from '../components/ui/LocationMapModal';
import AddonUpsellModal from '../components/quote/AddonUpsellModal';
import SummaryView from './SummaryView';
import SuccessView from './SuccessView';
import { formatCurrency } from '../lib/utils';
import { motion, useScroll, useSpring, AnimatePresence } from 'framer-motion';
import { ClientData, QuoteData, ServiceCategory, ServiceId, QuoteState, PricingContext } from '../types';
import { ChevronsDown, ArrowLeft } from 'lucide-react';

// === POO INTEGRATION ===
import { PricingEngine } from '../core/PricingEngine';
import { AppConfig } from '../config/AppConfig';
import { LocationService } from '../services/LocationService';

interface QuoteViewProps {
  clientData: ClientData; 
  onUpdateClientData: (data: ClientData) => void; 
  config: QuoteData;      
  onBack: () => void;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  onSuccess: () => void; 
}

type ViewState = 'config' | 'summary' | 'success';

const QuoteView: React.FC<QuoteViewProps> = ({ 
    clientData, onUpdateClientData, config, onBack, 
    quoteState, setQuoteState, onSuccess 
}) => {
  const [viewState, setViewState] = useState<ViewState>('config');
  const [showUpsell, setShowUpsell] = useState(false);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

  const [showScrollIndicator, setShowScrollIndicator] = useState(true);

  useEffect(() => {
    return scrollYProgress.on('change', (latest) => {
      if (latest > 0.9) setShowScrollIndicator(false);
      else setShowScrollIndicator(true);
    });
  }, [scrollYProgress]);

  const [showFooter, setShowFooter] = useState(true);

  const quoteData: QuoteData = useMemo(() => ({
    ...config,
    client: { ...config.client, ...clientData, projectTitle: `Project: ${clientData.name}` }
  }), [clientData, config]);

  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');

  const [distance, setDistance] = useState<number>(0); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false); 
  const [isApproved, setIsApproved] = useState(false);

  // Destructuring do State
  const { category, serviceId, hours, qty, addDrone, addRealTime, selectionMode } = quoteState;

  // Setters Helpers
  const setCategory = (c: ServiceCategory) => setQuoteState(prev => ({ ...prev, category: c }));
  const setServiceId = (s: ServiceId) => setQuoteState(prev => ({ ...prev, serviceId: s }));
  const setHours = (h: number) => setQuoteState(prev => ({ ...prev, hours: h }));
  const setQty = (q: number) => setQuoteState(prev => ({ ...prev, qty: q }));
  const setAddDrone = (b: boolean) => setQuoteState(prev => ({ ...prev, addDrone: b }));
  const setAddRealTime = (b: boolean) => setQuoteState(prev => ({ ...prev, addRealTime: b }));
  const setSelectionMode = (mode: 'duration' | 'quantity') => setQuoteState(prev => ({ ...prev, selectionMode: mode }));

  // --- LOGIC: LOCATION SERVICE ---
  useEffect(() => {
    let isMounted = true;
    const updateDistance = async () => {
        if (clientData.location) {
            const dist = await LocationService.calculateDistance(clientData.location);
            if (isMounted) setDistance(dist);
        }
    };
    updateDistance();
    return () => { isMounted = false; };
  }, [clientData.location]);

  const handleUpdateLocation = (address: string) => {
      onUpdateClientData({ ...clientData, location: address });
  };

  // --- LOGIC: SELECTION DEFAULTS ---
  useEffect(() => {
    // Sincroniza o modo de seleção com a categoria/serviço para melhor UX
    if (category === 'wedding') setSelectionMode('duration');
    if (category === 'commercial') setSelectionMode('quantity');
    if (category === 'studio' && serviceId === 'studio_photo') setSelectionMode('quantity');
    if (category === 'studio' && serviceId === 'studio_video') setSelectionMode('duration');
    if (category === 'social' && serviceId === 'graduation') setSelectionMode('duration');
  }, [category, serviceId]);

  // --- LOGIC: PRICING ENGINE INTEGRATION ---
  const { totalPrice, priceBreakdown } = useMemo(() => {
    // 1. Monta o Contexto com os preços base do Admin/Config
    const context: PricingContext = {
        pricePerKm: config.pricePerKm,
        photoUnitPrice: config.photoUnitPrice,
        videoUnitPrice: config.videoUnitPrice,
        distance: distance
    };

    // 2. Chama o Motor de Precificação (POO)
    const result = PricingEngine.calculate(quoteState, context);

    return { 
        totalPrice: result.totalPrice, 
        priceBreakdown: result.breakdown 
    };
  }, [quoteState, config, distance]);

  // --- LOGIC: RESET WHEN CHANGING CATEGORY ---
  useEffect(() => {
      // Valida se o ID atual pertence à categoria. Se não, reseta para o padrão da categoria.
      const table = AppConfig.PRICING_TABLE;
      const currentCategoryGroup = table[category as keyof typeof table];

      const isIdValid = currentCategoryGroup && Object.keys(currentCategoryGroup).some(key => key === serviceId);

      if (!isIdValid) {
        if (category === 'wedding') setServiceId('wedding_base');
        if (category === 'social') setServiceId('birthday');
        if (category === 'commercial') setServiceId('comm_photo');
        if (category === 'studio') setServiceId('studio_photo');
        if (category === 'video_production') setServiceId('edit_only');
        if (category === 'custom') setServiceId('custom_project');

        setHours(2);

        // Defaults inteligentes
        if (category === 'commercial') {
            if (serviceId === 'comm_photo') setQty(5);
            else if (serviceId === 'comm_video') setQty(1);
        } else if (category === 'video_production') {
            setQty(1);
        } else {
            setQty(10);
        }
      }
  }, [category]);

  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    setIsApproved(true);
    onSuccess();
    setViewState('success');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReset = () => { window.location.reload(); };

  const handleRemoveAddon = (addonName: string) => {
      const name = addonName.toLowerCase();
      if (name.includes('drone')) setAddDrone(false);
      if (name.includes('tempo real')) setAddRealTime(false);
      if (name.includes('horas extras')) setHours(2); 
  };

  const handleStartApproval = () => {
    const canShowUpsell = (category === 'wedding' || category === 'social') && (!addDrone || !addRealTime);

    if (canShowUpsell) {
        setShowUpsell(true);
    } else {
        setViewState('summary');
    }
  };

  const handleConfirmUpsell = () => {
    setShowUpsell(false);
    setViewState('summary');
  };

  // Label Resolution via AppConfig
  const serviceLabel = AppConfig.getServiceLabel(category, serviceId);

  let metricLabel = '';
  if (selectionMode === 'duration') {
       metricLabel = `${hours}h de Cobertura (Ilimitado)`;
  } else {
       metricLabel = `${qty} Unidades Entregues`;
  }

  if (category === 'wedding' && selectionMode === 'duration' && hours === 2) metricLabel = "Pacote Completo";
  if (category === 'custom') metricLabel = 'Sob medida';

  const activeAddons = [];
  if (addDrone && (category === 'wedding' || category === 'social' || category === 'commercial')) activeAddons.push('Drone (Aéreo)');
  if (addRealTime) activeAddons.push('Fotos em Tempo Real');

  const summaryDetails = {
    serviceName: serviceLabel,
    categoryLabel: category === 'wedding' ? 'Casamento' : category === 'social' ? 'Social' : category === 'commercial' ? 'Comercial' : category === 'studio' ? 'Estúdio' : 'Produção',
    metricLabel,
    addons: activeAddons
  };

  const quoteDetails = {
    occasion: category === 'custom' ? 'custom' : (category as any),
    customOccasionText: serviceLabel,
    location: (category === 'studio' ? 'studio' : 'external'),
    photoQty: selectionMode === 'quantity' ? qty : (category === 'commercial' && serviceId === 'comm_photo' ? qty : 0),
    videoQty: (category === 'video_production' && serviceId === 'edit_only') ? qty : 
              ((category === 'commercial' && (serviceId === 'comm_video' || serviceId === 'comm_combo'))) ? qty : 0,
    distance,
    paymentMethod 
  };

  if (viewState === 'success') {
      return (
        <SuccessView 
            onReset={handleReset} 
            clientData={clientData}
            totalPrice={totalPrice}
            quoteDetails={quoteDetails as any}
        />
      );
  }

  return (
    <div className="relative">
      <div className="block pb-40">
          <motion.div
            className="fixed top-0 left-0 right-0 h-1 bg-brand-DEFAULT z-50 origin-left shadow-[0_0_15px_var(--brand-glow)]"
            style={{ scaleX }}
          />

          <AnimatePresence>
              {viewState === 'config' && (
                  <motion.button 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -20 }}
                    onClick={onBack}
                    className="fixed top-6 left-6 z-[60] text-neutral-400 hover:text-white flex items-center gap-2 transition-colors text-sm uppercase tracking-wider bg-black/20 p-2 rounded-lg backdrop-blur-sm hover:bg-black/50 shadow-lg border border-white/5"
                    title="Voltar ao Cadastro"
                  >
                     <ArrowLeft size={18} /> Voltar
                  </motion.button>
              )}
          </AnimatePresence>

          <Hero data={quoteData} />

          <div className="relative z-10">
            <UpsellList 
              category={category} setCategory={setCategory}
              serviceId={serviceId} setServiceId={setServiceId}
              hours={hours} setHours={setHours}
              qty={qty} setQty={setQty}
              addDrone={addDrone} setAddDrone={setAddDrone}
              addRealTime={addRealTime} setAddRealTime={setAddRealTime}
              distance={distance}
              pricePerKm={quoteData.pricePerKm}
              locationClient={clientData.location}
              onOpenMap={() => setIsMapOpen(true)}
              selectionMode={selectionMode}
              setSelectionMode={setSelectionMode}
            />
          </div>

          <AnimatePresence>
            {showScrollIndicator && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="fixed bottom-36 md:bottom-36 left-1/2 -translate-x-1/2 z-50 pointer-events-none text-white drop-shadow-md"
              >
                 <motion.div
                    animate={{ y: [0, 8, 0] }}
                    transition={{ duration: 1.5, repeat: Infinity, ease: "easeInOut" }}
                    className="flex flex-col items-center"
                 >
                    <ChevronsDown size={28} className="animate-pulse" />
                 </motion.div>
              </motion.div>
            )}
          </AnimatePresence>

          <AnimatePresence>
            {showFooter && (
                <StickyFooter 
                    totalPrice={totalPrice} 
                    onApprove={handleStartApproval} 
                    isApproved={isApproved}
                    highlight={true} 
                />
            )}
          </AnimatePresence>
      </div>

      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={quoteData}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={summaryDetails}
                priceBreakdown={priceBreakdown}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
                onRemoveAddon={handleRemoveAddon}
            />
         )}
      </AnimatePresence>

      <AddonUpsellModal 
        isOpen={showUpsell}
        onClose={() => setShowUpsell(false)}
        onConfirm={handleConfirmUpsell}
        addDrone={addDrone}
        setAddDrone={setAddDrone}
        addRealTime={addRealTime}
        setAddRealTime={setAddRealTime}
        totalPrice={totalPrice}
      />

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleUpdateLocation}
        initialAddress={clientData.location}
      />
    </div>
  );
};

export default QuoteView;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Camera, Video, Gift, Crown, GraduationCap, Heart, 
  Store, Aperture, Plane, Clock, Minus, Plus, Route, Star, 
  Edit, Smartphone as SmartphoneIcon, Sparkles, Gem, HelpCircle, X, MessageCircle, Hand, CheckCircle2, HeartHandshake, Zap, Info, Lock, Timer, CircleHelp
} from 'lucide-react';

import { cn, formatCurrency, smoothScrollTo } from '../../lib/utils';
import { fadeInUp, staggerContainer, modalVariants } from '../../lib/animations';
import { ServiceCategory, ServiceId } from '../../types';
import AnimatedNumber from '../ui/AnimatedNumber';
import { AppConfig } from '../../config/AppConfig';

interface UpsellListProps {
  category: ServiceCategory;
  setCategory: (c: ServiceCategory) => void;
  serviceId: ServiceId;
  setServiceId: (s: ServiceId) => void;
  hours: number;
  setHours: (h: number) => void;
  qty: number;
  setQty: (q: number) => void;
  addDrone: boolean;
  setAddDrone: (b: boolean) => void;
  addRealTime: boolean;
  setAddRealTime: (b: boolean) => void;
  distance: number;
  pricePerKm: number;
  locationClient: string;
  onOpenMap?: () => void;
  selectionMode?: 'duration' | 'quantity';
  setSelectionMode?: (mode: 'duration' | 'quantity') => void;
}

const UpsellList: React.FC<UpsellListProps> = (props) => {
  const { 
    category, setCategory, serviceId, setServiceId,
    hours, setHours, qty, setQty, addDrone, setAddDrone, addRealTime, setAddRealTime,
    distance, pricePerKm, locationClient, onOpenMap, selectionMode, setSelectionMode 
  } = props;

  // Estado para controlar o modal de informações
  const [infoData, setInfoData] = useState<{ title: string; desc: string; price: string } | null>(null);
  const [showTutorial, setShowTutorial] = useState(true);

  // === READ FROM APP CONFIG ===
  const TABLE = AppConfig.PRICING_TABLE;

  const categories = [
    { id: 'wedding', label: 'Casamento', icon: Heart },
    { id: 'social', label: 'Social', icon: Gift },
    { id: 'commercial', label: 'Comercial', icon: Store },
    { id: 'studio', label: 'Estúdio', icon: Aperture },
    { id: 'video_production', label: 'Produção', icon: Video },
    { id: 'custom', label: 'Outros', icon: Star },
  ];

  const handleInteraction = () => { if (showTutorial) setShowTutorial(false); };

  const handleServiceSelect = (id: ServiceId, mode: 'duration' | 'quantity' = 'duration') => {
    setServiceId(id);
    if (setSelectionMode) setSelectionMode(mode);
    handleInteraction();

    // Smart Defaults (UX)
    if (id === 'comm_photo') setQty(20);
    else if (id === 'comm_video') setQty(1);
    else if (id === 'studio_photo') setQty(10);

    setTimeout(() => {
        const needsDuration = (category === 'social' || category === 'studio') && mode === 'duration';
        const needsQty = (category === 'commercial' || category === 'video_production' || category === 'studio') && mode === 'quantity';

        if (needsDuration) smoothScrollTo('duration-card');
        else if (needsQty) smoothScrollTo('qty-card');
    }, 250);
  };

  // Visibility Logic
  const showDuration = (category === 'wedding' || (category === 'social' && serviceId !== 'graduation') || (category === 'studio' && serviceId === 'studio_video') || category === 'video_production');
  const showQuantity = (category === 'commercial') || (category === 'studio' && serviceId === 'studio_photo') || (category === 'video_production' && serviceId === 'edit_only');
  const isSocialTimeBased = category === 'social' && (serviceId === 'birthday' || serviceId === 'fifteen');
  const canChooseMode = category === 'social' && serviceId !== 'graduation';

  const isNoTravelCost = category === 'studio' || category === 'custom' || serviceId === 'edit_only';
  const travelCost = isNoTravelCost ? 0 : distance * 2 * pricePerKm;

  return (
    <section className="pt-8 pb-48 px-4 md:px-8 bg-neutral-900/30 min-h-screen relative z-10" onClick={handleInteraction}>
      <div className="max-w-5xl mx-auto space-y-12">

        {/* === CATEGORY SELECTOR === */}
        <div className="space-y-8 text-center">
            <p className="text-[10px] uppercase tracking-[0.3em] text-neutral-500 font-medium">Selecione a Ocasião</p>
            <div className="flex flex-wrap justify-center gap-3 relative">
                {categories.map((cat) => {
                    const isActive = category === cat.id;
                    const Icon = cat.icon;
                    return (
                        <div key={cat.id} className="relative">
                            <motion.button
                                whileHover={{ scale: 1.05 }}
                                whileTap={{ scale: 0.95 }}
                                onClick={(e) => { e.stopPropagation(); setCategory(cat.id as ServiceCategory); handleInteraction(); }}
                                className={cn(
                                    "flex items-center gap-3 px-6 py-3 rounded-full transition-all duration-300 text-xs font-bold uppercase tracking-widest border",
                                    isActive 
                                        ? "bg-brand-DEFAULT border-brand-DEFAULT text-white shadow-[0_0_25px_var(--brand-glow)]" 
                                        : "bg-neutral-900/80 border-white/5 text-neutral-400 hover:border-white/20 hover:text-white backdrop-blur-sm"
                                )}
                            >
                                <Icon size={14} className={isActive ? "text-white" : "text-neutral-500"} />
                                {cat.label}
                            </motion.button>

                            <AnimatePresence>
                                {showTutorial && cat.id === 'social' && (
                                    <motion.div
                                        initial={{ opacity: 0, y: 10 }}
                                        animate={{ opacity: 0.6, y: 0, scale: [1, 0.9, 1] }} 
                                        exit={{ opacity: 0, scale: 0.5 }}
                                        transition={{ y: { duration: 0.5 }, scale: { repeat: Infinity, duration: 1.5 } }}
                                        className="absolute -bottom-8 left-1/2 -translate-x-1/2 text-white pointer-events-none z-[100]"
                                    >
                                         <Hand className="fill-white/20 rotate-[-15deg] drop-shadow-[0_0_10px_rgba(255,255,255,0.8)]" size={24} />
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </div>
                    )
                })}
            </div>

             <motion.div key={category} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                <p className="text-neutral-400 font-serif italic text-base md:text-lg max-w-2xl mx-auto">
                    "{AppConfig.TEXTS.CATEGORY_DESCRIPTIONS[category]}"
                </p>
            </motion.div>
        </div>

        {canChooseMode && setSelectionMode && (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center gap-4 bg-white/5 p-6 rounded-3xl border border-white/10 max-w-lg mx-auto">
                <p className="text-[10px] text-neutral-500 uppercase tracking-widest flex items-center gap-2">
                    <Info size={12} /> Como deseja contratar?
                </p>
                <div className="flex bg-black/40 p-1.5 rounded-full border border-white/5">
                    <button onClick={() => setSelectionMode('duration')} className={cn("px-6 py-3 rounded-full text-xs font-bold transition-all flex items-center gap-2", selectionMode === 'duration' ? "bg-brand-DEFAULT text-white shadow-lg" : "text-neutral-500 hover:text-white")}>
                        <Clock size={14} /> POR TEMPO
                    </button>
                    <button onClick={() => setSelectionMode('quantity')} className={cn("px-6 py-3 rounded-full text-xs font-bold transition-all flex items-center gap-2", selectionMode === 'quantity' ? "bg-brand-DEFAULT text-white shadow-lg" : "text-neutral-500 hover:text-white")}>
                        <Camera size={14} /> POR FOTO
                    </button>
                </div>
            </motion.div>
        )}

        {/* === SERVICE GRID === */}
        <motion.div 
            key={category} 
            variants={staggerContainer}
            initial="hidden"
            animate="visible"
            className="grid grid-cols-1 md:grid-cols-3 gap-6"
        >
             {/* Wedding Options */}
             {category === 'wedding' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'wedding_base'} 
                        onClick={() => handleServiceSelect('wedding_base')} 
                        onInfo={setInfoData}
                        icon={Heart} title={TABLE.wedding.wedding_base.label} price={formatCurrency(TABLE.wedding.wedding_base.base)} desc="Cerimônia Essencial" 
                    />
                    <ServiceCard 
                        active={serviceId === 'wedding_classic'} 
                        onClick={() => handleServiceSelect('wedding_classic')} 
                        onInfo={setInfoData}
                        icon={Sparkles} title={TABLE.wedding.wedding_classic.label} price={formatCurrency(TABLE.wedding.wedding_classic.base)} desc="Pré-Wedding + Cerimônia" highlight 
                    />
                    <ServiceCard 
                        active={serviceId === 'wedding_essence'} 
                        onClick={() => handleServiceSelect('wedding_essence')} 
                        onInfo={setInfoData}
                        icon={Gem} title={TABLE.wedding.wedding_essence.label} price={formatCurrency(TABLE.wedding.wedding_essence.base)} desc="Cobertura Completa + Drone" highlight 
                    />
                </>
            )}

            {/* Social Options */}
            {category === 'social' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'birthday'} 
                        onClick={() => handleServiceSelect('birthday')} 
                        onInfo={setInfoData}
                        icon={Gift} title={TABLE.social.birthday.label} price="A partir de R$ 400" desc="Cobertura de 2 Horas ou por Foto" 
                    />
                    <ServiceCard 
                        active={serviceId === 'fifteen'} 
                        onClick={() => handleServiceSelect('fifteen')} 
                        onInfo={setInfoData}
                        icon={Crown} title={TABLE.social.fifteen.label} price="A partir de R$ 450" desc="Festa e Detalhes" 
                    />
                    <ServiceCard 
                        active={serviceId === 'graduation'} 
                        onClick={() => handleServiceSelect('graduation')} 
                        onInfo={setInfoData}
                        icon={GraduationCap} title={TABLE.social.graduation.label} price={formatCurrency(TABLE.social.graduation.base)} desc="Evento Completo" 
                    />
                </>
            )}

            {/* Commercial Options */}
            {category === 'commercial' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'comm_photo'} 
                        onClick={() => handleServiceSelect('comm_photo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Camera} title={TABLE.commercial.photo.label} price={`R$ ${TABLE.commercial.photo.unit}/un`} desc="Alta Conversão" 
                    />
                    <ServiceCard 
                        active={serviceId === 'comm_video'} 
                        onClick={() => handleServiceSelect('comm_video', 'quantity')} 
