import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence, Variants } from 'framer-motion';
import { ArrowRight, Calendar, MapPin, User, Smartphone, CheckCircle2, Loader2, XCircle, AlertCircle, Map as MapIcon, ArrowLeft, Info } from 'lucide-react';
import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button';
import LocationMapModal from '../components/ui/LocationMapModal';
import { ClientData } from '../types';
import { CalendarService } from '../services/CalendarService';

interface WelcomeViewProps {
  onStart: (data: ClientData) => void;
  onAdminClick?: () => void;
  onBack?: () => void;
}

const introContainer: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.15, delayChildren: 0.1 } 
  }
};

const logoVariant: Variants = {
  hidden: { opacity: 0, y: 180, scale: 1.1 },
  visible: { 
    opacity: 1, y: 0, scale: 1,
    transition: { duration: 1.0, ease: [0.25, 0.1, 0.25, 1.0] } 
  }
};

const formVariant: Variants = {
  hidden: { opacity: 0, y: 40 },
  visible: { 
    opacity: 1, y: 0,
    transition: { duration: 0.6, ease: "easeOut" } 
  }
};

const SmartInput = ({ 
  icon: Icon, name, type = "text", placeholder, value, onChange, minLength = 3, className,
  externalStatus = null, errorMessage = "", rightElement = null, iconColor = "text-neutral-500", ...props 
}: any) => {
  const [internalStatus, setInternalStatus] = useState<'idle' | 'typing' | 'loading' | 'valid'>('idle');
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const status = externalStatus || internalStatus;

  useEffect(() => {
    if (externalStatus !== null) return;
    if (!value) {
      setInternalStatus('idle');
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      return;
    }
    setInternalStatus('typing');
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => {
      setInternalStatus('loading');
      setTimeout(() => {
        if (value.length >= minLength) setInternalStatus('valid');
        else setInternalStatus('idle');
      }, 500); 
    }, 600); 
    return () => { if (timeoutRef.current) clearTimeout(timeoutRef.current); };
  }, [value, minLength, externalStatus]);

  const paddingRight = rightElement ? 'pr-20' : 'pr-8';

  return (
    <div className="group relative">
      <Icon className={`absolute left-0 top-3 group-focus-within:text-brand-DEFAULT transition-colors ${iconColor}`} size={20} />
      <input 
        type={type} 
        name={name}
        required
        placeholder={placeholder}
        value={value}
        onChange={onChange}
        className={`w-full bg-transparent border-b border-white/20 py-3 pl-8 ${paddingRight} text-white focus:outline-none focus:border-brand-DEFAULT transition-colors placeholder:text-neutral-600 selection:bg-brand-DEFAULT selection:text-white ${className} ${status === 'error' ? 'border-red-500/50 text-red-100' : ''}`}
        {...props}
      />
      {rightElement && <div className="absolute right-0 top-1.5 z-20">{rightElement}</div>}

      <AnimatePresence mode="wait">
        {!rightElement && status === 'loading' && (
          <motion.div key="loader" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute right-0 top-3 text-neutral-400">
            <Loader2 size={18} className="animate-spin" />
          </motion.div>
        )}
        {!rightElement && status === 'valid' && (
          <motion.div key="success" initial={{ scale: 0 }} animate={{ scale: 1 }} exit={{ scale: 0 }} className="absolute right-0 top-3 text-emerald-500">
            <CheckCircle2 size={20} />
          </motion.div>
        )}
        {status === 'error' && (
           <motion.div key="error" initial={{ scale: 0 }} animate={{ scale: 1 }} exit={{ scale: 0 }} className={`absolute top-3 text-red-500 ${rightElement ? 'right-10' : 'right-0'}`}>
             <XCircle size={20} />
           </motion.div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {status === 'error' && errorMessage && (
            <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                <p className="text-red-400 text-xs mt-1 flex items-center gap-1"><AlertCircle size={10} /> {errorMessage}</p>
            </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

const WelcomeView: React.FC<WelcomeViewProps> = ({ onStart, onAdminClick, onBack }) => {
  const [formData, setFormData] = useState<ClientData>({
    name: '', location: '', date: '', contact: ''
  });
  const [isMapOpen, setIsMapOpen] = useState(false);
  const [dateStatus, setDateStatus] = useState<'idle' | 'loading' | 'valid' | 'error'>('idle');
  const [dateMessage, setDateMessage] = useState('');
  const dateTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const today = new Date().toLocaleDateString('en-CA');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;

    if (name === 'contact') {
        const numericValue = value.replace(/\D/g, ''); 
        if (numericValue.length > 15) return;
        setFormData({ ...formData, [name]: numericValue });
        return;
    }

    if (name === 'date') {
        if (value && value < today) {
            setDateStatus('error');
            setDateMessage("A data não pode ser anterior a hoje.");
            setFormData({ ...formData, [name]: value });
            return;
        }
        if (!value) {
            setDateStatus('idle');
            setFormData({ ...formData, [name]: value });
            return;
        }
        setDateStatus('loading');
        if (dateTimeoutRef.current) clearTimeout(dateTimeoutRef.current);
        dateTimeoutRef.current = setTimeout(async () => {
            const result = await CalendarService.checkAvailability(value);
            if (result.available) {
                setDateStatus('valid');
                setDateMessage('');
            } else {
                setDateStatus('error');
                setDateMessage(result.message || "Data indisponível");
            }
        }, 500); 
    }
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleLocationSelect = (address: string) => {
      setFormData(prev => ({ ...prev, location: address }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.contact && dateStatus === 'valid') {
      onStart(formData);
    }
  };

  const isFormValid = formData.name.length > 2 && formData.location.length > 3 && formData.date.length > 0 && dateStatus === 'valid' && formData.contact.length >= 8;

  return (
    <div className="w-full min-h-[100dvh] flex flex-col items-center justify-center relative overflow-hidden px-6 py-12">
      {onBack && (
          <button 
            onClick={onBack}
            className="fixed top-6 left-6 z-[60] text-neutral-400 hover:text-white flex items-center gap-2 transition-colors text-sm uppercase tracking-wider bg-black/20 p-2 rounded-lg backdrop-blur-sm hover:bg-black/50"
          >
             <ArrowLeft size={18} /> Voltar
          </button>
      )}

      <motion.div variants={introContainer} initial="hidden" animate="visible" className="relative z-10 w-full max-w-md">
        <motion.div variants={logoVariant} className="flex justify-center mb-8 md:mb-10">
          <Logo className="w-56 md:w-80" animate />
        </motion.div>

        <motion.form variants={formVariant} onSubmit={handleSubmit} className="space-y-6 md:space-y-8 bg-black/60 p-6 md:p-8 rounded-2xl border border-white/5 backdrop-blur-md shadow-2xl relative">
          <div className="absolute top-0 left-8 right-8 h-px bg-gradient-to-r from-transparent via-white/20 to-transparent" />
          <div className="flex flex-col items-center mb-6">
            <h2 className="text-lg md:text-xl text-white font-medium">Novo Orçamento</h2>
            <p className="text-xs text-neutral-500 uppercase tracking-widest font-medium mt-1 w-full text-center">(Preencha corretamente)</p>
          </div>

          <div className="space-y-4 md:space-y-5">
            <SmartInput 
              icon={User}
              name="name"
              placeholder="Seu Nome ou Empresa"
              value={formData.name}
              onChange={handleChange}
              minLength={3}
            />

            <div className="relative">
                <SmartInput 
                icon={MapPin}
                name="location"
                placeholder="Local do Serviço"
                value={formData.location}
                onChange={handleChange}
                minLength={4}
                rightElement={
                    <button 
                    type="button"
                    onClick={() => setIsMapOpen(true)}
                    className="bg-white/10 hover:bg-brand-DEFAULT/20 hover:text-brand-DEFAULT text-neutral-400 p-2 rounded-md transition-all flex items-center gap-1.5 text-xs font-medium border border-white/10"
                    title="Abrir Mapa"
                    >
                    <MapIcon size={14} />
                    <span>Mapa</span>
                    </button>
                }
                />
                <p className="text-[10px] text-neutral-500 mt-1 ml-8 flex items-center gap-1">
                    <Info size={10} /> Use o mapa para maior precisão de frete.
                </p>
            </div>

            <SmartInput 
              icon={Calendar}
              name="date"
              type="date"
              placeholder=""
              value={formData.date}
              onChange={handleChange}
              min={today}
              externalStatus={!formData.date ? 'idle' : dateStatus}
              errorMessage={dateMessage}
              className="[&::-webkit-calendar-picker-indicator]:bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20fill%3D%22none%22%20stroke%3D%22%23FFFFFF%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20viewBox%3D%220%200%2024%2024%22%3E%3Crect%20x%3D%223%22%20y%3D%224%22%20width%3D%2218%22%20height%3D%2218%22%20rx%3D%222%22%20ry%3D%222%22%2F%3E%3Cline%20x1%3D%2216%22%20y1%3D%222%22%20x2%3D%2216%22%20y2%3D%226%22%2F%3E%3Cline%20x1%3D%228%22%20y1%3D%222%22%20x2%3D%228%22%20y2%3D%226%22%2F%3E%3Cline%20x1%3D%223%22%20y1%3D%2210%22%20x2%3D%2221%22%20y2%3D%2210%22%2F%3E%3C%2Fsvg%3E')] [&::-webkit-calendar-picker-indicator]:bg-no-repeat [&::-webkit-calendar-picker-indicator]:bg-center [&::-webkit-calendar-picker-indicator]:w-5 [&::-webkit-calendar-picker-indicator]:h-5 [&::-webkit-calendar-picker-indicator]:cursor-pointer [&::-webkit-calendar-picker-indicator]:opacity-100"
            />

            <SmartInput 
              icon={Smartphone}
              name="contact"
              type="tel" 
              placeholder="Whatsapp (Somente Números)"
              value={formData.contact}
              onChange={handleChange}
              minLength={8}
            />
          </div>

          <motion.div variants={formVariant} className="pt-4">
            <motion.div className="rounded-full" animate={isFormValid ? { boxShadow: ["0 0 0px var(--brand-color)", "0 0 25px var(--brand-glow)", "0 0 0px var(--brand-color)"] } : { boxShadow: "0 0 0px rgba(0,0,0,0)" }} transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}>
              <Button className={`w-full group ${!isFormValid ? 'opacity-50 cursor-not-allowed' : ''}`} size="lg" disabled={!isFormValid}>
                <span className="mr-2 text-sm md:text-base">Visualizar Orçamento</span>
                <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
              </Button>
            </motion.div>
          </motion.div>
        </motion.form>
        <motion.p variants={formVariant} className="text-center text-neutral-600 text-xs md:text-sm mt-8">Experiência Audiovisual High-End</motion.p>
      </motion.div>

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleLocationSelect}
        initialAddress={formData.location}
      />
    </div>
  );
};

export default WelcomeView;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Lock, Save, DollarSign, LogOut, ShieldAlert, Loader2, KeyRound } from 'lucide-react';
import Button from '../components/ui/Button';
import Logo from '../components/ui/Logo';
import { QuoteData } from '../types';
import { fadeInUp, staggerContainer } from '../lib/animations';
import { formatCurrency } from '../lib/utils';
import { AuthService } from '../services/AuthService';

interface AdminDashboardProps {
  currentConfig: QuoteData;
  onUpdateConfig: (newConfig: QuoteData) => void;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentConfig, onUpdateConfig, onExit }) => {
  // Estado de Autenticação
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');

  // Estados de Segurança e Feedback
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [attempts, setAttempts] = useState(0);

  // Estado do Formulário de Edição
  const [formData, setFormData] = useState({
    basePrice: currentConfig.basePrice,
    studioFee: currentConfig.studioFee,
    photoUnitPrice: currentConfig.photoUnitPrice,
    videoUnitPrice: currentConfig.videoUnitPrice,
  });

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();

    setError('');
    setIsLoading(true);

    // Adiciona delay artificial via AuthService
    await AuthService.securityDelay();

    const isValid = await AuthService.verify(password);

    if (isValid) {
      setIsAuthenticated(true);
      setError('');
      setAttempts(0);
    } else {
      const newAttempts = attempts + 1;
      setAttempts(newAttempts);
      setIsLoading(false);
      setPassword('');

      // Lógica de Expulsão (3 tentativas erradas)
      if (newAttempts >= 3) {
        onExit();
      } else {
        setError(`Senha incorreta. Tentativas restantes: ${3 - newAttempts}`);
      }
    }

    setIsLoading(false);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: parseFloat(value) || 0
    }));
  };

  const handleSave = () => {
    onUpdateConfig({
      ...currentConfig,
      ...formData
    });
    alert('Configurações salvas com segurança!');
  };

  // TELA DE LOGIN (SECURE GATE)
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-neutral-950 flex flex-col items-center justify-center p-6 relative overflow-hidden">
        {/* Fundo dinâmico */}
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-neutral-900 via-neutral-950 to-black z-0" />

        <motion.div 
          initial="hidden"
          animate="visible"
          variants={staggerContainer}
          className="relative z-10 w-full max-w-sm bg-neutral-900/80 border border-white/5 p-8 rounded-2xl backdrop-blur-xl shadow-2xl"
        >
          <div className="flex justify-center mb-8">
            <motion.div 
                key="normal"
                initial={{ scale: 0 }} animate={{ scale: 1 }}
                className="p-4 bg-brand-DEFAULT/10 rounded-full text-brand-DEFAULT shadow-[0_0_20px_var(--brand-glow)]"
            >
                <Lock size={32} />
            </motion.div>
          </div>

          <h2 className="text-2xl font-serif text-white text-center mb-2">
            Acesso Restrito
          </h2>
          <p className="text-neutral-500 text-center text-sm mb-8">
            Área exclusiva para administradores.
          </p>

          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-2 relative">
              <div className="absolute left-3 top-3.5 text-neutral-500">
                <KeyRound size={18} />
              </div>
              <input 
                type="password" 
                placeholder="Senha Mestre"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                disabled={isLoading}
                className={`w-full bg-neutral-950 border rounded-lg pl-10 pr-4 py-3 text-white transition-colors focus:outline-none
                  ${error ? 'border-red-500/50 focus:border-red-500' : 'border-white/10 focus:border-brand-DEFAULT'}
                `}
                autoFocus
              />
            </div>

            {error && (
              <motion.div 
                initial={{ opacity: 0, y: -10 }} 
                animate={{ opacity: 1, y: 0 }}
                className="flex items-center gap-2 text-red-400 text-xs pl-1 bg-red-500/10 p-2 rounded"
              >
                <ShieldAlert size={12} />
                <span>{error}</span>
              </motion.div>
            )}

            <div className="flex gap-3 pt-2">
               <Button 
                type="button" 
                variant="secondary" 
                className="w-1/3"
                onClick={onExit}
                disabled={isLoading}
               >
                 Voltar
               </Button>
               <Button 
                type="submit" 
                className="w-2/3 relative"
                disabled={isLoading}
               >
                 {isLoading ? <Loader2 className="animate-spin" size={20} /> : "Autenticar"}
               </Button>
            </div>
          </form>
        </motion.div>

        <div className="mt-8 text-neutral-600 text-xs flex flex-col items-center gap-1">
            <p>Protected by SHA-256 Encryption</p>
            <p className="opacity-50">EAREC Secure System v1.0.2</p>
        </div>
      </div>
    );
  }

  // TELA DE DASHBOARD (Acesso concedido)
  return (
    <div className="min-h-screen bg-neutral-950 text-white font-sans">
      <header className="border-b border-white/5 bg-neutral-900/50 backdrop-blur-md sticky top-0 z-40">
        <div className="max-w-5xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Logo className="w-24" />
            <div className="hidden md:flex items-center gap-4">
               <span className="h-6 w-px bg-white/10" />
               <span className="text-sm font-medium text-neutral-400">Admin Mode</span>
               <span className="text-xs bg-green-500/10 text-green-500 px-2 py-0.5 rounded border border-green-500/20 flex items-center gap-1">
                 <Lock size={10} /> Secure Connection
               </span>
            </div>
          </div>
          <button 
            onClick={onExit}
            className="flex items-center gap-2 text-sm text-neutral-400 hover:text-white transition-colors border border-white/10 px-4 py-2 rounded-full hover:bg-white/5"
          >
            <LogOut size={16} />
            Sair com Segurança
          </button>
        </div>
      </header>

      <main className="max-w-3xl mx-auto py-12 px-6">
        <motion.div 
          initial="hidden" 
          animate="visible" 
          variants={staggerContainer}
        >
          <motion.div variants={fadeInUp} className="flex items-center justify-between mb-8">
            <div>
              <h1 className="text-3xl font-serif mb-2">Configuração de Preços</h1>
              <p className="text-neutral-400">Ajuste os valores base utilizados no cálculo automático dos orçamentos.</p>
            </div>
            <div className="p-3 bg-brand-DEFAULT/10 rounded-lg text-brand-DEFAULT">
              <DollarSign size={24} />
            </div>
          </motion.div>

          <motion.div variants={fadeInUp} className="bg-white/5 border border-white/5 rounded-xl p-8 space-y-8 shadow-inner">
            <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-8 border-b border-white/5">
              <div>
                <label className="block text-sm font-medium text-white mb-2">Preço Base (Mobilização)</label>
                <p className="text-xs text-neutral-500">Valor mínimo para saída da equipe. Incluído em todos os orçamentos.</p>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  name="basePrice"
                  value={formData.basePrice}
                  onChange={handleInputChange}
                  className="w-full bg-neutral-950 border border-white/10 rounded px-4 py-2 text-white focus:border-brand-DEFAULT focus:outline-none focus:ring-1 focus:ring-brand-DEFAULT transition-all"
                />
              </div>
            </motion.div>

            <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-8 border-b border-white/5">
              <div>
                <label className="block text-sm font-medium text-white mb-2">Taxa de Estúdio</label>
                <p className="text-xs text-neutral-500">Adicional cobrado quando o cliente seleciona "Estúdio Controlado".</p>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  name="studioFee"
                  value={formData.studioFee}
                  onChange={handleInputChange}
                  className="w-full bg-neutral-950 border border-white/10 rounded px-4 py-2 text-white focus:border-brand-DEFAULT focus:outline-none focus:ring-1 focus:ring-brand-DEFAULT transition-all"
                />
              </div>
            </motion.div>

            <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-8 border-b border-white/5">
              <div>
                <label className="block text-sm font-medium text-white mb-2">Preço por Foto</label>
                <p className="text-xs text-neutral-500">Valor unitário por fotografia tratada.</p>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  name="photoUnitPrice"
                  value={formData.photoUnitPrice}
                  onChange={handleInputChange}
                  className="w-full bg-neutral-950 border border-white/10 rounded px-4 py-2 text-white focus:border-brand-DEFAULT focus:outline-none focus:ring-1 focus:ring-brand-DEFAULT transition-all"
                />
              </div>
            </motion.div>

            <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <label className="block text-sm font-medium text-white mb-2">Preço por Vídeo</label>
                <p className="text-xs text-neutral-500">Valor unitário por vídeo (1 min).</p>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  name="videoUnitPrice"
                  value={formData.videoUnitPrice}
                  onChange={handleInputChange}
                  className="w-full bg-neutral-950 border border-white/10 rounded px-4 py-2 text-white focus:border-brand-DEFAULT focus:outline-none focus:ring-1 focus:ring-brand-DEFAULT transition-all"
                />
              </div>
            </motion.div>

          </motion.div>

          <motion.div variants={fadeInUp} className="mt-8 flex justify-end gap-4">
            <Button variant="secondary" onClick={onExit}>
              Cancelar
            </Button>
            <Button onClick={handleSave} className="flex items-center gap-2">
              <Save size={18} />
              Salvar Alterações
            </Button>
          </motion.div>

          <motion.div variants={fadeInUp} className="mt-12 p-6 bg-brand-DEFAULT/5 border border-brand-DEFAULT/10 rounded-lg">
            <h3 className="text-sm font-medium text-brand-DEFAULT mb-4">Simulação Atual</h3>
            <div className="flex justify-between text-sm text-neutral-400">
              <span>Orçamento Básico (Externo + 20 Fotos + 1 Vídeo):</span>
              <strong className="text-white">
                {formatCurrency(formData.basePrice + (20 * formData.photoUnitPrice) + (1 * formData.videoUnitPrice))}
              </strong>
            </div>
          </motion.div>
        </motion.div>
      </main>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Camera, Video, Gift, Crown, GraduationCap, Heart, 
  Store, Aperture, Plane, Clock, Minus, Plus, Route, Star, 
  Edit, Smartphone as SmartphoneIcon, Sparkles, Gem, HelpCircle, X, MessageCircle, Hand, CheckCircle2, HeartHandshake, Zap, Info, Lock, Timer, CircleHelp
} from 'lucide-react';

import { cn, formatCurrency, smoothScrollTo } from '../../lib/utils';
import { fadeInUp, staggerContainer, modalVariants } from '../../lib/animations';
import { ServiceCategory, ServiceId } from '../../types';
import AnimatedNumber from '../ui/AnimatedNumber';
import { AppConfig } from '../../config/AppConfig';

interface UpsellListProps {
  category: ServiceCategory;
  setCategory: (c: ServiceCategory) => void;
  serviceId: ServiceId;
  setServiceId: (s: ServiceId) => void;
  hours: number;
  setHours: (h: number) => void;
  qty: number;
  setQty: (q: number) => void;
  addDrone: boolean;
  setAddDrone: (b: boolean) => void;
  addRealTime: boolean;
  setAddRealTime: (b: boolean) => void;
  distance: number;
  pricePerKm: number;
  locationClient: string;
  onOpenMap?: () => void;
  selectionMode?: 'duration' | 'quantity';
  setSelectionMode?: (mode: 'duration' | 'quantity') => void;
}

const UpsellList: React.FC<UpsellListProps> = (props) => {
  const { 
    category, setCategory, serviceId, setServiceId,
    hours, setHours, qty, setQty, addDrone, setAddDrone, addRealTime, setAddRealTime,
    distance, pricePerKm, locationClient, onOpenMap, selectionMode, setSelectionMode 
  } = props;

  // Estado para controlar o modal de informações
  const [infoData, setInfoData] = useState<{ title: string; desc: string; price: string } | null>(null);
  const [showTutorial, setShowTutorial] = useState(true);

  // === READ FROM APP CONFIG ===
  const TABLE = AppConfig.PRICING_TABLE;

  const categories = [
    { id: 'wedding', label: 'Casamento', icon: Heart },
    { id: 'social', label: 'Social', icon: Gift },
    { id: 'commercial', label: 'Comercial', icon: Store },
    { id: 'studio', label: 'Estúdio', icon: Aperture },
    { id: 'video_production', label: 'Produção', icon: Video },
    { id: 'custom', label: 'Outros', icon: Star },
  ];

  const handleInteraction = () => { if (showTutorial) setShowTutorial(false); };

  const handleServiceSelect = (id: ServiceId, mode: 'duration' | 'quantity' = 'duration') => {
    setServiceId(id);
    if (setSelectionMode) setSelectionMode(mode);
    handleInteraction();

    // Smart Defaults (UX)
    if (id === 'comm_photo') setQty(20);
    else if (id === 'comm_video') setQty(1);
    else if (id === 'studio_photo') setQty(10);

    setTimeout(() => {
        const needsDuration = (category === 'wedding' || category === 'social' || category === 'studio') && mode === 'duration';
        const needsQty = (category === 'commercial' || category === 'video_production' || category === 'studio') && mode === 'quantity';

        if (needsDuration) smoothScrollTo('duration-card');
        else if (needsQty) smoothScrollTo('qty-card');
    }, 250);
  };

  // Visibility Logic
  // Alteração: Removido `|| category === 'video_production'` da lógica de duração.
  const showDuration = (category === 'wedding' || (category === 'social' && serviceId !== 'graduation') || (category === 'studio' && serviceId === 'studio_video'));

  // Alteração: Mantém quantidade apenas para comercial, foto estúdio ou edição de vídeo.
  const showQuantity = (category === 'commercial') || (category === 'studio' && serviceId === 'studio_photo') || (category === 'video_production' && serviceId === 'edit_only');

  const isSocialTimeBased = category === 'social' && (serviceId === 'birthday' || serviceId === 'fifteen');
  const canChooseMode = category === 'social' && serviceId !== 'graduation';

  const isNoTravelCost = category === 'studio' || category === 'custom' || serviceId === 'edit_only';
  const travelCost = isNoTravelCost ? 0 : distance * 2 * pricePerKm;

  return (
    <section className="pt-8 pb-48 px-4 md:px-8 bg-neutral-900/30 min-h-screen relative z-10" onClick={handleInteraction}>
      <div className="max-w-5xl mx-auto space-y-12">

        {/* === CATEGORY SELECTOR === */}
        <div className="space-y-8 text-center">
            <p className="text-[10px] uppercase tracking-[0.3em] text-neutral-500 font-medium">Selecione a Ocasião</p>
            <div className="flex flex-wrap justify-center gap-3 relative">
                {categories.map((cat) => {
                    const isActive = category === cat.id;
                    const Icon = cat.icon;
                    return (
                        <div key={cat.id} className="relative">
                            <motion.button
                                whileHover={{ scale: 1.05 }}
                                whileTap={{ scale: 0.95 }}
                                onClick={(e) => { e.stopPropagation(); setCategory(cat.id as ServiceCategory); handleInteraction(); }}
                                className={cn(
                                    "flex items-center gap-3 px-6 py-3 rounded-full transition-all duration-300 text-xs font-bold uppercase tracking-widest border",
                                    isActive 
                                        ? "bg-brand-DEFAULT border-brand-DEFAULT text-white shadow-[0_0_25px_var(--brand-glow)]" 
                                        : "bg-neutral-900/80 border-white/5 text-neutral-400 hover:border-white/20 hover:text-white backdrop-blur-sm"
                                )}
                            >
                                <Icon size={14} className={isActive ? "text-white" : "text-neutral-500"} />
                                {cat.label}
                            </motion.button>

                            <AnimatePresence>
                                {showTutorial && cat.id === 'social' && (
                                    <motion.div
                                        initial={{ opacity: 0, y: 10 }}
                                        animate={{ opacity: 0.6, y: 0, scale: [1, 0.9, 1] }} 
                                        exit={{ opacity: 0, scale: 0.5 }}
                                        transition={{ y: { duration: 0.5 }, scale: { repeat: Infinity, duration: 1.5 } }}
                                        className="absolute -bottom-8 left-1/2 -translate-x-1/2 text-white pointer-events-none z-[100]"
                                    >
                                         <Hand className="fill-white/20 rotate-[-15deg] drop-shadow-[0_0_10px_rgba(255,255,255,0.8)]" size={24} />
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </div>
                    )
                })}
            </div>

             <motion.div key={category} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                <p className="text-neutral-400 font-serif italic text-base md:text-lg max-w-2xl mx-auto">
                    "{AppConfig.TEXTS.CATEGORY_DESCRIPTIONS[category]}"
                </p>
            </motion.div>
        </div>

        {canChooseMode && setSelectionMode && (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center gap-4 bg-white/5 p-6 rounded-3xl border border-white/10 max-w-lg mx-auto">
                <p className="text-[10px] text-neutral-500 uppercase tracking-widest flex items-center gap-2">
                    <Info size={12} /> Como deseja contratar?
                </p>
                <div className="flex bg-black/40 p-1.5 rounded-full border border-white/5">
                    <button onClick={() => setSelectionMode('duration')} className={cn("px-6 py-3 rounded-full text-xs font-bold transition-all flex items-center gap-2", selectionMode === 'duration' ? "bg-brand-DEFAULT text-white shadow-lg" : "text-neutral-500 hover:text-white")}>
                        <Clock size={14} /> POR TEMPO
                    </button>
                    <button onClick={() => setSelectionMode('quantity')} className={cn("px-6 py-3 rounded-full text-xs font-bold transition-all flex items-center gap-2", selectionMode === 'quantity' ? "bg-brand-DEFAULT text-white shadow-lg" : "text-neutral-500 hover:text-white")}>
                        <Camera size={14} /> POR FOTO
                    </button>
                </div>
            </motion.div>
        )}

        {/* === SERVICE GRID === */}
        <motion.div 
            key={category} 
            variants={staggerContainer}
            initial="hidden"
            animate="visible"
            className="grid grid-cols-1 md:grid-cols-3 gap-6"
        >
             {/* Wedding Options */}
             {category === 'wedding' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'wedding_base'} 
                        onClick={() => handleServiceSelect('wedding_base')} 
                        onInfo={setInfoData}
                        icon={Heart} title={TABLE.wedding.wedding_base.label} price={formatCurrency(TABLE.wedding.wedding_base.base)} desc="Cerimônia Essencial" 
                    />
                    <ServiceCard 
                        active={serviceId === 'wedding_classic'} 
                        onClick={() => handleServiceSelect('wedding_classic')} 
                        onInfo={setInfoData}
                        icon={Sparkles} title={TABLE.wedding.wedding_classic.label} price={formatCurrency(TABLE.wedding.wedding_classic.base)} desc="Pré-Wedding + Cerimônia" highlight 
                    />
                    <ServiceCard 
                        active={serviceId === 'wedding_essence'} 
                        onClick={() => handleServiceSelect('wedding_essence')} 
                        onInfo={setInfoData}
                        icon={Gem} title={TABLE.wedding.wedding_essence.label} price={formatCurrency(TABLE.wedding.wedding_essence.base)} desc="Cobertura Completa + Drone" highlight 
                    />
                </>
            )}

            {/* Social Options */}
            {category === 'social' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'birthday'} 
                        onClick={() => handleServiceSelect('birthday')} 
                        onInfo={setInfoData}
                        icon={Gift} title={TABLE.social.birthday.label} price="A partir de R$ 400" desc="Cobertura de 2 Horas ou por Foto" 
                    />
                    <ServiceCard 
                        active={serviceId === 'fifteen'} 
                        onClick={() => handleServiceSelect('fifteen')} 
                        onInfo={setInfoData}
                        icon={Crown} title={TABLE.social.fifteen.label} price="A partir de R$ 450" desc="Festa e Detalhes" 
                    />
                    <ServiceCard 
                        active={serviceId === 'graduation'} 
                        onClick={() => handleServiceSelect('graduation')} 
                        onInfo={setInfoData}
                        icon={GraduationCap} title={TABLE.social.graduation.label} price={formatCurrency(TABLE.social.graduation.base)} desc="Evento Completo" 
                    />
                </>
            )}

            {/* Commercial Options */}
            {category === 'commercial' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'comm_photo'} 
                        onClick={() => handleServiceSelect('comm_photo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Camera} title={TABLE.commercial.photo.label} price={`R$ ${TABLE.commercial.photo.unit}/un`} desc="Alta Conversão" 
                    />
                    <ServiceCard 
                        active={serviceId === 'comm_video'} 
                        onClick={() => handleServiceSelect('comm_video', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Video} title={TABLE.commercial.video.label} price={`R$ ${TABLE.commercial.video.unit}/un`} desc="Reels / TikTok" 
                    />
                    <ServiceCard 
                        active={serviceId === 'comm_combo'} 
                        onClick={() => handleServiceSelect('comm_combo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Star} title={TABLE.commercial.combo.label} price={formatCurrency(TABLE.commercial.combo.videoBase)} desc="Foto + Vídeo" highlight 
                    />
                </>
            )}

            {/* Studio Options */}
            {category === 'studio' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'studio_photo'} 
                        onClick={() => handleServiceSelect('studio_photo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Aperture} title={TABLE.studio.photo.label} price={`R$ ${TABLE.studio.photo.unit}/un`} desc="Estúdio Controlado" 
                    />
                    <ServiceCard 
                        active={serviceId === 'studio_video'} 
                        onClick={() => handleServiceSelect('studio_video', 'duration')} 
                        onInfo={setInfoData}
                        icon={Video} title={TABLE.studio.video.label} price={formatCurrency(TABLE.studio.video.base)} desc="Clipes Cinematográficos" 
                    />
                </>
            )}

            {/* Production Options */}
            {category === 'video_production' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'edit_only'} 
                        onClick={() => handleServiceSelect('edit_only', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Edit} title={TABLE.video_production.edit.label} price={`R$ ${TABLE.video_production.edit.unit}`} desc="Pós-produção" 
                    />
                    <ServiceCard 
                        active={serviceId === 'cam_cap'} 
                        onClick={() => handleServiceSelect('cam_cap', 'duration')} 
                        onInfo={setInfoData}
                        icon={Video} title={TABLE.video_production.cam_cap.label} price={formatCurrency(TABLE.video_production.cam_cap.fixed)} desc="Diária Profissional" 
                    />
                    <ServiceCard 
                        active={serviceId === 'mobile_cap'} 
                        onClick={() => handleServiceSelect('mobile_cap', 'duration')} 
                        onInfo={setInfoData}
                        icon={SmartphoneIcon} title={TABLE.video_production.mobile_cap.label} price={formatCurrency(TABLE.video_production.mobile_cap.fixed)} desc="Captação iPhone" 
                    />
                    <ServiceCard 
                        active={serviceId === 'drone'} 
                        onClick={() => handleServiceSelect('drone', 'duration')} 
                        onInfo={setInfoData}
                        icon={Plane} title={TABLE.video_production.drone.label} price={formatCurrency(TABLE.video_production.drone.fixed)} desc="Imagens Aéreas" 
                    />
                </>
            )}

            {/* Custom Option */}
