                    />
                    <ServiceCard 
                        active={serviceId === 'cam_cap'} 
                        onClick={() => handleServiceSelect('cam_cap', 'duration')} 
                        onInfo={setInfoData}
                        icon={Video} title={TABLE.video_production.cam_cap.label} price={formatCurrency(TABLE.video_production.cam_cap.fixed)} desc="Diária Profissional" 
                    />
                    <ServiceCard 
                        active={serviceId === 'mobile_cap'} 
                        onClick={() => handleServiceSelect('mobile_cap', 'duration')} 
                        onInfo={setInfoData}
                        icon={SmartphoneIcon} title={TABLE.video_production.mobile_cap.label} price={formatCurrency(TABLE.video_production.mobile_cap.fixed)} desc="Captação iPhone" 
                    />
                    <ServiceCard 
                        active={serviceId === 'drone'} 
                        onClick={() => handleServiceSelect('drone', 'duration')} 
                        onInfo={setInfoData}
                        icon={Plane} title={TABLE.video_production.drone.label} price={formatCurrency(TABLE.video_production.drone.fixed)} desc="Imagens Aéreas" 
