                    />
                    <ServiceCard 
                        active={serviceId === 'fifteen'} 
                        onClick={() => handleServiceSelect('fifteen')} 
                        onInfo={setInfoData}
                        icon={Crown} title={TABLE.social.fifteen.label} price="A partir de R$ 450 ou 25/foto" desc="Festa e Detalhes" 
                    />
                    <ServiceCard 
                        active={serviceId === 'graduation'} 
                        onClick={() => handleServiceSelect('graduation')} 
                        onInfo={setInfoData}
                        icon={GraduationCap} title={TABLE.social.graduation.label} price={formatCurrency(TABLE.social.graduation.base)} desc="Evento Completo" 
                    />
                </>
            )}

            {/* Commercial Options */}
            {category === 'commercial' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'comm_photo'} 
                        onClick={() => handleServiceSelect('comm_photo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Camera} title={TABLE.commercial.photo.label} price={`R$ ${TABLE.commercial.photo.unit}/un`} desc="Alta Conversão" 
                    />
                    <ServiceCard 
                        active={serviceId === 'comm_video'} 
                        onClick={() => handleServiceSelect('comm_video', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Video} title={TABLE.commercial.video.label} price={`R$ ${TABLE.commercial.video.unit}/un`} desc="Reels / TikTok" 
                    />
                    <ServiceCard 
                        active={serviceId === 'comm_combo'} 
                        onClick={() => handleServiceSelect('comm_combo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Star} title={TABLE.commercial.combo.label} price={formatCurrency(TABLE.commercial.combo.videoBase)} desc="Foto + Vídeo" highlight 
                    />
                </>
            )}

            {/* Studio Options */}
            {category === 'studio' && (
                <>
                    <ServiceCard 
                        active={serviceId === 'studio_photo'} 
                        onClick={() => handleServiceSelect('studio_photo', 'quantity')} 
                        onInfo={setInfoData}
                        icon={Aperture} title={TABLE.studio.photo.label} price={`R$ ${TABLE.studio.photo.unit}/un`} desc="Estúdio Controlado" 
                    />
                    <ServiceCard 
                        active={serviceId === 'studio_video'} 
                        onClick={() => handleServiceSelect('studio_video', 'duration')} 
                        onInfo={setInfoData}
                        icon={Video} title={TABLE.studio.video.label} price={formatCurrency(TABLE.studio.video.base)} desc="Clipes Cinematográficos" 
                    />
                </>
            )}

            {/* Production Options */}
            {category === 'video_production' && (
                <>
