                        <div className="w-full h-1 bg-white/5 rounded-full mt-10 overflow-hidden">
                            <motion.div className="h-full bg-brand-DEFAULT shadow-[0_0_15px_var(--brand-color)]" animate={{ width: `${Math.min(100, (qty/100)*100)}%` }} />
                        </div>
