import React from 'react';
import { motion } from 'framer-motion';

/**
 * Componente SVG: Tira de Filme (Film Strip)
 * Renderiza uma tira vertical infinita com animação de rolagem contínua.
 */
const FilmStripTexture = ({ className, speed = 5, direction = 1 }: { className?: string, speed?: number, direction?: number }) => (
  <svg
    viewBox="0 0 100 100"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    preserveAspectRatio="none"
  >
    {/* Definição do Padrão de Furos (Sprockets) e Quadros */}
    <defs>
      {/* O padrão tem altura 60. Para o loop ser perfeito, a animação deve deslocar exatamente 60 unidades. */}
      <pattern id="film-holes" x="0" y="0" width="100" height="60" patternUnits="userSpaceOnUse">
         {/* Furos Esquerdos */}
         <rect x="5" y="15" width="10" height="20" rx="2" fill="currentColor" fillOpacity="0.6" />
         {/* Furos Direitos */}
         <rect x="85" y="15" width="10" height="20" rx="2" fill="currentColor" fillOpacity="0.6" />
         {/* Linha divisória de quadro (Frame Line) */}
         <line x1="20" y1="59" x2="80" y2="59" stroke="currentColor" strokeWidth="2" strokeOpacity="0.3" />
      </pattern>
    </defs>

    {/* Fundo sutil da tira */}
    <rect x="18" width="64" height="100%" fill="currentColor" fillOpacity="0.03" />

    {/* Bordas da área de imagem */}
    <line x1="20" y1="0" x2="20" y2="100%" stroke="currentColor" strokeWidth="1" strokeOpacity="0.5" />
    <line x1="80" y1="0" x2="80" y2="100%" stroke="currentColor" strokeWidth="1" strokeOpacity="0.5" />

    {/* 
        ANIMAÇÃO DE ROLAGEM (Infinite Scroll)
        O rect é preenchido com o padrão. Movemos o Y do rect (ou do fill via y) 
        para simular o movimento da fita.
    */}
    <motion.rect 
      x="0"
      y="-60" // Começa com offset para ter espaço de buffer
      width="100" 
      height="200%" // Altura extra para cobrir o deslocamento
      fill="url(#film-holes)"
      animate={{ 
        y: direction > 0 ? [0, -60] : [-60, 0] 
      }}
      transition={{ 
        repeat: Infinity, 
        ease: "linear", 
        duration: speed 
      }}
    />
  </svg>
);

const BackgroundFilmStrips: React.FC = () => {
  return (
    <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden h-screen w-screen">

      {/* 
        Tira Esquerda (Descendo suavemente) 
        Opacidade reduzida para não brigar com o conteúdo.
      */}
      <div className="absolute top-0 bottom-0 left-0 w-16 md:w-24 border-r border-white/5 bg-black/20 text-brand-DEFAULT/15">
         <FilmStripTexture className="w-full h-full" speed={8} direction={1} />
      </div>

      {/* 
        Tira Direita (Subindo suavemente - Contrafluxo)
        Dá um movimento mais dinâmico e cinematográfico.
      */}
      <div className="absolute top-0 bottom-0 right-0 w-16 md:w-24 border-l border-white/5 bg-black/20 text-brand-DEFAULT/15">
         <FilmStripTexture className="w-full h-full" speed={12} direction={-1} />
      </div>

      {/* Vignette Global para focar no centro */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.8)_100%)] pointer-events-none" />
    </div>
  );
};

