import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Camera, Video, Gift, Crown, GraduationCap, Heart, 
  Store, Aperture, Plane, Clock, Minus, Plus, Route, Star, 
  Edit, Smartphone as SmartphoneIcon, Sparkles, Gem, HelpCircle, X, MessageCircle, Hand, Check 
} from 'lucide-react';

import { cn, formatCurrency } from '../../lib/utils';
import { fadeInUp, staggerContainer, modalVariants } from '../../lib/animations';
import { ServiceCategory, ServiceId } from '../../types';
import AnimatedNumber from '../ui/AnimatedNumber';
import { AppConfig } from '../../config/AppConfig';
import Button from '../ui/Button';

interface UpsellListProps {
  category: ServiceCategory;
  setCategory: (c: ServiceCategory) => void;
  serviceId: ServiceId;
  setServiceId: (s: ServiceId) => void;
  hours: number;
  setHours: (h: number) => void;
  qty: number;
  setQty: (q: number) => void;
  addDrone: boolean;
  setAddDrone: (b: boolean) => void;
  addRealTime: boolean;
  setAddRealTime: (b: boolean) => void;
  distance: number;
  pricePerKm: number;
  locationClient: string;
  onOpenMap?: () => void;
  selectionMode?: 'duration' | 'quantity';
  setSelectionMode?: (mode: 'duration' | 'quantity') => void;
  // Nova prop para controlar o que é exibido
  viewMode?: 'categories' | 'services' | 'config';
}

const UpsellList: React.FC<UpsellListProps> = (props) => {
  const { 
    category, setCategory, serviceId, setServiceId,
    hours, setHours, qty, setQty, addDrone, setAddDrone, addRealTime, setAddRealTime,
    distance, pricePerKm, locationClient, onOpenMap, selectionMode, setSelectionMode,
    viewMode = 'categories' // Default para compatibilidade, mas será controlado pelo pai
  } = props;

  const [infoData, setInfoData] = useState<{ title: string; desc: string; price: string } | null>(null);

  // === READ FROM APP CONFIG ===
  const TABLE = AppConfig.PRICING_TABLE;

  const categories = [
    { id: 'wedding', label: 'Casamento', icon: Heart },
    { id: 'social', label: 'Social', icon: Gift },
    { id: 'commercial', label: 'Comercial', icon: Store },
    { id: 'studio', label: 'Estúdio', icon: Aperture },
    { id: 'video_production', label: 'Freelancer', icon: Video },
    { id: 'custom', label: 'Outros', icon: Star },
  ];

  const handleServiceSelect = (id: ServiceId, mode: 'duration' | 'quantity' = 'duration') => {
    setServiceId(id);
    if (setSelectionMode) setSelectionMode(mode);

    // Smart Defaults (UX)
    if (id === 'comm_photo') setQty(20);
    else if (id === 'comm_video') setQty(1);
    else if (id === 'studio_photo') setQty(8);
    else if (category === 'social') setQty(10);
  };

  // === VISIBILITY LOGIC ===
  const showDuration = (category === 'wedding') || 
                       (category === 'social' && selectionMode === 'duration') ||
                       (category === 'studio' && selectionMode === 'duration') ||
                       (category === 'video_production' && serviceId !== 'edit_only');

  const showQuantity = (category === 'commercial') || 
                       (category === 'social' && selectionMode === 'quantity') ||
                       (category === 'studio' && selectionMode === 'quantity') ||
                       (category === 'video_production' && serviceId === 'edit_only');

  const canChooseMode = category === 'social' && serviceId !== 'graduation';

  const isNoTravelCost = category === 'studio' || category === 'custom' || serviceId === 'edit_only';
  const travelCost = isNoTravelCost ? 0 : distance * 2 * pricePerKm;

  // Lógica de Mínimo
  let minQty = 1;
  if (category === 'studio' && serviceId === 'studio_photo') minQty = 8;
  if (category === 'social') minQty = 10;

  // Renderização Condicional baseada no viewMode
  return (
    <section className="w-full max-w-4xl mx-auto">

      {/* === STEP 1: CATEGORY SELECTION === */}
      {viewMode === 'categories' && (
        <div className="space-y-12 text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-wrap justify-center gap-4 relative">
                {categories.map((cat) => {
                    const isActive = category === cat.id;
                    const Icon = cat.icon;
                    return (
                        <motion.button
                            key={cat.id}
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => setCategory(cat.id as ServiceCategory)}
                            className={cn(
                                "flex flex-col items-center justify-center gap-3 w-32 h-32 rounded-2xl transition-all duration-300 border",
                                isActive 
                                    ? "bg-brand-DEFAULT border-brand-DEFAULT text-white shadow-[0_0_25px_var(--brand-glow)]" 
                                    : "bg-white/5 border-white/5 text-neutral-400 hover:border-white/20 hover:text-white hover:bg-white/10"
                            )}
                        >
                            <Icon size={32} className={isActive ? "text-white" : "text-neutral-500"} />
                            <span className="text-xs font-bold uppercase tracking-widest">{cat.label}</span>
                        </motion.button>
                    )
                })}
            </div>

             <motion.div 
                key={category} 
                initial={{ opacity: 0, y: 10 }} 
                animate={{ opacity: 1, y: 0 }}
                className="bg-white/5 p-6 rounded-xl border border-white/10 max-w-lg mx-auto"
            >
                <p className="text-neutral-300 font-serif italic text-lg">
                    "{AppConfig.TEXTS.CATEGORY_DESCRIPTIONS[category]}"
                </p>
            </motion.div>
        </div>
      )}

      {/* === STEP 2: SERVICE SELECTION === */}
      {viewMode === 'services' && (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-8 duration-500">

             {/* Modo de Seleção (Se aplicável) */}
             {canChooseMode && setSelectionMode && (
                <div className="flex justify-center mb-8">
                    <div className="flex bg-black/40 p-1.5 rounded-full border border-white/5">
                        <button onClick={() => setSelectionMode('duration')} className={cn("px-6 py-3 rounded-full text-xs font-bold transition-all flex items-center gap-2", selectionMode === 'duration' ? "bg-brand-DEFAULT text-white shadow-lg" : "text-neutral-500 hover:text-white")}>
                            <Clock size={14} /> POR TEMPO
                        </button>
                        <button onClick={() => setSelectionMode('quantity')} className={cn("px-6 py-3 rounded-full text-xs font-bold transition-all flex items-center gap-2", selectionMode === 'quantity' ? "bg-brand-DEFAULT text-white shadow-lg" : "text-neutral-500 hover:text-white")}>
                            <Camera size={14} /> POR FOTO
                        </button>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                 {/* Wedding Options */}
                 {category === 'wedding' && (
                    <>
                        <ServiceCard active={serviceId === 'wedding_base'} onClick={() => handleServiceSelect('wedding_base')} onInfo={setInfoData} icon={Heart} title={TABLE.wedding.wedding_base.label} price={formatCurrency(TABLE.wedding.wedding_base.base)} desc="Cerimônia Essencial" />
                        <ServiceCard active={serviceId === 'wedding_classic'} onClick={() => handleServiceSelect('wedding_classic')} onInfo={setInfoData} icon={Sparkles} title={TABLE.wedding.wedding_classic.label} price={formatCurrency(TABLE.wedding.wedding_classic.base)} desc="Pré-Wedding + Cerimônia" highlight />
                        <ServiceCard active={serviceId === 'wedding_essence'} onClick={() => handleServiceSelect('wedding_essence')} onInfo={setInfoData} icon={Gem} title={TABLE.wedding.wedding_essence.label} price={formatCurrency(TABLE.wedding.wedding_essence.base)} desc="Cobertura Completa + Drone" highlight />
                    </>
                )}

                {/* Social Options */}
                {category === 'social' && (
                    <>
                        <ServiceCard active={serviceId === 'birthday'} onClick={() => handleServiceSelect('birthday')} onInfo={setInfoData} icon={Gift} title={TABLE.social.birthday.label} price="A partir de R$ 400" desc="Cobertura Flexível" />
                        <ServiceCard active={serviceId === 'fifteen'} onClick={() => handleServiceSelect('fifteen')} onInfo={setInfoData} icon={Crown} title={TABLE.social.fifteen.label} price="A partir de R$ 450" desc="Festa e Detalhes" />
                        <ServiceCard active={serviceId === 'graduation'} onClick={() => handleServiceSelect('graduation')} onInfo={setInfoData} icon={GraduationCap} title={TABLE.social.graduation.label} price={formatCurrency(TABLE.social.graduation.base)} desc="Evento Completo" />
                    </>
                )}

                {/* Commercial Options */}
                {category === 'commercial' && (
                    <>
                        <ServiceCard active={serviceId === 'comm_photo'} onClick={() => handleServiceSelect('comm_photo', 'quantity')} onInfo={setInfoData} icon={Camera} title={TABLE.commercial.photo.label} price={`R$ ${TABLE.commercial.photo.unit}/un`} desc="Alta Conversão" />
                        <ServiceCard active={serviceId === 'comm_video'} onClick={() => handleServiceSelect('comm_video', 'quantity')} onInfo={setInfoData} icon={Video} title={TABLE.commercial.video.label} price={`R$ ${TABLE.commercial.video.unit}/un`} desc="Reels / TikTok" />
                        <ServiceCard active={serviceId === 'comm_combo'} onClick={() => handleServiceSelect('comm_combo', 'quantity')} onInfo={setInfoData} icon={Star} title={TABLE.commercial.combo.label} price={formatCurrency(TABLE.commercial.combo.videoBase)} desc="Foto + Vídeo" highlight />
                    </>
                )}

                {/* Studio Options */}
                {category === 'studio' && (
                    <>
                        <ServiceCard active={serviceId === 'studio_photo'} onClick={() => handleServiceSelect('studio_photo', 'quantity')} onInfo={setInfoData} icon={Aperture} title={TABLE.studio.photo.label} price={`R$ ${TABLE.studio.photo.unit}/un`} desc="Estúdio Controlado" />
                        <ServiceCard active={serviceId === 'studio_video'} onClick={() => handleServiceSelect('studio_video', 'duration')} onInfo={setInfoData} icon={Video} title={TABLE.studio.video.label} price={formatCurrency(TABLE.studio.video.base)} desc="Clipes Cinematográficos" />
                    </>
                )}

                {/* Production Options */}
                {category === 'video_production' && (
                    <>
                        <ServiceCard active={serviceId === 'edit_only'} onClick={() => handleServiceSelect('edit_only', 'quantity')} onInfo={setInfoData} icon={Edit} title={TABLE.video_production.edit.label} price={`R$ ${TABLE.video_production.edit.unit}`} desc="Pós-produção" />
                        <ServiceCard active={serviceId === 'cam_cap'} onClick={() => handleServiceSelect('cam_cap', 'duration')} onInfo={setInfoData} icon={Video} title={TABLE.video_production.cam_cap.label} price={formatCurrency(TABLE.video_production.cam_cap.fixed)} desc="Diária Profissional" />
                        <ServiceCard active={serviceId === 'mobile_cap'} onClick={() => handleServiceSelect('mobile_cap', 'duration')} onInfo={setInfoData} icon={SmartphoneIcon} title={TABLE.video_production.mobile_cap.label} price={formatCurrency(TABLE.video_production.mobile_cap.fixed)} desc="Captação iPhone" />
                        <ServiceCard active={serviceId === 'drone'} onClick={() => handleServiceSelect('drone', 'duration')} onInfo={setInfoData} icon={Plane} title={TABLE.video_production.drone.label} price={formatCurrency(TABLE.video_production.drone.fixed)} desc="Imagens Aéreas" />
                    </>
                )}

                {/* Custom Option */}
                {category === 'custom' && (
                    <motion.div variants={fadeInUp} className="col-span-1 md:col-span-3 bg-white/5 border border-white/10 p-10 rounded-2xl text-center backdrop-blur-sm flex flex-col items-center">
                        <Star className="mx-auto text-brand-DEFAULT mb-4" size={32} />
                        <h3 className="font-serif text-xl text-white mb-2">Projeto Personalizado</h3>
                        <p className="text-neutral-400 mb-6">Descreva sua necessidade específica no WhatsApp após finalizar ou entre em contato agora.</p>

                        <a 
                            href={`https://api.whatsapp.com/send?phone=${AppConfig.BRAND.WHATSAPP}`} 
                            target="_blank" 
                            rel="noopener noreferrer"
                        >
                            <Button variant="primary" size="md" className="flex items-center gap-2">
                                <MessageCircle size={18} />
                                Falar no WhatsApp
                            </Button>
                        </a>
                    </motion.div>
                )}
            </div>
        </div>
      )}

      {/* === STEP 3: CONFIGURATION (DETAILS) === */}
      {viewMode === 'config' && (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-8 duration-500 flex flex-col items-center">

            {/* 1. QUANTITY / DURATION CONTROLS */}
            <AnimatePresence mode="wait">
                {showDuration && (
                    <motion.div 
                        key="duration"
                        variants={fadeInUp} initial="hidden" animate="visible" exit="hidden"
                        className="w-full max-w-lg bg-neutral-900/40 p-8 rounded-[2rem] border border-white/10 shadow-2xl flex flex-col items-center text-center backdrop-blur-xl relative overflow-hidden"
                    >
                         <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-brand-DEFAULT/50 to-transparent" />

                        <div className="flex items-center gap-3 mb-6">
                             <Clock className="text-brand-DEFAULT" size={18} />
                             <h3 className="text-xs font-bold uppercase tracking-[0.2em] text-neutral-400">Tempo de Cobertura</h3>
                        </div>

                        <div className="flex items-center justify-between w-full gap-8 px-4">
                            <ControlBtn onClick={() => setHours(Math.max(2, hours - 1))} icon={Minus} />
                            <div className="text-center">
                                <span className="block text-5xl font-serif text-white tracking-tighter mb-1 drop-shadow-lg">
                                    <AnimatedNumber value={hours} />
                                </span>
                                <span className="text-[10px] text-neutral-500 font-bold uppercase tracking-[0.4em]">Horas</span>
                            </div>
                            <ControlBtn onClick={() => setHours(hours + 1)} icon={Plus} active />
                        </div>
                    </motion.div>
                )}

                {showQuantity && (
                    <motion.div 
                        key="quantity"
                        variants={fadeInUp} initial="hidden" animate="visible" exit="hidden"
                        className="w-full max-w-lg bg-neutral-900/40 p-8 rounded-[2rem] border border-white/10 shadow-2xl flex flex-col items-center text-center backdrop-blur-xl relative overflow-hidden"
                    >
                        <div className="absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-brand-DEFAULT/50 to-transparent" />

                        <div className="flex items-center gap-3 mb-6">
                             <Camera className="text-brand-DEFAULT" size={18} />
                             <h3 className="text-xs font-bold uppercase tracking-[0.2em] text-neutral-400">Quantidade</h3>
                        </div>

                        <div className="flex items-center justify-between w-full gap-8 px-4">
                            <ControlBtn onClick={() => setQty(Math.max(minQty, qty - 1))} icon={Minus} />
                            <div className="text-center">
                                <span className="block text-5xl font-serif text-white tracking-tighter mb-1 drop-shadow-lg">
                                    <AnimatedNumber value={qty} />
                                </span>
                                <span className="text-[10px] text-neutral-500 font-bold uppercase tracking-[0.4em]">Unidades</span>
                            </div>
                            <ControlBtn onClick={() => setQty(qty + 1)} icon={Plus} active />
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* 2. ADDONS (Drone / RealTime) */}
            {(category === 'wedding' || category === 'social' || category === 'commercial') && (
                <motion.div variants={fadeInUp} className="w-full max-w-lg grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <AddonCard 
                        label="Drone (Aéreo)" 
                        price={250} 
                        icon={Plane} 
                        active={addDrone} 
                        onClick={() => setAddDrone(!addDrone)} 
                    />
                    <AddonCard 
                        label="Fotos Tempo Real" 
                        price={600} 
                        icon={Timer} 
                        active={addRealTime} 
                        onClick={() => setAddRealTime(!addRealTime)} 
                    />
                </motion.div>
            )}

            {/* 3. LOGISTICS */}
            {!isNoTravelCost && (
                <motion.div 
                    variants={fadeInUp} 
                    onClick={onOpenMap} 
                    className="w-full max-w-lg border border-white/5 bg-white/[0.02] flex items-center justify-between cursor-pointer group hover:bg-white/[0.05] rounded-xl p-4 transition-colors"
                >
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-white/5 rounded-full text-brand-DEFAULT group-hover:bg-brand-DEFAULT group-hover:text-white transition-colors">
                            <Route size={20} />
                        </div>
                        <div className="text-left">
                            <p className="text-[10px] uppercase tracking-widest text-neutral-500">Logística</p>
                            <p className="text-white text-sm font-medium mt-0.5 truncate max-w-[180px]">{locationClient}</p>
                        </div>
                    </div>
                    <div className="text-right">
                         <p className="text-neutral-400 text-xs">
                            {distance}km • {travelCost > 0 ? formatCurrency(travelCost) : "Grátis"}
                        </p>
                    </div>
                </motion.div>
            )}
        </div>
      )}

      {/* INFO MODAL */}
      <AnimatePresence>
        {infoData && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
             <motion.div 
                initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                className="absolute inset-0 bg-black/60 backdrop-blur-md"
                onClick={() => setInfoData(null)}
             />
             <motion.div 
                variants={modalVariants} initial="hidden" animate="visible" exit="exit"
                className="relative bg-neutral-900 border border-white/10 rounded-2xl p-8 max-w-sm w-full text-center shadow-2xl"
             >
                <button 
                  onClick={() => setInfoData(null)}
                  className="absolute top-4 right-4 text-neutral-500 hover:text-white transition-colors"
                >
                    <X size={20} />
                </button>

                <h3 className="text-2xl font-serif text-white mb-4">{infoData.title}</h3>
                <div className="w-12 h-0.5 bg-brand-DEFAULT mx-auto mb-6" />
                <p className="text-neutral-300 leading-relaxed font-light text-sm mb-8">
                    {infoData.desc}
                    <br/><br/>
