            hoursIncluded: 2, 
            hourPrice: 250, 
            label: "Estúdio (Vídeo)",
            description: "Ideal para Videocasts, Cursos Online ou Institucionais com teleprompter e áudio perfeito." 
        },
    },
    video_production: {
        edit: { 
            unit: 250, 
