  // --- LOGIC: LOCATION SERVICE ---
  useEffect(() => {
    let isMounted = true;
    const updateDistance = async () => {
        if (clientData.location) {
            const dist = await LocationService.calculateDistance(clientData.location);
            if (isMounted) setDistance(dist);
        }
    };
    // No modo rápido, não calculamos distância inicialmente pois location está vazio
    if (!isQuickMode) {
        updateDistance();
    }
    return () => { isMounted = false; };
  }, [clientData.location, isQuickMode]);

  const handleUpdateLocation = (address: string) => {
      onUpdateClientData({ ...clientData, location: address });
  };

  // --- LOGIC: SELECTION DEFAULTS ---
  useEffect(() => {
    if (category === 'wedding') setSelectionMode('duration');
    if (category === 'commercial') setSelectionMode('quantity');
    if (category === 'studio' && serviceId === 'studio_photo') setSelectionMode('quantity');
    if (category === 'studio' && serviceId === 'studio_video') setSelectionMode('duration');
    if (category === 'social' && serviceId === 'graduation') setSelectionMode('duration');
  }, [category, serviceId]);

  // --- LOGIC: PRICING ENGINE ---
  const { totalPrice, priceBreakdown } = useMemo(() => {
    const context: PricingContext = {
        pricePerKm: config.pricePerKm,
        photoUnitPrice: config.photoUnitPrice,
        videoUnitPrice: config.videoUnitPrice,
        distance: distance,
        isQuickMode: isQuickMode // Flag passada para o motor
    };
    const result = PricingEngine.calculate(quoteState, context);
    return { totalPrice: result.totalPrice, priceBreakdown: result.breakdown };
  }, [quoteState, config, distance, isQuickMode]);

  // --- LOGIC: RESET WHEN CHANGING CATEGORY ---
  useEffect(() => {
      const table = AppConfig.PRICING_TABLE;
      const currentCategoryGroup = table[category as keyof typeof table];
      const isIdValid = currentCategoryGroup && Object.keys(currentCategoryGroup).some(key => key === serviceId);

      if (!isIdValid) {
        if (category === 'wedding') setServiceId('wedding_base');
        if (category === 'social') setServiceId('birthday');
        if (category === 'commercial') setServiceId('comm_photo');
        if (category === 'studio') setServiceId('studio_photo');
        if (category === 'video_production') setServiceId('edit_only');
        if (category === 'custom') setServiceId('custom_project');

        setHours(2);
        if (category === 'commercial') {
            if (serviceId === 'comm_photo') setQty(20);
            else if (serviceId === 'comm_video') setQty(1);
        } else if (category === 'studio' && serviceId === 'studio_photo') {
            setQty(8);
        } else if (category === 'video_production') {
            setQty(1);
        } else {
            setQty(10);
        }
      }
  }, [category]);

  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    setIsApproved(true);
    onSuccess();
    setViewState('success');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReset = () => { window.location.reload(); };

  const handleRemoveAddon = (addonName: string) => {
      const name = addonName.toLowerCase();
      if (name.includes('drone')) setAddDrone(false);
      if (name.includes('tempo real')) setAddRealTime(false);
      if (name.includes('horas extras')) setHours(2); 
  };

  // --- WIZARD NAVIGATION HANDLERS ---
  const handleNextStep = () => {
      if (currentStep < steps.length - 1) {
          setDirection(1);
          setCurrentStep(prev => prev + 1);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
          // Final Step - Lógica de Modo Rápido vs Normal
          setViewState('summary');
      }
  };

  const handlePrevStep = () => {
      if (currentStep > 0) {
          setDirection(-1);
          setCurrentStep(prev => prev - 1);
      } else {
          onBack();
      }
  };

  // Label Resolution
  const serviceLabel = AppConfig.getServiceLabel(category, serviceId);
  let metricLabel = '';
  if (selectionMode === 'duration') {
       metricLabel = `${hours}h de Cobertura`;
  } else {
       metricLabel = `${qty} Unidades`;
  }
  if (category === 'wedding' && selectionMode === 'duration' && hours === 2) metricLabel = "Pacote Completo";
  if (category === 'custom') metricLabel = 'Sob medida';

  const activeAddons = [];
  if (addDrone && (category === 'wedding' || category === 'social' || category === 'commercial')) activeAddons.push('Drone (Aéreo)');
  if (addRealTime) activeAddons.push('Fotos em Tempo Real');

  const summaryDetails = {
    serviceName: serviceLabel,
    categoryLabel: category === 'wedding' ? 'Casamento' : category === 'social' ? 'Social' : category === 'commercial' ? 'Comercial' : category === 'studio' ? 'Estúdio' : 'Produção',
    metricLabel,
    addons: activeAddons
  };

  const quoteDetails = {
    occasion: category === 'custom' ? 'custom' : (category as any),
    customOccasionText: serviceLabel,
    location: (category === 'studio' ? 'studio' : 'external'),
    photoQty: selectionMode === 'quantity' ? qty : (category === 'commercial' && serviceId === 'comm_photo' ? qty : 0),
    videoQty: (category === 'video_production' && serviceId === 'edit_only') ? qty : 
              ((category === 'commercial' && (serviceId === 'comm_video' || serviceId === 'comm_combo'))) ? qty : 0,
    distance,
    paymentMethod 
  };

  if (viewState === 'success') {
      return (
        <SuccessView 
            onReset={handleReset} 
            clientData={clientData}
            totalPrice={totalPrice}
            quoteDetails={quoteDetails as any}
        />
      );
  }

  return (
    <div className="relative min-h-screen bg-black/80 flex flex-col">

      {/* Background sutil para dar profundidade */}
      <div className="fixed inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-neutral-900 via-black to-black -z-10" />

      {/* HEADER: PROGRESS & NAV */}
      <div className="pt-8 px-6 pb-4 w-full max-w-5xl mx-auto flex flex-col items-center relative z-20">
          <div className="w-full flex justify-between items-center mb-6">
               <button onClick={handlePrevStep} className="p-2 rounded-full bg-white/5 hover:bg-white/10 text-neutral-400 hover:text-white transition-colors">
                   <ArrowLeft size={20} />
               </button>
               {/* LOGO AUMENTADA E ANIMATION FIX */}
               <Logo className="w-40 opacity-80" />
               <div className="w-10" /> {/* Spacer para centralizar logo */}
          </div>

          {/* Progress Bar */}
          <div className="flex items-center gap-2 w-full max-w-xs mb-2">
            {steps.map((_, idx) => (
                <div key={idx} className="h-1 flex-1 rounded-full overflow-hidden bg-white/10">
                    <motion.div 
                        className="h-full bg-brand-DEFAULT"
                        initial={{ width: "0%" }}
                        animate={{ width: idx <= currentStep ? "100%" : "0%" }}
                        transition={{ duration: 0.3 }}
                    />
                </div>
            ))}
          </div>
          <p className="text-[10px] text-neutral-500 font-mono uppercase tracking-widest">
                Passo {currentStep + 1}: {steps[currentStep].title}
          </p>
      </div>

      {/* MAIN CONTENT: WIZARD STEP */}
      <div className="flex-1 w-full max-w-5xl mx-auto relative px-4 pb-32 flex flex-col justify-center">
          <AnimatePresence initial={false} custom={direction} mode="wait">
            {viewState === 'config' && (
                <motion.div 
                    key={currentStep}
                    custom={direction}
                    variants={stepVariants}
                    initial="enter"
                    animate="center"
                    exit="exit"
                    className="w-full flex justify-center"
                >
                   <UpsellList 
                      viewMode={currentStepId} // Controla o que é renderizado
                      category={category} setCategory={setCategory}
                      serviceId={serviceId} setServiceId={setServiceId}
                      hours={hours} setHours={setHours}
                      qty={qty} setQty={setQty}
                      addDrone={addDrone} setAddDrone={setAddDrone}
                      addRealTime={addRealTime} setAddRealTime={setAddRealTime}
                      distance={distance}
                      pricePerKm={quoteData.pricePerKm}
                      locationClient={clientData.location}
                      onOpenMap={() => setIsMapOpen(true)}
                      selectionMode={selectionMode}
                      setSelectionMode={setSelectionMode}
                      isQuickMode={isQuickMode} // Passando prop para visualização
                    />
                </motion.div>
            )}
          </AnimatePresence>
      </div>

      {/* FOOTER NAVIGATION */}
      {viewState === 'config' && (
        <StickyFooter 
            totalPrice={totalPrice} 
            onApprove={handleNextStep} 
            isApproved={false}
            highlight={true}
            // Oculta o preço se estiver na etapa de categorias (indice 0)
            showPrice={currentStep !== 0} 
        />
      )}

      {/* SUMMARY MODAL/VIEW */}
      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={quoteData}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={summaryDetails}
                priceBreakdown={priceBreakdown}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
                onRemoveAddon={handleRemoveAddon}
            />
         )}
      </AnimatePresence>

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleUpdateLocation}
        initialAddress={clientData.location}
      />
    </div>
  );
};

export default QuoteView;

import React, { useState, useEffect, useLayoutEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import QuoteView from './src/pages/QuoteView';
import WelcomeView from './src/pages/WelcomeView';
import IntroView from './src/pages/IntroView';
import AdminDashboard from './src/pages/AdminDashboard';
import Loading from './src/components/ui/Loading';
import Logo from './src/components/ui/Logo';
import BackgroundFilmStrips from './src/components/ui/BackgroundFilmStrips';
import { ClientData, QuoteData, QuoteState } from './src/types';
import { mockQuote } from './src/data/mock';
import { delay } from './src/lib/utils';
import { AppConfig } from './src/config/AppConfig';

// Definição dos estados possíveis da aplicação
type ViewState = 'intro' | 'welcome' | 'quote' | 'admin';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [view, setView] = useState<ViewState>('intro');
  const [isLoading, setIsLoading] = useState(false);
  const [config, setConfig] = useState<QuoteData>(mockQuote);
  const [isQuoteSuccess, setIsQuoteSuccess] = useState(false);

  // Novo estado: Modo Rápido
  const [isQuickMode, setIsQuickMode] = useState(false);

  const [clientData, setClientData] = useState<ClientData | null>(() => {
    const saved = localStorage.getItem('earec_client_data');
    return saved ? JSON.parse(saved) : null;
  });

  const [quoteState, setQuoteState] = useState<QuoteState>({
    category: 'wedding',
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    addDrone: false,
    addRealTime: false,
    selectionMode: 'duration'
  });

  // === DESIGN SYSTEM INJECTION ===
  // Aplica as cores definidas no AppConfig como variáveis CSS globais
  useLayoutEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--brand-color', AppConfig.BRAND.COLORS.PRIMARY);
    root.style.setProperty('--brand-glow', `${AppConfig.BRAND.COLORS.PRIMARY}80`); // 50% opacity hex
  }, []);

  useEffect(() => {
    if (clientData) {
      localStorage.setItem('earec_client_data', JSON.stringify(clientData));
    }
  }, [clientData]);

  useEffect(() => {
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
    window.scrollTo(0, 0);
    const timer = setTimeout(() => setShowSplash(false), 2200); 
    return () => clearTimeout(timer);
  }, []);

  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    setIsQuoteSuccess(false);

    // Se não for modo rápido, simula um loading maior de "processamento"
    if (!isQuickMode) {
        await delay(2000);
    } else {
        await delay(500); // Retorno rápido do formulário
    }

    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  // Handler para Orçamento Rápido
  const handleQuickStart = async () => {
    // Define dados temporários para não quebrar a QuoteView
    setClientData({
        name: '', 
        location: '', 
        date: '', 
        contact: ''
    });
    setIsQuickMode(true); // Ativa flag
    setIsLoading(true);
    setIsQuoteSuccess(false);
    await delay(800); // Delay menor para sensação de rapidez
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

  const handleAdminUpdate = (newConfig: QuoteData) => {
    setConfig(newConfig);
  };

  // Callback chamado pelo QuoteView quando precisa dos dados no modo rápido
  const handleRequestForm = () => {
    setView('welcome');
    window.scrollTo(0, 0);
  };

  return (
    <main className="w-full min-h-screen bg-black text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans relative">
      {(view !== 'quote' || isQuoteSuccess) && <BackgroundFilmStrips />}

      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            transition={{ duration: 0.6, ease: "easeInOut" }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
             <div className="flex flex-col items-center justify-center w-full h-full p-4">
               <motion.div
                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 0.8, ease: "easeOut" }}
                 className="mb-4"
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.7, duration: 0.5 }}
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-400 font-serif italic text-xl md:text-2xl tracking-widest uppercase">
                    Orçamento Facilitado
                  </p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'intro' && (
                <IntroView 
                    onContinue={() => {
                        setIsQuickMode(false);
                        setView('welcome');
                    }}
                    onQuickStart={handleQuickStart}
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
                  onBack={() => setView(isQuickMode ? 'quote' : 'intro')} 
                />
            )}

            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView(isQuickMode ? 'intro' : 'welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                  onSuccess={() => setIsQuoteSuccess(true)}
                  isQuickMode={isQuickMode}
                  onRequestForm={handleRequestForm}
                />
            )}

            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={handleAdminUpdate}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

export default App;

import React from 'react';
import { motion, Variants } from 'framer-motion';
import { cn } from '../../lib/utils';

interface LogoProps {
  className?: string; // Classes CSS opcionais para ajustar tamanho (ex: w-32, h-auto)
  animate?: boolean;  // Se 'true', ativa a animação de entrada (fade-in + scale)
}

// Movido para fora para evitar recriação e reset de animação a cada render do pai
const SvgContent = React.memo(() => (
  <svg 
    viewBox="0 0 250 70" 
    fill="none" 
    xmlns="http://www.w3.org/2000/svg" 
    className="w-full h-full drop-shadow-[0_0_15px_rgba(255,255,255,0.05)]"
    aria-label="EAREC Logo"
  >
    {/* Texto EA - Cinza Claro/Branco - Ajustado para Negrito Extra (900) */}
    <text 
      x="10" 
      y="52" 
      fontFamily="'Inter', sans-serif" 
      fontWeight="900" 
      fontSize="55" 
      fill="#E5E5E5" 
      letterSpacing="-3"
      className="drop-shadow-sm"
    >
      EA
    </text>

    {/* Ponto Central - Vermelho Marca */}
    <motion.circle 
      cx="105" 
      cy="33" 
      r="16" 
      fill="#DC2626" 
      className="drop-shadow-[0_0_10px_rgba(220,38,38,0.9)]"
      animate={{ opacity: [1, 0.6, 1] }}
      transition={{ 
        duration: 3, 
        repeat: Infinity, 
        ease: "easeInOut" 
      }}
    />

    {/* Texto REC - Vermelho Marca - Ajustado para Fino (300) conforme solicitado */}
    <text 
      x="132" 
      y="52" 
      fontFamily="'Inter', sans-serif" 
      fontWeight="300" 
      fontSize="55" 
      fill="#DC2626" 
      letterSpacing="-3"
      className="drop-shadow-[0_0_5px_rgba(220,38,38,0.4)]"
    >
      REC
    </text>
  </svg>
));

/**
 * Componente: Logo
 * ----------------
 * Renderiza a marca EAREC vetorialmente (SVG).
 * Design: "EA" (Branco/Cinza) + Dot (Vermelho) + "REC" (Vermelho).
 * Elimina dependência de arquivos de imagem externos.
 * 
 * ATENÇÃO: Memoizado para evitar reinício de animação em re-renders do pai.
 */
const Logo: React.FC<LogoProps> = React.memo(({ className, animate = false }) => {

  const containerVariants: Variants = {
    hidden: { 
      opacity: 0, 
      scale: 0.8, 
      filter: 'blur(10px)' 
    },
    visible: { 
      opacity: 1, 
      scale: 1, 
      filter: 'blur(0px)',
      transition: { 
        duration: 1.2, 
        ease: [0.22, 1, 0.36, 1] 
      } 
    }
  };

  if (!animate) {
    return (
      <div className={cn("relative select-none", className)}>
        <SvgContent />
      </div>
    );
  }

  return (
    <motion.div 
      initial="hidden"
      animate="visible"
      variants={containerVariants}
      className={cn("relative select-none", className)}
    >
      <SvgContent />
    </motion.div>
  );
});

export default Logo;

import React, { useState, useMemo, useEffect } from 'react';
import UpsellList from '../components/quote/UpsellList';
import StickyFooter from '../components/quote/StickyFooter';
import SignatureModal from '../components/quote/SignatureModal';
import LocationMapModal from '../components/ui/LocationMapModal';
import SummaryView from './SummaryView';
import SuccessView from './SuccessView';
import { formatCurrency } from '../lib/utils';
import { motion, AnimatePresence, Variants } from 'framer-motion';
import { ClientData, QuoteData, ServiceCategory, ServiceId, QuoteState, PricingContext } from '../types';
import { ArrowLeft } from 'lucide-react';
import Logo from '../components/ui/Logo';

// === POO INTEGRATION ===
import { PricingEngine } from '../core/PricingEngine';
import { AppConfig } from '../config/AppConfig';
import { LocationService } from '../services/LocationService';

interface QuoteViewProps {
  clientData: ClientData; 
  onUpdateClientData: (data: ClientData) => void; 
  config: QuoteData;      
  onBack: () => void;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  onSuccess: () => void;
  isQuickMode?: boolean;
  onRequestForm?: () => void; // Callback para pedir o formulário completo
}

type ViewState = 'config' | 'summary' | 'success';

// Variantes de Animação para o Wizard (Slide Lateral)
const stepVariants: Variants = {
  enter: (direction: number) => ({
    x: direction > 0 ? 50 : -50,
    opacity: 0,
    filter: 'blur(10px)',
  }),
  center: {
    zIndex: 1,
    x: 0,
    opacity: 1,
    filter: 'blur(0px)',
    transition: {
        duration: 0.5,
        ease: [0.22, 1, 0.36, 1]
    }
  },
  exit: (direction: number) => ({
    zIndex: 0,
    x: direction < 0 ? 50 : -50,
    opacity: 0,
    filter: 'blur(10px)',
    transition: {
        duration: 0.4,
        ease: "easeIn"
    }
  })
};

const QuoteView: React.FC<QuoteViewProps> = ({ 
    clientData, onUpdateClientData, config, onBack, 
    quoteState, setQuoteState, onSuccess, isQuickMode = false, onRequestForm
}) => {
  const [viewState, setViewState] = useState<ViewState>('config');

  // === WIZARD STATE ===
  const [currentStep, setCurrentStep] = useState(0);
  const [direction, setDirection] = useState(0);

  // Definição das Etapas
  const steps = [
      { id: 'categories', title: 'Qual a ocasião?' },
      { id: 'services', title: 'Escolha o pacote ideal' },
      { id: 'config', title: 'Personalize os detalhes' }
  ];

  const currentStepId = steps[currentStep].id as 'categories' | 'services' | 'config';

  const quoteData: QuoteData = useMemo(() => ({
    ...config,
    client: { ...config.client, ...clientData, projectTitle: `Project: ${clientData.name}` }
  }), [clientData, config]);

  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');
  const [distance, setDistance] = useState<number>(0); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false); 
  const [isApproved, setIsApproved] = useState(false);

  // Destructuring do State
  const { category, serviceId, hours, qty, addDrone, addRealTime, selectionMode } = quoteState;

  // Setters Helpers
  const setCategory = (c: ServiceCategory) => setQuoteState(prev => ({ ...prev, category: c }));
  const setServiceId = (s: ServiceId) => setQuoteState(prev => ({ ...prev, serviceId: s }));
  const setHours = (h: number) => setQuoteState(prev => ({ ...prev, hours: h }));
  const setQty = (q: number) => setQuoteState(prev => ({ ...prev, qty: q }));
  const setAddDrone = (b: boolean) => setQuoteState(prev => ({ ...prev, addDrone: b }));
  const setAddRealTime = (b: boolean) => setQuoteState(prev => ({ ...prev, addRealTime: b }));
  const setSelectionMode = (mode: 'duration' | 'quantity') => setQuoteState(prev => ({ ...prev, selectionMode: mode }));

  // --- LOGIC: LOCATION SERVICE ---
  useEffect(() => {
    let isMounted = true;
    const updateDistance = async () => {
        if (clientData.location) {
            const dist = await LocationService.calculateDistance(clientData.location);
            if (isMounted) setDistance(dist);
        }
    };
    // No modo rápido, não calculamos distância inicialmente pois location está vazio
    if (!isQuickMode) {
        updateDistance();
    }
    return () => { isMounted = false; };
  }, [clientData.location, isQuickMode]);

  const handleUpdateLocation = (address: string) => {
      onUpdateClientData({ ...clientData, location: address });
  };

  // --- LOGIC: SELECTION DEFAULTS ---
  useEffect(() => {
    if (category === 'wedding') setSelectionMode('duration');
    if (category === 'commercial') setSelectionMode('quantity');
    if (category === 'studio' && serviceId === 'studio_photo') setSelectionMode('quantity');
    if (category === 'studio' && serviceId === 'studio_video') setSelectionMode('duration');
    if (category === 'social' && serviceId === 'graduation') setSelectionMode('duration');
  }, [category, serviceId]);

  // --- LOGIC: PRICING ENGINE ---
  const { totalPrice, priceBreakdown } = useMemo(() => {
    const context: PricingContext = {
        pricePerKm: config.pricePerKm,
        photoUnitPrice: config.photoUnitPrice,
        videoUnitPrice: config.videoUnitPrice,
        distance: distance,
        isQuickMode: isQuickMode // Flag passada para o motor
    };
    const result = PricingEngine.calculate(quoteState, context);
    return { totalPrice: result.totalPrice, priceBreakdown: result.breakdown };
  }, [quoteState, config, distance, isQuickMode]);

  // --- LOGIC: RESET WHEN CHANGING CATEGORY ---
  useEffect(() => {
      const table = AppConfig.PRICING_TABLE;
      const currentCategoryGroup = table[category as keyof typeof table];
      const isIdValid = currentCategoryGroup && Object.keys(currentCategoryGroup).some(key => key === serviceId);

      if (!isIdValid) {
        if (category === 'wedding') setServiceId('wedding_base');
        if (category === 'social') setServiceId('birthday');
        if (category === 'commercial') setServiceId('comm_photo');
        if (category === 'studio') setServiceId('studio_photo');
        if (category === 'video_production') setServiceId('edit_only');
        if (category === 'custom') setServiceId('custom_project');

        setHours(2);
        if (category === 'commercial') {
            if (serviceId === 'comm_photo') setQty(20);
            else if (serviceId === 'comm_video') setQty(1);
        } else if (category === 'studio' && serviceId === 'studio_photo') {
            setQty(8);
        } else if (category === 'video_production') {
            setQty(1);
        } else {
            setQty(10);
        }
      }
  }, [category]);

  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    setIsApproved(true);
    onSuccess();
    setViewState('success');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReset = () => { window.location.reload(); };

  const handleRemoveAddon = (addonName: string) => {
      const name = addonName.toLowerCase();
      if (name.includes('drone')) setAddDrone(false);
      if (name.includes('tempo real')) setAddRealTime(false);
      if (name.includes('horas extras')) setHours(2); 
  };

  // --- WIZARD NAVIGATION HANDLERS ---
  const handleNextStep = () => {
      if (currentStep < steps.length - 1) {
          setDirection(1);
          setCurrentStep(prev => prev + 1);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
          // Final Step - Lógica de Modo Rápido vs Normal
          setViewState('summary');
      }
  };

  const handlePrevStep = () => {
      if (currentStep > 0) {
          setDirection(-1);
          setCurrentStep(prev => prev - 1);
      } else {
          onBack();
      }
  };

  // Label Resolution
  const serviceLabel = AppConfig.getServiceLabel(category, serviceId);
  let metricLabel = '';
  if (selectionMode === 'duration') {
       metricLabel = `${hours}h de Cobertura`;
  } else {
       metricLabel = `${qty} Unidades`;
  }
  if (category === 'wedding' && selectionMode === 'duration' && hours === 2) metricLabel = "Pacote Completo";
  if (category === 'custom') metricLabel = 'Sob medida';

  const activeAddons = [];
  if (addDrone && (category === 'wedding' || category === 'social' || category === 'commercial')) activeAddons.push('Drone (Aéreo)');
  if (addRealTime) activeAddons.push('Fotos em Tempo Real');

  const summaryDetails = {
    serviceName: serviceLabel,
    categoryLabel: category === 'wedding' ? 'Casamento' : category === 'social' ? 'Social' : category === 'commercial' ? 'Comercial' : category === 'studio' ? 'Estúdio' : 'Produção',
    metricLabel,
    addons: activeAddons
  };

  const quoteDetails = {
    occasion: category === 'custom' ? 'custom' : (category as any),
    customOccasionText: serviceLabel,
    location: (category === 'studio' ? 'studio' : 'external'),
    photoQty: selectionMode === 'quantity' ? qty : (category === 'commercial' && serviceId === 'comm_photo' ? qty : 0),
    videoQty: (category === 'video_production' && serviceId === 'edit_only') ? qty : 
              ((category === 'commercial' && (serviceId === 'comm_video' || serviceId === 'comm_combo'))) ? qty : 0,
    distance,
    paymentMethod 
  };

  if (viewState === 'success') {
      return (
        <SuccessView 
            onReset={handleReset} 
            clientData={clientData}
            totalPrice={totalPrice}
            quoteDetails={quoteDetails as any}
        />
      );
  }

  return (
    <div className="relative min-h-screen bg-black/80 flex flex-col">

      {/* Background sutil para dar profundidade */}
      <div className="fixed inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-neutral-900 via-black to-black -z-10" />

      {/* HEADER: PROGRESS & NAV */}
      <div className="pt-8 px-6 pb-4 w-full max-w-5xl mx-auto flex flex-col items-center relative z-20">
          <div className="w-full flex justify-between items-center mb-6">
               <button onClick={handlePrevStep} className="p-2 rounded-full bg-white/5 hover:bg-white/10 text-neutral-400 hover:text-white transition-colors">
                   <ArrowLeft size={20} />
               </button>
               {/* LOGO AUMENTADA E ANIMATION FIX */}
               <Logo className="w-56 opacity-80" />
               <div className="w-10" /> {/* Spacer para centralizar logo */}
          </div>

          {/* Progress Bar */}
          <div className="flex items-center gap-2 w-full max-w-xs mb-2">
            {steps.map((_, idx) => (
                <div key={idx} className="h-1 flex-1 rounded-full overflow-hidden bg-white/10">
                    <motion.div 
                        className="h-full bg-brand-DEFAULT"
                        initial={{ width: "0%" }}
                        animate={{ width: idx <= currentStep ? "100%" : "0%" }}
                        transition={{ duration: 0.3 }}
                    />
                </div>
            ))}
          </div>
          <p className="text-[10px] text-neutral-500 font-mono uppercase tracking-widest">
                Passo {currentStep + 1}: {steps[currentStep].title}
          </p>
      </div>

      {/* MAIN CONTENT: WIZARD STEP */}
      <div className="flex-1 w-full max-w-5xl mx-auto relative px-4 pb-32 flex flex-col justify-center">
          <AnimatePresence initial={false} custom={direction} mode="wait">
            {viewState === 'config' && (
                <motion.div 
                    key={currentStep}
                    custom={direction}
                    variants={stepVariants}
                    initial="enter"
                    animate="center"
                    exit="exit"
                    className="w-full flex justify-center"
                >
                   <UpsellList 
                      viewMode={currentStepId} // Controla o que é renderizado
                      category={category} setCategory={setCategory}
                      serviceId={serviceId} setServiceId={setServiceId}
                      hours={hours} setHours={setHours}
                      qty={qty} setQty={setQty}
                      addDrone={addDrone} setAddDrone={setAddDrone}
                      addRealTime={addRealTime} setAddRealTime={setAddRealTime}
                      distance={distance}
                      pricePerKm={quoteData.pricePerKm}
                      locationClient={clientData.location}
                      onOpenMap={() => setIsMapOpen(true)}
                      selectionMode={selectionMode}
                      setSelectionMode={setSelectionMode}
                      isQuickMode={isQuickMode} // Passando prop para visualização
                    />
                </motion.div>
            )}
          </AnimatePresence>
      </div>

      {/* FOOTER NAVIGATION */}
      {viewState === 'config' && (
        <StickyFooter 
            totalPrice={totalPrice} 
            onApprove={handleNextStep} 
            isApproved={false}
            highlight={true}
            // Oculta o preço se estiver na etapa de categorias (indice 0)
            showPrice={currentStep !== 0} 
        />
      )}

      {/* SUMMARY MODAL/VIEW */}
      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={quoteData}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={summaryDetails}
                priceBreakdown={priceBreakdown}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
                onRemoveAddon={handleRemoveAddon}
            />
         )}
      </AnimatePresence>

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleUpdateLocation}
        initialAddress={clientData.location}
      />
    </div>
  );
};

export default QuoteView;

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Button from '../ui/Button';
import AnimatedPrice from '../ui/AnimatedPrice';
import { ArrowRight, ChevronRight } from 'lucide-react';
import { cn } from '../../lib/utils';

interface StickyFooterProps {
  totalPrice: number;
  onApprove: () => void;
  isApproved: boolean;
  highlight?: boolean;
  showPrice?: boolean; // Nova prop
}

const StickyFooter: React.FC<StickyFooterProps> = ({ 
  totalPrice, onApprove, isApproved, highlight = false, showPrice = true 
}) => {
  return (
    <motion.div 
      initial={{ y: 100 }}
      animate={{ y: 0 }}
      exit={{ y: 100 }}
      transition={{ duration: 0.5, type: "spring", damping: 20 }}
      className="fixed bottom-0 left-0 right-0 z-40"
    >
      {/* 
         GRADIENTE REDUZIDO
      */}
      <div className="absolute inset-0 bg-gradient-to-t from-black via-black/90 to-transparent pointer-events-none h-24 -top-24" />

      <div className="bg-neutral-950 border-t border-white/10 pb-8 pt-4 px-6 md:pb-8 md:px-12 relative z-10">
        <div className={cn(
            "max-w-4xl mx-auto flex items-center gap-4",
            showPrice ? "justify-between" : "justify-center"
        )}>

          <AnimatePresence mode="wait">
            {showPrice && (
              <motion.div 
                key="price"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="flex flex-col"
              >
                <span className="text-neutral-500 text-[10px] uppercase tracking-widest mb-0.5">Valor Estimado</span>
                <div className="text-3xl font-serif text-white flex items-baseline gap-2">
                  <AnimatedPrice value={totalPrice} />
                  <span className="text-xs font-sans text-neutral-600 font-normal">BRL</span>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Oculta a hint e mantém apenas o botão centralizado se showPrice for false */}
          {showPrice && (
             <motion.div 
                key="hint"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="hidden sm:block text-neutral-500 text-xs italic ml-auto mr-4"
             >
                {/* Espaço para dica se necessário */}
             </motion.div>
          )}

          <div className="flex items-center gap-4">
            <Button 
                variant="primary" 
                size="lg" 
                onClick={onApprove}
                className={cn(
                    "flex items-center gap-3 px-8 py-4 shadow-[0_0_25px_rgba(220,38,38,0.4)]",
                    !showPrice && "px-12 py-5 text-lg" // Botão maior quando centralizado na intro
                )}
            >
                <span className="font-medium">Continuar</span> 
                <div className="bg-white/20 p-1 rounded-full">
                    <ChevronRight size={16} />
                </div>
            </Button>
          </div>

        </div>
      </div>
    </motion.div>
  );
};

