import { PricingEngine } from '../core/PricingEngine';
import { AppConfig } from '../config/AppConfig';
import { LocationService } from '../services/LocationService';

interface QuoteViewProps {
  clientData: ClientData; 
  onUpdateClientData: (data: ClientData) => void; 
  config: QuoteData;      
  onBack: () => void;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  onSuccess: () => void;
  isQuickMode?: boolean;
  onRequestForm?: () => void; // Callback para pedir o formulário completo
}

type ViewState = 'config' | 'summary' | 'success';

// Variantes de Animação para o Wizard (Slide Lateral)
const stepVariants: Variants = {
  enter: (direction: number) => ({
    x: direction > 0 ? 50 : -50,
    opacity: 0,
    filter: 'blur(10px)',
  }),
  center: {
    zIndex: 1,
    x: 0,
    opacity: 1,
    filter: 'blur(0px)',
    transition: {
        duration: 0.5,
        ease: [0.22, 1, 0.36, 1]
    }
  },
  exit: (direction: number) => ({
    zIndex: 0,
    x: direction < 0 ? 50 : -50,
    opacity: 0,
    filter: 'blur(10px)',
    transition: {
        duration: 0.4,
        ease: "easeIn"
    }
  })
};

const QuoteView: React.FC<QuoteViewProps> = ({ 
    clientData, onUpdateClientData, config, onBack, 
    quoteState, setQuoteState, onSuccess, isQuickMode = false, onRequestForm
}) => {
  const [viewState, setViewState] = useState<ViewState>('config');

  // === WIZARD STATE ===
  const [currentStep, setCurrentStep] = useState(0);
  const [direction, setDirection] = useState(0);

  // Definição das Etapas
  const steps = [
      { id: 'categories', title: 'Qual a ocasião?' },
      { id: 'services', title: 'Escolha o pacote ideal' },
      { id: 'config', title: 'Personalize os detalhes' }
  ];

  const currentStepId = steps[currentStep].id as 'categories' | 'services' | 'config';

  const quoteData: QuoteData = useMemo(() => ({
    ...config,
    client: { ...config.client, ...clientData, projectTitle: `Project: ${clientData.name}` }
  }), [clientData, config]);

  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');
  const [distance, setDistance] = useState<number>(0); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false); 
  const [isApproved, setIsApproved] = useState(false);

  // Destructuring do State
  const { category, serviceId, hours, qty, addDrone, addRealTime, selectionMode } = quoteState;

  // Setters Helpers
  const setCategory = (c: ServiceCategory) => setQuoteState(prev => ({ ...prev, category: c }));
  const setServiceId = (s: ServiceId) => setQuoteState(prev => ({ ...prev, serviceId: s }));
  const setHours = (h: number) => setQuoteState(prev => ({ ...prev, hours: h }));
  const setQty = (q: number) => setQuoteState(prev => ({ ...prev, qty: q }));
  const setAddDrone = (b: boolean) => setQuoteState(prev => ({ ...prev, addDrone: b }));
  const setAddRealTime = (b: boolean) => setQuoteState(prev => ({ ...prev, addRealTime: b }));
  const setSelectionMode = (mode: 'duration' | 'quantity') => setQuoteState(prev => ({ ...prev, selectionMode: mode }));

  // --- LOGIC: LOCATION SERVICE ---
  useEffect(() => {
    let isMounted = true;
    const updateDistance = async () => {
        if (clientData.location) {
            const dist = await LocationService.calculateDistance(clientData.location);
            if (isMounted) setDistance(dist);
        }
    };
    // No modo rápido, não calculamos distância inicialmente pois location está vazio
    if (!isQuickMode) {
        updateDistance();
    }
    return () => { isMounted = false; };
  }, [clientData.location, isQuickMode]);

  const handleUpdateLocation = (address: string) => {
      onUpdateClientData({ ...clientData, location: address });
  };

  // --- LOGIC: SELECTION DEFAULTS ---
  useEffect(() => {
    if (category === 'wedding') setSelectionMode('duration');
    if (category === 'commercial') setSelectionMode('quantity');
    if (category === 'studio' && serviceId === 'studio_photo') setSelectionMode('quantity');
    if (category === 'studio' && serviceId === 'studio_video') setSelectionMode('duration');
    if (category === 'social' && serviceId === 'graduation') setSelectionMode('duration');
  }, [category, serviceId]);

  // --- LOGIC: PRICING ENGINE ---
  const { totalPrice, priceBreakdown } = useMemo(() => {
    const context: PricingContext = {
        pricePerKm: config.pricePerKm,
        photoUnitPrice: config.photoUnitPrice,
        videoUnitPrice: config.videoUnitPrice,
        distance: distance,
        isQuickMode: isQuickMode // Flag passada para o motor
    };
    const result = PricingEngine.calculate(quoteState, context);
    return { totalPrice: result.totalPrice, priceBreakdown: result.breakdown };
  }, [quoteState, config, distance, isQuickMode]);

  // --- LOGIC: RESET WHEN CHANGING CATEGORY ---
  useEffect(() => {
      const table = AppConfig.PRICING_TABLE;
      const currentCategoryGroup = table[category as keyof typeof table];
      const isIdValid = currentCategoryGroup && Object.keys(currentCategoryGroup).some(key => key === serviceId);

      if (!isIdValid) {
        if (category === 'wedding') setServiceId('wedding_base');
        if (category === 'social') setServiceId('birthday');
        if (category === 'commercial') setServiceId('comm_photo');
        if (category === 'studio') setServiceId('studio_photo');
        if (category === 'video_production') setServiceId('edit_only');
        if (category === 'custom') setServiceId('custom_project');

        setHours(2);
        if (category === 'commercial') {
            if (serviceId === 'comm_photo') setQty(20);
            else if (serviceId === 'comm_video') setQty(1);
        } else if (category === 'studio' && serviceId === 'studio_photo') {
            setQty(8);
        } else if (category === 'video_production') {
            setQty(1);
        } else {
            setQty(10);
        }
      }
  }, [category]);

  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    setIsApproved(true);
    onSuccess();
    setViewState('success');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReset = () => { window.location.reload(); };

  const handleRemoveAddon = (addonName: string) => {
      const name = addonName.toLowerCase();
      if (name.includes('drone')) setAddDrone(false);
      if (name.includes('tempo real')) setAddRealTime(false);
      if (name.includes('horas extras')) setHours(2); 
  };

  // --- WIZARD NAVIGATION HANDLERS ---
  const handleNextStep = () => {
      if (currentStep < steps.length - 1) {
          setDirection(1);
          setCurrentStep(prev => prev + 1);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
          // Final Step - Lógica de Modo Rápido vs Normal
          setViewState('summary');
      }
  };

  const handlePrevStep = () => {
      if (currentStep > 0) {
          setDirection(-1);
          setCurrentStep(prev => prev - 1);
      } else {
          onBack();
      }
  };

  // Label Resolution
  const serviceLabel = AppConfig.getServiceLabel(category, serviceId);
  let metricLabel = '';
  if (selectionMode === 'duration') {
       metricLabel = `${hours}h de Cobertura`;
  } else {
       metricLabel = `${qty} Unidades`;
  }
  if (category === 'wedding' && selectionMode === 'duration' && hours === 2) metricLabel = "Pacote Completo";
  if (category === 'custom') metricLabel = 'Sob medida';

  const activeAddons = [];
  if (addDrone && (category === 'wedding' || category === 'social' || category === 'commercial')) activeAddons.push('Drone (Aéreo)');
  if (addRealTime) activeAddons.push('Fotos em Tempo Real');

  const summaryDetails = {
    serviceName: serviceLabel,
    categoryLabel: category === 'wedding' ? 'Casamento' : category === 'social' ? 'Social' : category === 'commercial' ? 'Comercial' : category === 'studio' ? 'Estúdio' : 'Produção',
    metricLabel,
    addons: activeAddons
  };

  const quoteDetails = {
    occasion: category === 'custom' ? 'custom' : (category as any),
    customOccasionText: serviceLabel,
    location: (category === 'studio' ? 'studio' : 'external'),
    photoQty: selectionMode === 'quantity' ? qty : (category === 'commercial' && serviceId === 'comm_photo' ? qty : 0),
    videoQty: (category === 'video_production' && serviceId === 'edit_only') ? qty : 
              ((category === 'commercial' && (serviceId === 'comm_video' || serviceId === 'comm_combo'))) ? qty : 0,
    distance,
    paymentMethod 
  };

  if (viewState === 'success') {
      return (
        <SuccessView 
            onReset={handleReset} 
            clientData={clientData}
            totalPrice={totalPrice}
            quoteDetails={quoteDetails as any}
        />
      );
  }

  return (
    <div className="relative min-h-screen bg-black/80 flex flex-col">

      {/* Background sutil para dar profundidade */}
      <div className="fixed inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-neutral-900 via-black to-black -z-10" />

      {/* HEADER: PROGRESS & NAV */}
      <div className="pt-8 px-6 pb-4 w-full max-w-5xl mx-auto flex flex-col items-center relative z-20">
          <div className="w-full flex justify-between items-center mb-6">
               <button onClick={handlePrevStep} className="p-2 rounded-full bg-white/5 hover:bg-white/10 text-neutral-400 hover:text-white transition-colors">
                   <ArrowLeft size={20} />
               </button>
               {/* LOGO AUMENTADA E ANIMATION FIX */}
               <Logo className="w-56 opacity-80" />
               <div className="w-10" /> {/* Spacer para centralizar logo */}
          </div>

          {/* Progress Bar */}
          <div className="flex items-center gap-2 w-full max-w-xs mb-2">
            {steps.map((_, idx) => (
                <div key={idx} className="h-1 flex-1 rounded-full overflow-hidden bg-white/10">
                    <motion.div 
                        className="h-full bg-brand-DEFAULT"
                        initial={{ width: "0%" }}
                        animate={{ width: idx <= currentStep ? "100%" : "0%" }}
                        transition={{ duration: 0.3 }}
                    />
                </div>
            ))}
          </div>
          <p className="text-[10px] text-neutral-500 font-mono uppercase tracking-widest">
                Passo {currentStep + 1}: {steps[currentStep].title}
          </p>
      </div>

      {/* MAIN CONTENT: WIZARD STEP */}
      <div className="flex-1 w-full max-w-5xl mx-auto relative px-4 pb-32 flex flex-col justify-center">
          <AnimatePresence initial={false} custom={direction} mode="wait">
            {viewState === 'config' && (
                <motion.div 
                    key={currentStep}
                    custom={direction}
                    variants={stepVariants}
                    initial="enter"
                    animate="center"
                    exit="exit"
                    className="w-full flex justify-center"
                >
                   <UpsellList 
                      viewMode={currentStepId} // Controla o que é renderizado
                      category={category} setCategory={setCategory}
                      serviceId={serviceId} setServiceId={setServiceId}
                      hours={hours} setHours={setHours}
                      qty={qty} setQty={setQty}
                      addDrone={addDrone} setAddDrone={setAddDrone}
                      addRealTime={addRealTime} setAddRealTime={setAddRealTime}
                      distance={distance}
                      pricePerKm={quoteData.pricePerKm}
                      locationClient={clientData.location}
                      onOpenMap={() => setIsMapOpen(true)}
                      selectionMode={selectionMode}
                      setSelectionMode={setSelectionMode}
                      isQuickMode={isQuickMode} // Passando prop para visualização
                    />
                </motion.div>
            )}
          </AnimatePresence>
      </div>

      {/* FOOTER NAVIGATION */}
      {viewState === 'config' && category !== 'custom' && (
        <StickyFooter 
            totalPrice={totalPrice} 
            onApprove={handleNextStep} 
            isApproved={false}
            highlight={true}
            // Oculta o preço se estiver na etapa de categorias (indice 0)
            showPrice={currentStep !== 0} 
        />
      )}

      {/* SUMMARY MODAL/VIEW */}
      <AnimatePresence>
         {viewState === 'summary' && (
            <SummaryView 
                clientData={clientData}
                onUpdateClientData={onUpdateClientData}
                quoteData={quoteData}
                totalPrice={totalPrice}
                paymentMethod={paymentMethod}
                setPaymentMethod={setPaymentMethod}
                summaryDetails={summaryDetails}
                priceBreakdown={priceBreakdown}
                onBack={() => setViewState('config')}
                onProceedToSign={() => setIsModalOpen(true)}
                onRemoveAddon={handleRemoveAddon}
            />
         )}
      </AnimatePresence>

      <SignatureModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleSignatureSuccess}
        totalValue={formatCurrency(totalPrice)}
      />

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleUpdateLocation}
        initialAddress={clientData.location}
      />
    </div>
  );
};

export default QuoteView;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Camera, Video, Gift, Crown, GraduationCap, Heart, 
  Store, Aperture, Plane, Clock, Minus, Plus, Route, Star, 
  Edit, Smartphone as SmartphoneIcon, Sparkles, Gem, HelpCircle, X, MessageCircle, Hand, Check, Timer
} from 'lucide-react';

import { cn, formatCurrency } from '../../lib/utils';
import { fadeInUp, staggerContainer, modalVariants } from '../../lib/animations';
import { ServiceCategory, ServiceId } from '../../types';
import AnimatedNumber from '../ui/AnimatedNumber';
import { AppConfig } from '../../config/AppConfig';
import Button from '../ui/Button';

interface UpsellListProps {
  category: ServiceCategory;
  setCategory: (c: ServiceCategory) => void;
  serviceId: ServiceId;
  setServiceId: (s: ServiceId) => void;
  hours: number;
  setHours: (h: number) => void;
  qty: number;
  setQty: (q: number) => void;
  addDrone: boolean;
  setAddDrone: (b: boolean) => void;
  addRealTime: boolean;
  setAddRealTime: (b: boolean) => void;
  distance: number;
  pricePerKm: number;
  locationClient: string;
  onOpenMap?: () => void;
  selectionMode?: 'duration' | 'quantity';
  setSelectionMode?: (mode: 'duration' | 'quantity') => void;
  viewMode?: 'categories' | 'services' | 'config';
  isQuickMode?: boolean; // Nova prop
}

const UpsellList: React.FC<UpsellListProps> = (props) => {
  const { 
    category, setCategory, serviceId, setServiceId,
    hours, setHours, qty, setQty, addDrone, setAddDrone, addRealTime, setAddRealTime,
    distance, pricePerKm, locationClient, onOpenMap, selectionMode, setSelectionMode,
    viewMode = 'categories',
    isQuickMode = false
  } = props;

  const [infoData, setInfoData] = useState<{ title: string; desc: string; price: string } | null>(null);

  // === READ FROM APP CONFIG ===
  const TABLE = AppConfig.PRICING_TABLE;

  const categories = [
    { id: 'wedding', label: 'Casamento', icon: Heart },
    { id: 'social', label: 'Social', icon: Gift },
    { id: 'commercial', label: 'Comercial', icon: Store },
    { id: 'studio', label: 'Estúdio', icon: Aperture },
    { id: 'video_production', label: 'Freelancer', icon: Video },
    { id: 'custom', label: 'Outros', icon: Star },
  ];

  const handleServiceSelect = (id: ServiceId, mode: 'duration' | 'quantity' = 'duration') => {
    setServiceId(id);
    if (setSelectionMode) setSelectionMode(mode);

    // Smart Defaults (UX)
    if (id === 'comm_photo') setQty(20);
    else if (id === 'comm_video') setQty(1);
    else if (id === 'studio_photo') setQty(8);
    else if (category === 'social') setQty(10);
  };

  // === VISIBILITY LOGIC ===
  // Alteração: Removemos 'video_production' daqui para que Cam/Mobile/Drone não mostrem relógio
  const showDuration = (category === 'social' && serviceId !== 'graduation' && selectionMode === 'duration') ||
                       (category === 'studio' && selectionMode === 'duration');

  const showQuantity = (category === 'commercial') || 
                       (category === 'social' && serviceId !== 'graduation' && selectionMode === 'quantity') ||
                       (category === 'studio' && selectionMode === 'quantity') ||
                       (category === 'video_production' && serviceId === 'edit_only');

  const canChooseMode = category === 'social' && serviceId !== 'graduation';

  const isNoTravelCost = category === 'studio' || category === 'custom' || serviceId === 'edit_only';
  const travelCost = isNoTravelCost ? 0 : distance * 2 * pricePerKm;

  // Lógica de Mínimo
  let minQty = 1;
  if (category === 'studio' && serviceId === 'studio_photo') minQty = 8;
  if (category === 'social') minQty = 10;

  // Renderização Condicional baseada no viewMode
  return (
    <section className="w-full max-w-4xl mx-auto">

      {/* === STEP 1: CATEGORY SELECTION === */}
      {viewMode === 'categories' && (
        <div className="space-y-12 text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* MOBILE GRID ADJUSTMENT: Grid responsivo com aspect-square */}
            <div className="grid grid-cols-3 md:grid-cols-6 gap-3 md:gap-4 relative px-2">
                {categories.map((cat) => {
                    const isActive = category === cat.id;
                    const Icon = cat.icon;
                    return (
                        <motion.button
                            key={cat.id}
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => setCategory(cat.id as ServiceCategory)}
                            className={cn(
                                "flex flex-col items-center justify-center gap-2 md:gap-3 rounded-2xl transition-all duration-300 border w-full aspect-square",
                                isActive 
                                    ? "bg-brand-DEFAULT border-brand-DEFAULT text-white shadow-[0_0_25px_var(--brand-glow)]" 
                                    : "bg-white/5 border-white/5 text-neutral-400 hover:border-white/20 hover:text-white hover:bg-white/10"
                            )}
                        >
                            <Icon size={28} className={cn("md:w-8 md:h-8", isActive ? "text-white" : "text-neutral-500")} />
                            <span className="text-[9px] md:text-xs font-bold uppercase tracking-widest truncate w-full px-1">{cat.label}</span>
                        </motion.button>
                    )
                })}
            </div>

             <motion.div 
                key={category} 
                initial={{ opacity: 0, y: 10 }} 
                animate={{ opacity: 1, y: 0 }}
                className="bg-white/5 p-4 md:p-6 rounded-xl border border-white/10 max-w-lg mx-auto"
            >
                <p className="text-neutral-300 font-serif italic text-base md:text-lg">
                    "{AppConfig.TEXTS.CATEGORY_DESCRIPTIONS[category]}"
                </p>
            </motion.div>
        </div>
      )}

      {/* === STEP 2: SERVICE SELECTION === */}
      {viewMode === 'services' && (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-8 duration-500">

             {/* Modo de Seleção (Se aplicável) - VISUAL REFORÇADO */}
             {canChooseMode && setSelectionMode && (
                <div className="flex flex-col items-center mb-10">
                    <p className="text-center text-[10px] uppercase tracking-widest text-brand-DEFAULT mb-3 font-bold">
                        Como deseja contratar?
                    </p>
                    <div className="flex bg-neutral-900 p-2 rounded-2xl border border-white/10 shadow-lg">
                        <button 
                            onClick={() => setSelectionMode('duration')} 
                            className={cn(
                                "px-6 py-4 rounded-xl text-xs md:text-sm font-bold transition-all flex items-center gap-3 w-40 justify-center", 
                                selectionMode === 'duration' 
                                    ? "bg-white text-black shadow-lg scale-105 z-10" 
                                    : "text-neutral-500 hover:text-white hover:bg-white/5"
                            )}
                        >
                            <Clock size={18} className={selectionMode === 'duration' ? "text-brand-DEFAULT" : ""} /> 
                            POR TEMPO
                        </button>
                        <button 
                            onClick={() => setSelectionMode('quantity')} 
                            className={cn(
                                "px-6 py-4 rounded-xl text-xs md:text-sm font-bold transition-all flex items-center gap-3 w-40 justify-center", 
                                selectionMode === 'quantity' 
                                    ? "bg-white text-black shadow-lg scale-105 z-10" 
                                    : "text-neutral-500 hover:text-white hover:bg-white/5"
                            )}
                        >
                            <Camera size={18} className={selectionMode === 'quantity' ? "text-brand-DEFAULT" : ""} /> 
                            POR FOTO
                        </button>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
                 {/* Wedding Options */}
                 {category === 'wedding' && (
                    <>
                        <ServiceCard active={serviceId === 'wedding_base'} onClick={() => handleServiceSelect('wedding_base')} onInfo={setInfoData} icon={Heart} title={TABLE.wedding.wedding_base.label} price={formatCurrency(TABLE.wedding.wedding_base.base)} composition={TABLE.wedding.wedding_base.composition} desc={TABLE.wedding.wedding_base.description} />
                        <ServiceCard active={serviceId === 'wedding_classic'} onClick={() => handleServiceSelect('wedding_classic')} onInfo={setInfoData} icon={Sparkles} title={TABLE.wedding.wedding_classic.label} price={formatCurrency(TABLE.wedding.wedding_classic.base)} composition={TABLE.wedding.wedding_classic.composition} desc={TABLE.wedding.wedding_classic.description} highlight />
                        <ServiceCard active={serviceId === 'wedding_essence'} onClick={() => handleServiceSelect('wedding_essence')} onInfo={setInfoData} icon={Gem} title={TABLE.wedding.wedding_essence.label} price={formatCurrency(TABLE.wedding.wedding_essence.base)} composition={TABLE.wedding.wedding_essence.composition} desc={TABLE.wedding.wedding_essence.description} highlight />
                    </>
                )}

                {/* Social Options */}
                {category === 'social' && (
                    <>
                        <ServiceCard active={serviceId === 'birthday'} onClick={() => handleServiceSelect('birthday')} onInfo={setInfoData} icon={Gift} title={TABLE.social.birthday.label} price="A partir de R$ 400" composition={TABLE.social.birthday.composition} desc={TABLE.social.birthday.description} />
                        <ServiceCard active={serviceId === 'fifteen'} onClick={() => handleServiceSelect('fifteen')} onInfo={setInfoData} icon={Crown} title={TABLE.social.fifteen.label} price="A partir de R$ 450" composition={TABLE.social.fifteen.composition} desc={TABLE.social.fifteen.description} />
                        <ServiceCard active={serviceId === 'graduation'} onClick={() => handleServiceSelect('graduation')} onInfo={setInfoData} icon={GraduationCap} title={TABLE.social.graduation.label} price={formatCurrency(TABLE.social.graduation.base)} composition={TABLE.social.graduation.composition} desc={TABLE.social.graduation.description} />
                    </>
                )}

                {/* Commercial Options */}
                {category === 'commercial' && (
                    <>
                        <ServiceCard active={serviceId === 'comm_photo'} onClick={() => handleServiceSelect('comm_photo', 'quantity')} onInfo={setInfoData} icon={Camera} title={TABLE.commercial.photo.label} price={`R$ ${TABLE.commercial.photo.unit}/un`} composition={TABLE.commercial.photo.composition} desc={TABLE.commercial.photo.description} />
                        <ServiceCard active={serviceId === 'comm_video'} onClick={() => handleServiceSelect('comm_video', 'quantity')} onInfo={setInfoData} icon={Video} title={TABLE.commercial.video.label} price={`R$ ${TABLE.commercial.video.unit}/un`} composition={TABLE.commercial.video.composition} desc={TABLE.commercial.video.description} />
                        <ServiceCard active={serviceId === 'comm_combo'} onClick={() => handleServiceSelect('comm_combo', 'quantity')} onInfo={setInfoData} icon={Star} title={TABLE.commercial.combo.label} price={formatCurrency(TABLE.commercial.combo.videoBase)} composition={TABLE.commercial.combo.composition} desc={TABLE.commercial.combo.description} highlight />
                    </>
                )}

                {/* Studio Options */}
                {category === 'studio' && (
                    <>
                        <ServiceCard active={serviceId === 'studio_photo'} onClick={() => handleServiceSelect('studio_photo', 'quantity')} onInfo={setInfoData} icon={Aperture} title={TABLE.studio.photo.label} price={`R$ ${TABLE.studio.photo.unit}/un`} composition={TABLE.studio.photo.composition} desc={TABLE.studio.photo.description} />
                        <ServiceCard active={serviceId === 'studio_video'} onClick={() => handleServiceSelect('studio_video', 'duration')} onInfo={setInfoData} icon={Video} title={TABLE.studio.video.label} price={formatCurrency(TABLE.studio.video.base)} composition={TABLE.studio.video.composition} desc={TABLE.studio.video.description} />
                    </>
                )}

                {/* Production Options */}
                {category === 'video_production' && (
                    <>
                        <ServiceCard active={serviceId === 'edit_only'} onClick={() => handleServiceSelect('edit_only', 'quantity')} onInfo={setInfoData} icon={Edit} title={TABLE.video_production.edit.label} price={`R$ ${TABLE.video_production.edit.unit}`} composition={TABLE.video_production.edit.composition} desc={TABLE.video_production.edit.description} />
                        <ServiceCard active={serviceId === 'cam_cap'} onClick={() => handleServiceSelect('cam_cap', 'duration')} onInfo={setInfoData} icon={Video} title={TABLE.video_production.cam_cap.label} price={formatCurrency(TABLE.video_production.cam_cap.fixed)} composition={TABLE.video_production.cam_cap.composition} desc={TABLE.video_production.cam_cap.description} />
                        <ServiceCard active={serviceId === 'mobile_cap'} onClick={() => handleServiceSelect('mobile_cap', 'duration')} onInfo={setInfoData} icon={SmartphoneIcon} title={TABLE.video_production.mobile_cap.label} price={formatCurrency(TABLE.video_production.mobile_cap.fixed)} composition={TABLE.video_production.mobile_cap.composition} desc={TABLE.video_production.mobile_cap.description} />
                        <ServiceCard active={serviceId === 'drone'} onClick={() => handleServiceSelect('drone', 'duration')} onInfo={setInfoData} icon={Plane} title={TABLE.video_production.drone.label} price={formatCurrency(TABLE.video_production.drone.fixed)} composition={TABLE.video_production.drone.composition} desc={TABLE.video_production.drone.description} />
                    </>
                )}

                {/* Custom Option */}
                {category === 'custom' && (
                    <motion.div variants={fadeInUp} className="col-span-1 md:col-span-3 bg-white/5 border border-white/10 p-10 rounded-2xl text-center backdrop-blur-sm flex flex-col items-center">
