import React, { useId } from 'react';
import { motion } from 'framer-motion';

/**
 * Componente SVG: Tira de Filme (Film Strip)
 * Renderiza uma tira vertical infinita com animação de rolagem contínua.
 * Refinado para realismo: Furos tipo "Kodak" 35mm e bordas de película.
 */
const FilmStripTexture = ({ 
  className, 
  speed = 20, 
  direction = 1 
}: { 
  className?: string, 
  speed?: number, 
  direction?: number 
}) => {
  // Gera um ID único e estável para este componente específico
  // Isso impede que o navegador confunda o padrão da esquerda com o da direita
  const patternId = useId();

  // Altura exata de um "bloco" do filme (4 furos + espaço)
  const PATTERN_HEIGHT = 40; 

  return (
    <svg
      viewBox="0 0 100 100"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      preserveAspectRatio="none"
    >
      <defs>
        <pattern 
          id={patternId} 
          x="0" 
          y="0" 
          width="100" 
          height={PATTERN_HEIGHT} 
          patternUnits="userSpaceOnUse"
        >
           {/* Fundo da Película (Escuro) */}
           <rect x="0" y="0" width="100" height={PATTERN_HEIGHT} fill="currentColor" fillOpacity="0.1" />

           {/* Furos Esquerdos (Sprockets) - Menores e mais espaçados */}
           <rect x="8" y="5" width="6" height="8" rx="1.5" fill="currentColor" fillOpacity="0.6" />
           <rect x="8" y="15" width="6" height="8" rx="1.5" fill="currentColor" fillOpacity="0.6" />
           <rect x="8" y="25" width="6" height="8" rx="1.5" fill="currentColor" fillOpacity="0.6" />

           {/* Furos Direitos (Sprockets) */}
           <rect x="86" y="5" width="6" height="8" rx="1.5" fill="currentColor" fillOpacity="0.6" />
           <rect x="86" y="15" width="6" height="8" rx="1.5" fill="currentColor" fillOpacity="0.6" />
           <rect x="86" y="25" width="6" height="8" rx="1.5" fill="currentColor" fillOpacity="0.6" />

           {/* Linha divisória de quadro (Frame Line) */}
           <line x1="20" y1="39" x2="80" y2="39" stroke="currentColor" strokeWidth="0.5" strokeOpacity="0.3" />
        </pattern>
      </defs>

      {/* Bordas laterais sólidas da película */}
      <line x1="4" y1="0" x2="4" y2="100%" stroke="currentColor" strokeWidth="0.5" strokeOpacity="0.3" />
      <line x1="96" y1="0" x2="96" y2="100%" stroke="currentColor" strokeWidth="0.5" strokeOpacity="0.3" />

      {/* Área da Imagem (Zona segura central) */}
      <rect x="20" width="60" height="100%" fill="currentColor" fillOpacity="0.02" />
      <line x1="20" y1="0" x2="20" y2="100%" stroke="currentColor" strokeWidth="0.2" strokeOpacity="0.3" />
      <line x1="80" y1="0" x2="80" y2="100%" stroke="currentColor" strokeWidth="0.2" strokeOpacity="0.3" />

      {/* 
          ANIMAÇÃO DE ROLAGEM (Infinite Scroll)
          Importante: O 'y' deve mover exatamente a altura do pattern (ou múltiplos)
          para o loop ser imperceptível.
      */}
      <motion.rect 
        x="0"
        y={-PATTERN_HEIGHT} 
        width="100" 
        height={`calc(100% + ${PATTERN_HEIGHT}px)`} // Garante cobertura total
        fill={`url(#${patternId})`}
        animate={{ 
          y: direction > 0 ? [0, -PATTERN_HEIGHT] : [-PATTERN_HEIGHT, 0] 
        }}
        transition={{ 
          repeat: Infinity, 
          ease: "linear", 
          duration: speed 
        }}
      />
    </svg>
  );
};

