  opacity?: number
}) => {
  const patternId = useId();

  // Altura de UM quadro de filme (incluindo a barra de separação)
  // No SVG coordinate system: 0-100 largura. 
  // Proporção 35mm é aprox 3:2. Se largura é 100, altura do frame é aprox 66.
