        >
           {/* 1. Base da Película (Dark Celluloid) */}
           <rect x="0" y="0" width="100" height={FRAME_HEIGHT} fill="#050505" />

           {/* 2. Área da Imagem (O "buraco" central onde ficaria a foto) */}
           {/* Deixamos levemente transparente para ver o fundo do site ou cinza escuro */}
           <rect x="18" y="5" width="64" height="56" rx="2" fill="currentColor" fillOpacity="0.08" />

           {/* 3. Furos (Sprockets) - Padrão Kodak 35mm (4 furos por quadro) */}
