           </g>

           {/* Lado Direito */}
           <g fill="currentColor" fillOpacity="0.4">
             <rect x="88" y="4" width="8" height="10" rx="1.5" />
             <rect x="88" y="20" width="8" height="10" rx="1.5" />
             <rect x="88" y="36" width="8" height="10" rx="1.5" />
             <rect x="88" y="52" width="8" height="10" rx="1.5" />
           </g>

           {/* 4. Marcações de Texto (Edge Markings) - O detalhe que dá realismo */}
           {/* Texto Vertical Esquerdo: Tipo do Filme */}
           <text 
             x="15" y="35" 
             fontSize="3" 
             fontFamily="Arial, sans-serif" 
             fontWeight="bold" 
             fill="currentColor" 
             fillOpacity="0.3" 
