           {/* 5. Barra de Separação entre Quadros (Frame Line) */}
           <rect x="0" y="66" width="100" height="4" fill="#000000" fillOpacity="0.6" />
        </pattern>
      </defs>

      {/* 
          ANIMAÇÃO INFINITA
          Movemos o rect preenchido com o padrão.
          O 'y' vai de 0 até -FRAME_HEIGHT para criar o loop perfeito.
      */}
      <motion.rect 
        x="0"
