const RealisticFilmStripTexture = ({ className, speed = 10, direction = 1, opacity = 1 }: { className?: string, speed?: number, direction?: number, opacity?: number }) => (
  <div className={`relative overflow-hidden ${className}`} style={{ opacity }}>
      <svg
