              {/* 3. Sprockets (Furos) - Simula luz passando (Brilho alto) */}
              <g fill="#e5e5e5" fillOpacity="0.95">
                  <rect x="8" y="12" width="8" height="12" rx="1.5" />
                  <rect x="8" y="42" width="8" height="12" rx="1.5" />
                  <rect x="8" y="72" width="8" height="12" rx="1.5" />
