                  <rect x="124" y="42" width="8" height="12" rx="1.5" />
                  <rect x="124" y="72" width="8" height="12" rx="1.5" />
              </g>
            </pattern>

            {/* 
               REFINAMENTO 2: REFLEXO CILÍNDRICO (ANISOTRÓPICO)
               Um highlight vertical forte e fino no meio para simular curvatura da fita.
               Isso é crucial para dar volume 3D.
            */}
            <linearGradient id={sheenId} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="white" stopOpacity="0.02" />
                <stop offset="20%" stopColor="white" stopOpacity="0" />
                <stop offset="35%" stopColor="white" stopOpacity="0" />
                <stop offset="45%" stopColor="white" stopOpacity="0.05" />
                <stop offset="48%" stopColor="white" stopOpacity="0.5" /> {/* Brilho Especular Fino */}
                <stop offset="52%" stopColor="white" stopOpacity="0.05" />
                <stop offset="65%" stopColor="white" stopOpacity="0" />
                <stop offset="100%" stopColor="white" stopOpacity="0.02" />
            </linearGradient>

            {/* Sombra de Borda (Vignette Cilíndrica) */}
            <linearGradient id="edge-shadow" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="black" stopOpacity="0.8"/>
                <stop offset="10%" stopColor="black" stopOpacity="0"/>
                <stop offset="90%" stopColor="black" stopOpacity="0"/>
                <stop offset="100%" stopColor="black" stopOpacity="0.8"/>
            </linearGradient>

          </defs>

          {/* CAMADA 1: FITA EM MOVIMENTO */}
          <motion.rect 
            x="0"
            y="-90"
            width="140" 
            height="300%"
            fill={`url(#${patternId})`}
            animate={{ 
              y: direction > 0 ? [0, -90] : [-90, 0] 
            }}
            transition={{ 
              repeat: Infinity, 
              ease: "linear", 
              duration: speed 
