  const [isShining, setIsShining] = useState(false);

  const handleClick = useCallback(() => {
    if (!isShining) {
        setIsShining(true);
        setTimeout(() => setIsShining(false), 1000); // Tempo da animação
    }
  }, [isShining]);

  const containerVariants: Variants = {
    hidden: { 
      opacity: 0, 
      scale: 0.8, 
      filter: 'blur(10px)' 
    },
    visible: { 
      opacity: 1, 
      scale: 1, 
      filter: 'blur(0px)',
      transition: { 
        duration: 1.2, 
        ease: [0.22, 1, 0.36, 1] 
      } 
    }
  };

  return (
    <motion.div 
      initial={animate ? "hidden" : "visible"}
      animate="visible"
      variants={containerVariants}
      onClick={handleClick}
      className={cn("relative select-none cursor-pointer overflow-hidden rounded-lg group", className)}
      whileTap={{ scale: 0.95 }}
    >
      <SvgContent />

      {/* SHINE EFFECT OVERLAY */}
      <AnimatePresence>
        {isShining && (
            <motion.div
                initial={{ x: '-150%', opacity: 0 }}
                animate={{ x: '150%', opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.8, ease: "easeInOut" }}
                className="absolute inset-0 z-20 w-1/2 h-full -skew-x-12 bg-gradient-to-r from-transparent via-white/40 to-transparent blur-md"
                style={{ mixBlendMode: 'overlay' }}
            />
        )}
      </AnimatePresence>

      {/* Hint visual de interatividade (Sutil) */}
      <div className="absolute inset-0 bg-white/0 group-hover:bg-white/5 transition-colors duration-500 pointer-events-none rounded-lg" />
    </motion.div>
  );
});

