                                </span>
                                <span className="text-xs text-neutral-500 font-bold uppercase tracking-[0.4em]">Horas</span>
                            </div>
                            <ControlBtn onClick={() => setHours(hours + 1)} icon={Plus} active />
                        </div>
                    </motion.div>
                )}

                {showQuantity && (
                    <motion.div 
                        key="quantity"
                        variants={fadeInUp} initial="hidden" animate="visible" exit="hidden"
