                                    {cat.label}
                                </h3>
                                <p className={cn(
                                    "text-[10px] md:text-base font-medium tracking-wide transition-colors duration-300 opacity-80 hidden md:block",
                                    isActive ? "text-white/80" : "text-neutral-500 group-hover:text-neutral-400"
