                {/* Custom Option */}
                {category === 'custom' && (
                    <motion.div variants={fadeInUp} className="col-span-2 md:col-span-3 bg-white/5 border border-white/10 p-6 md:p-10 rounded-2xl text-center backdrop-blur-sm flex flex-col items-center justify-center h-full">
