    setIsQuickMode(true); // Ativa flag
    setIsLoading(true);
    setIsQuoteSuccess(false);
    await delay(800); // Delay menor para sensação de rapidez
    setIsLoading(false);
    setView('quote');
    window.scrollTo(0, 0);
  };

