                                >
                                    <Check size={10} className="md:w-[14px] md:h-[14px]" strokeWidth={4} />
                                </motion.div>
                            )}

                            <div className={cn(
                                "p-3 md:p-5 rounded-xl md:rounded-full transition-all duration-300 mb-1",
