/**
 * EnvConfig
 * ---------
 * Singleton para acesso seguro e tipado a variáveis de ambiente.
 * Centraliza a leitura de import.meta.env para facilitar manutenção e testes.
 */
export class EnvConfig {
  private static getEnv(key: string): string {
    // @ts-ignore - Vite uses import.meta.env
    return import.meta.env[key] || "";
  }

  static get GOOGLE_API_KEY(): string {
    return this.getEnv("VITE_GOOGLE_API_KEY");
  }

  static get GOOGLE_CALENDAR_ID(): string {
    return this.getEnv("VITE_GOOGLE_CALENDAR_ID");
  }

  /**
   * Verifica se estamos rodando em modo de produção
   */
  static get IS_PROD(): boolean {
    return this.getEnv("MODE") === "production";
  }

  /**
   * Verifica se as integrações externas estão configuradas
   */
  static get HAS_CALENDAR_INTEGRATION(): boolean {
    return !!this.GOOGLE_API_KEY && !!this.GOOGLE_CALENDAR_ID;
  }
}

/**
 * Módulo de Segurança
 * -------------------
 * Utilitários para criptografia, hash e saneamento de dados.
 */

/**
 * Gera um Hash SHA-256 de uma string.
 * Utiliza a API nativa de criptografia do navegador (SubtleCrypto).
 */
export const sha256 = async (message: string): Promise<string> => {
  const msgBuffer = new TextEncoder().encode(message);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  return hashHex;
};

/**
 * Verifica se a senha fornecida corresponde ao Hash armazenado.
 * @param input Senha digitada pelo usuário
 * @param targetHash Hash SHA-256 esperado
 */
export const verifyHash = async (input: string, targetHash: string): Promise<boolean> => {
  if (!input) return false;
  const inputHash = await sha256(input.trim().toUpperCase());
  return inputHash === targetHash;
};

/**
 * Remove tags HTML e caracteres perigosos de uma string (Basic XSS Prevention).
 * Útil para dados que serão exibidos na UI ou salvos em localStorage.
 */
export const sanitizeInput = (input: string): string => {
  if (!input) return "";
  return input
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
};

/**
 * Gera um delay artificial para prevenir Timing Attacks rudimentares e melhorar UX.
 */
export const securityDelay = () => new Promise(resolve => setTimeout(resolve, 800));

