import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ClientData, QuoteData, QuoteState, ServiceCategory } from '../types';
import { mockQuote } from '../data/mock';
import { AppConfig } from '../config/AppConfig';

interface QuoteContextType {
  clientData: ClientData;
  setClientData: React.Dispatch<React.SetStateAction<ClientData>>;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  config: QuoteData;
  setConfig: React.Dispatch<React.SetStateAction<QuoteData>>;
  isQuickMode: boolean;
  setIsQuickMode: React.Dispatch<React.SetStateAction<boolean>>;
  resetQuote: () => void;
}

const QuoteContext = createContext<QuoteContextType | undefined>(undefined);

export const QuoteProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Inicializa clientData do localStorage ou vazio
  const [clientData, setClientData] = useState<ClientData>(() => {
    const saved = localStorage.getItem('earec_client_data');
    return saved ? JSON.parse(saved) : {
        name: '', 
        location: '', 
        date: '', 
        contact: ''
    };
  });

  const [config, setConfig] = useState<QuoteData>(mockQuote);
  const [isQuickMode, setIsQuickMode] = useState(false);

  const initialQuoteState: QuoteState = {
    category: null, 
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    videoQty: 1,
    addDrone: false,
    addRealTime: false,
    selectionMode: 'duration'
  };

  const [quoteState, setQuoteState] = useState<QuoteState>(initialQuoteState);

  // Persistência automática
  useEffect(() => {
    if (clientData.name) {
      localStorage.setItem('earec_client_data', JSON.stringify(clientData));
    }
  }, [clientData]);

  // Função para resetar o estado (novo orçamento)
  const resetQuote = () => {
    setQuoteState(initialQuoteState);
    setClientData({ name: '', location: '', date: '', contact: '' });
    setIsQuickMode(false);
    localStorage.removeItem('earec_client_data');
  };

  return (
    <QuoteContext.Provider value={{
      clientData,
      setClientData,
      quoteState,
      setQuoteState,
      config,
      setConfig,
      isQuickMode,
      setIsQuickMode,
      resetQuote
    }}>
      {children}
    </QuoteContext.Provider>
  );
};

export const useQuote = () => {
  const context = useContext(QuoteContext);
  if (context === undefined) {
    throw new Error('useQuote must be used within a QuoteProvider');
  }
  return context;
};

