import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { ArrowLeft, Save, Shield } from 'lucide-react';
import { QuoteData } from '../types';
import Button from '../components/ui/Button';
import { verifyHash, securityDelay } from '../lib/security';

interface AdminDashboardProps {
  currentConfig: QuoteData;
  onUpdateConfig: (newConfig: QuoteData) => void;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentConfig, onUpdateConfig, onExit }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  // Local state for editing config
  const [config, setConfig] = useState<QuoteData>(currentConfig);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Hash for "admin123" (Example) - In production use robust auth
    // SHA-256 of "admin123": 240be518fabd2724ddb6f04eeb1da5967448d7e831c08c8fa822809f74c720a9
    const targetHash = "240be518fabd2724ddb6f04eeb1da5967448d7e831c08c8fa822809f74c720a9"; 

    await securityDelay(); // Simulate network delay / prevent brute-force

    const isValid = await verifyHash(password, targetHash);

    if (isValid) {
      setIsAuthenticated(true);
    } else {
      setError('Senha incorreta');
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>, field: keyof QuoteData) => {
     const val = parseFloat(e.target.value);
     setConfig(prev => ({ ...prev, [field]: isNaN(val) ? 0 : val }));
  };

  const handleSave = () => {
