import React, { useEffect, useRef, useState } from 'react';
import { motion as m, AnimatePresence } from 'framer-motion';
import { X, MapPin, Check, Loader2, Info } from 'lucide-react';
import Button from './Button';
import { modalVariants } from '../../lib/animations';
import L from 'leaflet';

const motion = m as any;

interface LocationMapModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectLocation: (address: string) => void;
  initialAddress?: string;
}

const LocationMapModal: React.FC<LocationMapModalProps> = ({ isOpen, onClose, onSelectLocation, initialAddress }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);
  const markerRef = useRef<L.Marker | null>(null);

  const [currentAddress, setCurrentAddress] = useState("Carregando posição...");
  const [isLoading, setIsLoading] = useState(true);

  // Inicialização do Mapa
  useEffect(() => {
    if (!isOpen) return;

    // Pequeno delay para garantir que o DOM renderizou o container
    const timer = setTimeout(() => {
        if (mapContainerRef.current && !mapInstanceRef.current) {
            // 1. Cria o mapa
            // Coordenadas iniciais: Goianinha/RN (Fallback)
            const initialLat = -6.2662; 
            const initialLng = -35.2227;

            const map = L.map(mapContainerRef.current).setView([initialLat, initialLng], 13);

            // 2. Adiciona TileLayer (Tema CLARO - CartoDB Positron)
            L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
                attribution: '&copy; OpenStreetMap contributors &copy; CARTO',
                subdomains: 'abcd',
                maxZoom: 19
            }).addTo(map);

            // 3. Ícone Personalizado
            const customIcon = L.divIcon({
                className: 'bg-transparent',
                html: `<svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 24 24" fill="#DC2626" stroke="#ffffff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-map-pin drop-shadow-lg"><path d="M20 10c0 6-9 13-9 13s-9-7-9-13a9 9 0 0 1 18 0Z"/><circle cx="12" cy="10" r="3" fill="white"/></svg>`,
                iconSize: [36, 36],
                iconAnchor: [18, 36],
            });

            // 4. Cria o Marcador Arrastável
            const marker = L.marker([initialLat, initialLng], { 
                draggable: true,
                icon: customIcon 
            }).addTo(map);

            markerRef.current = marker;
            mapInstanceRef.current = map;

            // 5. Tenta pegar geolocalização do usuário
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition(
                    (pos) => {
                        const { latitude, longitude } = pos.coords;
                        map.setView([latitude, longitude], 15);
                        marker.setLatLng([latitude, longitude]);
                        fetchAddress(latitude, longitude); 
                    },
                    () => {
                        fetchAddress(initialLat, initialLng); 
                    }
                );
            } else {
                fetchAddress(initialLat, initialLng);
            }

            // 6. Event Listener: Arrastar Marcador
            marker.on('dragend', async (e) => {
                const { lat, lng } = e.target.getLatLng();
                await fetchAddress(lat, lng);
            });

            // 7. Event Listener: Clicar no Mapa
            map.on('click', async (e) => {
                const { lat, lng } = e.latlng;
                marker.setLatLng([lat, lng]);
                await fetchAddress(lat, lng);
            });
        }
    }, 100);

    return () => {
        clearTimeout(timer);
        if (mapInstanceRef.current) {
            mapInstanceRef.current.remove();
            mapInstanceRef.current = null;
        }
    };
  }, [isOpen]);

  // Função para buscar endereço (Reverse Geocoding)
  const fetchAddress = async (lat: number, lng: number) => {
      setIsLoading(true);
      try {
          const response = await fetch(
              `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&zoom=18&addressdetails=1`,
              { headers: { 'Accept-Language': 'pt-BR' } }
          );
          if (!response.ok) throw new Error(`Nominatim error: ${response.status}`);
          const data = await response.json();

          if (data && data.address) {
              const street = data.address.road || data.address.pedestrian || "";
              const number = data.address.house_number || "";
              const district = data.address.suburb || data.address.neighbourhood || "";
              const city = data.address.city || data.address.town || data.address.village || "";
              const state = data.address.state || "";

              const fullAddress = [street, number, district, city, state]
                .filter(part => part && part.trim() !== "")
                .join(", ");

              setCurrentAddress(fullAddress || `${lat.toFixed(5)}, ${lng.toFixed(5)}`);
          } else {
              setCurrentAddress(`${lat.toFixed(5)}, ${lng.toFixed(5)}`);
          }
      } catch (error) {
          setCurrentAddress(`${lat.toFixed(5)}, ${lng.toFixed(5)}`);
      } finally {
          setIsLoading(false);
      }
  };

  const handleConfirm = () => {
      onSelectLocation(currentAddress);
      onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-neutral-950/90 backdrop-blur-sm"
            onClick={onClose}
          />

          <motion.div
            variants={modalVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            className="relative bg-neutral-900 border border-white/10 rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]"
          >
            {/* Header */}
            <div className="p-4 border-b border-white/10 flex justify-between items-center bg-neutral-900 z-10">
                <div>
                    <h3 className="text-white font-medium flex items-center gap-2">
                        <MapPin size={18} className="text-brand-DEFAULT" />
                        Local do Serviço
                    </h3>
                    <p className="text-xs text-neutral-500 flex items-center gap-1 mt-1">
                       <Info size={12} />
                       Arraste o pino vermelho ou clique no mapa.
                    </p>
                </div>
                <button onClick={onClose} className="text-neutral-400 hover:text-white p-2">
                    <X size={20} />
                </button>
            </div>

            {/* Mapa */}
            <div className="relative flex-1 min-h-[400px] w-full bg-neutral-950">
                <div ref={mapContainerRef} className="absolute inset-0 z-0" />

                {/* Overlay de Endereço */}
                <div className="absolute top-4 left-4 right-4 z-[400] bg-neutral-900/90 backdrop-blur border border-white/10 p-3 rounded-lg shadow-xl flex items-center gap-3">
                    {isLoading ? (
                        <Loader2 size={20} className="text-brand-DEFAULT animate-spin shrink-0" />
                    ) : (
                        <MapPin size={20} className="text-brand-DEFAULT shrink-0" />
                    )}
                    <p className="text-sm text-white truncate font-medium">
                        {currentAddress}
                    </p>
                </div>
            </div>

            {/* Footer */}
            <div className="p-4 border-t border-white/10 bg-neutral-900 z-10 flex justify-end gap-3">
                <Button variant="secondary" onClick={onClose} size="sm">Cancelar</Button>
                <Button 
                    variant="primary" 
                    onClick={handleConfirm} 
                    size="sm"
                    className="shadow-[0_0_15px_rgba(220,38,38,0.4)]"
                    disabled={isLoading}
                >
                    <Check size={16} className="mr-2" />
                    Confirmar Local
                </Button>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

export default LocationMapModal;

import React, { useId } from 'react';
import { motion as m } from 'framer-motion';

const motion = m as any;

/**
 * RealisticFilmStripTexture
 * -------------------------
 * Textura procedural de filme 35mm com simulação de volume cilíndrico.
 * 
 * TÉCNICAS DE VOLUME (CURVAS):
 * 1. Gradiente Cilíndrico (Sheen): Um highlight fino e intenso no centro-direita simula a crista da curva.
 * 2. Sombras de Borda (Fresnel Darkening): As bordas escurecem drasticamente para simular a superfície virando para trás.
 * 3. Iluminação de Borda (Rim Light): Uma linha fina de luz nas extremidades para separar do fundo.
 */
const RealisticFilmStripTexture = ({ 
    className, 
    speed = 10, 
    direction = 1, 
    opacity = 1,
    perspective = false
}: { 
    className?: string, 
    speed?: number, 
    direction?: number, 
    opacity?: number,
    perspective?: boolean
}) => {
  const uniqueId = useId().replace(/:/g, ''); 
  const patternId = `film-pattern-${uniqueId}`;
  const sheenId = `sheen-${uniqueId}`;
  const curvatureId = `curvature-${uniqueId}`;
  const frameGradId = `frame-grad-${uniqueId}`;

  return (
    <div className={`relative overflow-hidden ${className}`} style={{ opacity }}>

        {/* RIM LIGHTS (Luz de Borda) - Crucial para destacar a silhueta curva no preto */}
        <div className="absolute top-0 left-0 w-[2px] h-full bg-gradient-to-b from-cyan-500/20 via-white/40 to-cyan-500/20 blur-[1px] z-30 mix-blend-screen" />
        <div className="absolute top-0 right-0 w-[2px] h-full bg-gradient-to-b from-red-500/20 via-white/40 to-red-500/20 blur-[1px] z-30 mix-blend-screen" />

        <svg
          viewBox="0 0 140 100"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          className="w-full h-full block"
          preserveAspectRatio="none"
        >
          <defs>
            {/* Gradiente Metálico do Frame (Interno) */}
            <linearGradient id={frameGradId} x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stopColor="#222" />
                <stop offset="50%" stopColor="#333" />
                <stop offset="100%" stopColor="#1a1a1a" />
            </linearGradient>

            {/* PADRÃO DA FITA */}
            <pattern id={patternId} x="0" y="0" width="140" height="90" patternUnits="userSpaceOnUse">
              <rect width="140" height="90" fill="#050505" />

              {/* Frame com cantos levemente mais arredondados */}
              <rect x="24" y="8" width="92" height="74" rx="3" fill={`url(#${frameGradId})`} stroke="#444" strokeWidth="0.5" />

              {/* Reflexo de Vidro no Frame */}
              <path d="M 24 82 L 116 8 L 116 45 L 24 110 Z" fill="white" fillOpacity="0.04" />

              {/* Sprockets (Furos) */}
              <g fill="#eeeeee" fillOpacity="0.9">
                  <rect x="7" y="12" width="9" height="14" rx="2" />
                  <rect x="7" y="42" width="9" height="14" rx="2" />
                  <rect x="7" y="72" width="9" height="14" rx="2" />
              </g>

              <g fill="#eeeeee" fillOpacity="0.9">
                  <rect x="124" y="12" width="9" height="14" rx="2" />
                  <rect x="124" y="42" width="9" height="14" rx="2" />
                  <rect x="124" y="72" width="9" height="14" rx="2" />
              </g>
            </pattern>

            {/* 
               GRADIENTE DE CURVATURA (MAPA DE VOLUME) 
               Simula a forma cilíndrica da fita.
               Escuro nas bordas -> Claro no "pico" da curva -> Escuro na outra borda.
            */}
            <linearGradient id={curvatureId} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="black" stopOpacity="0.9" />   {/* Borda Esquerda (Sombra Profunda) */}
                <stop offset="15%" stopColor="black" stopOpacity="0.4" />
                <stop offset="30%" stopColor="black" stopOpacity="0.1" />  {/* Início da Curva iluminada */}
                <stop offset="50%" stopColor="black" stopOpacity="0" />    {/* Centro Plano */}
                <stop offset="70%" stopColor="black" stopOpacity="0.1" />
                <stop offset="85%" stopColor="black" stopOpacity="0.5" />
                <stop offset="100%" stopColor="black" stopOpacity="0.9" /> {/* Borda Direita (Sombra Profunda) */}
            </linearGradient>

            {/* 
               REFLEXO ESPECULAR (ANISOTRÓPICO)
               O brilho "plástico" concentrado em uma linha vertical.
            */}
            <linearGradient id={sheenId} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="white" stopOpacity="0" />
                <stop offset="35%" stopColor="white" stopOpacity="0" />
                <stop offset="42%" stopColor="white" stopOpacity="0.05" />
                <stop offset="45%" stopColor="white" stopOpacity="0.3" />  {/* Highlight Principal */}
                <stop offset="48%" stopColor="white" stopOpacity="0.05" />
                <stop offset="60%" stopColor="white" stopOpacity="0" />
                <stop offset="100%" stopColor="white" stopOpacity="0" />
            </linearGradient>

          </defs>

          {/* CAMADA 1: CONTEÚDO (Móvel) */}
          <motion.rect 
            x="0"
            y="-90"
            width="140" 
            height="300%"
            fill={`url(#${patternId})`}
            animate={{ 
              y: direction > 0 ? [0, -90] : [-90, 0] 
            }}
            transition={{ 
              repeat: Infinity, 
              ease: "linear", 
              duration: speed 
            }}
          />

          {/* CAMADA 2: REFLEXO PLÁSTICO (Fixo) */}
          <rect 
            width="100%" 
            height="100%" 
            fill={`url(#${sheenId})`} 
            style={{ mixBlendMode: 'screen' }} 
            pointerEvents="none" 
          />

          {/* CAMADA 3: SOMBRA DE VOLUME (Curvatura Geométrica) */}
          {/* Multiplica as sombras sobre a fita para "arredondar" as bordas */}
          <rect width="100%" height="100%" fill={`url(#${curvatureId})`} style={{ mixBlendMode: 'multiply' }} pointerEvents="none" />

        </svg>
    </div>
  );
};

