            <Route path="/admin" element={
              <AdminDashboard 
                currentConfig={config}
                onUpdateConfig={setConfig}
                onExit={() => navigate('/')}
              />
            } />

            {/* Redirects */}
            <Route path="/resumo" element={<Navigate to="/orcamento" replace />} />
            <Route path="/sucesso" element={<Navigate to="/orcamento" replace />} />

            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        )}
      </div>
    </main>
  );
};

