import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ClientData, QuoteData, QuoteState } from '../types';
import { mockQuote } from '../data/mock';

interface QuoteContextType {
  // Dados do Cliente
  clientData: ClientData;
  setClientData: (data: ClientData) => void;

  // Estado do Configurador (Inputs do usuário)
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;

  // Configurações Globais (Preços base)
  config: QuoteData;
  setConfig: (data: QuoteData) => void;

  // Flags de Controle
  isQuickMode: boolean;
  setIsQuickMode: (mode: boolean) => void;

  // Actions
  resetQuoteState: () => void;
}

const QuoteContext = createContext<QuoteContextType | undefined>(undefined);

export const QuoteProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // 1. Configuração Inicial (Mock Data)
  // Como removemos o Admin, o config será majoritariamente estático, mas mantemos no estado
  // para permitir mutações temporárias se necessário no futuro.
  const [config, setConfig] = useState<QuoteData>(mockQuote);

  // 2. Modo Rápido
  const [isQuickMode, setIsQuickMode] = useState(false);

  // 3. Dados do Cliente (Com Persistência)
  const [clientData, setClientDataState] = useState<ClientData>(() => {
    // Tenta recuperar do localStorage ou usa valor default vazio
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('earec_client_data');
      return saved ? JSON.parse(saved) : {
        name: '', 
        location: '', 
        date: '', 
        contact: ''
      };
    }
    return { name: '', location: '', date: '', contact: '' };
  });

  // Wrapper para salvar no localStorage sempre que atualizar
  const setClientData = (data: ClientData) => {
    setClientDataState(data);
    localStorage.setItem('earec_client_data', JSON.stringify(data));
  };

  // 4. Estado do Orçamento (Seleções atuais)
  const defaultQuoteState: QuoteState = {
    category: null, 
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    videoQty: 1,
    addDrone: false,
    addRealTime: false,
    selectionMode: 'duration'
  };

  const [quoteState, setQuoteState] = useState<QuoteState>(defaultQuoteState);

  const resetQuoteState = () => {
    setQuoteState(defaultQuoteState);
  };

  return (
    <QuoteContext.Provider value={{
      clientData,
      setClientData,
      quoteState,
      setQuoteState,
      config,
      setConfig,
      isQuickMode,
      setIsQuickMode,
      resetQuoteState
    }}>
      {children}
    </QuoteContext.Provider>
  );
};

// Hook Customizado para consumo fácil
export const useQuote = () => {
  const context = useContext(QuoteContext);
  if (context === undefined) {
    throw new Error('useQuote deve ser usado dentro de um QuoteProvider');
  }
  return context;
};

