// Interfaces simplificadas pois agora usamos Contexto
interface QuoteViewProps {
  clientData: ClientData; 
  onUpdateClientData: (data: ClientData) => void; 
  config: QuoteData;      
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  // Callbacks de navegação simplificados
  onBack: () => void;
  onRequestForm: () => void;
  // Extras
  onSuccess: () => void; 
  onSummary: () => void; // New callback for summary view
  isQuickMode?: boolean;
}

const stepVariants = {
  enter: (direction: number) => ({
    x: direction > 0 ? 50 : -50,
    opacity: 0,
  }),
  center: {
    zIndex: 1,
    x: 0,
    opacity: 1,
    transition: {
        duration: 0.4,
        ease: [0.22, 1, 0.36, 1]
    }
  },
  exit: (direction: number) => ({
    zIndex: 0,
    x: direction < 0 ? 50 : -50,
    opacity: 0,
    transition: {
        duration: 0.3,
        ease: "easeIn"
    }
  })
};

const QuoteView: React.FC<QuoteViewProps> = (props) => {
  // Usa o hook de lógica existente, mas controlamos a navegação "final" aqui
  const logic = useQuoteLogic({
    ...props,
    onSuccess: props.onSuccess
  });

  const { state, actions, computed } = logic;
  const { quoteState } = props;

  // Intercepta a navegação para a tela de Resumo
  // O hook original mudava viewState para 'summary'. Vamos observar isso ou sobrescrever handleNextStep.

  // Sobrescrevendo a ação de "Próximo" para usar callbacks quando finalizar o wizard
  const handleSmartNext = () => {
      // Se estiver na última etapa do wizard e não for Custom
      if (state.currentStep === state.steps.length - 1 && quoteState.category !== 'custom') {
          // Verifica nome no modo rápido
          if (props.isQuickMode && !props.clientData.name) {
              actions.setIsNameModalOpen(true);
              return; 
          }
          props.onSummary();
      } else {
          // Comportamento padrão (Avançar etapa ou finalizar Custom)
          actions.handleNextStep();
      }
  };

  // Efeito para navegar se o hook definir viewState como 'summary' ou 'success' internamente
  React.useEffect(() => {
      if (state.viewState === 'summary') {
          props.onSummary();
      } else if (state.viewState === 'success') {
          props.onSuccess();
      }
  }, [state.viewState, props]);

  return (
    <div className="relative min-h-screen bg-black/80 flex flex-col">

      {/* Background sutil */}
      <div className="fixed inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-neutral-900 via-black to-black -z-10" />

      {/* HEADER: PROGRESS & NAV */}
