      <div className="relative z-10">
        {!showSplash && !isLoading && (
            <>
            {view === 'intro' && (
                <IntroView 
                    onContinue={() => {
                        setIsQuickMode(false);
                        setView('welcome');
                    }}
                    onQuickStart={handleQuickStart}
                />
            )}

            {view === 'welcome' && (
                <WelcomeView 
                  onStart={handleStart} 
                  onAdminClick={() => setView('admin')}
                  onBack={() => setView(isQuickMode ? 'quote' : 'intro')} 
                />
            )}

            {view === 'quote' && clientData && (
                <QuoteView 
                  clientData={clientData} 
                  onUpdateClientData={setClientData}
                  config={config}
                  onBack={() => setView(isQuickMode ? 'intro' : 'welcome')}
                  quoteState={quoteState}
                  setQuoteState={setQuoteState}
                  onSuccess={() => {
                      setIsQuoteSuccess(true);
                      setView('success');
                  }}
                  onSummary={() => setView('summary')}
                  isQuickMode={isQuickMode}
                  onRequestForm={handleRequestForm}
                />
            )}

            {view === 'summary' && clientData && (
                <SummaryView
                    clientData={clientData}
                    onUpdateClientData={setClientData}
                    quoteData={config}
                    totalPrice={totalPrice}
                    paymentMethod={paymentMethod}
                    setPaymentMethod={setPaymentMethod}
                    onBack={() => setView('quote')}
                    onProceedToSign={() => setView('success')}
                    summaryDetails={summaryDetails}
                    priceBreakdown={priceBreakdown}
                    onRemoveAddon={(name) => {
                         // Simple logic to toggle off if addon is removed
                         if(name.toLowerCase().includes('drone')) setQuoteState(s => ({...s, addDrone: false}));
                         if(name.toLowerCase().includes('tempo')) setQuoteState(s => ({...s, addRealTime: false}));
                    }}
                />
            )}

            {view === 'success' && clientData && (
                <SuccessView 
                    clientData={clientData}
                    onReset={() => {
                        setQuoteState(prev => ({ ...prev, category: null }));
                        setView('intro');
                    }}
                    totalPrice={totalPrice}
                    quoteDetails={quoteDetails}
                />
            )}

            {view === 'admin' && (
                <AdminDashboard 
                  currentConfig={config}
                  onUpdateConfig={handleAdminUpdate}
                  onExit={() => setView('welcome')}
                />
            )}
            </>
        )}
      </div>
    </main>
  );
};

export default App;

import React, { createContext, useContext, useState, ReactNode } from 'react';
import { ClientData, QuoteData, QuoteState } from '../types';
import { mockQuote } from '../data/mock';

interface QuoteContextType {
  // Dados do Cliente
  clientData: ClientData;
  setClientData: (data: ClientData) => void;

  // Estado do Configurador
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;

  // Configurações
  config: QuoteData;
  setConfig: (data: QuoteData) => void;

  // Estado da Aplicação
  isQuickMode: boolean;
  setIsQuickMode: (mode: boolean) => void;
  paymentMethod: string;
  setPaymentMethod: (method: string) => void;

  // Actions
  resetQuoteState: () => void;
}

const QuoteContext = createContext<QuoteContextType | undefined>(undefined);

export const QuoteProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [config, setConfig] = useState<QuoteData>(mockQuote);
  const [isQuickMode, setIsQuickMode] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('Pix');

  const [clientData, setClientDataState] = useState<ClientData>(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('earec_client_data');
      return saved ? JSON.parse(saved) : { name: '', location: '', date: '', contact: '' };
    }
    return { name: '', location: '', date: '', contact: '' };
  });

  const setClientData = (data: ClientData) => {
    setClientDataState(data);
    localStorage.setItem('earec_client_data', JSON.stringify(data));
  };

  const defaultQuoteState: QuoteState = {
    category: null, 
    serviceId: 'wedding_base',
    hours: 2,
    qty: 10,
    videoQty: 1,
    addDrone: false,
    addRealTime: false,
    selectionMode: 'duration'
  };

  const [quoteState, setQuoteState] = useState<QuoteState>(defaultQuoteState);

  const resetQuoteState = () => {
    setQuoteState(defaultQuoteState);
    setPaymentMethod('Pix');
    setIsQuickMode(false);
  };

  return (
    <QuoteContext.Provider value={{
      clientData,
      setClientData,
      quoteState,
      setQuoteState,
      config,
      setConfig,
      isQuickMode,
      setIsQuickMode,
      paymentMethod,
      setPaymentMethod,
      resetQuoteState
    }}>
      {children}
    </QuoteContext.Provider>
  );
};

export const useQuote = () => {
  const context = useContext(QuoteContext);
  if (context === undefined) {
    throw new Error('useQuote deve ser usado dentro de um QuoteProvider');
  }
  return context;
};

