import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Check, MessageCircle, ArrowRight, RefreshCcw, Sparkles, Send, User, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button'; 
import { fadeInUp, staggerContainer, modalVariants } from '../lib/animations';
import { cn, formatCurrency } from '../lib/utils';
import { AppConfig } from '../config/AppConfig';
import { useQuote } from '../context/QuoteContext';
import { PricingEngine } from '../core/PricingEngine';

const SuccessView: React.FC = () => {
  const navigate = useNavigate();
  const { 
    clientData, 
    quoteState, 
    resetQuoteState, 
    paymentMethod,
    config, isQuickMode,
    setClientData
  } = useQuote();

  const [isNameModalOpen, setIsNameModalOpen] = useState(false);
  const [tempName, setTempName] = useState('');

  // Recalcula o preço final para garantir consistência
  const pricing = useMemo(() => {
    // Nota: Como não temos a distância persistida no Contexto (apenas no componente local SummaryView anteriormente),
    // aqui usamos 0. Idealmente, a distância deveria ir para o QuoteContext.
    // Para MVP, assumimos que o cliente já viu o preço correto na tela anterior.
    // Se fosse crítico, moveríamos 'distance' para QuoteContext.
    return PricingEngine.calculate(quoteState, {
        pricePerKm: config.pricePerKm,
        photoUnitPrice: config.photoUnitPrice,
        videoUnitPrice: config.videoUnitPrice,
        distance: 0, 
        isQuickMode
    });
  }, [quoteState, config, isQuickMode]);

  const formatDate = (dateStr: string) => {
    if (!dateStr) return 'A definir';
    try {
        const [y, m, d] = dateStr.split('-');
        return `${d}/${m}/${y}`;
    } catch { return dateStr; }
  };

  const generateWhatsappUrl = (overrideName?: string) => {
    const finalName = overrideName || clientData.name || "Cliente";
    let message = "";

    // Constrói lista de addons
    const addons: string[] = [];
    if (quoteState.addDrone) addons.push('Drone');
    if (quoteState.addRealTime) addons.push('Tempo Real');
    const addonsText = addons.length > 0 ? addons.join(", ") : "Nenhum";

    if (quoteState.category === 'custom') {
        message = `🚀 *SOLICITAÇÃO DE PROJETO EXCLUSIVO*
Olá, equipe EAREC!

Gostaria de uma consultoria para um projeto personalizado.

👤 *MEUS DADOS*
*Cliente:* ${finalName}
*Local:* ${clientData.location}
*Data Prevista:* ${formatDate(clientData.date)}

💡 *MINHA DEMANDA*
Tenho um projeto específico e gostaria de discutir o briefing.

*Aguardo o retorno!*`;
    } else {
        const serviceLabel = quoteState.category ? AppConfig.getServiceLabel(quoteState.category, quoteState.serviceId) : '';
        let escopo = "";

        if (quoteState.serviceId === 'comm_combo') {
            escopo = "Combo Comercial (10 Fotos + 1 Vídeo)";
            const extraPhotos = quoteState.qty - 10;
            const extraVideos = quoteState.videoQty - 1;
            if (extraPhotos > 0) escopo += `\n   + ${extraPhotos} Fotos Extras`;
            if (extraVideos > 0) escopo += `\n   + ${extraVideos} Vídeos Extras`;
        } else if (quoteState.serviceId === 'edit_only') {
            escopo = `${quoteState.qty} Minutos de Edição`;
        } else if (quoteState.selectionMode === 'duration') {
            escopo = `${quoteState.hours} Horas de Cobertura`;
        } else {
            escopo = `${quoteState.qty} Unidades`;
        }

        const ambiente = quoteState.category === 'studio' ? "Estúdio Controlado" : "Externo / In Loco";

        message = `✨ *OLÁ! NOVA PROPOSTA GERADA*
Acabei de configurar meu pacote no site da EAREC.

🗓️ *AGENDA*
*Data:* ${formatDate(clientData.date)}
*Local:* ${clientData.location}

👤 *CLIENTE*
*Nome:* ${finalName}

🎬 *SERVIÇOS SELECIONADOS*
• *Pacote:* ${serviceLabel}
• *Tipo:* ${ambiente}
• *Escopo:* ${escopo}
• *Adicionais:* ${addonsText}

📍 *VALORES*
• *Pagamento:* ${paymentMethod}
• *Total Aprovado: ${formatCurrency(pricing.totalPrice)}*

--------------------------------
*Poderiam confirmar a reserva desta data?*`;
    }

    return `https://api.whatsapp.com/send?phone=${AppConfig.BRAND.WHATSAPP}&text=${encodeURIComponent(message)}`;
  };

  const handleSendClick = (e: React.MouseEvent) => {
    e.preventDefault(); 
    if (!clientData.name || clientData.name.trim() === '') {
        setIsNameModalOpen(true);
    } else {
        window.open(generateWhatsappUrl(), '_blank');
    }
  };

  const handleConfirmName = () => {
      if (tempName.trim().length < 2) return;
      setClientData({ ...clientData, name: tempName });
      setIsNameModalOpen(false);
      window.open(generateWhatsappUrl(tempName), '_blank');
  };

  const handleReset = () => {
      resetQuoteState();
      navigate('/');
  };

  return (
    <div className="w-full min-h-screen flex flex-col items-center justify-center relative overflow-hidden px-4 md:px-6">

      <div className="absolute inset-0 bg-neutral-950">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-neutral-900 via-black to-black opacity-80" />
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-brand-DEFAULT/5 blur-[100px] rounded-full pointer-events-none" />
      </div>

      <motion.div variants={staggerContainer} initial="hidden" animate="visible" className="relative z-10 w-full max-w-sm">
        <motion.div variants={fadeInUp} className="flex justify-center mb-12 opacity-90">
          <Logo className="w-48 md:w-64" />
        </motion.div>

        <motion.div variants={fadeInUp} className="bg-neutral-900/60 backdrop-blur-xl border border-white/10 rounded-3xl overflow-hidden shadow-2xl relative">
            <div className="h-1.5 w-full bg-gradient-to-r from-emerald-600 to-emerald-400" />

            <div className="p-8 flex flex-col items-center text-center">
                <div className="mb-6 relative">
                    <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: "spring", stiffness: 200, delay: 0.2 }} className="w-16 h-16 bg-emerald-500/10 rounded-full flex items-center justify-center border border-emerald-500/20 shadow-[0_0_30px_rgba(16,185,129,0.2)]">
                        <Check className="text-emerald-500" size={32} strokeWidth={3} />
                    </motion.div>
                    <motion.div 
                        initial={{ opacity: 0, scale: 0, rotate: 0 }}
                        animate={{ scale: [0, 1.3, 0], opacity: [0, 1, 0], rotate: [0, 45, 90] }}
                        transition={{ duration: 1.8, ease: "easeInOut", delay: 0.5, repeat: 0 }}
                        className="absolute -top-5 -right-5 text-emerald-300 pointer-events-none"
                    >
                        <Sparkles size={28} className="fill-emerald-300/20" />
                    </motion.div>
                </div>

                <h1 className="text-2xl font-serif text-white mb-2">Proposta Pronta</h1>
                <p className="text-neutral-400 text-sm leading-relaxed mb-16 font-light">
                    Sua configuração foi salva com sucesso. <br/>
                    Envie o resumo para nossa equipe no WhatsApp.
                </p>

                <div className="w-full relative group">
                    <motion.button 
                        onClick={handleSendClick}
                        className="w-full block relative overflow-hidden rounded-xl group cursor-pointer"
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                    >
                        <div className="relative bg-gradient-to-br from-emerald-600 to-emerald-700 hover:from-emerald-500 hover:to-emerald-600 text-white p-4 flex items-center justify-center gap-3 shadow-lg border border-emerald-400/20 transition-all z-10">
                            <MessageCircle size={22} fill="currentColor" className="text-white/90" />
                            <span className="font-bold tracking-wide text-sm">ENVIAR E FINALIZAR</span>
                            <ArrowRight size={16} className="text-white/70 group-hover:translate-x-1 transition-transform" />
                        </div>
                    </motion.button>
                </div>

                <button onClick={handleReset} className="mt-6 text-neutral-500 hover:text-white transition-colors text-xs flex items-center gap-2 py-2 px-4 rounded-full hover:bg-white/5">
                    <RefreshCcw size={12} />
                    <span>Novo pedido</span>
                </button>
            </div>
        </motion.div>

        <AnimatePresence>
            {isNameModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-neutral-950/90 backdrop-blur-md" onClick={() => setIsNameModalOpen(false)} />
                    <motion.div variants={modalVariants} initial="hidden" animate="visible" exit="exit" className="relative z-10 w-full max-w-sm bg-neutral-900 border border-white/10 rounded-2xl p-6 shadow-2xl">
                         <button onClick={() => setIsNameModalOpen(false)} className="absolute top-4 right-4 text-neutral-500 hover:text-white transition-colors"><X size={20} /></button>
                         <div className="flex flex-col items-center text-center mb-6">
                             <div className="p-3 bg-brand-DEFAULT/10 rounded-full text-brand-DEFAULT mb-4"><User size={24} /></div>
                             <h3 className="text-xl text-white font-serif mb-2">Identifique-se</h3>
                             <p className="text-neutral-400 text-xs leading-relaxed">Para finalizar, precisamos saber seu nome.</p>
                         </div>
                         <div className="space-y-4">
                            <input type="text" placeholder="Digite seu nome..." value={tempName} onChange={(e) => setTempName(e.target.value)} autoFocus className="w-full bg-black/30 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-brand-DEFAULT outline-none transition-colors" onKeyDown={(e) => e.key === 'Enter' && handleConfirmName()} />
                            <Button onClick={handleConfirmName} disabled={tempName.trim().length < 2} className="w-full">Continuar para WhatsApp</Button>
                         </div>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
      </motion.div>
    </div>
  );
};

