// Componente Wrapper para injetar hooks de navegação e contexto nas views
const AppContent: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  // Consumindo o Contexto
  const { 
    clientData, 
    setClientData, 
    quoteState, 
    setQuoteState, 
    config, 
    setConfig,
    isQuickMode,
    setIsQuickMode,
    resetQuoteState
  } = useQuote();

  // === DESIGN SYSTEM INJECTION ===
  useLayoutEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--brand-color', AppConfig.BRAND.COLORS.PRIMARY);
    root.style.setProperty('--brand-glow', `${AppConfig.BRAND.COLORS.PRIMARY}80`);
  }, []);

  useEffect(() => {
    // Reset de scroll em troca de rota
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
    window.scrollTo(0, 0);
  }, [location.pathname]);

  // Splash Screen Logic
  useEffect(() => {
    const timer = setTimeout(() => setShowSplash(false), 2200);
    return () => clearTimeout(timer);
  }, []);

  // Handlers de Navegação
  const handleStart = async (data: ClientData) => {
    setClientData(data);
    setIsLoading(true);
    setQuoteState(prev => ({ ...prev, category: null }));
    await delay(1500); 
    setIsLoading(false);
    navigate('/orcamento');
  };

  const handleQuickStart = async () => {
    setClientData({ name: '', location: '', date: '', contact: '' });
    setQuoteState(prev => ({ ...prev, category: null }));
    setIsQuickMode(true);
    setIsLoading(true);
    await delay(800);
    setIsLoading(false);
    navigate('/orcamento');
  };

  const handleRequestForm = () => {
    navigate('/cadastro');
  };

  return (
    <main className="w-full min-h-screen bg-black text-neutral-100 selection:bg-brand-DEFAULT selection:text-white overflow-x-hidden font-sans relative">

      {/* Background persistente (some no Quote e Admin para foco, retorna no sucesso) */}
      {(location.pathname !== '/orcamento' && location.pathname !== '/admin') && <BackgroundFilmStrips />}

      <AnimatePresence mode="wait">
        {showSplash && (
          <motion.div 
            key="splash"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(10px)' }}
            transition={{ duration: 0.6, ease: "easeInOut" }}
            className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-black"
          >
             <div className="flex flex-col items-center justify-center w-full h-full p-4">
               <motion.div
                 initial={{ scale: 0.8, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 transition={{ duration: 0.8, ease: "easeOut" }}
                 className="mb-4"
               >
                  <Logo className="w-64 md:w-96" animate={true} />
               </motion.div>

               <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.7, duration: 0.5 }}
                  className="flex flex-col items-center"
               >
                  <div className="h-px w-16 bg-gradient-to-r from-transparent via-brand-DEFAULT to-transparent mb-4 opacity-50" />
                  <p className="text-neutral-500 font-sans font-medium text-sm md:text-base tracking-[0.4em] uppercase">
                    Orçamento Facilitado
                  </p>
               </motion.div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isLoading && <Loading key="loader" />}
      </AnimatePresence>

      <div className="relative z-10">
        {!showSplash && !isLoading && (
          <Routes location={location} key={location.pathname}>

            {/* Nova Rota Raiz: Landing View */}
            <Route path="/" element={<LandingView />} />

            {/* Rota Intro (Antiga Home): Instagram / Rápido / Personalizado */}
            <Route path="/intro" element={
              <IntroView 
                onContinue={() => navigate('/cadastro')}
                onQuickStart={handleQuickStart}
              />
            } />

            <Route path="/cadastro" element={
              <WelcomeView 
                onStart={handleStart} 
                onAdminClick={() => navigate('/admin')}
                onBack={() => navigate('/intro')}
                setIsLoading={setIsLoading}
              />
            } />

            <Route path="/orcamento" element={
              <QuoteView 
                clientData={clientData}
                onUpdateClientData={setClientData}
                config={config}
                quoteState={quoteState}
                setQuoteState={setQuoteState}
                // Se estiver no modo rápido, volta para o início do fluxo (Intro). 
                // Se não, volta para o cadastro.
                onBack={() => navigate(isQuickMode ? '/intro' : '/cadastro')}
                onSuccess={() => navigate('/concluido')}
                onSummary={() => navigate('/resumo')}
                isQuickMode={isQuickMode}
                onRequestForm={handleRequestForm}
              />
            } />

            <Route path="/resumo" element={<SummaryView />} />

            <Route path="/concluido" element={<SuccessView />} />

            <Route path="/admin" element={
              <AdminDashboard 
                currentConfig={config}
                onUpdateConfig={setConfig}
                onExit={() => navigate('/cadastro')}
              />
            } />

            {/* Redirects */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        )}
      </div>
    </main>
  );
};

