import { AppConfig } from "../config/AppConfig";
import { PricingContext, PricingResult, QuoteState, PriceBreakdownItem } from "../types";

/**
 * PricingEngine
 * -------------
 * Classe responsável puramente pela lógica matemática de precificação.
 * Recebe o Estado (O que o usuário escolheu) e o Contexto (Regras de preço atuais/Admin)
 * e retorna o Resultado calculado.
 * 
 * Princípio: SRP (Single Responsibility Principle) - Esta classe só muda se a matemática mudar.
 */
export class PricingEngine {

  /**
   * Método principal de cálculo.
   */
  static calculate(state: QuoteState, context: PricingContext): PricingResult {
    const { category } = state;

    let result: PricingResult = {
      totalPrice: 0,
      breakdown: [],
      currency: 'BRL'
    };

    // Roteamento de Estratégia
    switch (category) {
      case 'wedding':
        result = this.calculateWedding(state, context);
        break;
      case 'social':
        result = this.calculateSocial(state, context);
        break;
      case 'commercial':
        result = this.calculateCommercial(state, context);
        break;
      case 'studio':
        result = this.calculateStudio(state, context);
        break;
      case 'video_production':
        result = this.calculateProduction(state, context);
        break;
      case 'custom':
        result = {
          totalPrice: AppConfig.PRICING_TABLE.custom.custom_project.base,
          breakdown: [{ label: AppConfig.PRICING_TABLE.custom.custom_project.label, value: 0, type: 'base' }],
          currency: 'BRL'
        };
        break;
    }

    // Cálculos Globais (Frete e Adicionais Transversais)
    result = this.applyAddonsAndFreight(state, context, result);

    return result;
  }

  // --- ESTRATÉGIAS ESPECÍFICAS POR CATEGORIA ---

  private static calculateWedding(state: QuoteState, ctx: PricingContext): PricingResult {
    const { serviceId, hours } = state;
    const table = AppConfig.PRICING_TABLE.wedding;
    const breakdown: PriceBreakdownItem[] = [];
    let total = 0;

    // Base Price Lookup
    let baseVal = 0;
    let baseLabel = "";

    // Mapeamento seguro (Type Guarded no runtime)
    const key = serviceId as keyof typeof table;
    if (table[key] && 'base' in table[key]) {
        // @ts-ignore
        baseVal = table[key].base;
        // @ts-ignore
        baseLabel = table[key].label;
    }

    total += baseVal;
    breakdown.push({ label: baseLabel, value: baseVal, type: 'base' });

    // Horas Extras (Regra: Acima de 2h, +250/h)
    // Nota: Em casamentos, normalmente pacotes são fechados, mas mantemos a lógica caso o user altere
    if (state.selectionMode === 'duration' && hours > 2) {
      const extraHoursVal = (hours - 2) * 250;
      total += extraHoursVal;
      breakdown.push({ label: `Horas Extras (+${hours - 2}h)`, value: extraHoursVal, type: 'addon' });
    }

    return { totalPrice: total, breakdown, currency: 'BRL' };
  }

  private static calculateSocial(state: QuoteState, ctx: PricingContext): PricingResult {
    const { serviceId, hours, qty, selectionMode } = state;
    const table = AppConfig.PRICING_TABLE.social;
    const breakdown: PriceBreakdownItem[] = [];
    let total = 0;

    if (serviceId === 'graduation') {
      total += table.graduation.base;
      breakdown.push({ label: table.graduation.label, value: table.graduation.base, type: 'base' });
    } else {
      // Birthday / Fifteen / Baptism / Party / Event
      let ref;
      if (serviceId === 'baptism') ref = table.baptism;
      else if (serviceId === 'fifteen') ref = table.fifteen;
      else if (serviceId === 'social_party') ref = table.social_party;
      else if (serviceId === 'social_event') ref = table.social_event;
      else ref = table.birthday; // Default

      if (selectionMode === 'duration') {
        total += ref.base;
        breakdown.push({ label: `${ref.label} (Base 2h)`, value: ref.base, type: 'base' });

        if (hours > ref.hoursIncluded) {
          const extraHoursVal = (hours - ref.hoursIncluded) * ref.hourPrice;
          total += extraHoursVal;
          breakdown.push({ label: `Horas Extras (+${hours - ref.hoursIncluded}h)`, value: extraHoursVal, type: 'addon' });
        }
      } else {
        // Cobrança por foto
        const val = qty * ctx.photoUnitPrice; // Usa o preço configurado no Admin Context
        total += val;
        breakdown.push({ label: `${ref.label} (${qty} Fotos)`, value: val, type: 'base' });
      }
    }

    return { totalPrice: total, breakdown, currency: 'BRL' };
  }

  private static calculateCommercial(state: QuoteState, ctx: PricingContext): PricingResult {
    const { serviceId, qty, videoQty } = state; // videoQty usado apenas no combo
    const table = AppConfig.PRICING_TABLE.commercial;
    const breakdown: PriceBreakdownItem[] = [];
    let total = 0;

    if (serviceId === 'comm_photo') {
      // FIX: Usa o preço unitário específico de comercial (20) em vez do global (25)
      const val = qty * table.comm_photo.unit;
      total += val;
      breakdown.push({ label: `${table.comm_photo.label} (${qty}x)`, value: val, type: 'base' });
    }
    else if (serviceId === 'comm_video') {
      // FIX: Usa o preço unitário específico da tabela (500) em vez do global (videoUnitPrice do contexto)
      const val = qty * table.comm_video.unit;
      total += val;
      breakdown.push({ label: `${table.comm_video.label} (${qty}x)`, value: val, type: 'base' });
    }
    else if (serviceId === 'comm_combo') {
      // 1. Preço Fixo do Pacote (Base 700 para 10F + 1V)
      const baseVal = table.comm_combo.videoBase;
      total += baseVal;
      breakdown.push({ label: "Combo Base (10F + 1V)", value: baseVal, type: 'base' });

      // 2. Fotos Extras (Acima de 10)
      if (qty > 10) {
          const extraPhotos = qty - 10;
          const photoPrice = table.comm_photo.unit; // 20
          const val = extraPhotos * photoPrice;
          total += val;
          breakdown.push({ label: `Fotos Extras (+${extraPhotos})`, value: val, type: 'addon' });
      }

      // 3. Vídeos Extras (Acima de 1)
      // Nota: O prompt pediu explicitamente 350 por vídeo adicional no combo
      if (videoQty > 1) {
          const extraVideos = videoQty - 1;
          const videoPrice = 350; 
          const val = extraVideos * videoPrice;
          total += val;
          breakdown.push({ label: `Vídeos Extras (+${extraVideos})`, value: val, type: 'addon' });
      }
    }

    return { totalPrice: total, breakdown, currency: 'BRL' };
  }

  private static calculateStudio(state: QuoteState, ctx: PricingContext): PricingResult {
    const { serviceId, qty, hours, selectionMode } = state;
    const table = AppConfig.PRICING_TABLE.studio;
    const breakdown: PriceBreakdownItem[] = [];
    let total = 0;

    if (selectionMode === 'quantity') {
      if (serviceId === 'studio_photo') {
        // Usa o preço unitário do contexto para consistência com o admin
        const val = qty * ctx.photoUnitPrice;
        total += val;
        breakdown.push({ label: `${table.studio_photo.label} (${qty}x)`, value: val, type: 'base' });
      } else {
        total += table.studio_video.base;
        breakdown.push({ label: table.studio_video.label, value: table.studio_video.base, type: 'base' });
      }
    } else {
      const baseHour = 350; // Valor fixo para locação de estúdio
      total += baseHour;
      breakdown.push({ label: `Sessão Estúdio (2h)`, value: baseHour, type: 'base' });

      if (hours > 2) {
        const extraVal = (hours - 2) * 200;
        total += extraVal;
        breakdown.push({ label: `Horas Extras (+${hours - 2}h)`, value: extraVal, type: 'addon' });
      }
    }

    return { totalPrice: total, breakdown, currency: 'BRL' };
  }

  private static calculateProduction(state: QuoteState, ctx: PricingContext): PricingResult {
    const { serviceId, qty, hours } = state;
    const table = AppConfig.PRICING_TABLE.video_production;
    const breakdown: PriceBreakdownItem[] = [];
    let total = 0;

    if (serviceId === 'edit_only') {
      const val = qty * table.edit_only.unit;
      total += val;
      breakdown.push({ label: `${table.edit_only.label} (${qty}x)`, value: val, type: 'base' });
    }
    else if (serviceId === 'cam_cap') { 
      // IMPLEMENTAÇÃO DE HORAS EXTRAS PARA FREELANCERS
      total += table.cam_cap.fixed; 
      breakdown.push({ label: `${table.cam_cap.label} (Base 2h)`, value: table.cam_cap.fixed, type: 'base' }); 

      if (hours > 2) {
          const extraVal = (hours - 2) * 200; // Hora extra Captação Pro
          total += extraVal;
          breakdown.push({ label: `Horas Extras (+${hours - 2}h)`, value: extraVal, type: 'addon' });
      }
    }
    else if (serviceId === 'mobile_cap') { 
      total += table.mobile_cap.fixed; 
      breakdown.push({ label: `${table.mobile_cap.label} (Base 2h)`, value: table.mobile_cap.fixed, type: 'base' }); 

      if (hours > 2) {
          const extraVal = (hours - 2) * 150; // Hora extra Mobile (Mais barato)
          total += extraVal;
          breakdown.push({ label: `Horas Extras (+${hours - 2}h)`, value: extraVal, type: 'addon' });
      }
    }
    else if (serviceId === 'drone') { 
      // Alterado para multiplicar por QTY (Baterias)
      const val = qty * table.drone.fixed; 
      total += val; 
      breakdown.push({ label: `${table.drone.label} (${qty}x)`, value: val, type: 'base' }); 
    }

    return { totalPrice: total, breakdown, currency: 'BRL' };
  }

  // --- CÁLCULOS GLOBAIS ---

  private static applyAddonsAndFreight(state: QuoteState, ctx: PricingContext, currentResult: PricingResult): PricingResult {
    const { category, addDrone, addRealTime, commercialMode } = state;
    const { distance, pricePerKm, isQuickMode } = ctx;

    // 1. Drone (Se aplicável à categoria)
    if (addDrone && (category === 'wedding' || category === 'social' || category === 'commercial')) {
       const dronePrice = AppConfig.PRICING_TABLE.video_production.drone.fixed;
       currentResult.totalPrice += dronePrice;
       currentResult.breakdown.push({ label: AppConfig.TEXTS.LABELS.ADD_DRONE, value: dronePrice, type: 'addon' });
    }

    // 2. Fotos em Tempo Real (Aplicável a Wedding, Social e Commercial)
    if (addRealTime && (category === 'wedding' || category === 'social' || category === 'commercial')) {
       // Usamos o preço base configurado no objeto 'wedding' como referência global (R$ 600)
       const realtimePrice = AppConfig.PRICING_TABLE.wedding.realtime.fixed;
       const realtimeLabel = AppConfig.TEXTS.LABELS.ADD_REALTIME;

       currentResult.totalPrice += realtimePrice;
       currentResult.breakdown.push({ label: realtimeLabel, value: realtimePrice, type: 'addon' });
    }

    // 3. Frete / Deslocamento
    // Regra: Estúdio é SEMPRE isento, independente de distância ou modo. Edição também.
    // NOVO: Se for comercial em modo ESTÚDIO, também é isento.
    const isCommercialStudio = category === 'commercial' && commercialMode === 'studio';
    const isExemptFromTravel = category === 'studio' || state.serviceId === 'edit_only' || isCommercialStudio;

    if (!isExemptFromTravel) {
      // CORREÇÃO: Prioridade para distância real > 0.
      if (distance > 0) {
        // Cálculo Normal: Ida e Volta
        const freight = (distance * 2 * pricePerKm);
        currentResult.totalPrice += freight;
        currentResult.breakdown.push({ label: `Deslocamento (${distance}km)`, value: freight, type: 'freight' });
      } else if (isQuickMode) {
        // Modo Rápido sem local definido: "A consultar" (Valor 0, mas com label específico)
        currentResult.breakdown.push({ label: "Deslocamento (A consultar)", value: 0, type: 'freight' });
      } else {
        // Modo normal sem distância (ainda não calculou ou é perto da base)
        currentResult.breakdown.push({ label: "Deslocamento", value: 0, type: 'freight' });
      }
    } 
    // Se for Estúdio, explicitamente não adiciona nada ao breakdown, resultando em custo 0.

    return currentResult;
  }
}

import React, { useState, useMemo, useEffect } from 'react';
import { ClientData, QuoteData, QuoteState, PricingContext, ServiceCategory, ServiceId } from '../types';
import { AppConfig } from '../config/AppConfig';
import { PricingEngine } from '../core/PricingEngine';
import { LocationService } from '../services/LocationService';

interface UseQuoteLogicProps {
  clientData: ClientData;
  onUpdateClientData: (data: ClientData) => void;
  config: QuoteData;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  onSuccess: () => void;
  onBack: () => void;
  isQuickMode?: boolean;
}

export type ViewState = 'config' | 'summary' | 'success';

export const useQuoteLogic = ({
  clientData,
  onUpdateClientData,
  config,
  quoteState,
  setQuoteState,
  onSuccess,
  onBack,
  isQuickMode = false
}: UseQuoteLogicProps) => {

  // === STATE: VIEW & NAVIGATION ===
  const [viewState, setViewState] = useState<ViewState>('config');
  const [currentStep, setCurrentStep] = useState(0);
  const [direction, setDirection] = useState(0);
  const [isCategoryMenuOpen, setIsCategoryMenuOpen] = useState(false);

  // === STATE: LOCAL UI ===
  const [paymentMethod, setPaymentMethod] = useState<string>('Pix');
  const [distance, setDistance] = useState<number>(0);
  const [isModalOpen, setIsModalOpen] = useState(false); // Signature Modal
  const [isMapOpen, setIsMapOpen] = useState(false);     // Map Modal

  // === STATE: NAME CAPTURE (Quick Mode) ===
  const [isNameModalOpen, setIsNameModalOpen] = useState(false);
  const [tempName, setTempName] = useState('');
  const [pendingAction, setPendingAction] = useState<'next_step' | 'custom_project' | 'commercial_custom' | null>(null);

  // === CONSTANTS ===
  const steps = [
      { id: 'categories', title: 'Qual a ocasião?' },
      { id: 'services', title: 'Escolha o pacote ideal' },
      { id: 'config', title: 'Personalize os detalhes' }
  ];

  const categoryLabels: Record<string, string> = {
    wedding: 'Casamento',
    social: 'Social',
    commercial: 'Comercial',
    studio: 'Estúdio',
    video_production: 'Freelancer',
    custom: 'Personalizado'
  };

  // === DERIVED STATE ===
  const currentStepId = steps[currentStep].id as 'categories' | 'services' | 'config';

  const quoteData: QuoteData = useMemo(() => ({
    ...config,
    client: { ...config.client, ...clientData, projectTitle: `Project: ${clientData.name}` }
  }), [clientData, config]);

  // Destructuring QuoteState for internal use
  const { category, serviceId, hours, qty, videoQty, addDrone, addRealTime, selectionMode, commercialMode } = quoteState;

  // === HELPERS: STATE SETTERS ===
  const actions = {
      setCategory: (c: ServiceCategory) => {
          setQuoteState(prev => ({ ...prev, category: c }));

          // Lógica de Navegação:
          // Se estivermos na tela inicial (Step 0), APENAS selecionamos a categoria visualmente.
          // O usuário deve clicar em "Ver Detalhes/Continuar" no rodapé para avançar.
          // Se estivermos nas etapas seguintes (via Menu Dropdown currentStep > 0), 
          // aí sim forçamos o reinício para Step 1 para evitar inconsistência.
          if (currentStep > 0) {
              setCurrentStep(1);
              window.scrollTo({ top: 0, behavior: 'smooth' });
          }

          setIsCategoryMenuOpen(false);
      },
      setServiceId: (s: ServiceId) => setQuoteState(prev => ({ ...prev, serviceId: s })),
      setHours: (h: number) => setQuoteState(prev => ({ ...prev, hours: h })),
      setQty: (q: number) => setQuoteState(prev => ({ ...prev, qty: q })),
      setVideoQty: (q: number) => setQuoteState(prev => ({ ...prev, videoQty: q })),
      setAddDrone: (b: boolean) => setQuoteState(prev => ({ ...prev, addDrone: b })),
      setAddRealTime: (b: boolean) => setQuoteState(prev => ({ ...prev, addRealTime: b })),
      setSelectionMode: (mode: 'duration' | 'quantity') => setQuoteState(prev => ({ ...prev, selectionMode: mode })),
      setCommercialMode: (mode: 'on_location' | 'studio') => setQuoteState(prev => ({ ...prev, commercialMode: mode })),

      handleUpdateLocation: (address: string) => {
          onUpdateClientData({ ...clientData, location: address });
      },

      setPaymentMethod,
      setIsMapOpen,
      setIsCategoryMenuOpen,
      setIsModalOpen,
      setIsNameModalOpen,
      setTempName,
      setViewState
  };

  // === EFFECT: LOCATION SERVICE ===
  useEffect(() => {
    let isMounted = true;
    const updateDistance = async () => {
        if (clientData.location && clientData.location.length > 3) {
            const dist = await LocationService.calculateDistance(clientData.location);
            if (isMounted) setDistance(dist);
        } else {
            if (isMounted) setDistance(0);
        }
    };
    updateDistance();
    return () => { isMounted = false; };
  }, [clientData.location]);

  // === EFFECT: SMART DEFAULTS (Category Change) ===
  useEffect(() => {
      if (category === 'wedding') actions.setSelectionMode('duration');
      if (category === 'commercial') {
          actions.setSelectionMode('quantity');
          // Default commercial mode
          if (!commercialMode) actions.setCommercialMode('on_location');
      }
      if (category === 'studio' && serviceId === 'studio_photo') actions.setSelectionMode('quantity');
      if (category === 'studio' && serviceId === 'studio_video') actions.setSelectionMode('duration');
      if (category === 'social' && serviceId === 'graduation') actions.setSelectionMode('duration');
  }, [category, serviceId]);

  // === EFFECT: RESET ON CATEGORY CHANGE ===
  useEffect(() => {
      if (!category) return;

      const table = AppConfig.PRICING_TABLE;
      const currentCategoryGroup = table[category as keyof typeof table];
      // @ts-ignore
      const isIdValid = currentCategoryGroup && Object.keys(currentCategoryGroup).some(key => key === serviceId);

      if (!isIdValid) {
        if (category === 'wedding') actions.setServiceId('wedding_base');
        if (category === 'social') actions.setServiceId('birthday');
        if (category === 'commercial') actions.setServiceId('comm_photo');
        if (category === 'studio') actions.setServiceId('studio_photo');
        if (category === 'video_production') actions.setServiceId('edit_only');
        if (category === 'custom') actions.setServiceId('custom_project');

        actions.setHours(2);
        actions.setAddDrone(false);
        actions.setAddRealTime(false);

        if (category === 'commercial') {
            if (serviceId === 'comm_photo') actions.setQty(5);
            else if (serviceId === 'comm_video') actions.setQty(1);
        } else if (category === 'studio' && serviceId === 'studio_photo') {
            actions.setQty(8);
        } else if (category === 'video_production') {
            actions.setQty(1);
        } else {
            actions.setQty(10);
        }
      }

      if (category === 'commercial' && serviceId === 'comm_combo') {
          actions.setQty(10);      
          actions.setVideoQty(1);  
      } else {
          actions.setVideoQty(0);
      }
  }, [category, serviceId]);

  // === PRICING ENGINE ===
  const { totalPrice, priceBreakdown } = useMemo(() => {
    const context: PricingContext = {
        pricePerKm: config.pricePerKm,
        photoUnitPrice: config.photoUnitPrice,
        videoUnitPrice: config.videoUnitPrice,
        distance: distance,
        isQuickMode: isQuickMode 
    };
    const result = PricingEngine.calculate(quoteState, context);
    return { totalPrice: result.totalPrice, priceBreakdown: result.breakdown };
  }, [quoteState, config, distance, isQuickMode]);

  // === ACTIONS: WHATSAPP ===
  const openWhatsappAction = (type: 'custom_project' | 'commercial_custom', nameOverride?: string) => {
    const clientName = nameOverride || clientData.name || "Cliente";
    let message = "";

    if (type === 'custom_project') {
        message = `🚀 *SOLICITAÇÃO DE PROJETO ESPECIAL*\nOlá! Me chamo ${clientName}.\n\nGostaria de discutir um projeto exclusivo que não se encaixa nos pacotes padrão.\n\n💡 *MINHA IDEIA*\n(Descreva brevemente aqui)\n\n*Podemos agendar uma conversa?*`;
    } else if (type === 'commercial_custom') {
        message = `💼 *CONSULTORIA COMERCIAL*\nOlá, equipe EAREC! Me chamo ${clientName}.\n\nEstou no configurador e gostaria de um orçamento personalizado para minha empresa/marca.\n\n💡 *DETALHES DA DEMANDA*\n• Objetivo: (Descreva aqui)\n• Referência: Opção "Comercial Personalizado"\n\n*Aguardo contato para alinharmos o projeto!*`;
    }

    window.open(`https://api.whatsapp.com/send?phone=${AppConfig.BRAND.WHATSAPP}&text=${encodeURIComponent(message)}`, '_blank');
  };

  // === HANDLERS: NAVIGATION & INTERACTION ===

  const handleNextStep = () => {
      if (currentStep === 0 && !category) return;

      if (currentStep < steps.length - 1) {
          setDirection(1);
          setCurrentStep(prev => prev + 1);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
          if (category === 'custom') {
              onSuccess(); 
              setViewState('success');
              window.scrollTo({ top: 0, behavior: 'smooth' });
          } else {
              if (isQuickMode && !clientData.name) {
                  setPendingAction('next_step');
                  setIsNameModalOpen(true);
                  return;
              }
              setViewState('summary');
          }
      }
  };

  const handlePrevStep = () => {
      if (currentStep > 0) {
          setDirection(-1);
          setCurrentStep(prev => prev - 1);
      } else {
          onBack();
      }
  };

  const handleConfirmName = () => {
      if (tempName.trim().length < 2) return;
      onUpdateClientData({ ...clientData, name: tempName });
      setIsNameModalOpen(false);

      if (pendingAction === 'next_step') setViewState('summary');
      else if (pendingAction === 'custom_project') openWhatsappAction('custom_project', tempName);
      else if (pendingAction === 'commercial_custom') openWhatsappAction('commercial_custom', tempName);

      setPendingAction(null);
  };

  const handleSignatureSuccess = (signatureData: string) => {
    setIsModalOpen(false);
    onSuccess();
    setViewState('success');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleRemoveAddon = (addonName: string) => {
      const name = addonName.toLowerCase();
      if (name.includes('drone')) actions.setAddDrone(false);
      if (name.includes('tempo real')) actions.setAddRealTime(false);
      if (name.includes('horas extras')) actions.setHours(2); 
  };

  const handleContactRequest = (type: 'custom_project' | 'commercial_custom') => {
      if (!clientData.name || clientData.name.trim() === '') {
          setPendingAction(type);
          setIsNameModalOpen(true);
      } else {
          openWhatsappAction(type);
      }
  };

  // === COMPUTED: LABELS & DETAILS ===
  const serviceLabel = category ? AppConfig.getServiceLabel(category, serviceId) : '';
  let metricLabel = '';
  if (selectionMode === 'duration') {
       metricLabel = `${hours}h de Cobertura`;
  } else {
       if (serviceId === 'comm_combo') metricLabel = `${qty} Fotos + ${videoQty} Vídeos`;
       else metricLabel = `${qty} Unidades`;
  }
  if (category === 'wedding' && selectionMode === 'duration' && hours === 2) metricLabel = "Pacote Completo";
  if (category === 'custom') metricLabel = 'Sob medida';

  const activeAddons = [];
  if (addDrone && (['wedding','social','commercial'].includes(category || ''))) activeAddons.push('Drone (Aéreo)');
  if (addRealTime) activeAddons.push('Fotos em Tempo Real');

  const getFooterLabel = () => {
    if (currentStep === 0) return "Ver Detalhes"; 
    if (currentStep === 1) return "Configurar Detalhes";
    if (currentStep === 2) {
        if (category === 'custom') return "Solicitar";
        if (selectionMode === 'quantity') return "Confirmar Quantidade";
        if (selectionMode === 'duration') return "Confirmar Tempo";
    }
    return "Continuar";
  };

  return {
    state: {
        viewState,
        currentStep,
        direction,
        isCategoryMenuOpen,
        paymentMethod,
        distance,
        isModalOpen,
        isMapOpen,
        isNameModalOpen,
        tempName,
        steps,
        currentStepId,
        categoryLabels,
        quoteData,
        totalPrice,
        priceBreakdown,
        commercialMode 
    },
    actions: {
        ...actions,
        handleNextStep,
        handlePrevStep,
        handleConfirmName,
        handleSignatureSuccess,
        handleRemoveAddon,
        handleContactRequest
    },
    computed: {
        serviceLabel,
        metricLabel,
        activeAddons,
        summaryDetails: {
            serviceName: serviceLabel,
            categoryLabel: category ? (categoryLabels[category] || '') : '',
            metricLabel,
            addons: activeAddons
        },
        footerLabel: getFooterLabel(),
        isNextDisabled: currentStep === 0 && !category
    }
  };
};

