  Edit, Smartphone as SmartphoneIcon, Sparkles, Gem, HelpCircle, X, MessageCircle, Hand, Check, Timer, Cross, Battery, Music, GlassWater, Building, MapPin
} from 'lucide-react';

import { cn, formatCurrency } from '../../lib/utils';
import { fadeInUp, staggerContainer, modalVariants } from '../../lib/animations';
import { ServiceCategory, ServiceId } from '../../types';
import AnimatedNumber from '../ui/AnimatedNumber';
import { AppConfig } from '../../config/AppConfig';
import Button from '../ui/Button';

interface UpsellListProps {
  category: ServiceCategory | null; 
  setCategory: (c: ServiceCategory) => void;
  serviceId: ServiceId;
  setServiceId: (s: ServiceId) => void;
  hours: number;
  setHours: (h: number) => void;
  qty: number;
  setQty: (q: number) => void;
  videoQty?: number;          // Novo: Quantidade de vídeos
  setVideoQty?: (q: number) => void; // Novo: Setter
  addDrone: boolean;
  setAddDrone: (b: boolean) => void;
  addRealTime: boolean;
  setAddRealTime: (b: boolean) => void;
  distance: number;
  pricePerKm: number;
  locationClient: string;
  onOpenMap?: () => void;
  selectionMode?: 'duration' | 'quantity';
  setSelectionMode?: (mode: 'duration' | 'quantity') => void;
  viewMode?: 'categories' | 'services' | 'config';
  isQuickMode?: boolean;
  onContactRequest?: (type: 'custom_project' | 'commercial_custom') => void; 
  commercialMode?: 'on_location' | 'studio';
  setCommercialMode?: (mode: 'on_location' | 'studio') => void;
}

const UpsellList: React.FC<UpsellListProps> = (props) => {
  const { 
    category, setCategory, serviceId, setServiceId,
    hours, setHours, qty, setQty, videoQty = 1, setVideoQty, 
    addDrone, setAddDrone, addRealTime, setAddRealTime,
    distance, pricePerKm, locationClient, onOpenMap, selectionMode, setSelectionMode,
    viewMode = 'categories',
    isQuickMode = false,
    onContactRequest,
    commercialMode, setCommercialMode
  } = props;

  const [infoData, setInfoData] = useState<{ title: string; desc: string; price: string } | null>(null);

  // === READ FROM APP CONFIG ===
  const TABLE = AppConfig.PRICING_TABLE;

  const categories = [
    { id: 'wedding', label: 'Casamento', icon: Heart, desc: "Eternize o sim." },
    { id: 'social', label: 'Social', icon: Gift, desc: "15 anos e festas." },
    { id: 'commercial', label: 'Comercial', icon: Store, desc: "Venda mais." },
    { id: 'studio', label: 'Estúdio', icon: Aperture, desc: "Produção controlada." },
    { id: 'video_production', label: 'Freelancer', icon: Video, desc: "Equipe técnica." },
    { id: 'custom', label: 'Outros', icon: Star, desc: "Projetos únicos." },
  ];

  const handleServiceSelect = (id: ServiceId, mode: 'duration' | 'quantity' = 'duration') => {
    setServiceId(id);
    if (setSelectionMode) setSelectionMode(mode);

    // Smart Defaults (UX)
    if (id === 'comm_photo') setQty(5);
    else if (id === 'comm_video') setQty(1);
    else if (id === 'studio_photo') setQty(8);
    else if (id === 'drone') setQty(1); // Default 1 bateria
    else if (category === 'social') setQty(10);
  };

  // Redireciona a ação de clique para o pai (QuoteView) para validar o nome
  const handleCustomCommercialClick = () => {
    if (onContactRequest) {
        onContactRequest('commercial_custom');
    }
  };

  const handleCustomProjectClick = (e: React.MouseEvent) => {
      e.preventDefault();
      if (onContactRequest) {
          onContactRequest('custom_project');
      }
  };

  // === VISIBILITY LOGIC ===
  const isCombo = serviceId === 'comm_combo';

  const showDuration = (category === 'social' && serviceId !== 'graduation' && selectionMode === 'duration') ||
                       (category === 'studio' && selectionMode === 'duration') ||
                       (category === 'video_production' && (serviceId === 'cam_cap' || serviceId === 'mobile_cap')); 

  const showQuantity = ((category === 'commercial' && serviceId !== 'comm_combo') || 
                       (category === 'social' && serviceId !== 'graduation' && selectionMode === 'quantity') ||
                       (category === 'studio' && selectionMode === 'quantity') ||
                       (category === 'video_production' && (serviceId === 'edit_only' || serviceId === 'drone'))) && !isCombo; 

  const canChooseMode = category === 'social' && serviceId !== 'graduation';

  // Isenção de frete atualizada: Estúdio, Apenas Edição OU Comercial em Estúdio
  const isNoTravelCost = category === 'studio' || serviceId === 'edit_only' || (category === 'commercial' && commercialMode === 'studio');
  const travelCost = isNoTravelCost ? 0 : distance * 2 * pricePerKm;

  // Drone Visibility:
  // Mostra em Wedding, Social e Comercial (mas em Comercial, some se for Estúdio)
  const isCommercialStudio = category === 'commercial' && commercialMode === 'studio';
  const showDroneAddon = !isCommercialStudio && (category === 'wedding' || category === 'social' || category === 'commercial');

  // RealTime Price Logic
  const realTimePrice = category === 'commercial' ? TABLE.commercial.realtime.fixed : TABLE.wedding.realtime.fixed;

  // Lógica de Mínimo
  let minQty = 1;
  if (category === 'studio' && serviceId === 'studio_photo') minQty = 8;
  if (category === 'social') minQty = 10;
  if (category === 'commercial' && serviceId === 'comm_photo') minQty = 5;

  // Verifica se a quantidade é de VÍDEO ou FOTO para ajustar ícone e texto
  const isVideoQuantity = (category === 'commercial' && serviceId === 'comm_video') ||
                          (category === 'video_production' && serviceId === 'edit_only');
  const isDroneQuantity = category === 'video_production' && serviceId === 'drone';

  // Lógica de Layout do Grid
  // FIX: 'items-start' impede que os cards vizinhos estiquem quando um card expande
  const isCompactGrid = category === 'studio';
  const gridClasses = cn(
    "grid gap-4 md:gap-6 w-full mx-auto justify-center items-start", 
    isCompactGrid 
        ? "grid-cols-2 max-w-2xl" 
        : "grid-cols-2 lg:grid-cols-4 max-w-5xl" 
  );

  // === HELPER PARA CALCULAR CUSTO INCREMENTAL (VISUAL) ===
  const getIncrementPrice = (type: 'hour' | 'qty' | 'combo_photo' | 'combo_video') => {
    // Valores baseados no PricingEngine.ts e AppConfig.ts

    if (type === 'hour') {
        if (category === 'studio') return 200; // Hora extra estúdio
        if (category === 'video_production') {
            if (serviceId === 'cam_cap') return 200;
            if (serviceId === 'mobile_cap') return 150;
        }
        return 250; // Hora extra padrão (Social/Wedding)
    }

    if (type === 'combo_photo') return 20;  // Foto extra no combo
    if (type === 'combo_video') return 350; // Vídeo extra no combo

    if (type === 'qty') {
        if (serviceId === 'comm_photo') return TABLE.commercial.comm_photo.unit; // 20
        if (serviceId === 'comm_video') return TABLE.commercial.comm_video.unit; // 500
        if (serviceId === 'drone') return TABLE.video_production.drone.fixed; // 250
        if (serviceId === 'edit_only') return TABLE.video_production.edit_only.unit; // 250
        // Padrão (Social/Studio Photos)
        return 25; 
    }

    return 0;
  };

  // Componente de Tooltip Sutil
  const PriceTooltip = ({ value }: { value: number }) => (
    <div className="absolute -top-10 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-all duration-300 transform translate-y-2 group-hover:translate-y-0 pointer-events-none z-30">
        <div className="bg-neutral-800/90 backdrop-blur-md text-white text-[10px] font-medium px-2.5 py-1.5 rounded-lg border border-white/10 shadow-xl whitespace-nowrap flex items-center gap-1">
           <span className="text-brand-DEFAULT font-bold">+</span> {formatCurrency(value)}
        </div>
        {/* Seta do tooltip */}
        <div className="w-2 h-2 bg-neutral-800/90 border-b border-r border-white/10 transform rotate-45 absolute left-1/2 -translate-x-1/2 -bottom-1"></div>
    </div>
  );

  // Renderização Condicional baseada no viewMode
  return (
    <section className="w-full max-w-5xl mx-auto flex flex-col items-center">

      {/* === STEP 1: CATEGORY SELECTION === */}
      {viewMode === 'categories' && (
        <div className="space-y-8 w-full">
            <motion.div 
                key="categories-grid" 
                variants={staggerContainer}
                initial="hidden"
                animate="visible"
                className="grid grid-cols-3 gap-2 md:gap-6 px-1 md:px-0"
            >
                {categories.map((cat) => {
                    const isActive = category === cat.id;
                    const Icon = cat.icon;
                    return (
                        <motion.button
                            key={cat.id}
                            variants={fadeInUp}
                            onClick={() => setCategory(cat.id as ServiceCategory)}
                            className={cn(
                                "relative group flex flex-col items-center justify-center gap-2 p-3 md:p-5 rounded-xl md:rounded-3xl border transition-all duration-500 overflow-hidden text-center h-36 md:h-52",
                                isActive 
                                    ? "bg-brand-DEFAULT border-brand-DEFAULT shadow-[0_0_40px_rgba(220,38,38,0.3)] scale-[1.02] z-10" 
                                    : "bg-white/[0.03] border-white/5 hover:bg-white/[0.07] hover:border-white/20"
                            )}
                        >
                            {!isActive && (
                                <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                            )}

                            {isActive && (
                                <motion.div 
                                    initial={{ scale: 0 }} animate={{ scale: 1 }}
                                    className="absolute top-2 right-2 md:top-4 md:right-4 bg-white text-brand-DEFAULT rounded-full p-0.5 md:p-1 shadow-lg z-20"
                                >
                                    <Check size={10} className="md:w-[14px] md:h-[14px]" strokeWidth={4} />
                                </motion.div>
                            )}

                            <div className={cn(
                                "p-3 md:p-4 rounded-xl md:rounded-full transition-all duration-300 mb-1",
                                isActive ? "bg-white/20 text-white" : "bg-white/5 text-neutral-500 group-hover:text-white group-hover:bg-white/10"
                            )}>
                                <Icon size={24} className="md:w-8 md:h-8" />
                            </div>

                            <div className="relative z-10 w-full">
                                <h3 className={cn(
                                    "font-serif text-sm md:text-2xl mb-1 transition-colors duration-300 w-full font-bold",
                                    isActive ? "text-white" : "text-neutral-300 group-hover:text-white"
                                )}>
                                    {cat.label}
                                </h3>
                                <p className={cn(
                                    "text-[10px] md:text-sm font-medium tracking-wide transition-colors duration-300 opacity-80 hidden md:block",
                                    isActive ? "text-white/80" : "text-neutral-500 group-hover:text-neutral-400"
                                )}>
                                    {cat.desc}
                                </p>
                            </div>

                            {!isActive && (
                                <div className="absolute -inset-full top-0 block w-1/2 -skew-x-12 bg-gradient-to-r from-transparent to-white opacity-0 group-hover:animate-shine" />
                            )}
                        </motion.button>
                    )
                })}
            </motion.div>

            <div className="h-24 md:h-32 flex items-center justify-center px-4 overflow-hidden relative">
                <AnimatePresence mode="wait">
                    {category ? (
                        <motion.div 
                            key={category} 
                            initial={{ opacity: 0, y: 10, filter: 'blur(4px)' }} 
                            animate={{ opacity: 1, y: 0, filter: 'blur(0px)' }}
                            exit={{ opacity: 0, y: -10, filter: 'blur(4px)' }}
                            transition={{ duration: 0.4, ease: "easeOut" }}
                            className="max-w-2xl text-center"
                        >
                            <p className="text-white font-serif text-xl md:text-3xl leading-snug drop-shadow-xl">
                                {AppConfig.TEXTS.CATEGORY_DESCRIPTIONS[category]}
                            </p>
                        </motion.div>
                    ) : (
                        <motion.div
                            key="placeholder"
                            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                            className="flex flex-col items-center gap-2 opacity-40 animate-pulse"
                        >
                            <div className="w-1 h-8 bg-gradient-to-b from-transparent to-white/50" />
                            <p className="text-sm font-medium uppercase tracking-widest text-neutral-400">
                                Selecione uma categoria acima
                            </p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
      )}

      {/* === STEP 2: SERVICE SELECTION === */}
      {viewMode === 'services' && (
        <motion.div 
            initial="hidden"
            animate="visible"
            className="space-y-8 w-full flex flex-col items-center"
        >
            {/* SELETOR DE MODO: COMERCIAL (Comércio vs Estúdio) */}
            {category === 'commercial' && setCommercialMode && commercialMode && (
                <motion.div variants={fadeInUp} className="flex flex-col items-center mb-10">
                    <p className="text-center text-xs uppercase tracking-widest text-brand-DEFAULT mb-3 font-bold">
                        Onde será o serviço?
                    </p>
                    <div className="flex bg-neutral-900 p-2 rounded-2xl border border-white/10 shadow-lg">
                        <button 
                            onClick={() => setCommercialMode('on_location')} 
                            className={cn(
                                "px-6 py-4 rounded-xl text-sm md:text-base font-bold transition-all flex items-center gap-3 w-44 justify-center border", 
                                commercialMode === 'on_location' 
                                    ? "bg-white text-black border-white shadow-lg scale-105 z-10" 
                                    : "bg-transparent border-transparent text-neutral-500 hover:text-white hover:bg-white/5"
                            )}
                        >
                            <Store size={20} className={commercialMode === 'on_location' ? "text-brand-DEFAULT" : ""} /> 
                            NO COMÉRCIO
                        </button>
                        <button 
                            onClick={() => setCommercialMode('studio')} 
                            className={cn(
                                "px-6 py-4 rounded-xl text-sm md:text-base font-bold transition-all flex items-center gap-3 w-44 justify-center border", 
                                commercialMode === 'studio' 
                                    ? "bg-white text-black border-white shadow-lg scale-105 z-10" 
                                    : "bg-transparent border-transparent text-neutral-500 hover:text-white hover:bg-white/5"
                            )}
                        >
                            <Aperture size={20} className={commercialMode === 'studio' ? "text-brand-DEFAULT" : ""} /> 
                            NO ESTÚDIO
                        </button>
                    </div>
                    {commercialMode === 'studio' && (
                        <p className="text-[10px] text-green-500 mt-2 flex items-center gap-1">
                            <Check size={10} /> Frete Grátis no Estúdio
                        </p>
                    )}
                </motion.div>
            )}

            {/* SELETOR DE MODO: SOCIAL (Tempo vs Quantidade) */}
            {canChooseMode && setSelectionMode && (
                <motion.div variants={fadeInUp} className="flex flex-col items-center mb-10">
                    <p className="text-center text-xs uppercase tracking-widest text-brand-DEFAULT mb-3 font-bold">
                        Como deseja contratar?
                    </p>
                    <div className="flex bg-neutral-900 p-2 rounded-2xl border border-white/10 shadow-lg">
                        <button 
                            onClick={() => setSelectionMode('duration')} 
                            className={cn(
                                "px-6 py-4 rounded-xl text-sm md:text-base font-bold transition-all flex items-center gap-3 w-44 justify-center border", 
                                selectionMode === 'duration' 
                                    ? "bg-white text-black border-white shadow-lg scale-105 z-10" 
                                    : "bg-transparent border-transparent text-neutral-500 hover:text-white hover:bg-white/5"
                            )}
                        >
                            <Clock size={20} className={selectionMode === 'duration' ? "text-brand-DEFAULT" : ""} /> 
                            POR TEMPO
                        </button>
                        <button 
                            onClick={() => setSelectionMode('quantity')} 
                            className={cn(
                                "px-6 py-4 rounded-xl text-sm md:text-base font-bold transition-all flex items-center gap-3 w-44 justify-center border", 
                                selectionMode === 'quantity' 
                                    ? "bg-white text-black border-white shadow-lg scale-105 z-10" 
                                    : "bg-transparent border-transparent text-neutral-500 hover:text-white hover:bg-white/5"
                            )}
                        >
                            <Camera size={20} className={selectionMode === 'quantity' ? "text-brand-DEFAULT" : ""} /> 
                            POR FOTO
                        </button>
                    </div>
                </motion.div>
            )}

            <motion.div 
                key="services-grid"
                variants={staggerContainer}
                initial="hidden"
                animate="visible"
                className={gridClasses}
            >
                 {/* Wedding Options */}
                 {category === 'wedding' && (
                    <>
                        <ServiceCard active={serviceId === 'wedding_base'} onClick={() => handleServiceSelect('wedding_base')} onInfo={setInfoData} icon={Heart} title={TABLE.wedding.wedding_base.label} price={formatCurrency(TABLE.wedding.wedding_base.base)} composition={TABLE.wedding.wedding_base.composition} desc={TABLE.wedding.wedding_base.description} />
                        <ServiceCard active={serviceId === 'wedding_classic'} onClick={() => handleServiceSelect('wedding_classic')} onInfo={setInfoData} icon={Sparkles} title={TABLE.wedding.wedding_classic.label} price={formatCurrency(TABLE.wedding.wedding_classic.base)} composition={TABLE.wedding.wedding_classic.composition} desc={TABLE.wedding.wedding_classic.description} />
                        <ServiceCard active={serviceId === 'wedding_romance'} onClick={() => handleServiceSelect('wedding_romance')} onInfo={setInfoData} icon={Hand} title={TABLE.wedding.wedding_romance.label} price={formatCurrency(TABLE.wedding.wedding_romance.base)} composition={TABLE.wedding.wedding_romance.composition} desc={TABLE.wedding.wedding_romance.description} highlight />
                        <ServiceCard active={serviceId === 'wedding_essence'} onClick={() => handleServiceSelect('wedding_essence')} onInfo={setInfoData} icon={Gem} title={TABLE.wedding.wedding_essence.label} price={formatCurrency(TABLE.wedding.wedding_essence.base)} composition={TABLE.wedding.wedding_essence.composition} desc={TABLE.wedding.wedding_essence.description} highlight />

                        <ServiceCard active={false} onClick={handleCustomProjectClick} onInfo={setInfoData} icon={MessageCircle} title="Personalizado" price="A Consultar" composition="Projeto Especial" desc="Demandas específicas? Fale com nossa equipe." />
                    </>
                )}

                {/* Social Options */}
                {category === 'social' && (
                    <>
                        <ServiceCard 
                            active={serviceId === 'birthday'} 
                            onClick={() => handleServiceSelect('birthday', selectionMode || 'duration')} 
                            onInfo={setInfoData} 
                            icon={Gift} 
                            title={TABLE.social.birthday.label} 
                            price={selectionMode === 'duration' ? "A partir de R$ 400" : "R$ 25,00 / foto"} 
                            composition={selectionMode === 'duration' ? TABLE.social.birthday.composition : "Seleção de Fotos Avulsas"} 
                            desc={TABLE.social.birthday.description} 
                        />
                        <ServiceCard 
                            active={serviceId === 'social_party'} 
                            onClick={() => handleServiceSelect('social_party', selectionMode || 'duration')} 
                            onInfo={setInfoData} 
                            icon={Music} 
                            title={TABLE.social.social_party.label} 
                            price={selectionMode === 'duration' ? "A partir de R$ 400" : "R$ 25,00 / foto"} 
                            composition={selectionMode === 'duration' ? TABLE.social.social_party.composition : "Seleção de Fotos Avulsas"} 
                            desc={TABLE.social.social_party.description} 
                        />
                        <ServiceCard 
                            active={serviceId === 'social_event'} 
                            onClick={() => handleServiceSelect('social_event', selectionMode || 'duration')} 
                            onInfo={setInfoData} 
                            icon={GlassWater} 
                            title={TABLE.social.social_event.label} 
                            price={selectionMode === 'duration' ? "A partir de R$ 400" : "R$ 25,00 / foto"} 
                            composition={selectionMode === 'duration' ? TABLE.social.social_event.composition : "Seleção de Fotos Avulsas"} 
                            desc={TABLE.social.social_event.description} 
                        />
                         <ServiceCard 
                            active={serviceId === 'baptism'} 
                            onClick={() => handleServiceSelect('baptism', selectionMode || 'duration')} 
                            onInfo={setInfoData} 
                            icon={Cross} 
                            title={TABLE.social.baptism.label} 
                            price={selectionMode === 'duration' ? "A partir de R$ 500" : "R$ 25,00 / foto"} 
                            composition={selectionMode === 'duration' ? TABLE.social.baptism.composition : "Seleção de Fotos Avulsas"} 
                            desc={TABLE.social.baptism.description} 
                        />
                        <ServiceCard 
                            active={serviceId === 'fifteen'} 
                            onClick={() => handleServiceSelect('fifteen', selectionMode || 'duration')} 
                            onInfo={setInfoData} 
                            icon={Crown} 
                            title={TABLE.social.fifteen.label} 
                            price={selectionMode === 'duration' ? "A partir de R$ 450" : "R$ 25,00 / foto"} 
                            composition={selectionMode === 'duration' ? TABLE.social.fifteen.composition : "Seleção de Fotos Avulsas"} 
                            desc={TABLE.social.fifteen.description} 
                        />
                        <ServiceCard 
                            active={serviceId === 'graduation'} 
                            onClick={() => handleServiceSelect('graduation')} 
                            onInfo={setInfoData} 
                            icon={GraduationCap} 
                            title={TABLE.social.graduation.label} 
                            price={formatCurrency(TABLE.social.graduation.base)} 
                            composition={TABLE.social.graduation.composition} 
                            desc={TABLE.social.graduation.description} 
                        />

                        <ServiceCard active={false} onClick={handleCustomProjectClick} onInfo={setInfoData} icon={MessageCircle} title="Personalizado" price="A Consultar" composition="Projeto Especial" desc="Demandas específicas? Fale com nossa equipe." />
                    </>
                )}

                {/* Commercial Options */}
                {category === 'commercial' && (
                    <>
                        <ServiceCard active={serviceId === 'comm_photo'} onClick={() => handleServiceSelect('comm_photo', 'quantity')} onInfo={setInfoData} icon={Camera} title={TABLE.commercial.comm_photo.label} price={`R$ ${TABLE.commercial.comm_photo.unit} / foto`} composition={TABLE.commercial.comm_photo.composition} desc={TABLE.commercial.comm_photo.description} />
                        <ServiceCard active={serviceId === 'comm_video'} onClick={() => handleServiceSelect('comm_video', 'quantity')} onInfo={setInfoData} icon={Video} title={TABLE.commercial.comm_video.label} price={`R$ ${TABLE.commercial.comm_video.unit} / vídeo`} composition={TABLE.commercial.comm_video.composition} desc={TABLE.commercial.comm_video.description} />
                        <ServiceCard active={serviceId === 'comm_combo'} onClick={() => handleServiceSelect('comm_combo', 'quantity')} onInfo={setInfoData} icon={Star} title={TABLE.commercial.comm_combo.label} price={formatCurrency(TABLE.commercial.comm_combo.videoBase)} composition={TABLE.commercial.comm_combo.composition} desc={TABLE.commercial.comm_combo.description} highlight />

                        <ServiceCard 
                            active={false}
                            onClick={handleCustomCommercialClick}
                            onInfo={setInfoData}
                            icon={MessageCircle}
                            title="Personalizado"
                            price="A Consultar"
                            composition="Projeto Especial"
                            desc="Demandas específicas? Campanhas grandes? Fale diretamente com nossa equipe."
                        />
                    </>
                )}

                {/* Studio Options */}
                {category === 'studio' && (
                    <>
                        <ServiceCard active={serviceId === 'studio_photo'} onClick={() => handleServiceSelect('studio_photo', 'quantity')} onInfo={setInfoData} icon={Aperture} title={TABLE.studio.studio_photo.label} price={`R$ ${TABLE.studio.studio_photo.unit} / foto`} composition={TABLE.studio.studio_photo.composition} desc={TABLE.studio.studio_photo.description} />
                        <ServiceCard active={serviceId === 'studio_video'} onClick={() => handleServiceSelect('studio_video', 'duration')} onInfo={setInfoData} icon={Video} title={TABLE.studio.studio_video.label} price={formatCurrency(TABLE.studio.studio_video.base)} composition={TABLE.studio.studio_video.composition} desc={TABLE.studio.studio_video.description} />

                        <ServiceCard active={false} onClick={handleCustomProjectClick} onInfo={setInfoData} icon={MessageCircle} title="Personalizado" price="A Consultar" composition="Projeto Especial" desc="Demandas específicas? Fale com nossa equipe." />
                    </>
                )}

                {/* Production Options */}
                {category === 'video_production' && (
                    <>
                        <ServiceCard 
                            active={serviceId === 'edit_only'} 
                            onClick={() => handleServiceSelect('edit_only', 'quantity')} 
                            onInfo={setInfoData} 
                            icon={Edit} 
                            title={TABLE.video_production.edit_only.label} 
                            price={`R$ ${TABLE.video_production.edit_only.unit} / 1min`} // FIX: Preço por minuto
                            composition={TABLE.video_production.edit_only.composition} 
                            desc={TABLE.video_production.edit_only.description} 
                        />
                        <ServiceCard active={serviceId === 'cam_cap'} onClick={() => handleServiceSelect('cam_cap', 'duration')} onInfo={setInfoData} icon={Video} title={TABLE.video_production.cam_cap.label} price={formatCurrency(TABLE.video_production.cam_cap.fixed)} composition={TABLE.video_production.cam_cap.composition} desc={TABLE.video_production.cam_cap.description} />
                        <ServiceCard active={serviceId === 'mobile_cap'} onClick={() => handleServiceSelect('mobile_cap', 'duration')} onInfo={setInfoData} icon={SmartphoneIcon} title={TABLE.video_production.mobile_cap.label} price={formatCurrency(TABLE.video_production.mobile_cap.fixed)} composition={TABLE.video_production.mobile_cap.composition} desc={TABLE.video_production.mobile_cap.description} />
                        <ServiceCard 
                            active={serviceId === 'drone'} 
                            onClick={() => handleServiceSelect('drone', 'quantity')} 
                            onInfo={setInfoData} 
                            icon={Plane} 
                            title={TABLE.video_production.drone.label} 
                            price={`R$ ${TABLE.video_production.drone.fixed} / bateria`}
                            composition={TABLE.video_production.drone.composition} 
                            desc={TABLE.video_production.drone.description} 
