            {/* 3. LOGISTICS */}
            {!isNoTravelCost && (
                <motion.div 
                    variants={fadeInUp} 
                    initial="hidden"
                    animate="visible"
                    onClick={onOpenMap} 
                    className="w-full max-w-lg border border-white/5 bg-white/[0.02] flex items-center justify-between cursor-pointer group hover:bg-white/[0.05] rounded-xl p-6 transition-colors gap-4"
