      )}

      {/* INFO MODAL */}
      {createPortal(
        <AnimatePresence>
          {infoData && (
            <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
               <motion.div 
                  key="backdrop"
                  initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
