import React, { useId } from 'react';
import { motion } from 'framer-motion';

/**
 * RealisticFilmStripTexture
 * -------------------------
 * Textura procedural de filme 35mm com simulação de volume cilíndrico.
 */
const RealisticFilmStripTexture = ({ 
    className, 
    speed = 10, 
    direction = 1, 
    opacity = 1,
}: { 
    className?: string, 
    speed?: number, 
    direction?: number, 
    opacity?: number,
}) => {
  const uniqueId = useId().replace(/:/g, ''); 
  const patternId = `film-pattern-${uniqueId}`;
  const sheenId = `sheen-${uniqueId}`;
  const curvatureId = `curvature-${uniqueId}`;
  const frameGradId = `frame-grad-${uniqueId}`;

  return (
    <div className={`relative overflow-hidden ${className}`} style={{ opacity }}>

        {/* RIM LIGHTS (Luz de Borda) - Ajustado para PRATA/BRANCO (Silver Aesthetic) */}
        {/* A curvatura visual é reforçada por essas luzes nas bordas */}
        <div className="absolute top-0 left-0 w-[3px] h-full bg-gradient-to-b from-white/10 via-white/60 to-white/10 blur-[2px] z-30 mix-blend-overlay" />
        <div className="absolute top-0 right-0 w-[2px] h-full bg-gradient-to-b from-white/5 via-white/40 to-white/5 blur-[2px] z-30 mix-blend-overlay" />

        <svg
          viewBox="0 0 140 100"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          className="w-full h-full block"
          preserveAspectRatio="none"
        >
          <defs>
            {/* Gradiente Metálico do Frame (Interno) - Mais contraste para parecer metal */}
            <linearGradient id={frameGradId} x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stopColor="#1a1a1a" />
                <stop offset="40%" stopColor="#404040" />
                <stop offset="60%" stopColor="#262626" />
                <stop offset="100%" stopColor="#0a0a0a" />
            </linearGradient>

            {/* PADRÃO DA FITA */}
            <pattern id={patternId} x="0" y="0" width="140" height="56" patternUnits="userSpaceOnUse">
              <rect width="140" height="56" fill="#050505" />

              {/* Frame da Foto */}
              <rect x="24" y="6" width="92" height="44" rx="2" fill={`url(#${frameGradId})`} stroke="#555" strokeWidth="0.5" />

              {/* Reflexo de Vidro no Frame (Diagonal) */}
              <path d="M 24 50 L 116 6 L 116 25 L 24 60 Z" fill="white" fillOpacity="0.03" />

              {/* Sprockets (Furos) - Prateados */}
              <g fill="#d4d4d4" fillOpacity="0.95">
                  <rect x="7" y="8" width="9" height="10" rx="1.5" />
                  <rect x="7" y="23" width="9" height="10" rx="1.5" />
                  <rect x="7" y="38" width="9" height="10" rx="1.5" />
              </g>

              <g fill="#d4d4d4" fillOpacity="0.95">
                  <rect x="124" y="8" width="9" height="10" rx="1.5" />
                  <rect x="124" y="23" width="9" height="10" rx="1.5" />
                  <rect x="124" y="38" width="9" height="10" rx="1.5" />
              </g>
            </pattern>

            {/* 
               GRADIENTE DE CURVATURA (INTENSIFICADO) 
               Para simular uma curva maior, escurecemos mais as bordas.
            */}
            <linearGradient id={curvatureId} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="black" stopOpacity="0.95" />
                <stop offset="20%" stopColor="black" stopOpacity="0.3" />
                <stop offset="50%" stopColor="black" stopOpacity="0" />    
                <stop offset="80%" stopColor="black" stopOpacity="0.3" />
                <stop offset="100%" stopColor="black" stopOpacity="0.95" /> 
            </linearGradient>

            {/* REFLEXO PRATEADO VERTICAL (SHEEN) */}
            <linearGradient id={sheenId} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="white" stopOpacity="0" />
                <stop offset="40%" stopColor="white" stopOpacity="0.02" />
                <stop offset="45%" stopColor="white" stopOpacity="0.15" /> 
                <stop offset="50%" stopColor="white" stopOpacity="0.02" />
                <stop offset="100%" stopColor="white" stopOpacity="0" />
            </linearGradient>

          </defs>

          {/* CAMADA 1: CONTEÚDO (Móvel) */}
          <motion.rect 
            x="0"
            y="-56"
            width="140" 
            height="300%"
            fill={`url(#${patternId})`}
            animate={{ 
              y: direction > 0 ? [0, -56] : [-56, 0] 
            }}
            transition={{ 
              repeat: Infinity, 
              ease: "linear", 
              duration: speed 
            }}
          />

          {/* CAMADA 2: REFLEXO METAL (Fixo) */}
          <rect width="100%" height="100%" fill={`url(#${sheenId})`} style={{ mixBlendMode: 'screen' }} pointerEvents="none" />

          {/* CAMADA 3: SOMBRA DE VOLUME */}
          <rect width="100%" height="100%" fill={`url(#${curvatureId})`} style={{ mixBlendMode: 'multiply' }} pointerEvents="none" />

        </svg>
    </div>
  );
};

