interface QuoteViewProps {
  clientData: ClientData; 
  onUpdateClientData: (data: ClientData) => void; 
  config: QuoteData;      
  onBack: () => void;
  quoteState: QuoteState;
  setQuoteState: React.Dispatch<React.SetStateAction<QuoteState>>;
  onSuccess: () => void;
  isQuickMode?: boolean;
  onRequestForm?: () => void; 
}

const stepVariants: Variants = {
  enter: (direction: number) => ({
    x: direction > 0 ? 50 : -50,
    opacity: 0,
  }),
  center: {
    zIndex: 1,
    x: 0,
    opacity: 1,
    transition: {
        duration: 0.4,
        ease: [0.22, 1, 0.36, 1]
    }
  },
  exit: (direction: number) => ({
    zIndex: 0,
    x: direction < 0 ? 50 : -50,
    opacity: 0,
    transition: {
        duration: 0.3,
        ease: "easeIn"
    }
  })
};

const QuoteView: React.FC<QuoteViewProps> = (props) => {
  // Encapsulated Logic
  const logic = useQuoteLogic(props);
  const { state, actions, computed } = logic;
  const { quoteState, clientData } = props;

  // View Routing
  if (state.viewState === 'success') {
      return (
        <SuccessView 
            onReset={() => window.location.reload()} 
            clientData={props.clientData}
            totalPrice={state.totalPrice}
            quoteDetails={{
                occasion: quoteState.category as any,
                customOccasionText: computed.serviceLabel,
                location: quoteState.category === 'studio' ? 'studio' : 'external',
                distance: state.distance,
                paymentMethod: state.paymentMethod,
                addons: computed.activeAddons,
                serviceId: quoteState.serviceId,
                selectionMode: quoteState.selectionMode,
                hours: quoteState.hours,
                photoQty: quoteState.qty,
                videoQty: quoteState.videoQty,
                commercialMode: state.commercialMode // Passando o modo comercial
            }}
        />
      );
  }

  return (
    <div className="relative min-h-screen bg-[#161616]/80 flex flex-col">

      {/* Background sutil */}
      <div className="fixed inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-neutral-900 via-[#161616] to-[#161616] -z-10" />

      {/* HEADER: PROGRESS & NAV */}
      <div className="pt-8 px-6 pb-4 w-full max-w-5xl mx-auto flex flex-col items-center relative z-20">
          <div className="w-full flex justify-between items-center mb-6">
               <button onClick={actions.handlePrevStep} className="p-2 rounded-full bg-white/5 hover:bg-white/10 text-neutral-400 hover:text-white transition-colors">
                   <ArrowLeft size={20} />
               </button>
               <Logo className="w-56 opacity-80" />
               <div className="w-10" /> 
          </div>

          {/* Progress Bar */}
          <div className="flex items-center gap-2 w-full max-w-xs mb-2">
            {state.steps.map((_, idx) => (
                <div key={idx} className="h-1 flex-1 rounded-full overflow-hidden bg-white/10">
                    <motion.div 
                        className="h-full bg-brand-DEFAULT"
                        initial={{ width: "0%" }}
                        animate={{ width: idx <= state.currentStep ? "100%" : "0%" }}
                        transition={{ duration: 0.3 }}
                    />
                </div>
            ))}
          </div>

          {/* Badge de Categoria Interativo */}
          <AnimatePresence>
            {state.currentStep > 0 && quoteState.category && (
                 <motion.button
                    initial={{ opacity: 0, y: 10, scale: 0.9 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.9 }}
                    onClick={() => actions.setIsCategoryMenuOpen(true)}
                    className="mt-5 flex items-center gap-3 px-5 py-2 rounded-full bg-neutral-900/80 backdrop-blur-md border border-white/10 shadow-xl shadow-black/40 hover:border-brand-DEFAULT/30 transition-all duration-500 group relative overflow-hidden"
                 >
                    <div className="relative flex items-center justify-center w-3 h-3">
                        <motion.div 
                            className="w-2 h-2 rounded-full bg-[#DC2626] shadow-[0_0_10px_rgba(220,38,38,0.9)]"
                            animate={{ opacity: [1, 0.6, 1] }}
                            transition={{ 
                                duration: 3, 
                                repeat: Infinity, 
                                ease: "easeInOut" 
                            }}
                        />
                    </div>
                    <div className="h-3 w-px bg-white/10 group-hover:bg-white/20 transition-colors" />
                    <span className="text-[10px] uppercase tracking-[0.25em] text-neutral-400 font-medium group-hover:text-white transition-colors">
                        {state.categoryLabels[quoteState.category]}
                    </span>
                    <ChevronsUpDown size={14} className="text-neutral-500 group-hover:text-white transition-colors ml-1" />
                 </motion.button>
            )}
          </AnimatePresence>

          <p className="text-[10px] text-neutral-500 font-mono uppercase tracking-widest mt-2 opacity-60">
                {state.steps[state.currentStep].title}
          </p>
      </div>

      {/* MAIN CONTENT: WIZARD STEP */}
      <div className="flex-1 w-full max-w-5xl mx-auto relative px-8 pb-48 flex flex-col justify-center">
          <AnimatePresence initial={false} custom={state.direction} mode="wait">
            {state.viewState === 'config' && (
                <motion.div 
                    key={state.currentStep}
                    custom={state.direction}
                    variants={stepVariants}
                    initial="enter"
                    animate="center"
                    exit="exit"
                    className="w-full flex justify-center"
                >
                   <UpsellList 
                      viewMode={state.currentStepId} 
                      category={quoteState.category} 
                      setCategory={actions.setCategory}
                      serviceId={quoteState.serviceId} 
                      setServiceId={actions.setServiceId}
                      hours={quoteState.hours} 
                      setHours={actions.setHours}
                      qty={quoteState.qty} 
                      setQty={actions.setQty}
                      videoQty={quoteState.videoQty} 
                      setVideoQty={actions.setVideoQty}
                      addDrone={quoteState.addDrone} 
                      setAddDrone={actions.setAddDrone}
                      addRealTime={quoteState.addRealTime} 
                      setAddRealTime={actions.setAddRealTime}
                      distance={state.distance}
                      pricePerKm={state.quoteData.pricePerKm}
                      locationClient={props.clientData.location}
                      onOpenMap={() => actions.setIsMapOpen(true)}
                      selectionMode={quoteState.selectionMode}
                      setSelectionMode={actions.setSelectionMode}
                      isQuickMode={props.isQuickMode} 
                      onContactRequest={actions.handleContactRequest}
                      commercialMode={state.commercialMode}
                      setCommercialMode={actions.setCommercialMode}
                    />
                </motion.div>
            )}
          </AnimatePresence>
      </div>

      {/* FOOTER NAVIGATION */}
      {state.viewState === 'config' && (
        <div className="opacity-100 transition-all duration-300">
            <StickyFooter 
                totalPrice={state.totalPrice} 
                onApprove={actions.handleNextStep} 
                isApproved={false}
                highlight={true}
                showPrice={state.currentStep !== 0} 
                disabled={computed.isNextDisabled}
                customLabel={computed.footerLabel} 
            />
        </div>
      )}

      {/* MENU CASCATA (DROPDOWN MODAL) */}
      <AnimatePresence>
          {state.isCategoryMenuOpen && (
              <div className="fixed inset-0 z-[100] flex items-start justify-center pt-24 px-4">
                  <motion.div 
                      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                      className="absolute inset-0 bg-black/60 backdrop-blur-lg"
                      onClick={() => actions.setIsCategoryMenuOpen(false)}
                  />
                  <motion.div
                      initial={{ opacity: 0, y: -20, scale: 0.95 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: -20, scale: 0.95 }}
                      className="relative bg-neutral-900 border border-white/10 rounded-2xl w-full max-w-xs overflow-hidden shadow-2xl"
                  >
                      <div className="p-4 bg-white/5 border-b border-white/5 text-center">
                          <h3 className="text-white font-serif text-lg">Trocar Ocasião</h3>
                          <p className="text-neutral-500 text-[10px] uppercase tracking-wider">Selecione uma nova categoria</p>
                      </div>

                      <div className="p-2 space-y-1 max-h-[60vh] overflow-y-auto">
                          {Object.entries(state.categoryLabels).map(([key, label], index) => {
                              const isActive = quoteState.category === key;
                              return (
                                  <motion.button
                                      key={key}
                                      initial={{ opacity: 0, x: -10 }}
                                      animate={{ opacity: 1, x: 0 }}
                                      transition={{ delay: index * 0.05 }}
                                      onClick={() => {
                                          actions.setCategory(key as ServiceCategory);
                                          actions.setIsCategoryMenuOpen(false);
                                      }}
                                      className={cn(
                                          "w-full text-left px-4 py-3 rounded-xl flex items-center justify-between transition-all",
                                          isActive 
                                              ? "bg-brand-DEFAULT text-white shadow-lg shadow-brand-DEFAULT/20" 
                                              : "text-neutral-400 hover:bg-white/5 hover:text-white"
                                      )}
                                  >
                                      <span className="text-sm font-medium tracking-wide uppercase">{label}</span>
                                      {isActive && <CheckCircle size={16} />}
                                  </motion.button>
                              )
                          })}
                      </div>
                  </motion.div>
              </div>
          )}
      </AnimatePresence>

      {/* SUMMARY MODAL/VIEW */}
      <AnimatePresence>
         {state.viewState === 'summary' && (
            <SummaryView 
                clientData={props.clientData}
                onUpdateClientData={props.onUpdateClientData}
                quoteData={state.quoteData}
                totalPrice={state.totalPrice}
                paymentMethod={state.paymentMethod}
                setPaymentMethod={actions.setPaymentMethod}
                summaryDetails={computed.summaryDetails}
                priceBreakdown={state.priceBreakdown}
                onBack={() => actions.setViewState('config')}
                onProceedToSign={() => actions.setIsModalOpen(true)}
                onRemoveAddon={actions.handleRemoveAddon}
            />
         )}
      </AnimatePresence>

      <SignatureModal 
        isOpen={state.isModalOpen}
        onClose={() => actions.setIsModalOpen(false)}
        onConfirm={actions.handleSignatureSuccess}
        totalValue={formatCurrency(state.totalPrice)}
      />

      <LocationMapModal 
        isOpen={state.isMapOpen}
        onClose={() => actions.setIsMapOpen(false)}
        onSelectLocation={actions.handleUpdateLocation}
        initialAddress={props.clientData.location}
      />

      {/* NAME CAPTURE MODAL */}
      <AnimatePresence>
        {state.isNameModalOpen && (
             <div className="fixed inset-0 z-[60] flex items-center justify-center p-6">
                <motion.div 
                    initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                    className="absolute inset-0 bg-neutral-950/90 backdrop-blur-sm"
                    onClick={() => actions.setIsNameModalOpen(false)}
                />
                <motion.div
                    initial={{ scale: 0.9, opacity: 0, y: 20 }}
                    animate={{ scale: 1, opacity: 1, y: 0 }}
                    exit={{ scale: 0.9, opacity: 0, y: 20 }}
                    className="relative bg-neutral-900 border border-white/10 p-8 rounded-2xl w-full max-w-sm shadow-2xl"
                >
                     <button 
                        onClick={() => actions.setIsNameModalOpen(false)}
                        className="absolute top-4 right-4 text-neutral-500 hover:text-white transition-colors"
                     >
                        <X size={20} />
                     </button>

                    <div className="mb-6 flex justify-center">
                        <div className="p-3 bg-brand-DEFAULT/10 rounded-full text-brand-DEFAULT">
                            <User size={32} />
                        </div>
                    </div>
                    <h3 className="text-xl text-white font-serif text-center mb-2">Identifique-se</h3>
                    <p className="text-neutral-400 text-center text-sm mb-6">
                        Para prosseguir com o atendimento personalizado, precisamos saber como podemos te chamar.
                    </p>

                    <div className="space-y-4">
                        <input 
                            type="text"
                            placeholder="Seu nome ou empresa..."
                            value={state.tempName}
                            onChange={(e) => actions.setTempName(e.target.value)}
                            autoFocus
                            className="w-full bg-black/30 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-brand-DEFAULT outline-none transition-colors"
                            onKeyDown={(e) => e.key === 'Enter' && actions.handleConfirmName()}
                        />
                        <Button 
                            className="w-full"
                            onClick={actions.handleConfirmName}
                            disabled={state.tempName.trim().length < 2}
                        >
                            Continuar
                        </Button>
                    </div>
                </motion.div>
             </div>
        )}
      </AnimatePresence>

    </div>
  );
};

export default QuoteView;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Lock, Save, DollarSign, LogOut, ShieldAlert, Loader2, KeyRound } from 'lucide-react';
import Button from '../components/ui/Button';
import Logo from '../components/ui/Logo';
import { QuoteData } from '../types';
import { fadeInUp, staggerContainer } from '../lib/animations';
import { formatCurrency } from '../lib/utils';
import { AuthService } from '../services/AuthService';

interface AdminDashboardProps {
  currentConfig: QuoteData;
  onUpdateConfig: (newConfig: QuoteData) => void;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentConfig, onUpdateConfig, onExit }) => {
  // Estado de Autenticação
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');

  // Estados de Segurança e Feedback
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [attempts, setAttempts] = useState(0);

  // Estado do Formulário de Edição
  const [formData, setFormData] = useState({
    basePrice: currentConfig.basePrice,
    studioFee: currentConfig.studioFee,
    photoUnitPrice: currentConfig.photoUnitPrice,
    videoUnitPrice: currentConfig.videoUnitPrice,
  });

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();

    setError('');
    setIsLoading(true);

    // Adiciona delay artificial via AuthService
    await AuthService.securityDelay();

    const isValid = await AuthService.verify(password);

    if (isValid) {
      setIsAuthenticated(true);
      setError('');
      setAttempts(0);
    } else {
      const newAttempts = attempts + 1;
      setAttempts(newAttempts);
      setIsLoading(false);
      setPassword('');

      // Lógica de Expulsão (3 tentativas erradas)
      if (newAttempts >= 3) {
        onExit();
      } else {
        setError(`Senha incorreta. Tentativas restantes: ${3 - newAttempts}`);
      }
    }

    setIsLoading(false);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: parseFloat(value) || 0
    }));
  };

  const handleSave = () => {
    onUpdateConfig({
      ...currentConfig,
      ...formData
    });
    alert('Configurações salvas com segurança!');
  };

  // TELA DE LOGIN (SECURE GATE)
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-[#161616] flex flex-col items-center justify-center p-6 relative overflow-hidden">
        {/* Fundo dinâmico */}
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-neutral-900 via-[#161616] to-black z-0" />

        <motion.div 
          initial="hidden"
          animate="visible"
          variants={staggerContainer}
          className="relative z-10 w-full max-w-sm bg-neutral-900/80 border border-white/5 p-8 rounded-2xl backdrop-blur-xl shadow-2xl"
        >
          <div className="flex justify-center mb-8">
            <motion.div 
                key="normal"
                initial={{ scale: 0 }} animate={{ scale: 1 }}
                className="p-4 bg-brand-DEFAULT/10 rounded-full text-brand-DEFAULT shadow-[0_0_20px_var(--brand-glow)]"
            >
                <Lock size={32} />
            </motion.div>
          </div>

          <h2 className="text-2xl font-serif text-white text-center mb-2">
            Acesso Restrito
          </h2>
          <p className="text-neutral-500 text-center text-sm mb-8">
            Área exclusiva para administradores.
          </p>

          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-2 relative">
              <div className="absolute left-3 top-3.5 text-neutral-500">
                <KeyRound size={18} />
              </div>
              <input 
                type="password" 
                placeholder="Senha Mestre"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                disabled={isLoading}
                className={`w-full bg-neutral-950 border rounded-lg pl-10 pr-4 py-3 text-white transition-colors focus:outline-none
                  ${error ? 'border-red-500/50 focus:border-red-500' : 'border-white/10 focus:border-brand-DEFAULT'}
                `}
                autoFocus
              />
            </div>

            {error && (
              <motion.div 
                initial={{ opacity: 0, y: -10 }} 
                animate={{ opacity: 1, y: 0 }}
                className="flex items-center gap-2 text-red-400 text-xs pl-1 bg-red-500/10 p-2 rounded"
              >
                <ShieldAlert size={12} />
                <span>{error}</span>
              </motion.div>
            )}

            <div className="flex gap-3 pt-2">
               <Button 
                type="button" 
                variant="secondary" 
                className="w-1/3"
                onClick={onExit}
                disabled={isLoading}
               >
                 Voltar
               </Button>
               <Button 
                type="submit" 
                className="w-2/3 relative"
                disabled={isLoading}
               >
                 {isLoading ? <Loader2 className="animate-spin" size={20} /> : "Autenticar"}
               </Button>
            </div>
          </form>
        </motion.div>

        <div className="mt-8 text-neutral-600 text-xs flex flex-col items-center gap-1">
            <p>Protected by SHA-256 Encryption</p>
            <p className="opacity-50">EAREC Secure System v1.0.2</p>
        </div>
      </div>
    );
  }

  // TELA DE DASHBOARD (Acesso concedido)
  return (
    <div className="min-h-screen bg-[#161616] text-white font-sans">
      <header className="border-b border-white/5 bg-neutral-900/50 backdrop-blur-md sticky top-0 z-40">
        <div className="max-w-5xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Logo className="w-24" />
            <div className="hidden md:flex items-center gap-4">
               <span className="h-6 w-px bg-white/10" />
               <span className="text-sm font-medium text-neutral-400">Admin Mode</span>
               <span className="text-xs bg-green-500/10 text-green-500 px-2 py-0.5 rounded border border-green-500/20 flex items-center gap-1">
                 <Lock size={10} /> Secure Connection
               </span>
            </div>
          </div>
          <button 
            onClick={onExit}
            className="flex items-center gap-2 text-sm text-neutral-400 hover:text-white transition-colors border border-white/10 px-4 py-2 rounded-full hover:bg-white/5"
          >
            <LogOut size={16} />
            Sair com Segurança
          </button>
        </div>
      </header>

      <main className="max-w-3xl mx-auto py-12 px-6">
        <motion.div 
          initial="hidden" 
          animate="visible" 
          variants={staggerContainer}
        >
          <motion.div variants={fadeInUp} className="flex items-center justify-between mb-8">
            <div>
              <h1 className="text-3xl font-serif mb-2">Configuração de Preços</h1>
              <p className="text-neutral-400">Ajuste os valores base utilizados no cálculo automático dos orçamentos.</p>
            </div>
            <div className="p-3 bg-brand-DEFAULT/10 rounded-lg text-brand-DEFAULT">
              <DollarSign size={24} />
            </div>
          </motion.div>

          <motion.div variants={fadeInUp} className="bg-white/5 border border-white/5 rounded-xl p-8 space-y-8 shadow-inner">
            <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-8 border-b border-white/5">
              <div>
                <label className="block text-sm font-medium text-white mb-2">Preço Base (Mobilização)</label>
                <p className="text-xs text-neutral-500">Valor mínimo para saída da equipe. Incluído em todos os orçamentos.</p>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  name="basePrice"
                  value={formData.basePrice}
                  onChange={handleInputChange}
                  className="w-full bg-neutral-950 border border-white/10 rounded px-4 py-2 text-white focus:border-brand-DEFAULT focus:outline-none focus:ring-1 focus:ring-brand-DEFAULT transition-all"
                />
              </div>
            </motion.div>

            <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-8 border-b border-white/5">
              <div>
                <label className="block text-sm font-medium text-white mb-2">Taxa de Estúdio</label>
                <p className="text-xs text-neutral-500">Adicional cobrado quando o cliente seleciona "Estúdio Controlado".</p>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  name="studioFee"
                  value={formData.studioFee}
                  onChange={handleInputChange}
                  className="w-full bg-neutral-950 border border-white/10 rounded px-4 py-2 text-white focus:border-brand-DEFAULT focus:outline-none focus:ring-1 focus:ring-brand-DEFAULT transition-all"
                />
              </div>
            </motion.div>

            <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-8 border-b border-white/5">
              <div>
                <label className="block text-sm font-medium text-white mb-2">Preço por Foto</label>
                <p className="text-xs text-neutral-500">Valor unitário por fotografia tratada.</p>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  name="photoUnitPrice"
                  value={formData.photoUnitPrice}
                  onChange={handleInputChange}
                  className="w-full bg-neutral-950 border border-white/10 rounded px-4 py-2 text-white focus:border-brand-DEFAULT focus:outline-none focus:ring-1 focus:ring-brand-DEFAULT transition-all"
                />
              </div>
            </motion.div>

            <motion.div variants={fadeInUp} className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <label className="block text-sm font-medium text-white mb-2">Preço por Vídeo</label>
                <p className="text-xs text-neutral-500">Valor unitário por vídeo (1 min).</p>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  name="videoUnitPrice"
                  value={formData.videoUnitPrice}
                  onChange={handleInputChange}
                  className="w-full bg-neutral-950 border border-white/10 rounded px-4 py-2 text-white focus:border-brand-DEFAULT focus:outline-none focus:ring-1 focus:ring-brand-DEFAULT transition-all"
                />
              </div>
            </motion.div>

          </motion.div>

          <motion.div variants={fadeInUp} className="mt-8 flex justify-end gap-4">
            <Button variant="secondary" onClick={onExit}>
              Cancelar
            </Button>
            <Button onClick={handleSave} className="flex items-center gap-2">
              <Save size={18} />
              Salvar Alterações
            </Button>
          </motion.div>

          <motion.div variants={fadeInUp} className="mt-12 p-6 bg-brand-DEFAULT/5 border border-brand-DEFAULT/10 rounded-lg">
            <h3 className="text-sm font-medium text-brand-DEFAULT mb-4">Simulação Atual</h3>
            <div className="flex justify-between text-sm text-neutral-400">
              <span>Orçamento Básico (Externo + 20 Fotos + 1 Vídeo):</span>
              <strong className="text-white">
                {formatCurrency(formData.basePrice + (20 * formData.photoUnitPrice) + (1 * formData.videoUnitPrice))}
              </strong>
            </div>
          </motion.div>
        </motion.div>
      </main>
    </div>
  );
};

export default AdminDashboard;

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Calendar, Copyright, CreditCard, ArrowLeft, PenTool, MapPin, User, Phone, Edit2, X, Banknote, QrCode, FileText, Map as MapIcon, Trash2, PlusCircle, Check, Loader2, Cloud, ChevronDown, Sparkles, ShieldCheck } from 'lucide-react';
import Logo from '../components/ui/Logo';
import Button from '../components/ui/Button';
import AnimatedPrice from '../components/ui/AnimatedPrice';
import LocationMapModal from '../components/ui/LocationMapModal';
import { QuoteData, ClientData } from '../types';
import { cn, formatCurrency } from '../lib/utils';
import { fadeInUp, staggerContainer } from '../lib/animations';

interface SummaryDetails {
    serviceName: string;
    categoryLabel: string;
    metricLabel: string;
    addons: string[];
}

interface PriceItem {
    label: string;
    value: number;
    type: 'base' | 'addon' | 'freight';
}

interface SummaryViewProps {
  clientData: ClientData;
  onUpdateClientData: (data: ClientData) => void;
  quoteData: QuoteData;
  totalPrice: number;
  paymentMethod: string;
  setPaymentMethod: (method: string) => void;
  onBack: () => void;
  onProceedToSign: () => void;
  summaryDetails: SummaryDetails;
  priceBreakdown?: PriceItem[];
  onRemoveAddon?: (addonName: string) => void;
}

// Componente Auxiliar para Campos de Informação
interface InfoFieldProps {
  label: string;
  children: React.ReactNode;
  icon: any;
  editing: boolean;
}

const InfoField: React.FC<InfoFieldProps> = ({ label, children, icon: Icon, editing }) => (
    <div className={cn("flex gap-3", editing ? "opacity-100" : "opacity-80")}>
        <div className="mt-1 text-neutral-500 shrink-0">
            <Icon size={16} />
        </div>
        <div className="w-full">
            <p className="text-[10px] text-neutral-500 uppercase tracking-widest font-bold mb-0.5">{label}</p>
            <div className="text-sm md:text-base text-white font-light break-words leading-snug">
                {children}
            </div>
        </div>
    </div>
);

const SummaryView: React.FC<SummaryViewProps> = ({ 
  clientData, onUpdateClientData, quoteData, totalPrice, paymentMethod,
  setPaymentMethod, onBack, onProceedToSign, summaryDetails, priceBreakdown = [], onRemoveAddon
}) => {
  const [showContent, setShowContent] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false);
  const [tempData, setTempData] = useState<ClientData>(clientData);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [hasScrolled, setHasScrolled] = useState(false);

  const today = new Date().toISOString().split('T')[0];

  // Sincroniza dados apenas quando NÃO está editando
  useEffect(() => { 
      if (!isEditing) {
          setTempData(clientData); 
      }
  }, [clientData, isEditing]);

  // Animação de entrada atrasada para permitir a transição do modal anterior
  useEffect(() => {
    const timer = setTimeout(() => { setShowContent(true); }, 800); 
    return () => clearTimeout(timer);
  }, []);

  // --- LÓGICA DE AUTO-SAVE (DEBOUNCE) ---
  useEffect(() => {
    if (!isEditing) return;

    setSaveStatus('saving');
    const handler = setTimeout(() => {
        onUpdateClientData(tempData);
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
    }, 600); 

    return () => clearTimeout(handler);
  }, [tempData, isEditing, onUpdateClientData]);

  const handleFinishEditing = () => {
      onUpdateClientData(tempData);
      setIsEditing(false);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    if (name === 'contact') {
        const numericValue = value.replace(/\D/g, ''); 
        if (numericValue.length > 15) return; 
        setTempData(prev => ({ ...prev, [name]: numericValue }));
        return;
    }
    setTempData(prev => ({ ...prev, [name]: value }));
  };

  const handleLocationSelect = (address: string) => {
      setTempData(prev => ({ ...prev, location: address }));
  };

  const formatDateSafe = (dateString: string) => {
    if (!dateString) return 'A definir';
    try {
        const datePart = dateString.includes('T') ? dateString.split('T')[0] : dateString;
        const date = new Date(`${datePart}T12:00:00`);
        return date.toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
    } catch (e) { return dateString; }
  };

  const getInputDateValue = (dateString: string) => {
      if (!dateString) return '';
      return dateString.includes('T') ? dateString.split('T')[0] : dateString;
  };

  return (
    <div 
        className="fixed inset-0 z-50 bg-[#161616] overflow-y-auto"
        onScroll={(e) => setHasScrolled(e.currentTarget.scrollTop > 50)}
    >
      <AnimatePresence>
        {!showContent && (
          <motion.div
            key="intro-overlay"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0, filter: 'blur(20px)' }}
            transition={{ duration: 0.8 }}
            className="absolute inset-0 flex items-center justify-center bg-[#161616] z-50"
          >
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ duration: 0.8 }}>
              <Logo className="w-64" animate />
              <p className="text-center text-neutral-500 text-[10px] uppercase tracking-widest mt-4">Preparando resumo...</p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none">
          <div className="absolute top-[-10%] left-[-10%] w-[500px] h-[500px] bg-brand-DEFAULT/10 blur-[120px] rounded-full" />
          <div className="absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] bg-blue-900/10 blur-[120px] rounded-full" />
      </div>

      {showContent && (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="min-h-screen py-8 px-4 md:px-8 relative z-10 flex flex-col items-center"
        >
             <motion.div className="w-full max-w-6xl mx-auto" variants={staggerContainer} initial="hidden" animate="visible">

                {/* HEADER */}
                <motion.div variants={fadeInUp} className="flex flex-col md:flex-row items-center justify-between mb-8 pb-6 border-b border-white/5 gap-4">
                    <button onClick={onBack} className="flex items-center gap-2 text-neutral-400 hover:text-white transition-colors group text-sm font-medium bg-white/5 px-4 py-2 rounded-full hover:bg-white/10">
                        <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
                        Voltar à Configuração
                    </button>
                    <div className="text-center md:text-right">
                        <h2 className="text-white font-serif text-2xl md:text-3xl">Revisão do Pedido</h2>
                        <p className="text-neutral-500 text-xs uppercase tracking-widest mt-1">ID: {quoteData.id}</p>
                    </div>
                </motion.div>

                {/* MAIN GRID LAYOUT */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-10">

                    {/* COLUNA ESQUERDA: DADOS + PAGAMENTO (lg:col-span-7) */}
                    <motion.div variants={fadeInUp} className="lg:col-span-7 space-y-6">

                        {/* 1. CARD DADOS DO CLIENTE */}
                        <div className="bg-neutral-900/40 backdrop-blur-md border border-white/10 rounded-2xl overflow-hidden relative group">
                            <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-brand-DEFAULT to-transparent opacity-50" />

                            <div className="flex items-center justify-between px-6 py-4 border-b border-white/5 bg-white/[0.02]">
                                <h3 className="text-sm font-bold text-white flex items-center gap-2 uppercase tracking-wide">
                                    <User size={16} className="text-brand-DEFAULT" />
                                    Dados do Contrato
                                </h3>

                                {!isEditing ? (
                                    <button onClick={() => setIsEditing(true)} className="text-xs text-neutral-400 hover:text-white flex items-center gap-1.5 transition-colors px-3 py-1.5 rounded-full hover:bg-white/5 border border-transparent hover:border-white/10">
                                        <Edit2 size={12} /> Alterar
                                    </button>
                                ) : (
                                    <div className="flex items-center gap-3">
                                        <div className="flex items-center gap-1.5 text-[10px] uppercase tracking-wider transition-all">
                                            {saveStatus === 'saving' && <><Loader2 size={10} className="animate-spin text-neutral-500" /><span className="text-neutral-500">Salvando...</span></>}
                                            {saveStatus === 'saved' && <><Cloud size={10} className="text-green-500" /><span className="text-green-500">Salvo</span></>}
                                        </div>
                                        <button onClick={handleFinishEditing} className="text-xs flex items-center gap-1 bg-green-500/10 hover:bg-green-500/20 text-green-500 px-3 py-1.5 rounded-full transition-colors border border-green-500/20 font-medium">
                                            <Check size={12} /> Concluir
                                        </button>
                                    </div>
                                )}
                            </div>

                            <div className="p-6 md:p-8">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
                                    <InfoField label="Nome / Empresa" icon={User} editing={isEditing}>
                                        {isEditing ? (
                                            <input name="name" value={tempData.name} onChange={handleChange} className="w-full bg-transparent border-b border-white/20 text-white py-1 focus:border-brand-DEFAULT outline-none transition-colors placeholder:text-neutral-700" placeholder="Nome completo" />
                                        ) : clientData.name}
                                    </InfoField>

                                    <InfoField label="Data do Evento" icon={Calendar} editing={isEditing}>
                                        {isEditing ? (
                                            <input name="date" type="date" min={today} value={getInputDateValue(tempData.date)} onChange={handleChange} className="w-full bg-transparent border-b border-white/20 text-white py-1 focus:border-brand-DEFAULT outline-none transition-colors [&::-webkit-calendar-picker-indicator]:invert" />
                                        ) : formatDateSafe(clientData.date)}
                                    </InfoField>

                                    <InfoField label="Localização" icon={MapPin} editing={isEditing}>
                                        {isEditing ? (
                                            <div className="relative">
                                                <input name="location" value={tempData.location} onChange={handleChange} className="w-full bg-transparent border-b border-white/20 text-white py-1 pr-8 focus:border-brand-DEFAULT outline-none transition-colors placeholder:text-neutral-700" placeholder="Cidade ou Endereço" />
                                                <button onClick={() => setIsMapOpen(true)} className="absolute right-0 top-1 text-neutral-500 hover:text-brand-DEFAULT"><MapIcon size={16} /></button>
                                            </div>
                                        ) : (clientData.location || "A definir")}
                                    </InfoField>

                                    <InfoField label="WhatsApp" icon={Phone} editing={isEditing}>
                                        {isEditing ? (
                                            <input name="contact" type="tel" value={tempData.contact} onChange={handleChange} className="w-full bg-transparent border-b border-white/20 text-white py-1 focus:border-brand-DEFAULT outline-none transition-colors placeholder:text-neutral-700" placeholder="(00) 00000-0000" />
                                        ) : (clientData.contact || "A definir")}
                                    </InfoField>
                                </div>
                            </div>
                        </div>

                        {/* 2. CARD PAGAMENTO */}
                        <div className="bg-neutral-900/40 backdrop-blur-md border border-white/10 rounded-2xl p-6 relative">
                             <div className="flex items-center gap-2 mb-4 text-white">
                                <div className="p-2 bg-white/5 rounded-lg text-brand-DEFAULT">
                                    <CreditCard size={20} />
                                </div>
                                <div>
                                    <h4 className="text-sm font-bold uppercase tracking-wide">Forma de Pagamento</h4>
                                    <p className="text-[10px] text-neutral-500">Selecione como prefere realizar o pagamento</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                                {['Pix', 'Cartão', 'Espécie'].map((method) => {
                                    const isActive = paymentMethod === method;
                                    return (
                                        <button 
                                            key={method}
                                            onClick={() => setPaymentMethod(method)}
                                            className={cn(
                                                "relative flex flex-col items-center justify-center py-4 px-2 rounded-xl border transition-all duration-300 group overflow-hidden",
                                                isActive 
                                                    ? "bg-brand-DEFAULT/10 border-brand-DEFAULT text-white shadow-[0_0_15px_rgba(220,38,38,0.2)]" 
                                                    : "bg-black/20 border-white/5 text-neutral-400 hover:bg-white/5 hover:border-white/10 hover:text-white"
                                            )}
                                        >
                                            {isActive && <div className="absolute top-2 right-2 text-brand-DEFAULT"><Check size={14} /></div>}

                                            <div className={cn("mb-2 transition-transform duration-300", isActive ? "scale-110 text-brand-DEFAULT" : "group-hover:scale-110")}>
                                                {method === 'Pix' && <QrCode size={24} />}
                                                {method === 'Cartão' && <CreditCard size={24} />}
                                                {method === 'Espécie' && <Banknote size={24} />}
                                            </div>
                                            <span className="text-sm font-medium">{method}</span>
                                        </button>
                                    )
                                })}
                            </div>

                            <motion.div 
                                key={paymentMethod}
                                initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }}
                                className="mt-4 p-3 bg-white/5 rounded-lg border border-white/5 flex items-start gap-3"
                            >
                                <ShieldCheck size={16} className="text-green-500 mt-0.5 shrink-0" />
                                <p className="text-xs text-neutral-400 leading-relaxed">
                                    {paymentMethod === 'Pix' && <>Pagamento de <strong>50% na assinatura</strong> para reserva da data e <strong>50% na entrega</strong> do material.</>}
                                    {paymentMethod === 'Cartão' && <>Parcelamento em até <strong>12x no cartão de crédito</strong> (consultar taxas da maquininha).</>}
                                    {paymentMethod === 'Espécie' && <>Pagamento de <strong>50% na assinatura</strong> e 50% na entrega do material.</>}
                                </p>
                            </motion.div>
                        </div>

                    </motion.div>

                    {/* COLUNA DIREITA: RECIBO / TICKET (lg:col-span-5) */}
                    <motion.div variants={fadeInUp} className="lg:col-span-5 relative">
                        {/* EFEITO DE TICKET FLUTUANTE */}
                        <div className="sticky top-8">
                            <div className="relative bg-[#111] border border-white/10 rounded-2xl overflow-hidden shadow-2xl flex flex-col">

                                {/* TOPO DO TICKET */}
                                <div className="bg-brand-DEFAULT/10 p-6 border-b border-white/10 flex justify-between items-start">
                                    <div>
                                        <p className="text-[10px] text-brand-DEFAULT uppercase tracking-[0.2em] font-bold mb-1">Serviço Principal</p>
                                        <h3 className="text-xl md:text-2xl text-white font-serif leading-none">{summaryDetails.serviceName}</h3>
                                        <p className="text-neutral-400 text-xs mt-1">{summaryDetails.metricLabel}</p>
                                    </div>
                                    <div className="p-2 bg-white/5 rounded-lg border border-white/5">
                                        <FileText size={20} className="text-white opacity-80" />
                                    </div>
                                </div>

                                {/* LISTA DE ITENS */}
                                <div className="p-6 space-y-4 bg-dots-pattern">
                                    <p className="text-[10px] text-neutral-500 uppercase tracking-widest mb-2 border-b border-white/5 pb-2">Detalhamento</p>

                                    <div className="space-y-3">
                                        {priceBreakdown.map((item, idx) => (
                                            <div key={idx} className="flex justify-between items-start group">
                                                <div className="flex items-start gap-2 max-w-[70%]">
                                                    {item.type === 'addon' && onRemoveAddon && (
                                                        <button 
                                                            onClick={() => onRemoveAddon(item.label)} 
                                                            className="text-neutral-600 hover:text-red-500 transition-colors mt-0.5"
                                                            title="Remover Item"
                                                        >
                                                            <Trash2 size={12} />
                                                        </button>
                                                    )}
                                                    <span className={cn(
                                                        "text-sm leading-tight",
                                                        item.type === 'base' ? "text-white font-medium" : "text-neutral-400",
                                                        item.type === 'freight' && "italic"
                                                    )}>
                                                        {item.label}
                                                    </span>
                                                </div>
                                                <span className={cn(
                                                    "text-sm font-mono",
                                                    item.value === 0 ? "text-green-500 text-xs uppercase font-bold mt-0.5" : "text-white"
                                                )}>
                                                    {item.label.includes("A consultar") 
                                                            ? "Consultar" 
                                                            : item.value === 0 ? "Incluso" : formatCurrency(item.value)
                                                    }
                                                </span>
                                            </div>
                                        ))}
                                    </div>

                                    <div className="my-6 border-t-2 border-dashed border-white/10 relative">
                                        {/* Bolinhas decorativas do ticket */}
                                        <div className="absolute -left-[32px] -top-[10px] w-5 h-5 bg-neutral-950 rounded-full" />
                                        <div className="absolute -right-[32px] -top-[10px] w-5 h-5 bg-neutral-950 rounded-full" />
                                    </div>

                                    {/* TOTAL */}
                                    <div className="flex justify-between items-end">
                                        <span className="text-sm text-neutral-500 font-medium uppercase tracking-widest">Valor Total</span>
                                        <div className="text-right">
                                            <span className="text-3xl md:text-4xl text-brand-DEFAULT font-serif block leading-none">
                                                <AnimatedPrice value={totalPrice} />
                                            </span>
                                            <span className="text-[10px] text-neutral-500 uppercase font-medium">Moeda: BRL</span>
                                        </div>
                                    </div>
                                </div>

                                {/* AÇÃO */}
                                <div className="p-4 bg-neutral-900 border-t border-white/5">
                                    <Button 
                                        onClick={onProceedToSign}
                                        size="lg" 
                                        className="w-full shadow-[0_0_30px_rgba(220,38,38,0.2)] py-4 text-base tracking-wide flex items-center justify-center gap-2"
                                    >
                                        <PenTool size={18} />
                                        <span>CONFIRMAR ORÇAMENTO</span>
                                    </Button>
                                    <div className="mt-3 text-center flex items-center justify-center gap-1.5 opacity-50">
                                        <Copyright size={10} className="text-neutral-500" />
                                        <p className="text-[9px] text-neutral-500 uppercase tracking-widest">EAREC Audiovisual Experience</p>
                                    </div>
                                </div>

                            </div>

                            {/* Brilho de Fundo do Ticket */}
                            <div className="absolute -z-10 top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[110%] h-[90%] bg-brand-DEFAULT/5 blur-3xl rounded-full" />
                        </div>
                    </motion.div>

                </div>
             </motion.div>
        </motion.div>
      )}

      <LocationMapModal 
        isOpen={isMapOpen}
        onClose={() => setIsMapOpen(false)}
        onSelectLocation={handleLocationSelect}
        initialAddress={tempData.location}
      />
    </div>
  );
};

export default SummaryView;

