                                        <p className="text-neutral-400 text-xs mt-1">{summaryDetails.metricLabel}</p>
                                    </div>
                                    <div className="p-2 bg-white/5 rounded-lg border border-white/5">
                                        <FileText size={20} className="text-white opacity-80" />
